/* Central stylesheet — every component's styles live here, in cascade order.
   The final section is the Double Dash design layer. */
@import url("https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800;900&display=swap");

/* ==========================================================================
   SECTION: styles/theme.css
   ========================================================================== */
/**
 * NHL Franchise Mode — canonical design tokens
 * Authority: DESIGN.md / .impeccable/design.json
 * Three registers: Office Sanctum · Broadcast Ops · Franchise Shell
 */



/* Font guard — nothing may fall back to a serif or Arial default */
html {
  font-family: var(--font-ops-ui);
  -webkit-text-size-adjust: 100%;
}

button,
input,
select,
textarea {
  font-family: inherit;
}

/* Readability floor for operational surfaces */
.game-root {
  --type-floor: 11px;
}

/* Semantic type utilities (opt-in classes) */
.type-office-display {
  font-family: var(--font-office-display);
  font-size: var(--type-office-display-size);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.type-ops-heading {
  font-family: var(--font-ops-ui);
  font-size: var(--type-ops-heading-size);
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.type-phase-label,
.type-dept-label {
  font-family: var(--font-ops-ui);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  line-height: 1.2;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.type-body {
  font-family: var(--font-ops-ui);
  font-size: var(--type-body-size);
  font-weight: 400;
  line-height: 1.45;
}

.type-financial {
  font-family: var(--font-mono-data);
  font-size: var(--type-financial-size);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

.type-score {
  font-family: var(--font-broadcast-display);
  font-size: var(--type-score-size);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

/* Register scopes */
[data-register="office"],
.register-office {
  --local-bg: var(--office-bg);
  --local-text: var(--office-text);
  --local-muted: var(--office-text-secondary);
  --local-accent: var(--office-brass);
  --local-line: var(--office-line);
  --local-panel: var(--office-desk);
  --local-radius: var(--radius-hud);
  --local-font: var(--font-office-display);
  color: var(--local-text);
  font-family: var(--local-font);
}

[data-register="ops"],
.register-ops {
  --local-bg: var(--ops-navy);
  --local-text: var(--ops-text);
  --local-muted: var(--ops-text-secondary);
  --local-accent: var(--ops-cyan);
  --local-line: var(--ops-grid);
  --local-panel: var(--ops-panel);
  --local-radius: var(--radius-card);
  --local-font: var(--font-ops-ui);
  color: var(--local-text);
  font-family: var(--local-font);
}

[data-register="shell"],
.register-shell {
  --local-bg: var(--shell-bg);
  --local-text: var(--shell-text);
  --local-muted: var(--shell-text-muted);
  --local-accent: var(--shell-orange);
  --local-line: rgba(255, 255, 255, 0.08);
  --local-panel: var(--shell-structure);
  --local-radius: var(--radius-control);
  --local-font: var(--font-shell-body);
  color: var(--local-text);
  font-family: var(--local-font);
}

/* Ops headings share the Entry Draft display face. Screen-level rules that set
   their own heading family (office scene, nhlcal title) still win on order. */
:is([data-register="ops"], .register-ops, .nhlcal-root, .nhlcal-sl-root, .stats-central-screen,
  .cap-office-screen, .lo-screen, .chemistry-screen, .nhlrost-root, .free-agency-screen,
  .linebuilder-root) :is(h1, h2, h3) {
  font-family: var(--font-ops-head);
  letter-spacing: 0.04em;
}

/* Depth helpers */
.depth-flat { box-shadow: var(--depth-flat); }
.depth-registered { box-shadow: var(--depth-registered); }
.depth-lifted { box-shadow: var(--depth-lifted); }
.depth-overlay { box-shadow: var(--depth-overlay); }
.depth-cinematic { box-shadow: var(--depth-cinematic); }

/* Status marks — not pills by default */
.mark-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: var(--font-ops-ui);
  font-size: var(--type-table-meta-size);
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ops-text-secondary);
  border: 0;
  background: transparent;
  padding: 0;
}

.mark-status::before {
  content: "";
  width: 8px;
  height: 2px;
  background: currentColor;
  flex-shrink: 0;
}

.mark-status--injured { color: var(--ops-injury); }
.mark-status--injured::before { width: 10px; height: 10px; border: 1.5px solid currentColor; background: transparent; border-radius: 1px; clip-path: polygon(50% 0, 100% 100%, 0 100%); }

.mark-status--warning { color: var(--ops-warning); }
.mark-status--success { color: var(--ops-success); }
.mark-status--info { color: var(--ops-info); }
.mark-status--expiring { color: var(--ops-gold); }
.mark-status--unsigned { color: var(--ops-ice); }
.mark-status--scouted { color: var(--ops-cyan); }

.mark-seal {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 52px;
  padding: 2px 6px;
  border: 1px solid currentColor;
  border-radius: var(--radius-ops);
  font-size: 0.65rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.92;
}

/* Operational empty / loading / error states */
.ops-state {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-4);
  border: 1px dashed var(--ops-grid);
  border-radius: var(--radius-control);
  background: rgba(13, 37, 85, 0.55);
  color: var(--ops-text-secondary);
  max-width: 420px;
}

.ops-state__kicker {
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ops-cyan);
}

.ops-state__title {
  margin: 0;
  font-size: var(--type-ops-heading-size);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ops-text);
}

.ops-state__body {
  margin: 0;
  font-size: var(--type-compact-size);
  line-height: 1.45;
}

.ops-state--error {
  border-style: solid;
  border-color: rgba(255, 96, 109, 0.35);
}

.ops-state--loading .ops-state__kicker::after {
  content: "";
  display: inline-block;
  width: 28px;
  height: 2px;
  margin-left: 8px;
  vertical-align: middle;
  background: linear-gradient(90deg, transparent, var(--ops-cyan), transparent);
  background-size: 200% 100%;
  animation: opsSyncSweep 1.1s linear infinite;
}

@keyframes opsSyncSweep {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}

/* Focus rings */
:focus-visible {
  outline: 2px solid var(--ops-cyan);
  outline-offset: 2px;
}

[data-register="office"] :focus-visible,
.register-office :focus-visible {
  outline-color: var(--office-brass);
}

[data-register="shell"] :focus-visible,
.register-shell :focus-visible {
  outline-color: var(--shell-neon);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .ops-state--loading .ops-state__kicker::after {
    animation: none !important;
    opacity: 0.5;
  }
}

/* --- Motion system utilities --- */
.motion-micro {
  transition:
    color var(--motion-micro),
    background var(--motion-micro),
    border-color var(--motion-micro),
    box-shadow var(--motion-micro),
    transform var(--motion-micro);
}

.motion-workspace-enter {
  animation: workspaceEnter var(--motion-workspace) var(--ease-out-expo) both;
}

.motion-department-enter {
  animation: departmentEnter var(--motion-department) var(--ease-out-expo) both;
}

.motion-focus-sweep::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(105deg, transparent 40%, rgba(46, 230, 214, 0.08) 50%, transparent 60%);
  background-size: 220% 100%;
  animation: focusSweep 520ms var(--ease-out-expo) both;
}

@keyframes workspaceEnter {
  from {
    opacity: 0;
    transform: translateX(10px);
    clip-path: inset(0 8% 0 0);
  }
  to {
    opacity: 1;
    transform: none;
    clip-path: inset(0 0 0 0);
  }
}

@keyframes departmentEnter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes focusSweep {
  from { background-position: 120% 0; }
  to { background-position: -20% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .motion-workspace-enter,
  .motion-department-enter,
  .motion-focus-sweep::after {
    animation: none !important;
  }
}

/* ═══════════════════════════════════════════════════════════
   State-change motion vocabulary
   Each entry communicates one specific change. No entry animates
   a layout dimension, so nothing reflows while it plays.
   ═══════════════════════════════════════════════════════════ */

/* Tab / category swap: the panel shell stays put, only content is replaced. */
.motion-tabswap {
  animation: tabSwap 170ms var(--ease-out-expo) both;
}

@keyframes tabSwap {
  from { opacity: 0; transform: translate3d(0, 4px, 0); }
  to { opacity: 1; transform: none; }
}

/* Inspector content swap: no travel, so the reader's eye stays on the value. */
.motion-inspector-swap {
  animation: inspectorSwap 190ms var(--ease-out-expo) both;
}

@keyframes inspectorSwap {
  from { opacity: 0.15; }
  to { opacity: 1; }
}

/* Row / unit selection confirm: a rail wipes in from the leading edge. */
.motion-select-confirm::before {
  animation: selectRail 200ms var(--ease-out-expo) both;
}

@keyframes selectRail {
  from { transform: scaleY(0.2); opacity: 0; }
  to { transform: scaleY(1); opacity: 1; }
}

/* Trade asset entering / leaving a package well. */
.motion-asset-in {
  animation: assetIn 220ms var(--ease-out-expo) both;
}

.motion-asset-out {
  animation: assetOut 160ms ease-in both;
}

@keyframes assetIn {
  from { opacity: 0; transform: translate3d(0, -6px, 0); box-shadow: inset 0 0 0 1px var(--ops-gold); }
  to { opacity: 1; transform: none; box-shadow: none; }
}

@keyframes assetOut {
  from { opacity: 1; }
  to { opacity: 0; transform: translate3d(0, 4px, 0); }
}

/* Lineup placement feedback: the affected unit flashes its rail, not the board. */
.motion-placement {
  animation: placementMark 420ms var(--ease-out-expo) both;
}

@keyframes placementMark {
  0% { box-shadow: inset 3px 0 0 var(--ops-cyan), inset 0 0 0 100vmax rgba(46, 230, 214, 0.12); }
  100% { box-shadow: inset 3px 0 0 var(--ops-cyan), inset 0 0 0 100vmax rgba(46, 230, 214, 0); }
}

/* Value changed in a table cell (sort / filter / refresh). */
.motion-value-change {
  animation: valueChange 380ms ease-out both;
}

@keyframes valueChange {
  0% { color: var(--ops-cyan); }
  100% { color: inherit; }
}

/* ─── Overlay categories ─── */

/* Standard modal: restrained. It is a form, not an event. */
.overlay-anim--modal {
  animation: overlayModal 170ms var(--ease-out-expo) both;
}

@keyframes overlayModal {
  from { opacity: 0; transform: translate3d(0, 8px, 0); }
  to { opacity: 1; transform: none; }
}

/* Transaction popup: consequence lands from the side, like a wire slip. */
.overlay-anim--transaction {
  animation: overlayTransaction 260ms var(--ease-out-expo) both;
}

@keyframes overlayTransaction {
  from { opacity: 0; transform: translate3d(24px, 0, 0); }
  to { opacity: 1; transform: none; }
}

/* Broadcast interrupt: a hard horizontal wipe, no fade-in drift. */
.overlay-anim--broadcast {
  animation: overlayBroadcast 300ms cubic-bezier(0.7, 0, 0.2, 1) both;
}

@keyframes overlayBroadcast {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

/* Decision event: the frame settles before the choices become readable. */
.overlay-anim--decision {
  animation: overlayDecision 340ms var(--ease-out-expo) both;
}

@keyframes overlayDecision {
  0% { opacity: 0; transform: scale(0.985); }
  60% { opacity: 1; }
  100% { opacity: 1; transform: none; }
}

/* Cinematic event: longest reveal, reserved for league-scale moments. */
.overlay-anim--cinematic {
  animation: overlayCinematic var(--motion-cinematic) both;
}

@keyframes overlayCinematic {
  0% { opacity: 0; transform: scale(1.015); filter: brightness(0.7); }
  100% { opacity: 1; transform: none; filter: none; }
}

@media (prefers-reduced-motion: reduce) {
  .motion-tabswap,
  .motion-inspector-swap,
  .motion-select-confirm::before,
  .motion-asset-in,
  .motion-asset-out,
  .motion-placement,
  .motion-value-change,
  .overlay-anim--modal,
  .overlay-anim--transaction,
  .overlay-anim--broadcast,
  .overlay-anim--decision,
  .overlay-anim--cinematic {
    animation: none !important;
  }

  /* Selected and consequence states must still read without motion. */
  .motion-asset-in {
    box-shadow: inset 3px 0 0 var(--ops-gold);
  }

  .overlay-anim--broadcast {
    clip-path: none;
    border-left: 3px solid var(--ops-cyan);
  }
}

