  --g-space-1: var(--space-3);
  --g-space-2: var(--space-4);
  --g-space-3: var(--space-5);
  --bg: var(--ops-navy);
  --bg-2: var(--ops-black);
  --panel: var(--ops-panel);
  --panel-2: var(--ops-panel-2);
  --panel-3: var(--ops-panel-3);
  --line: var(--ops-grid);
  --line-2: var(--ops-grid-2);
  --line-strong: var(--ops-grid-strong);
  --muted: var(--ops-text-secondary);
  --muted-2: var(--ops-text-disabled);
  --cyan: var(--ops-cyan);
  --cyan-soft: var(--ops-cyan-soft);
  --gold: var(--ops-gold);
  --gold-soft: var(--ops-gold-soft);
  --green: var(--ops-success);
  --green-soft: var(--ops-success-soft);
  --red: var(--ops-injury);
  --red-soft: var(--ops-injury-soft);
  --blue: var(--ops-info);
  --blue-soft: var(--ops-info-soft);
  --purple: var(--ops-info, #8ab4ff);
  --shadow: var(--depth-overlay);
  --fcn-cut: 10px;
  --fcn-cut-sm: 6px;
  --fcn-rail-w: 3px;
}

/* 1 · Rink Cut — a single clipped corner taken from rink-board geometry.
   Reserved for committing actions and department headers. */
.fcn-cut {
  clip-path: polygon(
    0 0,
    calc(100% - var(--fcn-cut)) 0,
    100% var(--fcn-cut),
    100% 100%,
    0 100%
  );
  border-radius: 0;
}

.fcn-cut--sm {
  --fcn-cut: var(--fcn-cut-sm);
}

.fcn-cut--lead {
  clip-path: polygon(
    var(--fcn-cut) 0,
    100% 0,
    100% 100%,
    0 100%,
    0 var(--fcn-cut)
  );
  border-radius: 0;
}

/* 2 · Broadcast Rail — encodes selection, live state, or side ownership. */
.fcn-rail {
  position: relative;
}

.fcn-rail::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: var(--fcn-rail-w);
  background: var(--fcn-rail-color, var(--ops-cyan));
  transform-origin: center top;
}

.fcn-rail--gold { --fcn-rail-color: var(--ops-gold); }
.fcn-rail--red { --fcn-rail-color: var(--ops-signal-red); }
.fcn-rail--brass { --fcn-rail-color: var(--office-brass); }
.fcn-rail--quiet { --fcn-rail-color: var(--ops-text-disabled); }

.fcn-rail--top::before {
  left: 0;
  right: 0;
  bottom: auto;
  width: auto;
  height: var(--fcn-rail-w);
}

/* 3 · Equipment Plate — identification label: number, position, code, term. */
.fcn-plate {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  padding: 1px 5px;
  border: 1px solid var(--fcn-plate-line, var(--ops-grid));
  border-radius: var(--radius-ops);
  background: var(--fcn-plate-fill, rgba(255, 255, 255, 0.03));
  color: var(--fcn-plate-ink, var(--ops-text));
  font-family: var(--font-ops-ui);
  font-size: var(--type-table-meta-size);
  font-weight: 900;
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
  text-transform: uppercase;
  line-height: 1.5;
}

.fcn-plate--number {
  --fcn-plate-ink: var(--ops-text);
  --fcn-plate-line: var(--ops-grid-2);
  letter-spacing: 0.02em;
}

.fcn-plate--position {
  --fcn-plate-ink: var(--ops-cyan);
  --fcn-plate-line: rgba(46, 230, 214, 0.32);
  --fcn-plate-fill: var(--ops-cyan-soft);
}

.fcn-plate--term {
  --fcn-plate-ink: var(--ops-gold);
  --fcn-plate-line: rgba(233, 168, 60, 0.32);
  --fcn-plate-fill: var(--ops-gold-soft);
}

.fcn-plate--office {
  --fcn-plate-ink: var(--office-brass);
  --fcn-plate-line: var(--office-line-strong);
  --fcn-plate-fill: var(--office-brass-soft);
  font-family: var(--font-office-display);
}

/* 4 · League Stamp — formal document status. Framed text, never a bubble. */
.fcn-stamp {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 7px;
  border: 1px solid currentColor;
  border-radius: var(--radius-ops);
  font-family: var(--font-ops-ui);
  font-size: var(--type-table-meta-size);
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ops-text-secondary);
  background: transparent;
}

.fcn-stamp--approved { color: var(--ops-success); }
.fcn-stamp--pending { color: var(--ops-gold); }
.fcn-stamp--rejected { color: var(--ops-injury); }
.fcn-stamp--filed { color: var(--ops-info); }
.fcn-stamp--locked { color: var(--ops-text-disabled); }
.fcn-stamp--office {
  color: var(--office-brass);
  font-family: var(--font-office-display);
  letter-spacing: 0.14em;
}

/* 5 · Scorebug Header — compact department context, never a hero banner. */
.fcn-scorebug {
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 38px;
  padding: 6px 12px;
  border-bottom: 1px solid var(--ops-grid);
  background: linear-gradient(180deg, rgba(14, 40, 88, 0.94), rgba(12, 33, 77, 0.88));
  font-family: var(--font-ops-ui);
}

.fcn-scorebug__code {
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ops-cyan);
}

.fcn-scorebug__title {
  margin: 0;
  font-size: var(--type-ops-heading-size);
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ops-text);
}

.fcn-scorebug__context {
  font-size: var(--type-compact-size);
  font-weight: 700;
  color: var(--ops-text-secondary);
  font-variant-numeric: tabular-nums;
}

.fcn-scorebug__spacer { margin-left: auto; }

/* 6 · Tactical Tape — coaching emphasis and concern annotation. */
.fcn-tape {
  position: relative;
  padding-left: 12px;
  font-size: var(--type-compact-size);
  color: var(--ops-text-secondary);
}

.fcn-tape::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 8px;
  height: 2px;
  background: var(--fcn-tape-color, var(--ops-gold));
}

.fcn-tape--concern { --fcn-tape-color: var(--ops-injury); }
.fcn-tape--strength { --fcn-tape-color: var(--ops-success); }

/* 7 · Ledger Spine — connects paired financial or transaction structure. */
.fcn-spine {
  position: relative;
}

.fcn-spine::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  background: linear-gradient(
    180deg,
    transparent,
    var(--ops-grid-2) 12%,
    var(--ops-grid-2) 88%,
    transparent
  );
  pointer-events: none;
}

/* 8 · Signal Lamp — live binary state. Text is mandatory, colour never alone. */
.fcn-lamp {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-ops-ui);
  font-size: var(--type-table-meta-size);
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ops-text-secondary);
}

.fcn-lamp::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 1px;
  background: var(--fcn-lamp-color, var(--ops-text-disabled));
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.4) inset;
  flex-shrink: 0;
}

.fcn-lamp--live { --fcn-lamp-color: var(--ops-success); color: var(--ops-success); }
.fcn-lamp--working { --fcn-lamp-color: var(--ops-cyan); color: var(--ops-cyan); }
.fcn-lamp--warning { --fcn-lamp-color: var(--ops-gold); color: var(--ops-gold); }
.fcn-lamp--fault { --fcn-lamp-color: var(--ops-injury); color: var(--ops-injury); }
.fcn-lamp--idle { --fcn-lamp-color: var(--ops-text-disabled); }

.fcn-lamp--working::before {
  animation: fcnLampPulse 1.6s ease-in-out infinite;
}

@keyframes fcnLampPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

/* 9 · Broadcast Wipe — context change and interruption only. */
.fcn-wipe {
  animation: fcnWipe var(--motion-department) cubic-bezier(0.7, 0, 0.2, 1) both;
}

@keyframes fcnWipe {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

/* ─── Loader families: one per register, none of them a spinner ─── */
.fcn-load {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: var(--font-ops-ui);
}

.fcn-load__label {
  margin: 0;
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ops-text-secondary);
}

/* Office: a brass registration line sweeping a filing drawer. */
.fcn-load--office .fcn-load__track {
  height: 2px;
  background: var(--office-line);
  position: relative;
  overflow: hidden;
}

.fcn-load--office .fcn-load__track::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, var(--office-brass), transparent);
  transform: translateX(-100%);
  animation: fcnOfficeRegister 1.6s ease-in-out infinite;
}

.fcn-load--office .fcn-load__label {
  color: var(--office-text-secondary);
  font-family: var(--font-office-display);
}

@keyframes fcnOfficeRegister {
  to { transform: translateX(100%); }
}

/* Ops: three scoreboard segments cycling like a data rail update. */
.fcn-load--ops .fcn-load__track {
  display: flex;
  gap: 3px;
}

.fcn-load--ops .fcn-load__track span {
  height: 3px;
  flex: 1;
  background: var(--ops-grid);
  animation: fcnOpsSegment 1.2s ease-in-out infinite;
}

.fcn-load--ops .fcn-load__track span:nth-child(2) { animation-delay: 0.16s; }
.fcn-load--ops .fcn-load__track span:nth-child(3) { animation-delay: 0.32s; }

@keyframes fcnOpsSegment {
  0%, 100% { background: var(--ops-grid); }
  40% { background: var(--ops-cyan); }
}

/* Cinematic: an event title bar registering into place. */
.fcn-load--cinematic .fcn-load__track {
  height: 4px;
  background: rgba(233, 168, 60, 0.16);
  position: relative;
  overflow: hidden;
}

.fcn-load--cinematic .fcn-load__track::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--ops-gold);
  transform: scaleX(0.18);
  transform-origin: left center;
  animation: fcnCinematicRegister 1.8s var(--ease-out-expo) infinite;
}

.fcn-load--cinematic .fcn-load__label {
  color: var(--ops-gold);
  letter-spacing: 0.2em;
}

@keyframes fcnCinematicRegister {
  0% { transform: scaleX(0.12); opacity: 0.6; }
  60% { transform: scaleX(1); opacity: 1; }
  100% { transform: scaleX(1); opacity: 0.25; }
}

/* Table skeletons keep the real row geometry so nothing shifts on arrival. */
.fcn-skeleton-row {
  height: 28px;
  border-bottom: 1px solid rgba(156, 218, 236, 0.08);
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.02) 0%,
    rgba(255, 255, 255, 0.05) 40%,
    rgba(255, 255, 255, 0.02) 80%
  );
  background-size: 220% 100%;
  animation: fcnSkeleton 1.4s linear infinite;
}

@keyframes fcnSkeleton {
  from { background-position: 120% 0; }
  to { background-position: -60% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .fcn-wipe,
  .fcn-lamp--working::before,
  .fcn-skeleton-row,
  .fcn-load--office .fcn-load__track::after,
  .fcn-load--ops .fcn-load__track span,
  .fcn-load--cinematic .fcn-load__track::after {
    animation: none !important;
  }

  /* Loading must still read as loading without movement. */
  .fcn-load--ops .fcn-load__track span:first-child { background: var(--ops-cyan); }
  .fcn-load--office .fcn-load__track::after { transform: none; opacity: 0.5; }
  .fcn-load--cinematic .fcn-load__track::after { transform: scaleX(0.4); }
  .fcn-lamp--working::before { opacity: 1; }
}

/* Short viewport densify (1366x768 class) */
@media (max-height: 800px) {
  .nhlcal-topbar {
    min-height: 72px !important;
    gap: 12px !important;
  }
  .nhlcal-main {
    padding: 14px 16px 16px !important;
  }
}

@media (max-width: 1400px) and (max-height: 800px) {
  .game-screen .ops-state {
    padding: 10px 12px;
  }
}

/* ==========================================================================
   SECTION: styles/fluid-ui.css
   ========================================================================== */
/*
  Resolution-relative layout. No CSS zoom / transform scale.
  html[data-display] is set from the real window size.
*/

html.ui-fluid,
html.ui-fluid body,
html.ui-fluid #root {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

html.ui-fluid #root {
  position: relative;
}

html.ui-fluid .game-root,
html.ui-fluid .game-canvas {
  width: 100%;
