/* ==========================================================================
   SECTION: styles/game-ui.css
   ========================================================================== */
/* Full-viewport Franchise Shell — tokens live in theme.css */
/* Shell register aliases kept for local selectors; canonical values from theme.css */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}

body {
  font-family: var(--g-font-body);
  background: var(--g-navy0);
  color: var(--g-text);
  -webkit-font-smoothing: antialiased;
}

.game-root {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: stretch;
  overflow: hidden;
}

.game-canvas {
  position: relative;
  flex: 1;
  width: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: linear-gradient(145deg, #0f2155 0%, #0c1c48 42%, #0c1a44 100%);
  border-radius: 0;
  box-shadow: none;
}

.game-canvas::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 120% 80% at 20% 0%, rgba(56, 189, 248, 0.12), transparent 55%),
    radial-gradient(ellipse 100% 60% at 100% 100%, rgba(224, 112, 32, 0.1), transparent 50%);
  animation: hubBgDrift 28s ease-in-out infinite alternate;
  pointer-events: none;
  z-index: 0;
}

.game-canvas::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.04;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  animation: hubNoise 6s steps(4) infinite;
  pointer-events: none;
  z-index: 0;
}

@keyframes hubBgDrift {
  0% {
    transform: translate(0, 0) scale(1);
  }
  100% {
    transform: translate(-3%, 2%) scale(1.04);
  }
}

@keyframes hubNoise {
  0% {
    opacity: 0.035;
  }
  100% {
    opacity: 0.055;
  }
}

@keyframes hubNewsIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes hubAdvancePulse {
  0%,
  100% {
    box-shadow:
      0 0 0 0 rgba(224, 112, 32, 0.35),
      inset 0 1px 0 rgba(255, 255, 255, 0.25);
  }
  50% {
    box-shadow:
      0 0 28px 2px rgba(224, 112, 32, 0.45),
      inset 0 1px 0 rgba(255, 255, 255, 0.25);
  }
}

@media (prefers-reduced-motion: reduce) {
  .game-canvas::before,
  .game-canvas::after,
  .hub-news-line,
  .game-btn--advance:not(:disabled),
  .hub-radial-center__ring,
  .hub-radial-center__glow,
  .hub-gm-avatar__halo,
  .hub-station__ring {
    animation: none !important;
  }

  .ui-interactive {
    transition: none !important;
  }

  .ui-interactive:hover {
    transform: none !important;
  }
}

.game-screen {
  position: relative;
  z-index: 1;
  flex: 1;
  min-height: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  font-family: var(--g-font-body);
}

/* ----- Glass + tooltips + interactive ----- */

.hub-glass {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow:
    0 12px 40px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.hub-glass--inner {
  background: rgba(0, 0, 0, 0.22);
}

[data-tooltip] {
  position: relative;
}

[data-tooltip]::after {
  content: attr(data-tooltip);
  position: absolute;
  left: 50%;
  bottom: calc(100% + 10px);
  transform: translate(-50%, 4px);
  padding: 8px 10px;
  max-width: 280px;
  white-space: normal;
  text-align: center;
  font-family: var(--g-font-body);
  font-size: 0.6875rem;
  letter-spacing: 0.04em;
  line-height: 1.35;
  color: var(--g-text);
  background: rgba(14, 30, 76, 0.95);
  border: 1px solid rgba(56, 189, 248, 0.35);
  border-radius: 6px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.55);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition:
    opacity 0.22s ease,
    transform 0.22s ease,
    visibility 0.22s;
  z-index: var(--z-tooltip, 400);
}

[data-tooltip]:hover::after {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
}

/* Controls respond, they do not float. 1px press, no scale, no glow bloom. */
.ui-interactive {
  transition:
    transform var(--motion-micro),
    box-shadow var(--motion-micro),
    border-color var(--motion-micro),
    color var(--motion-micro),
    background var(--motion-micro);
}

.ui-interactive:hover {
  filter: none;
  background-color: rgba(255, 255, 255, 0.04);
}

.ui-interactive:active {
  transform: translateY(1px);
}

button.ui-interactive:disabled {
  transform: none;
  filter: none;
}

/* ----- Header — Franchise Command Network context bar ----- */
.game-header {
  flex-shrink: 0;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--g-space-2) 0 0;
  background: linear-gradient(180deg, rgba(14, 40, 88, 0.96) 0%, rgba(12, 33, 77, 0.94) 100%);
  border-bottom: 1px solid var(--ops-grid);
  box-shadow: inset 0 -2px 0 rgba(46, 230, 214, 0.22);
}

/* Team side reads as a club identification plate clipped into the bar. */
.game-header__teamMark {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 100%;
  padding: 0 16px 0 12px;
  background: linear-gradient(90deg, rgba(46, 230, 214, 0.12), transparent);
  border-right: 1px solid var(--ops-grid);
  clip-path: polygon(0 0, 100% 0, calc(100% - 12px) 100%, 0 100%);
}

.game-header__logoSlot {
  width: 26px;
  height: 26px;
  background: linear-gradient(145deg, rgba(46, 230, 214, 0.18), rgba(12, 33, 77, 0.9));
  border: 1px solid var(--ops-grid-2);
  border-radius: var(--radius-ops);
  box-shadow: none;
}

.game-header__teamText {
  font-family: var(--font-ops-ui);
  font-size: 0.9rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ops-text);
  text-shadow: none;
}

/* Department label: scorebug segment with a leading rink-cut notch. */
.game-header__section {
  position: relative;
  padding-left: 16px;
  font-family: var(--font-ops-ui);
  font-size: 0.86rem;
  font-weight: 900;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ops-text);
  text-shadow: none;
}

.game-header__section::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 8px;
  height: 8px;
  background: var(--ops-cyan);
  clip-path: polygon(0 0, 100% 0, 100% 100%);
}

.game-header__brand {
  display: flex;
  align-items: baseline;
  gap: 8px;
  text-align: right;
}

/* Network mark — this game's own broadcast identity. */
.game-header__espn {
  font-family: var(--font-ops-ui);
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0.16em;
  color: var(--ops-gold);
  border: 1px solid rgba(233, 168, 60, 0.42);
  border-radius: var(--radius-ops);
  padding: 1px 5px;
}

.game-header__tag {
  font-size: 0.625rem;
  letter-spacing: 0.2em;
  color: var(--ops-text-secondary);
  text-transform: uppercase;
}

@media (max-width: 1400px) {
  .game-header__tag {
    display: none;
  }
}

/* ----- Footer — bench communication strip ----- */
.game-footer {
  flex-shrink: 0;
  height: 30px;
  background: rgba(12, 33, 77, 0.96);
  border-top: 1px solid var(--ops-grid);
  display: flex;
  align-items: center;
  padding: 0 var(--g-space-2);
}

.game-footer__bar {
  position: relative;
  padding-left: 14px;
  font-family: var(--font-ops-ui);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--ops-text-secondary);
  text-transform: uppercase;
}

.game-footer__bar::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 2px;
  background: var(--ops-cyan);
}

.game-panel-bevel {
  background: linear-gradient(160deg, rgba(26, 36, 61, 0.75) 0%, rgba(19, 37, 92, 0.85) 100%);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  box-shadow:
    inset 1px 1px 0 rgba(255, 255, 255, 0.07),
    inset -1px -1px 0 rgba(0, 0, 0, 0.35),
    0 8px 28px rgba(0, 0, 0, 0.35);
}

/* ----- Setup ----- */
.setup-screen .setup-body {
  flex: 1;
  min-height: 0;
  width: 100%;
  padding: clamp(var(--g-space-2), 4vw, var(--g-space-3)) clamp(var(--g-space-2), 5vw, 80px);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
}

.setup-panel {
  width: 100%;
  padding: var(--g-space-3) clamp(var(--g-space-2), 3vw, 32px);
}

.setup-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--g-space-1) var(--g-space-1);
  margin-bottom: 8px;
  border-radius: 6px;
  cursor: default;
}

.setup-row.is-focus-row {
  outline: 2px solid var(--g-orange);
  background: rgba(224, 112, 32, 0.12);
  box-shadow: none;
}

.setup-label {
  font-family: var(--g-font-head);
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  color: var(--g-silver-dim);
}

.setup-value {
  font-size: 1rem;
  font-weight: 600;
  color: var(--g-text);
}

.setup-club-picker {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  max-width: min(520px, 70vw);
}

.setup-select {
  width: 100%;
  max-width: 420px;
  padding: 8px 10px;
  background: var(--g-navy0);
  border: 2px inset #3a465e;
  border-radius: 4px;
  color: var(--g-text);
  font-family: var(--g-font-body);
  font-size: 0.88rem;
  cursor: pointer;
}

.game-input {
  flex: 1;
  width: 100%;
  background: var(--g-navy0);
  border: 2px inset #3a465e;
  color: var(--g-text);
  padding: 8px 10px;
  font-family: var(--g-font-body);
  font-size: 0.95rem;
}

.game-cta {
  width: 100%;
  margin-top: var(--g-space-2);
  padding: 14px;
  font-family: var(--g-font-head);
  font-size: 0.95rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  background: linear-gradient(180deg, var(--g-orange) 0%, var(--g-orange-dim) 100%);
  border: 2px solid #ffb070;
  color: #171d38;
  cursor: pointer;
  border-radius: 6px;
}

.game-cta:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.setup-hint {
  margin-top: var(--g-space-2);
  font-size: 0.75rem;
  color: var(--g-silver-dim);
  text-align: center;
  width: 100%;
}

.game-toast {
  margin-top: var(--g-space-1);
  padding: 10px 14px;
  font-size: 0.85rem;
  border: 2px solid var(--g-silver-dim);
  background: rgba(0, 0, 0, 0.35);
  width: 100%;
}

.game-toast--err {
  border-color: #c8102e;
  background: rgba(200, 16, 46, 0.15);
}

/* ----- Hub fullscreen layout ----- */

.hub-screen {
  min-height: 0;
}

.hub-franchise-shell {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
  gap: var(--g-space-2);
  padding: var(--g-space-2) var(--g-space-2) 0;
  overflow: hidden;
}

.hub-sidebar {
  width: 232px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  padding: var(--g-space-2);
  border-radius: 10px;
  overflow: hidden;
}

.hub-sidebar__brand {
  padding-bottom: var(--g-space-2);
  margin-bottom: var(--g-space-2);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

/* Network mark stamped like office door hardware, not a logo bubble. */
.hub-sidebar__espn {
  display: inline-block;
  font-family: var(--font-office-display);
  font-size: 0.95rem;
  letter-spacing: 0.2em;
  color: var(--office-brass);
  border: 1px solid var(--office-line-strong);
  border-radius: var(--radius-ops);
  padding: 1px 7px;
}

.hub-sidebar__title {
  display: block;
  font-family: var(--g-font-head);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  color: var(--g-silver);
  margin-top: 4px;
}

.hub-sidebar__tag {
  display: block;
  font-size: 0.6875rem;
  letter-spacing: 0.28em;
  color: var(--g-neon);
  margin-top: 6px;
}

.hub-sidebar__nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

/* Department rows read as filing-cabinet tabs, not sidebar buttons. */
.hub-sidebar__link {
  position: relative;
  padding: 11px var(--g-space-2) 11px 14px;
  font-family: var(--font-office-display);
  font-size: 0.76rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--office-text-secondary);
  border-left: 3px solid transparent;
  border-bottom: 1px solid var(--office-line);
  border-radius: 0;
  cursor: default;
}

.hub-sidebar__link:hover {
  color: var(--office-text);
  background: rgba(255, 255, 255, 0.03);
}

/* Active department is registered in brass and notched at the trailing edge. */
.hub-sidebar__link.is-selected {
  color: var(--office-text);
  background: var(--office-selection);
  border-left-color: var(--office-brass);
  text-shadow: none;
  box-shadow: none;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
}

.hub-sidebar__link.is-selected::after {
  content: "";
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  width: 5px;
  height: 5px;
  background: var(--office-brass);
  border-radius: 1px;
}

.hub-workspace {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: var(--g-space-2);
  overflow: hidden;
}

.hub-live-status {
  position: relative;
  flex-shrink: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--g-space-2);
  padding: var(--g-space-2) var(--g-space-3);
  border-radius: 10px;
  overflow: hidden;
}

.hub-live-status__glow {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--g-orange), var(--g-neon), transparent);
  box-shadow: 0 0 18px rgba(224, 112, 32, 0.65);
  pointer-events: none;
}

.hub-live-status__primary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--g-space-2);
  min-width: 0;
}

.hub-live-status__team {
  font-family: var(--g-font-head);
  font-size: clamp(1rem, 1.8vw, 1.35rem);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--g-text);
  text-shadow: 0 0 18px rgba(56, 189, 248, 0.25);
}

/* Office status marks are stamped, not pilled. */
.hub-live-status__chip {
  font-family: var(--g-font-head);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  padding: 5px 10px;
  border-radius: 2px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(0, 0, 0, 0.25);
  color: var(--g-silver);
}

.hub-live-status__meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--g-space-3);
  align-items: flex-end;
}

.hub-live-status__meta-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 120px;
}

.hub-live-status__k {
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.2em;
  color: var(--g-silver-dim);
}

.hub-live-status__v {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--g-silver);
}

.hub-live-status__v--phase {
  color: var(--g-neon);
  letter-spacing: 0.08em;
}

.hub-live-status__sub {
  font-size: 0.6875rem;
  color: var(--g-silver-dim);
}

.hub-live-panel {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: var(--g-space-2);
  padding: var(--g-space-2) var(--g-space-3);
  border-radius: 12px;
  overflow: hidden;
}

.hub-snapshot-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: var(--g-space-2);
  flex-shrink: 0;
}

.hub-snap-card {
  padding: var(--g-space-2);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: 0 0 0 1px rgba(56, 189, 248, 0.08);
}

.hub-snap-card:hover {
  border-color: rgba(224, 112, 32, 0.45);
  box-shadow:
    0 0 24px rgba(224, 112, 32, 0.12),
    0 0 0 1px rgba(56, 189, 248, 0.15);
}

.hub-snap-card__label {
  display: block;
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.16em;
  color: var(--g-silver-dim);
  margin-bottom: 6px;
}

.hub-snap-card__num {
  font-family: var(--g-font-head);
  font-size: 1.35rem;
  letter-spacing: 0.06em;
  color: var(--g-text);
  text-shadow: 0 0 12px rgba(56, 189, 248, 0.2);
}

.hub-controls-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--g-space-2);
  align-items: stretch;
  flex-shrink: 0;
}

.hub-sim-speed {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: var(--g-space-1) var(--g-space-2);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.hub-sim-speed__label {
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.2em;
  color: var(--g-silver-dim);
  margin-right: 4px;
}

.hub-sim-speed__btn {
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  padding: 8px 12px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
  color: var(--g-silver);
  cursor: pointer;
}

.hub-sim-speed__btn.is-active {
  border-color: rgba(56, 189, 248, 0.65);
  color: var(--g-text);
  background: rgba(56, 189, 248, 0.12);
  box-shadow: 0 0 16px rgba(56, 189, 248, 0.25);
}

.hub-schedule-block {
  flex: 1;
  min-width: 200px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hub-block-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.18em;
  color: var(--g-silver-dim);
}

.hub-block-heading__hint {
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  color: var(--g-silver-dim);
  opacity: 0.85;
}

.hub-schedule-strip {
  display: flex;
  flex-direction: row;
  gap: 10px;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 4px;
  scrollbar-width: thin;
  scrollbar-color: var(--g-orange) rgba(0, 0, 0, 0.3);
}

.hub-schedule-strip--empty {
  align-items: center;
  padding: var(--g-space-1);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.2);
}

.hub-schedule-strip__empty {
  font-size: 0.72rem;
  color: var(--g-silver-dim);
}

.hub-schedule-tile {
  flex: 0 0 auto;
  width: 92px;
  padding: 8px 8px 10px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.hub-schedule-tile__logo {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: conic-gradient(from 180deg, var(--g-orange), var(--g-neon), var(--g-orange));
  opacity: 0.85;
  box-shadow: inset 0 0 0 3px rgba(0, 0, 0, 0.45);
}

.hub-schedule-tile__abbr {
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  color: var(--g-silver);
}

.hub-schedule-tile__wl {
  font-size: 0.6875rem;
  color: var(--g-neon);
  letter-spacing: 0.08em;
}

.hub-live-toast {
  flex-shrink: 0;
}

.hub-news-feed {
  flex: 1;
  min-height: 140px;
  display: flex;
  flex-direction: column;
  border-radius: 10px;
  background: rgba(11, 25, 65, 0.65);
  border: 1px solid rgba(56, 189, 248, 0.12);
  box-shadow: inset 0 0 40px rgba(0, 0, 0, 0.45);
  overflow: hidden;
}

.hub-news-feed__head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 10px var(--g-space-2);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.2em;
  color: var(--g-orange);
}

.hub-news-feed__sub {
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  color: var(--g-silver-dim);
}

.hub-news-feed__scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: var(--g-space-2);
  font-family: var(--dd-font-ui);
  font-size: 0.74rem;
  line-height: 1.5;
}

.hub-news-line {
  margin-bottom: 8px;
  padding: 6px 8px;
  border-radius: 6px;
  border-left: 3px solid rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.02);
  color: #b8c0d0;
  animation: hubNewsIn 0.42s ease both;
}

.hub-news-line--empty {
  border: none;
  background: transparent;
  color: var(--g-silver-dim);
  animation: none;
}

.hub-news-line--breakout {
  border-left-color: var(--g-orange);
  color: #ffe8d4;
  background: rgba(224, 112, 32, 0.08);
}

.hub-news-line--injury {
  border-left-color: #c8102e;
  color: #ffd0d8;
  background: rgba(200, 16, 46, 0.1);
}

.hub-news-line--trade {
  border-left-color: var(--ops-gold, #e9a83c);
  color: #f5e6c8;
  background: rgba(233, 168, 60, 0.12);
}

.hub-news-line--score {
  border-left-color: var(--g-neon);
  color: #d8f6ff;
  background: rgba(56, 189, 248, 0.08);
}

.hub-news-line--daystamp {
  border-left-color: rgba(148, 163, 184, 0.5);
  color: var(--g-silver-dim);
  background: rgba(18, 38, 92, 0.45);
  font-size: 0.7rem;
}

.hub-news-line--slate {
  border-left-color: #94a3b8;
  color: #cbd5e1;
  background: rgba(30, 41, 59, 0.35);
  font-size: 0.6875rem;
  line-height: 1.45;
}

.hub-news-line--record {
  border-left-color: var(--g-orange);
  color: #ffe8d4;
  background: rgba(224, 112, 32, 0.1);
  font-weight: 600;
}

.hub-news-line--idle {
  border-left-color: rgba(224, 112, 32, 0.55);
  color: #dcd6ff;
  background: rgba(224, 112, 32, 0.08);
}

.hub-decisions {
  flex-shrink: 0;
  max-height: 38vh;
  overflow-y: auto;
  padding: var(--g-space-2);
  border-radius: 10px;
}

.hub-decisions--critical {
  border: 1px solid rgba(248, 113, 113, 0.45);
  box-shadow: 0 0 0 1px rgba(248, 113, 113, 0.12), 0 8px 28px rgba(0, 0, 0, 0.35);
}

.hub-notifications {
  flex-shrink: 0;
  max-height: 22vh;
  min-height: 72px;
  display: flex;
  flex-direction: column;
  padding: var(--g-space-2);
  border-radius: 10px;
  margin-bottom: var(--g-space-1);
}

.hub-notifications__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  font-family: var(--g-font-head);
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  color: var(--g-neon);
  margin-bottom: 6px;
}

.hub-notifications__sub {
  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  color: var(--g-silver-dim);
}

.hub-notifications__scroll {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-right: 4px;
}

.hub-notif-line {
  font-size: 0.78rem;
  line-height: 1.35;
  padding: 6px 8px;
  border-radius: 8px;
  border-left: 3px solid rgba(148, 163, 184, 0.45);
  background: rgba(0, 0, 0, 0.18);
}

.hub-notif-line--empty {
  color: var(--g-silver-dim);
  font-style: italic;
  border-left-color: transparent;
  background: transparent;
}

.hub-notif-line--trade {
  border-left-color: rgba(56, 189, 248, 0.85);
}

.hub-notif-line--alert {
  border-left-color: rgba(251, 191, 36, 0.9);
  background: rgba(251, 191, 36, 0.06);
}

.hub-notif-line--major {
  border-left-color: rgba(248, 113, 113, 0.85);
  font-weight: 600;
}

.decision-block--critical {
