  max-width: 520px;
}

.hub-radial-center {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 46%;
  height: 46%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: default;
  border: 1px solid rgba(56, 189, 248, 0.25);
  background: radial-gradient(circle at 50% 30%, rgba(56, 189, 248, 0.18), rgba(12, 26, 65, 0.92));
  box-shadow:
    0 0 40px rgba(56, 189, 248, 0.22),
    inset 0 0 50px rgba(0, 0, 0, 0.5);
}

.hub-radial-center__ring {
  position: absolute;
