}

@keyframes hubCenterRing {
  to {
    transform: rotate(360deg);
  }
}

@keyframes hubCenterGlow {
  from {
    opacity: 0.55;
  }
  to {
    opacity: 1;
  }
}

.hub-station {
  position: absolute;
  left: 50%;
  top: 50%;
  width: clamp(100px, 26%, 142px);
  min-height: 76px;
  padding: 10px 8px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(14, 30, 76, 0.72);
  backdrop-filter: blur(10px);
