.hub-station__ring {
  position: absolute;
  inset: -3px;
  border-radius: 10px;
  border: 1px solid rgba(56, 189, 248, 0.12);
  opacity: 0;
  transition: opacity 0.25s ease;
  pointer-events: none;
}

.hub-station:hover .hub-station__ring {
