  letter-spacing: 0.14em;
  color: var(--g-silver-dim);
}

.hub-station--0 {
  transform: translate(-50%, -50%) rotate(0deg) translateY(-42%) rotate(0deg);
}

.hub-station--0:hover {
  transform: translate(-50%, -50%) rotate(0deg) translateY(calc(-42% - 8px)) rotate(0deg) scale(1.06);
}

.hub-station--1 {
  transform: translate(-50%, -50%) rotate(72deg) translateY(-42%) rotate(-72deg);
}

.hub-station--1:hover {
  transform: translate(-50%, -50%) rotate(72deg) translateY(calc(-42% - 8px)) rotate(-72deg) scale(1.06);
}

.hub-station--2 {
  transform: translate(-50%, -50%) rotate(144deg) translateY(-42%) rotate(-144deg);
}

.hub-station--2:hover {
  transform: translate(-50%, -50%) rotate(144deg) translateY(calc(-42% - 8px)) rotate(-144deg) scale(1.06);
}

.hub-station--3 {
  transform: translate(-50%, -50%) rotate(216deg) translateY(-42%) rotate(-216deg);
}

.hub-station--3:hover {
  transform: translate(-50%, -50%) rotate(216deg) translateY(calc(-42% - 8px)) rotate(-216deg) scale(1.06);
}

.hub-station--4 {
