  font-size: 0.6875rem;
  letter-spacing: 0.16em;
  color: var(--g-text);
}

.hub-office-rail__p {
  margin: 0 0 10px;
  font-size: 0.72rem;
  line-height: 1.4;
  color: var(--g-silver-dim);
}

.hub-office-tier-card {
  padding: 10px 12px;
  border-radius: 10px;
}

.hub-office-tier-card__label {
  display: block;
  font-size: 0.6875rem;
  letter-spacing: 0.16em;
  color: var(--g-silver-dim);
  margin-bottom: 2px;
}

.hub-office-tier-card__name {
  font-family: var(--g-font-head);
  font-size: 0.82rem;
  letter-spacing: 0.08em;
  color: var(--g-neon);
}

.hub-office-tier-card__now {
  margin-bottom: 8px;
}

.hub-office-tier-card__next {
  margin-bottom: 10px;
}

.hub-progress {
  margin-top: 4px;
}

.hub-progress--tight {
  margin-top: 10px;
}

.hub-progress__title {
  display: block;
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  color: var(--g-silver-dim);
  margin-bottom: 6px;
}

.hub-progress__track {
  height: 10px;
  border-radius: 1px;
  background:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.1) 0 1px, transparent 1px 25%),
    rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.hub-progress__fill {
  height: 100%;
  border-radius: 0;
  background: var(--g-neon);
  box-shadow: none;
  transition: opacity 0.2s ease;
}

.hub-progress__fill--gold {
  background: linear-gradient(90deg, var(--g-orange-dim), var(--g-orange));
  box-shadow: 0 0 12px rgba(224, 112, 32, 0.35);
}

.hub-progress__cap {
  display: block;
  margin-top: 6px;
  font-size: 0.6875rem;
  color: var(--g-silver-dim);
  letter-spacing: 0.06em;
}

.hub-tier-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.hub-tier-preview {
  flex: 1 1 calc(33% - 8px);
  min-width: 72px;
  padding: 8px 6px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.25);
  text-align: center;
}

.hub-tier-preview.is-current {
  border-color: rgba(224, 112, 32, 0.45);
  box-shadow: 0 0 14px rgba(224, 112, 32, 0.15);
}

.hub-tier-preview__viz {
  height: 36px;
  margin-bottom: 6px;
  border-radius: 6px;
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.25), rgba(12, 26, 65, 0.9));
}

.hub-tier-preview__viz--1 {
  height: 40px;
}

.hub-tier-preview__viz--2 {
  height: 44px;
}

.hub-tier-preview__viz--3 {
  height: 48px;
  background: linear-gradient(180deg, rgba(224, 112, 32, 0.28), rgba(12, 26, 65, 0.92));
}

.hub-tier-preview__viz--4 {
  height: 52px;
}

.hub-tier-preview__viz--5 {
  height: 56px;
  background: linear-gradient(180deg, rgba(224, 112, 32, 0.35), rgba(12, 26, 65, 0.92));
}

.hub-tier-preview__lbl {
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  color: var(--g-silver);
}

.hub-office-cat-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hub-office-cat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.6875rem;
  color: var(--g-silver-dim);
  letter-spacing: 0.06em;
}

.hub-reward-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.hub-reward-tile {
  padding: 8px 10px;
  border-radius: 8px;
  text-align: center;
}

.hub-reward-tile__k {
  display: block;
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  color: var(--g-silver-dim);
}

.hub-reward-tile__v {
  font-family: var(--g-font-head);
  font-size: 1.1rem;
  color: var(--g-neon);
}

.hub-perk-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hub-perk-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.hub-perk-row__tier {
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  color: var(--g-orange);
}

.hub-perk-row__txt {
  font-size: 0.6875rem;
  color: var(--g-silver-dim);
  line-height: 1.35;
}

.office-screen .hub-workspace {
  gap: 10px;
}

.office-screen__header {
  flex-shrink: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--g-space-2);
  padding: var(--g-space-2) var(--g-space-3);
  border-radius: 12px;
}

.office-screen__kicker {
  display: block;
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.28em;
  color: var(--g-neon);
  margin-bottom: 4px;
}

.office-screen__title {
  margin: 0 0 6px;
  font-family: var(--g-font-head);
  font-size: clamp(1.05rem, 2vw, 1.45rem);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--g-text);
}

.office-screen__sub {
  margin: 0;
  max-width: 52ch;
  font-size: 0.78rem;
  line-height: 1.45;
  color: var(--g-silver-dim);
}

.office-screen__chips {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: flex-end;
}

.office-screen__body {
  flex: 1;
  min-height: 0;
  padding: var(--g-space-2);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  gap: var(--g-space-2);
  overflow: hidden;
}

.office-screen__grid {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--g-space-2);
  align-content: start;
}

.office-screen__panel {
  padding: var(--g-space-2);
  border-radius: 10px;
}

.office-screen__panel--wide {
  grid-column: 1 / -1;
}

@media (max-width: 1100px) {
  .hub-takeover-header__top {
    grid-template-columns: 1fr;
  }

  .hub-takeover-body {
    flex-direction: column;
    overflow-y: auto;
  }

  .hub-office-rail {
    width: 100%;
    max-height: none;
  }

  .hub-radial-grid {
    max-height: 50vh;
  }

  .office-screen__chips {
    align-items: flex-start;
    flex-direction: row;
    flex-wrap: wrap;
  }
}

.game-btn {
  font-family: var(--g-font-head);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  padding: 10px 18px;
  background: linear-gradient(180deg, var(--g-panel-hi) 0%, rgba(26, 36, 61, 0.9) 100%);
  border: 2px solid #5a657e;
  color: var(--g-silver);
  cursor: pointer;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  min-width: 0;
  max-width: 100%;
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.2;
}

.game-btn--primary {
  background: linear-gradient(180deg, var(--g-orange) 0%, var(--g-orange-dim) 100%);
  color: #171d38;
  border-color: #ffd4a8;
}

.game-btn--secondary {
  background: linear-gradient(180deg, rgba(42, 53, 85, 0.95) 0%, rgba(26, 36, 61, 0.85) 100%);
  color: var(--g-silver);
  border-color: rgba(90, 101, 126, 0.85);
}

.game-btn--advance:not(:disabled) {
  animation: hubAdvancePulse 2.8s ease-in-out infinite;
}

.game-btn--sm {
  padding: 6px 10px;
  font-size: 0.6875rem;
}

@media (max-width: 980px) {
  .game-btn {
    letter-spacing: 0.08em;
    padding: 8px 12px;
  }

  .game-btn--sm {
    letter-spacing: 0.06em;
    padding: 6px 9px;
  }

  .hub-office-rail {
    width: min(320px, 42vw);
  }
}

.hub-decisions__title {
  font-family: var(--g-font-head);
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  color: var(--g-orange);
  margin-bottom: 8px;
}

.hub-decisions__note {
  margin: 0 0 10px;
  font-size: 0.75rem;
  color: var(--g-orange);
  letter-spacing: 0.04em;
}

.decision-block {
  border: 1px solid rgba(58, 70, 94, 0.85);
  padding: 10px;
  margin-bottom: 8px;
  background: rgba(0, 0, 0, 0.22);
  border-radius: 8px;
}

.decision-block__t {
  font-weight: 700;
  margin-bottom: 4px;
}

.decision-block__d {
  font-size: 0.8rem;
  color: var(--g-silver-dim);
  margin-bottom: 8px;
}

.decision-block__opts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

/* ----- Roster ----- */
.roster-screen .roster-toolbar {
  flex-shrink: 0;
  width: 100%;
  margin: 0 var(--g-space-2) var(--g-space-1);
  padding: var(--g-space-2) var(--g-space-3);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.roster-toolbar__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.roster-toolbar__row--split {
  justify-content: space-between;
}

.roster-toolbar__label {
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.18em;
  color: var(--g-silver-dim);
  margin-right: 6px;
}

.roster-toolbar__select {
  min-width: 200px;
  max-width: min(520px, 100%);
  flex: 1;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(0, 0, 0, 0.35);
  color: var(--g-text);
  font-family: var(--g-font-body);
  font-size: 0.8rem;
}

.roster-toolbar__counts {
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  color: var(--g-silver-dim);
  line-height: 1.4;
}

.roster-screen .roster-layout {
  flex: 1;
  min-height: 0;
  width: 100%;
  padding: 0 var(--g-space-2) var(--g-space-1);
  display: flex;
  gap: var(--g-space-2);
  overflow: hidden;
}

.roster-screen .roster-layout--has-ratings .roster-table-wrap {
  flex: 1;
  min-width: 0;
}

.roster-ratings-panel {
  width: min(280px, 30vw);
  flex-shrink: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: var(--g-space-2);
  overflow: hidden;
}

.roster-ratings-panel__head {
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.2em;
  color: var(--g-orange);
  margin-bottom: 10px;
  flex-shrink: 0;
}

.roster-ratings-panel__scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 4px;
}

.roster-ratings-group {
  margin-bottom: 14px;
}

.roster-ratings-group__title {
  margin: 0 0 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid rgba(255, 140, 66, 0.35);
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  color: var(--g-silver);
}

.roster-ratings-group__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.roster-ratings-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  padding: 3px 0;
  font-size: 0.6875rem;
  border-bottom: 1px solid rgba(58, 70, 94, 0.35);
}

.roster-ratings-row__label {
  color: var(--g-silver-dim);
  line-height: 1.25;
  min-width: 0;
}

.roster-ratings-row__v {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  color: var(--g-neon);
  flex-shrink: 0;
}

/* ----- Draft class board (EA-style scout vs true) ----- */
.draft-board-header,
.draft-board-row {
  display: grid;
  grid-template-columns: 0.35fr 0.42fr 1.35fr 0.35fr 0.32fr 0.55fr 0.38fr 0.42fr 0.52fr;
  gap: 4px;
  padding: 6px 8px;
  align-items: center;
  font-size: 0.6875rem;
}

.draft-board-header {
  font-family: var(--g-font-head);
  letter-spacing: 0.08em;
  color: var(--g-silver-dim);
  background: #121a2e;
  border-bottom: 2px solid var(--g-orange);
}

.draft-board-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 2px 0;
}

.draft-board-row {
  border-bottom: 1px solid rgba(58, 70, 94, 0.45);
  color: var(--g-silver);
}

.draft-board-row.is-selected {
  background: rgba(224, 112, 32, 0.22);
  color: var(--g-text);
  box-shadow: inset 0 0 0 1px var(--g-orange);
}

.draft-board-row .d-name {
  text-align: left;
  font-weight: 600;
}

.draft-board-row .d-rnk,
.draft-board-row .d-age,
.draft-board-row .d-ovr,
.draft-board-row .d-scout {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.draft-board-row .d-scout {
  color: var(--g-neon);
  font-weight: 700;
}

.draft-board-row .d-ovr {
  color: var(--g-silver);
}

.draft-board-row .d-tier {
  font-family: var(--g-font-head);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  color: var(--g-orange);
}

.draft-trend-flag--up {
  color: #4ade80;
}

.draft-trend-flag--down {
  color: #f87171;
}

.draft-trend-flag--new {
  color: var(--g-neon);
}

.draft-trend-flag--same {
  color: var(--g-silver-dim);
}

.roster-spotlight {
  width: min(280px, 32vw);
  flex-shrink: 0;
  padding: var(--g-space-2);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.roster-portrait {
  width: 180px;
  height: 200px;
  max-width: 100%;
  background: linear-gradient(180deg, #2a3350 0%, #151a2e 100%);
  border: 3px solid var(--g-silver-dim);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
}

.roster-portrait__silhouette {
  width: 80px;
  height: 120px;
  background: #0f204c;
  border-radius: 12px 12px 12px 12px;
  opacity: 0.7;
}

.roster-spotlight__name {
  font-family: var(--g-font-head);
  font-size: 1.15rem;
  letter-spacing: 0.06em;
  text-align: center;
  margin-bottom: 14px;
  color: var(--g-text);
}

.roster-meta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 12px;
  width: 100%;
  font-size: 0.78rem;
}

.roster-meta-grid span:nth-child(odd) {
  color: var(--g-silver-dim);
  font-family: var(--g-font-head);
  letter-spacing: 0.08em;
}

.roster-table-wrap {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
}

.roster-table-header,
.roster-row {
  display: grid;
  grid-template-columns: 2fr 0.55fr 0.45fr 0.45fr 0.55fr 0.45fr 0.55fr 0.55fr;
  gap: 4px;
  padding: 6px 12px;
  align-items: center;
  font-size: 0.72rem;
}

.roster-table-header {
  font-family: var(--g-font-head);
  letter-spacing: 0.1em;
  color: var(--g-silver-dim);
  background: #121a2e;
  border-bottom: 2px solid var(--g-orange);
}

.roster-table-header .col-name {
  text-align: left;
}

.col-num,
.col-j,
.col-age,
.col-pos,
.col-cpt,
.col-st,
.col-off {
  text-align: right;
}

.col-name {
  text-align: left;
}

.roster-table-body {
  flex: 1;
  overflow-y: auto;
  padding: 4px 0;
}

.roster-row {
  cursor: default;
  border-bottom: 1px solid rgba(58, 70, 94, 0.45);
  color: var(--g-silver);
}

.roster-row.is-selected {
  position: relative;
  background: rgba(224, 112, 32, 0.22);
  color: var(--g-text);
  box-shadow: inset 0 0 0 1px var(--g-orange);
}

/* ----- Settings ----- */
.settings-screen .settings-list {
  flex: 1;
  min-height: 0;
  width: 100%;
  margin: 0 var(--g-space-2) var(--g-space-1);
  padding: var(--g-space-2) var(--g-space-3);
  overflow-y: auto;
}

.settings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  margin-bottom: 8px;
  border-radius: 6px;
}

.settings-row.is-selected {
  background: rgba(224, 112, 32, 0.16);
  outline: 2px solid var(--g-neon);
}

.settings-row__label {
  font-family: var(--g-font-head);
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  flex: 0 0 160px;
}

.settings-slider {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
}

.settings-slider__track {
  flex: 1;
  height: 14px;
  background: #0f204c;
  border: 2px inset #3a465e;
  border-radius: 3px;
}

.settings-slider__fill {
  height: 100%;
  background: linear-gradient(90deg, var(--g-orange-dim), var(--g-orange));
  border-radius: 1px;
}

.settings-slider__val {
  width: 36px;
  text-align: right;
  font-weight: 700;
  color: var(--g-orange);
  font-size: 0.85rem;
}

.settings-note {
  margin-top: 20px;
  font-size: 0.72rem;
  color: var(--g-silver-dim);
}

.roster-row.ui-interactive:hover {
  transform: none;
  filter: brightness(1.08);
}

.settings-row.ui-interactive {
  cursor: default;
}

/* ---- Stats Central ---- */
.stats-central-screen {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1;
  color: var(--g-silver);
}

.stats-central-toolbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 20px 6px;
}

.stats-central-toolbar__hint {
  font-size: 0.72rem;
  color: var(--g-silver-dim);
  letter-spacing: 0.04em;
}

.stats-central-grid {
  display: grid;
  grid-template-columns: minmax(200px, 1fr) minmax(320px, 1.4fr) minmax(240px, 1fr);
  grid-template-rows: auto auto;
  gap: 12px;
  padding: 8px 20px 16px;
  flex: 1;
  min-height: 0;
  overflow: auto;
}

.stats-panel {
  border-radius: 8px;
  padding: 12px 14px;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.stats-panel--wide {
  grid-row: span 2;
}

.stats-panel--full {
  grid-column: 1 / -1;
}

.stats-panel__title {
  margin: 0 0 4px;
  font-family: var(--g-font-head);
  font-size: 0.82rem;
  letter-spacing: 0.12em;
  color: var(--g-orange);
}

.stats-panel__sub {
  margin: 0 0 10px;
  font-size: 0.6875rem;
  color: var(--g-silver-dim);
  line-height: 1.35;
}

.stats-cal-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow: auto;
  max-height: 52vh;
}

.stats-cal-pill {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(14, 30, 74, 0.55);
  color: var(--g-silver);
  font-size: 0.78rem;
  text-align: left;
  cursor: pointer;
}

.stats-cal-pill.is-active {
  border-color: var(--g-orange-dim);
  box-shadow: 0 0 0 1px rgba(255, 140, 60, 0.25);
}

.stats-cal-pill__n {
  font-size: 0.6875rem;
  opacity: 0.75;
  margin-left: 8px;
}

.stats-score-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: auto;
  max-height: 58vh;
  padding-right: 4px;
}

.stats-score-card {
  background: rgba(13, 29, 70, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 6px;
  padding: 8px 10px;
}

.stats-score-card__line {
  display: grid;
  grid-template-columns: 1fr auto auto auto 1fr;
  align-items: center;
  gap: 8px;
  font-size: 0.78rem;
}

.stats-score-card__team {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
