}

.stats-table-wrap {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1;
  overflow: hidden;
}

.stats-table-header,
.stats-table-row {
  display: grid;
  grid-template-columns: 28px 1fr 34px 36px 32px 28px 28px 32px;
  gap: 6px;
  align-items: center;
  font-size: 0.6875rem;
  padding: 4px 6px;
}

.stats-table-header {
  font-family: var(--g-font-head);
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.45);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.stats-table-header--wide {
  grid-template-columns: 1fr 40px 32px 28px 28px 32px 36px 36px;
}

.stats-table-body {
  overflow: auto;
  max-height: 36vh;
}

.stats-table-row--wide {
  grid-template-columns: 1fr 40px 32px 28px 28px 32px 36px 36px;
}

.stats-table-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.stats-table-abbr {
  font-size: 0.6875rem;
  opacity: 0.8;
}

.stats-table-pts {
