/* ----- NHL franchise calendar (grid) + hub date strip ----- */

.calendar-screen.cal-fr {
  flex: 1;
  min-height: 0;
  padding: var(--g-space-2) var(--g-space-3);
  display: flex;
  flex-direction: column;
  gap: var(--g-space-2);
  overflow: hidden;
}

.cal-fr-nav {
  display: grid;
  grid-template-columns: minmax(160px, 1fr) auto minmax(200px, 1fr);
  align-items: center;
  gap: var(--g-space-2);
  padding: 10px 14px;
  border-radius: 12px;
}

.cal-fr-nav__team-label {
  display: block;
  font-size: 0.6875rem;
  letter-spacing: 0.2em;
  color: var(--g-silver-dim);
}

.cal-fr-nav__team-name {
  font-family: var(--g-font-head);
  font-size: 0.85rem;
  letter-spacing: 0.08em;
}

.cal-fr-nav__month {
  text-align: center;
  font-family: var(--g-font-head);
  font-size: 1rem;
  letter-spacing: 0.14em;
  color: var(--g-text);
  text-shadow: 0 0 18px rgba(56, 189, 248, 0.2);
}

.cal-fr-nav__ctl {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.cal-fr-body {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  gap: var(--g-space-2);
  overflow: hidden;
}

.cal-fr-main {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border-radius: 12px;
  min-height: 0;
}

.cal-fr-sub {
  font-size: 0.6875rem;
  letter-spacing: 0.12em;
  color: var(--g-silver-dim);
}

.cal-fr-cursor {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px 10px;
  padding: 6px 8px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.cal-fr-cursor__k {
  font-size: 0.6875rem;
  letter-spacing: 0.18em;
  color: var(--g-silver-dim);
  text-transform: uppercase;
}

.cal-fr-cursor__v {
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  color: var(--g-silver-bright, #e8ecf0);
  font-weight: 600;
}

.cal-fr-pending {
  flex: 1 1 100%;
  margin: 0;
  font-size: 0.6875rem;
  line-height: 1.35;
  color: #f0c674;
  letter-spacing: 0.04em;
}

.cal-fr-panel__kicker-hint {
  font-weight: 400;
  letter-spacing: 0.06em;
  color: var(--g-silver-dim);
}

.cal-fr-dow {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
}

.cal-fr-dow__cell {
  text-align: center;
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  color: var(--g-silver-dim);
  padding: 4px 0;
}

.cal-fr-grid {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  grid-auto-rows: minmax(92px, auto);
  gap: 4px;
  padding: 2px 2px 6px;
}

.cal-fr-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 4px;
}

.cal-fr-aside {
  display: flex;
  flex-direction: column;
  gap: var(--g-space-2);
  min-height: 0;
}

.cal-fr-mini {
  padding: 10px;
  border-radius: 10px;
  flex-shrink: 0;
}

.cal-fr-mini__title {
  font-size: 0.6875rem;
  letter-spacing: 0.16em;
  color: var(--g-silver-dim);
  margin-bottom: 8px;
}

.cal-fr-mini__grid {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.cal-fr-mini__row {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 3px;
  justify-items: center;
}

.cal-fr-mini__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(71, 85, 105, 0.55);
}

.cal-fr-mini__dot--pad {
