}

.cal-fr-mini__dot.has-game {
  background: rgba(59, 130, 246, 0.75);
  box-shadow: 0 0 6px rgba(59, 130, 246, 0.45);
}

.cal-fr-mini__dot.is-today {
  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.9);
}

.cal-fr-mini__dot.evt-deadline {
  background: rgba(239, 68, 68, 0.9);
}
.cal-fr-mini__dot.evt-allstar {
  background: rgba(234, 179, 8, 0.95);
}
.cal-fr-mini__dot.evt-olympics {
  background: rgba(147, 51, 234, 0.9);
}
.cal-fr-mini__dot.evt-draft {
  background: rgba(168, 85, 247, 0.85);
}
.cal-fr-mini__dot.evt-playoffs {
  background: rgba(147, 51, 234, 0.75);
}
.cal-fr-mini__dot.evt-pause {
  background: rgba(148, 163, 184, 0.5);
}
.cal-fr-mini__dot.evt-intl {
  background: rgba(14, 165, 233, 0.8);
}

.cal-fr-mini__dot.evt-heritage {
  background: rgba(220, 38, 38, 0.95);
  box-shadow: 0 0 8px rgba(248, 113, 113, 0.55);
}

.cal-fr-mini__dot.evt-winter {
  background: rgba(56, 189, 248, 0.95);
  box-shadow: 0 0 8px rgba(125, 211, 252, 0.55);
}

.cal-fr-mini__dot.evt-four_nations {
  background: rgba(234, 179, 8, 0.95);
  box-shadow: 0 0 8px rgba(253, 224, 71, 0.45);
}

.cal-fr-mini__legend {
  margin: 8px 0 0;
  font-size: 0.6875rem;
  color: var(--g-silver-dim);
  line-height: 1.35;
}

.cal-fr-panel {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 12px;
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.cal-fr-panel__kicker {
  font-size: 0.6875rem;
  letter-spacing: 0.18em;
  color: var(--g-silver-dim);
}

.cal-fr-panel__date {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.06em;
}

.cal-fr-panel__phase {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--g-neon);
}

.cal-fr-panel__note {
  margin: 0;
  font-size: 0.6875rem;
  color: var(--g-silver);
  line-height: 1.4;
}

.cal-fr-panel__section {
  padding-top: 8px;
  border-top: 1px solid rgba(148, 163, 184, 0.15);
}

.cal-fr-panel__section--alert {
  border-color: rgba(239, 68, 68, 0.35);
  background: linear-gradient(90deg, rgba(239, 68, 68, 0.08), transparent);
  border-radius: 8px;
  padding: 8px;
}

.cal-fr-panel__section--gold {
  border-color: rgba(234, 179, 8, 0.35);
  background: linear-gradient(90deg, rgba(234, 179, 8, 0.1), transparent);
  border-radius: 8px;
  padding: 8px;
}

.cal-fr-panel__section--rival {
  border-color: rgba(251, 191, 36, 0.35);
  box-shadow: inset 0 0 0 1px rgba(251, 191, 36, 0.1);
  border-radius: 8px;
  padding-left: 4px;
  padding-right: 4px;
}

.cal-fr-panel__h {
  margin: 0 0 6px;
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  color: var(--g-silver-dim);
}

.cal-fr-panel__match {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.cal-fr-panel__vs {
  font-weight: 800;
  font-size: 0.85rem;
  color: var(--g-orange);
}

.cal-fr-panel__rec {
  text-align: center;
  font-size: 0.6875rem;
  color: var(--g-silver-dim);
}

.cal-fr-panel__score {
  text-align: center;
  font-size: 0.78rem;
  font-weight: 700;
  margin-top: 4px;
}

.cal-fr-panel__idle {
  margin: 0;
  font-size: 0.6875rem;
  color: var(--g-silver-dim);
}

.cal-fr-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.cal-fr-panel__li {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.6875rem;
}

.cal-fr-panel__li--rival {
  border-radius: 6px;
  padding: 2px 4px;
  box-shadow: 0 0 0 1px rgba(251, 191, 36, 0.28);
  background: rgba(251, 191, 36, 0.04);
}

.cal-fr-panel__ab {
  font-weight: 700;
  letter-spacing: 0.06em;
}

.cal-fr-panel__at {
  opacity: 0.6;
  font-size: 0.6875rem;
}

.cal-fr-panel__scr {
  margin-left: auto;
  color: var(--g-silver);
}

.cal-fr-panel__scrOt {
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: rgba(251, 191, 36, 0.9);
}

.cal-fr-panel__alert {
  margin: 0;
  font-size: 0.6875rem;
  line-height: 1.35;
}

.cal-fr-panel__rank {
  margin: 0 0 8px;
  font-size: 0.6875rem;
}

.cal-fr-stand {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cal-fr-stand li {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 8px;
  font-size: 0.6875rem;
  padding: 4px 6px;
  border-radius: 6px;
}

.cal-fr-stand li.is-user {
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.35);
}

.cal-fr-stand__n {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cal-fr-stand__r {
  opacity: 0.85;
}

.cal-fr-stand__p {
  font-weight: 700;
  color: var(--g-orange);
}

/* Day cells — NHL schedule tile */
.cal-cell {
  position: relative;
  border: 1px solid rgba(71, 85, 105, 0.4);
  border-radius: 8px;
  padding: 2px 3px 3px;
  background: linear-gradient(165deg, rgba(18, 38, 92, 0.58), rgba(30, 41, 59, 0.38));
  color: var(--g-text);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  min-height: 96px;
  cursor: pointer;
  transition:
    border-color 0.15s,
    box-shadow 0.15s,
    transform 0.12s;
}

.cal-cell:not(.cal-cell--game):not(.cal-cell--mega):not(.cal-cell--evt-heritage):not(.cal-cell--evt-winter):not(.cal-cell--evt-four_nations) {
  background: linear-gradient(165deg, rgba(15, 34, 83, 0.7), rgba(17, 26, 45, 0.52));
}

.cal-cell:hover:not(.cal-cell--pad) {
  transform: translateY(-1px);
  border-color: rgba(148, 163, 184, 0.45);
}

.cal-cell--pad {
  cursor: default;
  opacity: 0.22;
  background: transparent;
  border-color: transparent;
  min-height: 92px;
}

.cal-cell--past:not(.cal-cell--pad) {
  opacity: 0.72;
}

.cal-cell--today {
  border-color: rgba(56, 189, 248, 0.85);
  box-shadow:
    0 0 0 2px rgba(56, 189, 248, 0.25),
    0 0 20px rgba(56, 189, 248, 0.18);
}

.cal-cell--game {
  border-color: rgba(59, 130, 246, 0.55);
  box-shadow: inset 0 0 0 1px rgba(59, 130, 246, 0.12);
}

.cal-cell--pause {
  opacity: 0.55;
  border-style: dashed;
}

.cal-cell.is-selected {
  outline: 2px solid rgba(249, 115, 22, 0.95);
  outline-offset: 1px;
  box-shadow:
    0 0 0 2px rgba(249, 115, 22, 0.2),
    0 0 24px rgba(249, 115, 22, 0.2);
}

.cal-cell--evt-deadline {
  border-color: rgba(239, 68, 68, 0.65);
  box-shadow: 0 0 14px rgba(239, 68, 68, 0.12);
}
.cal-cell--evt-allstar {
  border-color: rgba(234, 179, 8, 0.65);
  box-shadow: 0 0 14px rgba(234, 179, 8, 0.12);
}
.cal-cell--evt-olympics {
  border-color: rgba(147, 51, 234, 0.65);
}
.cal-cell--evt-draft,
.cal-cell--evt-playoffs {
  border-color: rgba(168, 85, 247, 0.55);
}
.cal-cell--evt-pause {
  border-color: rgba(148, 163, 184, 0.45);
}
.cal-cell--evt-intl {
  border-color: rgba(14, 165, 233, 0.5);
}

.cal-cell--evt-heritage {
  border-color: rgba(220, 38, 38, 0.7);
  box-shadow: 0 0 16px rgba(220, 38, 38, 0.14);
}

.cal-cell--evt-winter {
  border-color: rgba(56, 189, 248, 0.85);
  box-shadow: 0 0 20px rgba(56, 189, 248, 0.2);
}

.cal-cell--evt-four_nations {
  border-color: rgba(234, 179, 8, 0.8);
  box-shadow: 0 0 16px rgba(234, 179, 8, 0.16);
}

.cal-cell--mega {
  min-height: 104px;
}

.cal-cell--outdoor {
  border-color: rgba(251, 191, 36, 0.45);
  box-shadow:
    inset 0 0 0 1px rgba(251, 191, 36, 0.12),
    0 0 20px rgba(251, 146, 60, 0.12);
}

.cal-cell--rivalry {
  border-color: rgba(251, 191, 36, 0.55);
  box-shadow:
    0 0 0 1px rgba(251, 191, 36, 0.25),
    0 0 16px rgba(251, 146, 60, 0.18);
}

.cal-cell__mega {
  position: absolute;
  left: 2px;
  right: 2px;
  top: 16px;
  bottom: 18px;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  gap: 2px;
  pointer-events: none;
  z-index: 0;
  padding: 0 1px;
}

.cal-cell__megaTitle {
  text-align: center;
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(248, 250, 252, 0.92);
  line-height: 1.1;
}

.cal-cell__megaPair {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  flex: 1;
  min-height: 0;
}

.cal-cell__megaVs {
  font-size: 0.6875rem;
  font-weight: 900;
  color: #fb923c;
  flex-shrink: 0;
}

.cal-cell__mega4 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
  flex: 1;
  min-height: 0;
  align-content: center;
}

.cal-cell__megaNation {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 36px;
  font-size: 0.95rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  border-radius: 8px;
  background: rgba(18, 38, 92, 0.88);
  border: 1px solid rgba(251, 191, 36, 0.45);
  color: #fef3c7;
}

.cal-cell__num {
  font-size: 0.6875rem;
  font-weight: 800;
  color: rgba(148, 163, 184, 0.95);
  line-height: 1;
  min-width: 1.1em;
  text-align: right;
}

.cal-cell__match {
  display: flex;
  align-items: center;
  gap: 4px;
}

.cal-cell__ha {
  font-size: 0.6875rem;
  font-weight: 900;
  color: #fdba74;
  letter-spacing: 0.08em;
  line-height: 1;
}

.cal-cell__slate {
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  color: rgba(96, 165, 250, 0.9);
}

.cal-cell__res {
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--g-silver);
}

.cal-cell__stack {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 0 1px;
  position: relative;
  z-index: 2;
  margin-top: 10px;
}

.cal-cell--mega .cal-cell__stack {
  margin-top: 40px;
}

.cal-cell__footer {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 3px;
  justify-content: center;
  align-items: center;
  padding: 1px 2px 0;
  margin-top: auto;
  min-height: 14px;
  position: relative;
  z-index: 2;
}

.cal-cell__pin {
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 1px 4px;
  border-radius: 2px;
  line-height: 1.2;
  border: 1px solid rgba(71, 85, 105, 0.45);
  color: rgba(203, 213, 225, 0.85);
  background: rgba(18, 38, 92, 0.5);
}

.cal-cell__pin--rival {
  border-color: rgba(251, 191, 36, 0.45);
  color: #fde68a;
  box-shadow: 0 0 8px rgba(251, 191, 36, 0.15);
}

.cal-cell__pin--ha {
  border-color: rgba(249, 115, 22, 0.35);
  color: rgba(254, 215, 170, 0.95);
}

.cal-cell__pin--b2b {
  border-color: rgba(56, 189, 248, 0.35);
  color: #bae6fd;
}

.cal-cell__pin--off {
  border-color: rgba(148, 163, 184, 0.35);
  color: rgba(148, 163, 184, 0.9);
}

.cal-cell__pin--evt {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cal-cell__dayhit,
.cal-cell__pasthit,
.cal-cell__uphit,
.cal-cell__slatehit {
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  padding: 0;
  margin: 0;
  cursor: pointer;
  border-radius: 4px;
}

.cal-cell__uphit,
.cal-cell__slatehit {
  width: 100%;
  position: relative;
  z-index: 2;
}

.cal-cell__dayhit {
  position: absolute;
  top: 2px;
  right: 3px;
  z-index: 4;
  width: auto;
  min-width: 0;
  padding: 0;
  display: flex;
  justify-content: flex-end;
  align-items: flex-start;
}

.cal-cell__pasthit {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  width: 100%;
  padding: 2px 2px 3px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(148, 163, 184, 0.18);
  position: relative;
  z-index: 2;
  border-radius: 6px;
}

.cal-cell__pasthit:hover {
  border-color: rgba(251, 191, 36, 0.45);
}

.cal-cell--pastuser.cal-cell--past {
  opacity: 0.95;
}

.cal-cell__past-top {
  display: flex;
  align-items: center;
  gap: 4px;
}

.cal-cell__scoreLine {
  display: flex;
  flex-direction: row;
  align-items: baseline;
