/* --- Global franchise cinematic events (playoffs + offseason chain) --- */
.franchise-event-layer {
  position: fixed;
  inset: 0;
  z-index: var(--z-cinematic, 13000);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  pointer-events: auto;
}

.franchise-event-overlay {
  position: relative;
  flex: 1;
  min-height: 0;
  height: 100%;
  width: 100%;
  overflow: hidden;
}

.franchise-event-content {
  height: 100%;
  width: 100%;
  min-height: 0;
  transform-origin: center center;
  will-change: filter, opacity, transform;
}

.franchise-event-layer.is-entering .franchise-event-content,
.franchise-event-layer.is-swapping-in .franchise-event-content {
  animation: franchise-event-enter 560ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.franchise-event-layer.is-exiting .franchise-event-content,
.franchise-event-layer.is-swapping-out .franchise-event-content {
  animation: franchise-event-exit 480ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

.franchise-event-layer.is-phase-blur .franchise-event-content {
  filter: blur(14px) saturate(0.88);
  opacity: 0.72;
  transform: scale(1.015);
  transition:
    filter 420ms ease,
    opacity 420ms ease,
    transform 420ms ease;
}

.franchise-event-phase-blur {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: grid;
  place-items: center;
  pointer-events: auto;
}

.franchise-event-phase-blur__veil {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 42%, rgba(14, 35, 83, 0.18), rgba(12, 28, 67, 0.58)),
    linear-gradient(180deg, rgba(12, 28, 67, 0.24), rgba(12, 28, 67, 0.46));
  backdrop-filter: blur(18px) saturate(1.05);
  -webkit-backdrop-filter: blur(18px) saturate(1.05);
}

.franchise-event-phase-blur__label {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: 10px 18px;
  border-radius: 999px;
  border: 1px solid rgba(46, 230, 214, 0.28);
  background: rgba(13, 32, 74, 0.72);
  color: rgba(223, 252, 255, 0.92);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.35);
}

@keyframes franchise-event-enter {
  from {
    opacity: 0;
    filter: blur(22px) saturate(0.75);
    transform: scale(1.03);
  }
  to {
    opacity: 1;
    filter: blur(0) saturate(1);
    transform: scale(1);
  }
}

@keyframes franchise-event-exit {
  from {
    opacity: 1;
    filter: blur(0) saturate(1);
    transform: scale(1);
  }
  to {
    opacity: 0;
    filter: blur(20px) saturate(0.8);
    transform: scale(0.985);
  }
}

@media (prefers-reduced-motion: reduce) {
  .franchise-event-layer.is-entering .franchise-event-content,
  .franchise-event-layer.is-swapping-in .franchise-event-content,
  .franchise-event-layer.is-exiting .franchise-event-content,
  .franchise-event-layer.is-swapping-out .franchise-event-content {
    animation: none !important;
  }

  .franchise-event-layer.is-phase-blur .franchise-event-content {
    filter: none;
    opacity: 0.85;
    transform: none;
    transition: opacity 180ms ease;
  }
}

