}

.media-alert__section--impact {
  border-color: rgba(255, 96, 109, 0.18);
  background: rgba(255, 96, 109, 0.05);
}

.media-alert--positive .media-alert__section--impact {
  border-color: rgba(82, 223, 148, 0.2);
