}

.media-alert__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.media-alert__action {
  cursor: pointer;
  border: 1px solid rgba(156, 218, 236, 0.18);
  border-radius: 8px;
  padding: 8px 14px;
  background: rgba(255, 255, 255, 0.04);
