/* --- League Trade Wire popup --- */
.showcase-popup__panel--trade-wire {
  width: min(760px, 100%);
  max-height: min(92vh, 900px);
  overflow: auto;
  border-color: rgba(46, 230, 214, 0.35);
}

.trade-wire {
  padding: 12px 14px 10px;
  color: #e9f7fb;
}

.trade-wire__source-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 6px;
}

.trade-wire__source-icon {
  width: 28px;
  height: 28px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(46, 230, 214, 0.45);
  color: #2ee6d6;
  font-size: 0.85rem;
  font-weight: 900;
  flex-shrink: 0;
}

.trade-wire__source-copy {
  flex: 1;
  min-width: 0;
}

.trade-wire__source {
  margin: 0;
  font-size: 0.6875rem;
  font-weight: 1000;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #2ee6d6;
}

.trade-wire__date {
  font-size: 0.6875rem;
  color: #8096a8;
  letter-spacing: 0.04em;
}

.trade-wire__close {
  border: none;
  background: transparent;
  color: #8096a8;
  font-size: 1.2rem;
  line-height: 1;
  cursor: pointer;
  padding: 2px 6px;
}

.trade-wire__title {
  margin: 0 0 4px;
  font-size: 1.35rem;
  font-weight: 1000;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #fff;
}

.trade-wire__summary {
  margin: 0 0 10px;
  font-size: 0.78rem;
  line-height: 1.35;
  color: rgba(233, 247, 251, 0.9);
}

.trade-wire__exchange {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 8px;
  align-items: stretch;
  padding: 8px;
  border: 1px solid rgba(46, 230, 214, 0.28);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.22);
  margin-bottom: 8px;
}

.trade-wire__swap {
  align-self: center;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  color: #2ee6d6;
  border: 1px solid rgba(46, 230, 214, 0.4);
  font-weight: 900;
  font-size: 0.9rem;
  background: rgba(46, 230, 214, 0.08);
}

.trade-wire__side {
  min-width: 0;
}

.trade-wire__side-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.trade-wire__logo,
.trade-wire__logo-fallback {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  object-fit: contain;
  flex-shrink: 0;
}

.trade-wire__logo-fallback {
  display: grid;
  place-items: center;
  background: rgba(46, 230, 214, 0.12);
  border: 1px solid rgba(46, 230, 214, 0.28);
  font-size: 0.6875rem;
  font-weight: 1000;
  color: #2ee6d6;
}

.trade-wire__side-name {
  font-size: 0.78rem;
  font-weight: 1000;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1.1;
}

.trade-wire__side-receives {
  font-size: 0.6875rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  color: #2ee6d6;
}

.trade-wire__side-assets {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.trade-wire__player-card {
  padding: 7px 8px;
  border: 1px solid rgba(46, 230, 214, 0.22);
  border-radius: 8px;
  background: rgba(14, 35, 79, 0.72);
}

.trade-wire__player-top {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: flex-start;
}

.trade-wire__player-name {
  font-size: 0.82rem;
  font-weight: 1000;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  line-height: 1.15;
}

.trade-wire__player-role {
  margin-top: 2px;
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #2ee6d6;
}

.trade-wire__ovr {
  min-width: 38px;
  padding: 3px 5px;
  border: 1px solid rgba(46, 230, 214, 0.35);
  border-radius: 6px;
  text-align: center;
  background: rgba(46, 230, 214, 0.08);
}

.trade-wire__ovr span {
  display: block;
  font-size: 0.6875rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  color: #8096a8;
}

.trade-wire__ovr strong {
  display: block;
  font-size: 0.95rem;
  font-weight: 1000;
  line-height: 1.1;
}

.trade-wire__contract {
  margin-top: 4px;
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: #c5d3e3;
}

.trade-wire__stats-head {
  margin-top: 5px;
  margin-bottom: 3px;
  font-size: 0.6875rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  color: #8096a8;
}

.trade-wire__stats-row {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 2px;
}

.trade-wire__stat {
  text-align: center;
  padding: 2px 0;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.03);
}

.trade-wire__stat span {
  display: block;
  font-size: 0.6875rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  color: #8096a8;
}

.trade-wire__stat strong {
  display: block;
  font-size: 0.6875rem;
  font-weight: 1000;
  line-height: 1.15;
}

.trade-wire__picks {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.trade-wire__picks-label {
  font-size: 0.6875rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  color: #2ee6d6;
}

.trade-wire__pick-chip {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 5px 7px;
  border: 1px dashed rgba(46, 230, 214, 0.35);
  border-radius: 6px;
  background: rgba(46, 230, 214, 0.05);
}

.trade-wire__pick-label {
  font-size: 0.6875rem;
  font-weight: 900;
  letter-spacing: 0.03em;
}

.trade-wire__pick-val {
  font-size: 0.6875rem;
  font-weight: 800;
  color: #2ee6d6;
}

.trade-wire__empty {
  font-size: 0.6875rem;
  color: #8096a8;
  font-style: italic;
  padding: 8px 4px;
}

.trade-wire__value {
  padding: 8px 9px;
  border: 1px solid rgba(46, 230, 214, 0.22);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.18);
  margin-bottom: 8px;
}

.trade-wire__section-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.6875rem;
  font-weight: 1000;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #2ee6d6;
  margin-bottom: 6px;
}

.trade-wire__value-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 8px;
  align-items: center;
}

.trade-wire__value-end {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  font-weight: 1000;
}

.trade-wire__value-end.is-right {
  flex-direction: row;
}

.trade-wire__value-track {
  display: flex;
  height: 10px;
  border-radius: 1px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(46, 230, 214, 0.18);
}

.trade-wire__value-fill.is-left {
  background: linear-gradient(90deg, #0ea8b5, #2ee6d6);
}

.trade-wire__value-fill.is-right {
  background: linear-gradient(90deg, #2a6f9c, #4aa3d8);
}

.trade-wire__reason {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 8px;
  padding: 8px 9px;
  border: 1px solid rgba(46, 230, 214, 0.22);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.18);
  margin-bottom: 10px;
  min-height: 88px;
}

.trade-wire__reason-meta {
  border-right: 1px solid rgba(46, 230, 214, 0.14);
  padding-right: 8px;
}

.trade-wire__type-pill {
  display: inline-block;
  margin-top: 4px;
  padding: 3px 7px;
  border-radius: 2px;
  border: 1px solid rgba(46, 230, 214, 0.35);
  background: rgba(46, 230, 214, 0.1);
  color: #2ee6d6;
  font-size: 0.6875rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: capitalize;
}

.trade-wire__reason-body p {
  margin: 0;
  font-size: 0.78rem;
  line-height: 1.45;
  color: rgba(233, 247, 251, 0.9);
}

.trade-wire__foot {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.trade-wire__btn {
  cursor: pointer;
  border: 1px solid rgba(156, 218, 236, 0.22);
  border-radius: 8px;
  padding: 8px 12px;
  background: transparent;
  color: #c5d3e3;
  font-size: 0.6875rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.trade-wire__btn.is-primary {
  border: none;
  background: linear-gradient(180deg, #2ee6d6 0%, #0ea8b5 100%);
  color: #0c214d;
  margin-left: auto;
}

.trade-wire__btn:hover {
  filter: brightness(1.08);
}

@media (max-width: 700px) {
  .trade-wire__exchange {
    grid-template-columns: 1fr;
  }

  .trade-wire__swap {
    justify-self: center;
    transform: rotate(90deg);
  }

  .trade-wire__reason {
    grid-template-columns: 1fr;
  }

  .trade-wire__reason-meta {
    border-right: none;
    border-bottom: 1px solid rgba(46, 230, 214, 0.14);
    padding-right: 0;
    padding-bottom: 8px;
  }

  .trade-wire__stats-row {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}


/* QA polish densify */
.game-screen {
  animation: departmentEnter var(--motion-department, 380ms) var(--ease-out-expo, cubic-bezier(0.16, 1, 0.3, 1)) both;
}

.game-screen .register-ops,
.game-screen [data-register="ops"] {
  min-height: 0;
}

@media (max-height: 800px) {
  .game-header {
    min-height: 0;
  }
  .game-footer {
    height: 30px;
  }
  .hub-live-status {
    padding-top: 8px;
    padding-bottom: 8px;
  }
  .chemistry-screen {
    padding: 12px 14px 72px;
  }
  .office-hud-card {
    max-width: min(320px, calc(50vw - 20px));
    padding: 10px 12px;
  }
  .office-control-bar {
    bottom: 12px;
    gap: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .game-screen {
    animation: none !important;
  }
  .franchise-advancing-spinner {
    animation: none !important;
  }
  .franchise-event-layer.is-entering .franchise-event-content,
  .franchise-event-layer.is-swapping-in .franchise-event-content,
  .franchise-event-layer.is-exiting .franchise-event-content,
  .franchise-event-layer.is-swapping-out .franchise-event-content {
    animation: none !important;
  }
  .showcase-popup__panel--v2 {
    animation: none !important;
  }
}

/* --- Franchise advance overlay --- */
.franchise-advancing-overlay {
  position: fixed;
  inset: 0;
  z-index: 11500;
  display: grid;
  place-items: center;
  background: rgba(12, 28, 67, 0.52);
  backdrop-filter: blur(4px);
  pointer-events: all;
}

.franchise-advancing-card {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: min(360px, calc(100vw - 32px));
  padding: 16px 20px;
  border-radius: 12px;
  border: 1px solid rgba(46, 230, 214, 0.38);
  background:
    radial-gradient(circle at 0% 0%, rgba(46, 230, 214, 0.14), transparent 55%),
    linear-gradient(165deg, rgba(14, 40, 88, 0.98), rgba(13, 32, 74, 0.99));
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.45);
  color: #dffcff;
}

.franchise-advancing-spinner {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  border-radius: 50%;
  border: 2px solid rgba(46, 230, 214, 0.22);
  border-top-color: #2ee6d6;
  animation: franchise-advance-spin 0.85s linear infinite;
}

.franchise-advancing-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.franchise-advancing-copy strong {
  font-size: 0.78rem;
  font-weight: 1000;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.franchise-advancing-copy span {
  font-size: 0.72rem;
  color: #9eb4c8;
  letter-spacing: 0.04em;
}

.franchise-advancing-copy {
  flex: 1 1 auto;
  min-width: 0;
}

.franchise-advancing-bar {
  height: 4px;
  margin-top: 4px;
  border-radius: 2px;
  background: rgba(46, 230, 214, 0.16);
  overflow: hidden;
}

.franchise-advancing-bar__fill {
  height: 100%;
  background: #2ee6d6;
  transition: width 0.4s ease;
}

.franchise-advancing-stop {
  flex: 0 0 auto;
  padding: 8px 14px;
  border-radius: 8px;
  border: 1px solid rgba(255, 120, 110, 0.55);
  background: rgba(255, 90, 80, 0.12);
  color: #ffd9d4;
  font-size: 0.7rem;
  font-weight: 1000;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
}

.franchise-advancing-stop:hover:not(:disabled) {
  background: rgba(255, 90, 80, 0.24);
}

.franchise-advancing-stop:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

@keyframes franchise-advance-spin {
  to {
    transform: rotate(360deg);
  }
}

/* --- Showcase popup v2 polish --- */
.showcase-popup--v2 .showcase-popup__backdrop--v2 {
  background: rgba(11, 26, 65, 0.72);
  backdrop-filter: blur(6px);
}

.showcase-popup__panel--v2 {
  animation: showcase-popup-rise 0.28s cubic-bezier(0.16, 1, 0.3, 1) both;
  box-shadow:
    0 32px 100px rgba(0, 0, 0, 0.72),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

@keyframes showcase-popup-rise {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.media-alert--v2 {
  padding: 0;
}

.media-alert__topbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px 0;
}

.media-alert__kind-pill {
  padding: 3px 8px;
  border-radius: 999px;
  border: 1px solid rgba(46, 230, 214, 0.28);
  background: rgba(46, 230, 214, 0.1);
  font-size: 0.62rem;
  font-weight: 1000;
  letter-spacing: 0.14em;
  color: #2ee6d6;
}

.media-alert--danger .media-alert__kind-pill {
  border-color: rgba(255, 96, 109, 0.35);
  background: rgba(255, 96, 109, 0.12);
  color: #ff808a;
}

.media-alert__queue-pill {
  margin-left: auto;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #b8c9dc;
}

.media-alert__close {
  margin-left: auto;
  width: 28px;
  height: 28px;
  border: 1px solid rgba(156, 218, 236, 0.18);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.2);
  color: #e9f7fb;
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.media-alert__topbar:has(.media-alert__queue-pill) .media-alert__close {
  margin-left: 0;
}

.media-alert--v2 .media-alert__source-row {
  padding: 10px 18px 0;
  margin-bottom: 10px;
}

.media-alert--v2 .media-alert__hero {
  margin: 0 18px 12px;
  padding-bottom: 12px;
}

.media-alert__identity {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 18px 12px;
}

.media-alert__identity .player-headshot {
  width: 72px;
  height: 84px;
  flex-shrink: 0;
}

.media-alert__team-logo {
  width: 42px;
  height: 42px;
  object-fit: contain;
}

.media-alert__team-fallback {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 900;
  color: #9ad8ea;
  border: 1px solid rgba(154, 216, 234, 0.3);
  border-radius: 8px;
}

.media-alert__ratings {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.media-alert__ovr,
.media-alert__pot {
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.06em;
  color: #e8fbff;
  background: rgba(14, 42, 92, 0.85);
  border: 1px solid rgba(120, 210, 230, 0.35);
  border-radius: 6px;
  padding: 3px 8px;
}

.media-alert__body-scroll {
  max-height: min(42vh, 360px);
  overflow: auto;
  padding: 0 18px 8px;
}

.media-alert--v2 .media-alert__actions {
  padding: 0 18px 8px;
}

.media-alert--v2 .media-alert__foot {
  padding: 12px 18px 16px;
  border-top: 1px solid rgba(156, 218, 236, 0.1);
}

.media-alert__continue.is-primary {
  width: 100%;
  min-height: 40px;
  border: 0;
  border-radius: 8px;
  background: linear-gradient(180deg, #1de8f5, #2ee6d6);
  color: #0c214d;
  font-size: 0.72rem;
  font-weight: 1000;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
}

.media-alert__continue.is-primary:hover {
  filter: brightness(1.05);
}

/* ==========================================================================
   SECTION: styles/retro.css
   ========================================================================== */
/* NHL broadcast / franchise menu feel */
.app-shell {
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

.app-body {
  display: flex;
  flex: 1;
  min-height: 0;
}

.app-main {
  flex: 1;
  padding: 1.25rem 1.5rem;
  overflow: auto;
  background: linear-gradient(180deg, #0d1f4c 0%, #0c1d48 40%);
}

.page-title {
  font-family: var(--font-head);
  font-size: 1.35rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin: 0 0 0.35rem;
  color: var(--text);
}

.page-sub {
  color: var(--text-muted);
  margin: 0 0 1.25rem;
  font-size: 0.95rem;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.65rem 1.25rem;
  background: linear-gradient(90deg, #0f255a 0%, #0c1a30 50%, #0f255a 100%);
  border-bottom: 3px solid var(--accent);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.45);
}

.app-header__brand {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
}

.app-header__mark {
  font-family: var(--font-head);
  font-size: 1.5rem;
  color: var(--text);
  letter-spacing: 0.06em;
}

.app-header__title {
  font-family: var(--font-head);
  font-size: 1rem;
  color: var(--silver);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.app-header__tag {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.15em;
}

.app-sidebar {
  width: 220px;
  flex-shrink: 0;
  background: var(--bg-panel);
  border-right: 1px solid var(--border);
}

.app-sidebar__nav {
  display: flex;
  flex-direction: column;
  padding: 0.75rem 0;
}

.app-sidebar__link {
  padding: 0.55rem 1rem;
  font-size: 0.88rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  border-left: 3px solid transparent;
}

.app-sidebar__link:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}

.app-sidebar__link--active {
  background: var(--highlight);
  color: var(--text);
  border-left-color: var(--accent);
}

/* Shared UI — Broadcast Ops default; variants via data-register / modifiers */

.ui-panel {
  background: var(--ops-panel);
  color: var(--ops-text);
  border: 1px solid var(--ops-grid);
  border-radius: var(--radius-card);
  margin-bottom: var(--space-4);
  box-shadow: var(--depth-lifted);
  font-family: var(--font-ops-ui);
}

.ui-panel[data-register="office"],
.ui-panel--office {
  background: var(--office-desk);
  color: var(--office-text);
  border-color: var(--office-line);
  border-radius: var(--radius-hud);
  box-shadow: var(--depth-hud);
  font-family: var(--font-office-display);
}

.ui-panel[data-register="shell"],
.ui-panel--shell {
  background: var(--shell-structure);
  color: var(--shell-text);
  border-color: rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-control);
  box-shadow: var(--depth-shell-glass);
  font-family: var(--font-shell-body);
}

.ui-panel--flat {
  box-shadow: var(--depth-flat);
  border-radius: var(--radius-ops);
}

.ui-panel__head {
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--ops-grid);
  background: rgba(13, 37, 85, 0.55);
}

.ui-panel__scorebug {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 4px;
}

.ui-panel__title {
  margin: 0;
  font-family: var(--font-ops-ui);
  font-size: var(--type-ops-heading-size);
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ops-text);
}

.ui-panel__sub {
  margin: 0.25rem 0 0;
  font-size: var(--type-compact-size);
  color: var(--ops-text-secondary);
}

.ui-panel__body {
  padding: var(--space-4);
}

.ui-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 34px;
  font-family: var(--font-ops-ui);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 900;
  padding: 10px 16px;
  border: 1px solid var(--ops-grid);
  border-radius: var(--radius-hud);
  cursor: pointer;
  font-size: var(--type-control-label-size);
  transition:
    background var(--motion-micro),
    border-color var(--motion-micro),
    color var(--motion-micro),
    transform var(--motion-micro);
}

.ui-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.ui-btn[data-loading="true"] {
  cursor: progress;
  color: transparent;
}

/* Loading uses the ops segment rail, not a spinning icon. */
.ui-btn[data-loading="true"]::after {
  content: "";
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 6px;
  height: 2px;
  background: linear-gradient(90deg, transparent, currentColor, transparent);
  background-size: 200% 100%;
  color: var(--ops-cyan);
  animation: uiBtnLoad 1s linear infinite;
}

@keyframes uiBtnLoad {
  from { background-position: 120% 0; }
  to { background-position: -60% 0; }
}

.ui-btn:focus-visible {
  outline: 2px solid var(--ops-cyan);
  outline-offset: 2px;
}

/* Primary — commits an action. Rink Cut marks it as the deciding control. */
.ui-btn--primary {
  background: var(--ops-cyan);
  color: var(--ops-navy);
  border-color: transparent;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  border-radius: 0;
}

.ui-btn--primary:hover:not(:disabled) {
  background: var(--ops-ice);
}

.ui-btn--primary:active:not(:disabled) {
  transform: translateY(1px);
}

/* Broadcast — advances live league time or opens a live result. */
.ui-btn--broadcast {
  background: rgba(12, 33, 77, 0.9);
  color: var(--ops-gold);
  border-color: rgba(233, 168, 60, 0.42);
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  border-radius: 0;
  padding-left: 20px;
}

.ui-btn--broadcast::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--ops-gold);
}

.ui-btn--broadcast:hover:not(:disabled) {
  background: rgba(233, 168, 60, 0.12);
  color: #ffd88d;
}

.ui-btn--broadcast:active:not(:disabled) {
  transform: translateY(1px);
}

.ui-btn--secondary,
.ui-btn--ghost {
  background: rgba(12, 31, 47, 0.72);
  color: var(--ops-text);
  border-color: var(--ops-grid);
}

.ui-btn--secondary:hover:not(:disabled),
.ui-btn--ghost:hover:not(:disabled) {
  background: var(--ops-cyan-soft);
  border-color: var(--ops-grid-strong);
}

.ui-btn--shell {
  background: var(--shell-orange);
  color: var(--shell-text);
  border-color: rgba(255, 255, 255, 0.12);
  font-family: var(--font-shell-headline);
  letter-spacing: 0.06em;
}

.ui-btn--shell:hover:not(:disabled) {
  filter: brightness(1.08);
}

/* Destructive — irreversible club action. Signal red, squared, no cut. */
.ui-btn--legacy,
.ui-btn--danger,
.ui-btn--destructive {
  background: transparent;
  color: var(--ops-injury);
  border-color: rgba(255, 96, 109, 0.42);
  border-radius: var(--radius-ops);
}

.ui-btn--legacy:hover:not(:disabled),
.ui-btn--danger:hover:not(:disabled),
.ui-btn--destructive:hover:not(:disabled) {
  background: var(--ops-signal-red);
  border-color: var(--ops-signal-red);
  color: #fff;
}

.ui-btn--legacy:active:not(:disabled),
.ui-btn--danger:active:not(:disabled),
.ui-btn--destructive:active:not(:disabled) {
  transform: translateY(1px);
}

/* Executive — Office Sanctum. Brass hardware, physical rather than lit. */
.ui-btn--office,
.ui-btn--executive {
  background: linear-gradient(180deg, rgba(22, 37, 68, 0.92), rgba(17, 31, 63, 0.94));
  color: var(--office-text);
  border: 1px solid var(--office-line-strong);
  border-radius: var(--radius-hud);
  font-family: var(--font-office-display);
  letter-spacing: 0.1em;
  box-shadow: inset 0 1px 0 rgba(248, 213, 138, 0.14);
}

.ui-btn--office:hover:not(:disabled),
.ui-btn--executive:hover:not(:disabled) {
  background: var(--office-selection);
  border-color: var(--office-brass);
  color: var(--office-brass);
}

.ui-btn--office:active:not(:disabled),
.ui-btn--executive:active:not(:disabled) {
  transform: translateY(1px);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.4);
}

.ui-btn--office:focus-visible,
.ui-btn--executive:focus-visible {
  outline-color: var(--office-brass);
}

/* Icon-only — square hit area, never a floating bubble. */
.ui-btn--icon {
  min-width: 30px;
  min-height: 30px;
  padding: 0 6px;
  gap: 0;
  border-radius: var(--radius-ops);
  letter-spacing: 0;
}

.ui-table-wrap {
  overflow: auto;
  max-height: 55vh;
  border: 1px solid var(--ops-grid);
  border-radius: var(--radius-ops);
  background: rgba(12, 33, 77, 0.55);
  box-shadow: var(--depth-flat);
}

.ui-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--type-table-value-size);
  font-family: var(--font-ops-ui);
  font-variant-numeric: tabular-nums;
}

.ui-table th {
  text-align: left;
  padding: 8px 10px;
  background: rgba(13, 37, 85, 0.96);
  color: var(--ops-text-secondary);
  text-transform: uppercase;
  font-size: var(--type-table-meta-size);
  font-weight: 900;
  letter-spacing: 0.1em;
  border-bottom: 1px solid var(--ops-grid);
  position: sticky;
  top: 0;
  z-index: 1;
}

.ui-table td {
  padding: 7px 10px;
  border-bottom: 1px solid rgba(156, 218, 236, 0.08);
  color: var(--ops-text);
}

.ui-table__empty {
  color: var(--ops-text-secondary);
  font-style: normal;
  padding: 14px 10px;
}

.ui-table__row {
  transition: background var(--motion-micro);
}

.ui-table__row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.ui-table__row--sel {
  background: var(--ops-table-sel);
  box-shadow: inset 3px 0 0 var(--ops-cyan);
}

.ui-loader {
  margin: var(--space-4) 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  max-width: 360px;
}

.ui-loader__bar {
  height: 2px;
  width: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    var(--ops-cyan),
    transparent
  );
  background-size: 200% 100%;
  animation: ui-scan 1.1s linear infinite;
}

@keyframes ui-scan {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

.ui-loader__text {
  margin: 0;
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ops-text-secondary);
}

/* Tabs */
.ui-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
  border-bottom: 1px solid var(--ops-grid);
  margin-bottom: var(--space-3);
}

.ui-tab {
  position: relative;
  padding: 10px 14px;
  border: 0;
  background: transparent;
  color: var(--ops-text-secondary);
  font-family: var(--font-ops-ui);
  font-size: var(--type-control-label-size);
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color var(--motion-micro), background var(--motion-micro);
}

.ui-tab:hover {
  color: var(--ops-text);
  background: rgba(255, 255, 255, 0.03);
}

.ui-tab.is-active,
.ui-tab--active {
  color: var(--ops-cyan);
  background: linear-gradient(180deg, rgba(46, 230, 214, 0.1), transparent);
}

/* Active tab reads as a scorebug segment: full-width base rail, not a pill. */
.ui-tab.is-active::after,
.ui-tab--active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2px;
  background: var(--ops-cyan);
}

/* Modal / inspector overlays */
.ui-modal-scrim {
  position: fixed;
  inset: 0;
  z-index: var(--z-modal);
  background: var(--shell-scrim);
  display: grid;
  place-items: center;
  padding: var(--space-5);
}

.ui-modal {
  width: min(720px, 100%);
  max-height: min(86vh, 900px);
  overflow: auto;
  background: var(--ops-panel);
  border: 1px solid var(--ops-grid);
  border-radius: var(--radius-card);
  box-shadow: var(--depth-overlay);
  color: var(--ops-text);
}

.ui-modal--cinematic {
  z-index: var(--z-cinematic);
  box-shadow: var(--depth-cinematic);
  border-radius: var(--radius-panel);
}

.ui-inspector {
  border-left: 1px solid var(--ops-grid);
  background: var(--ops-panel-2);
  box-shadow: var(--depth-lifted);
  border-radius: var(--radius-card) 0 0 var(--radius-card);
}

.log-view {
  max-height: min(70vh, 720px);
  overflow: auto;
  margin: 0;
  padding: 0.75rem;
  background: #0e1e46;
  border: 1px solid var(--border);
  white-space: pre-wrap;
  word-break: break-word;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.form-grid label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.form-grid input,
.form-grid select {
  padding: 0.4rem 0.5rem;
  background: #0e1e46;
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 0.9rem;
}

.alert {
  padding: 0.65rem 0.85rem;
  border: 1px solid var(--border);
  font-size: 0.88rem;
  margin-bottom: 0.75rem;
}

.alert--err {
  border-color: var(--accent);
  background: var(--highlight);
  color: var(--text);
}

.alert--ok {
  border-color: var(--border-bright);
  color: var(--silver);
}

.home-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1rem;
}

.home-tile {
  display: block;
  padding: 1rem;
  background: var(--bg-panel);
  border: 1px solid var(--border);
  color: var(--text);
  transition: border-color 0.15s, background 0.15s;
}

.home-tile:hover {
  border-color: var(--accent);
  background: var(--bg-panel-alt);
}

.home-tile h3 {
  margin: 0 0 0.35rem;
  font-family: var(--font-head);
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.home-tile p {
  margin: 0;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.franchise-dashboard {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.franchise-topbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem 1rem;
  background: var(--bg-panel-alt);
  border: 1px solid var(--border);
  border-left: 4px solid var(--accent);
}

.franchise-topbar__team {
  font-family: var(--font-head);
  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.franchise-topbar__sub {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 0.15rem;
}

.franchise-topbar__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem;
}

.franchise-topbar__label {
  display: block;
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
}

.franchise-topbar__value {
  font-weight: 700;
  color: var(--silver);
}

.franchise-grid {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 1rem;
  align-items: start;
}

@media (max-width: 1100px) {
  .franchise-grid {
    grid-template-columns: 1fr;
  }
}

.decision-card {
  border: 1px solid var(--border);
  padding: 0.75rem 1rem;
  margin-bottom: 0.75rem;
  background: #0e1e46;
}

.decision-card__title {
  margin: 0 0 0.35rem;
  font-family: var(--font-head);
  font-size: 0.85rem;
  text-transform: uppercase;
}

.decision-card__desc {
  margin: 0 0 0.65rem;
  font-size: 0.88rem;
  color: var(--text-muted);
}

.decision-card__opts {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.note-list {
  margin: 0;
  padding-left: 1.1rem;
  font-size: 0.82rem;
  color: var(--silver);
  max-height: 200px;
  overflow: auto;
}

/* ==========================================================================
   SECTION: styles/nhlcalShell.css
   ========================================================================== */
/**
 * Shared NHL calendar shell — Broadcast Ops register
 * Authority: theme.css · DESIGN.md
 */

.nhlcal-root {
  --bg: var(--ops-navy);
  --bg-2: var(--ops-black);
  --panel: var(--ops-panel);
  --panel-2: var(--ops-panel-2);
  --panel-3: var(--ops-panel-3);
  --line: var(--ops-grid);
  --line-2: var(--ops-grid-2);
  --line-strong: var(--ops-grid-strong);
  --text: var(--ops-text);
  --muted: var(--ops-text-secondary);
  --muted-2: var(--ops-text-disabled);
  --cyan: var(--ops-cyan);
  --cyan-soft: var(--ops-cyan-soft);
  --gold: var(--ops-gold);
  --gold-soft: var(--ops-gold-soft);
  --green: var(--ops-success);
  --green-soft: var(--ops-success-soft);
  --red: var(--ops-injury);
  --red-soft: var(--ops-injury-soft);
  --blue: var(--ops-info);
  --blue-soft: var(--ops-info-soft);
  --purple: var(--ops-info, #8ab4ff);
  --shadow: var(--depth-overlay);

  min-height: 100dvh;
  height: 100dvh;
  width: 100%;
  background:
    radial-gradient(circle at 24% 0%, rgba(46, 230, 214, 0.08), transparent 30%),
    radial-gradient(circle at 92% 18%, rgba(233, 168, 60, 0.05), transparent 26%),
    linear-gradient(180deg, var(--ops-black) 0%, var(--ops-navy-deep) 100%);
  color: var(--text);
  display: grid;
  grid-template-columns: 94px minmax(0, 1fr);
  overflow: hidden;
  font-family: var(--font-ops-ui);
}

.nhlcal-root *,
.nhlcal-root *::before,
.nhlcal-root *::after {
  box-sizing: border-box;
}

.nhlcal-root button {
  font-family: inherit;
}

/* ─── Sidebar rail ─── */

.nhlcal-sidebar {
  min-height: 100dvh;
  height: 100dvh;
  background:
    linear-gradient(180deg, rgba(12, 33, 77, 0.98), rgba(12, 29, 69, 0.98));
  border-right: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  position: relative;
  z-index: var(--z-rail);
}

.nhlcal-brand-button {
  height: 112px;
  border: 0;
  background: transparent;
  color: var(--text);
  display: grid;
  place-items: center;
  border-bottom: 1px solid var(--line);
  cursor: pointer;
}

.nhlcal-shield-icon {
  width: 30px;
  height: 34px;
  border: 2px solid rgba(223, 245, 250, 0.42);
  display: grid;
  place-items: center;
  color: rgba(223, 245, 250, 0.68);
  clip-path: polygon(50% 0, 92% 16%, 92% 72%, 50% 100%, 8% 72%, 8% 16%);
  font-size: 15px;
  border-radius: var(--radius-ops);
}

.nhlcal-side-nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 16px 0;
}

.nhlcal-side-button {
  width: 100%;
  min-height: 66px;
  border: 0;
  background: transparent;
  color: var(--muted);
  display: grid;
  place-items: center;
  gap: 4px;
  cursor: pointer;
  position: relative;
  transition: color var(--motion-micro), background var(--motion-micro);
}

.nhlcal-side-button:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.03);
}

.nhlcal-side-button.is-active {
  color: var(--cyan);
  background: linear-gradient(90deg, rgba(46, 230, 214, 0.12), transparent 72%);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
}

.nhlcal-side-button.is-active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  border-radius: 0;
  background: var(--cyan);
}

.nhlcal-side-icon {
  font-size: 22px;
  line-height: 1;
}

.nhlcal-side-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ─── Main scroll owner ─── */

.nhlcal-main {
  min-width: 0;
  height: 100dvh;
  max-height: 100dvh;
  overflow: auto;
  overscroll-behavior: contain;
  padding: 20px 24px 24px;
  scrollbar-width: thin;
  scrollbar-color: rgba(110, 173, 191, 0.28) transparent;
}

.nhlcal-main::-webkit-scrollbar {
  width: 8px;
}

.nhlcal-main::-webkit-scrollbar-thumb {
  background: rgba(110, 173, 191, 0.28);
  border-radius: var(--radius-ops);
}

/* ─── Topbar ─── */

.nhlcal-topbar {
  min-height: 96px;
  display: grid;
  grid-template-columns: minmax(250px, 1fr) minmax(280px, 1.2fr) minmax(320px, 1fr);
  align-items: center;
  gap: 20px;
}

.nhlcal-team-identity {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
}

.nhlcal-team-logo {
  display: grid;
  place-items: center;
  border-radius: var(--radius-control);
  overflow: hidden;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--line);
}

.nhlcal-team-logo.size-large {
  width: 72px;
  height: 72px;
}

.nhlcal-team-logo.size-large img {
  width: 58px;
  height: 58px;
  object-fit: contain;
}

.nhlcal-team-logo.size-xlarge {
  width: 96px;
  height: 96px;
}

.nhlcal-team-logo.size-xlarge img {
  width: 80px;
  height: 80px;
  object-fit: contain;
}

.nhlcal-team-city {
  margin: 0 0 2px;
  color: rgba(233, 247, 251, 0.72);
  font-size: var(--type-dept-label-size);
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.nhlcal-team-identity h1 {
  margin: 0;
  font-family: var(--font-broadcast-display);
  font-size: clamp(26px, 2.6vw, 38px);
  line-height: 0.92;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text);
}

.nhlcal-month-control {
  text-align: center;
  min-width: 0;
}

.nhlcal-month-control p {
  margin: 0 0 6px;
  color: var(--cyan);
  text-transform: uppercase;
  letter-spacing: 0.32em;
  font-size: var(--type-phase-label-size);
  font-weight: 900;
}

.nhlcal-month-control h2 {
  margin: 0;
  font-family: var(--font-broadcast-display);
  font-size: clamp(26px, 2.4vw, 36px);
  line-height: 0.92;
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

.nhlcal-month-control .nhlcal-subtitle {
  margin-top: 6px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: none;
}

.nhlcal-action-cluster {
  justify-self: end;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  min-width: 0;
  flex-wrap: wrap;
}

.nhlcal-quick-link {
  border: 1px solid var(--line);
  border-radius: var(--radius-hud);
  background: rgba(12, 31, 47, 0.72);
  color: var(--text);
  padding: 8px 12px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color var(--motion-micro), background var(--motion-micro);
}

.nhlcal-quick-link:hover,
.nhlcal-quick-link.is-active {
  border-color: var(--line-strong);
  background: var(--cyan-soft);
  color: var(--cyan);
}

.nhlcal-date-chip {
  min-width: 158px;
  height: 54px;
  border-left: 1px solid var(--line);
  padding-left: 18px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.nhlcal-date-icon {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: var(--radius-control);
  background: var(--blue-soft);
  border: 1px solid rgba(138, 180, 255, 0.18);
  color: var(--blue);
}

.nhlcal-date-chip strong,
.nhlcal-date-chip span {
  display: block;
}

.nhlcal-date-chip strong {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.nhlcal-date-chip span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.nhlcal-advance-button {
  height: 54px;
  min-width: 190px;
  border: 0;
  border-radius: var(--radius-hud);
  background: linear-gradient(180deg, #f4bd52, #d99023);
  color: #182138;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 12px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: var(--depth-registered);
  transition: filter var(--motion-micro);
}

.nhlcal-advance-button:hover {
  filter: brightness(1.04);
}

.nhlcal-advance-button:disabled {
  cursor: not-allowed;
  opacity: 0.72;
}

.nhlcal-advance-button-secondary {
  min-width: 92px;
  background: rgba(14, 37, 86, 0.92);
  color: #dffcff;
  border: 1px solid rgba(46, 230, 214, 0.32);
  box-shadow: none;
}

.nhlcal-advance-button-secondary:hover:not(:disabled) {
  border-color: rgba(46, 230, 214, 0.52);
  background: var(--cyan-soft);
}

/* ─── Stat strip (flat board, not card grid) ─── */

.nhlcal-stat-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0;
  border: 1px solid var(--line);
  background: rgba(14, 38, 86, 0.86);
  border-radius: var(--radius-control);
  overflow: hidden;
  box-shadow: var(--depth-registered);
  margin-top: 4px;
}

.nhlcal-stat-pill {
  min-height: 78px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-right: 1px solid rgba(156, 218, 236, 0.08);
  background: rgba(13, 36, 82, 0.55);
}

.nhlcal-stat-pill:last-child {
  border-right: 0;
}

.nhlcal-stat-icon {
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: var(--radius-hud);
  background: rgba(148, 185, 205, 0.1);
  border: 1px solid rgba(148, 185, 205, 0.12);
  color: rgba(233, 247, 251, 0.75);
  font-size: 16px;
}

.nhlcal-stat-pill span,
.nhlcal-stat-pill small {
  display: block;
}

.nhlcal-stat-pill span {
  color: var(--muted);
  font-size: var(--type-phase-label-size);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 900;
}

.nhlcal-stat-pill strong {
  display: block;
  margin-top: 2px;
  color: var(--text);
  font-family: var(--font-mono-data);
  font-size: 20px;
  line-height: 1;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.nhlcal-stat-pill small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.nhlcal-stat-pill.tone-cyan .nhlcal-stat-icon { color: var(--cyan); background: var(--cyan-soft); }
.nhlcal-stat-pill.tone-green .nhlcal-stat-icon { color: var(--green); background: var(--green-soft); }
.nhlcal-stat-pill.tone-danger .nhlcal-stat-icon { color: var(--red); background: var(--red-soft); }
.nhlcal-stat-pill.tone-gold .nhlcal-stat-icon { color: var(--gold); background: var(--gold-soft); }
.nhlcal-stat-pill.tone-blue .nhlcal-stat-icon { color: var(--blue); background: var(--blue-soft); }

/* ─── Content grid & panels ─── */

.nhlcal-content-grid {
  margin-top: 14px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 14px;
  align-items: start;
}

.nhlcal-calendar-panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-card);
  background: var(--panel);
  overflow: hidden;
  box-shadow: var(--depth-registered);
}

.nhlcal-week-header {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 48px;
  align-items: center;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  background: rgba(12, 34, 78, 0.62);
}

.nhlcal-right-rail {
  min-width: 0;
  display: grid;
  gap: 12px;
}

.nhlcal-card {
  border: 1px solid var(--line);
  border-radius: var(--radius-card);
  background: var(--panel);
  box-shadow: var(--depth-registered);
}

.nhlcal-card-header {
  min-height: 52px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 14px 16px 8px;
  border-bottom: 1px solid rgba(156, 218, 236, 0.08);
}

.nhlcal-card-header p {
  margin: 0;
  color: var(--cyan);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.nhlcal-card-header h3 {
  margin: 4px 0 0;
  font-size: var(--type-ops-heading-size);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.nhlcal-header-pill {
  border: 1px solid var(--line);
  border-radius: var(--radius-hud);
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  padding: 4px 8px;
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  text-transform: uppercase;
  white-space: nowrap;
}

.nhlcal-preview-lines {
  padding: 8px 12px 12px;
  display: grid;
}

.nhlcal-preview-lines div {
  min-height: 30px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid rgba(156, 218, 236, 0.08);
}

.nhlcal-preview-lines div:last-child {
  border-bottom: 0;
}

.nhlcal-preview-lines span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.nhlcal-preview-lines strong {
  color: rgba(233, 247, 251, 0.9);
  font-family: var(--font-mono-data);
  font-size: 12px;
  font-weight: 800;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.nhlcal-meter-row {
  padding: 0 12px 10px;
}

.nhlcal-meter-row label {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 5px;
}

.nhlcal-meter {
  height: 4px;
  border-radius: var(--radius-ops);
  background: rgba(30, 41, 59, 0.9);
  overflow: hidden;
}

.nhlcal-meter span {
  display: block;
  height: 100%;
  border-radius: var(--radius-ops);
  background: var(--cyan);
}

.nhlcal-meter.is-risk span {
  background: linear-gradient(90deg, var(--gold), var(--red));
}

/* ─── Empty states ─── */

.nhlcal-small-empty {
  color: var(--muted);
  font-size: var(--type-compact-size);
  text-align: center;
  padding: 1.5rem 1rem;
}

.nhlcal-empty-state {
  margin-top: 14px;
  border: 1px dashed var(--line);
  border-radius: var(--radius-control);
  background: rgba(14, 38, 86, 0.55);
  padding: 2.5rem 1.5rem;
  text-align: center;
  max-width: 420px;
}

.nhlcal-empty-state::before {
  content: "NO DATA";
  display: block;
  margin-bottom: 8px;
  color: var(--cyan);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.14em;
}

.nhlcal-empty-state h3 {
  margin: 0 0 6px;
  color: var(--text);
  font-size: var(--type-ops-heading-size);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.nhlcal-empty-state p {
  margin: 0;
  color: var(--muted);
  font-size: var(--type-compact-size);
  line-height: 1.45;
}

@media (max-width: 1100px) {
  .nhlcal-topbar {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .nhlcal-action-cluster {
    justify-self: start;
  }
  .nhlcal-content-grid {
    grid-template-columns: 1fr;
  }
  .nhlcal-stat-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .nhlcal-root {
    grid-template-columns: 1fr;
    height: auto;
    min-height: 100dvh;
  }
  .nhlcal-sidebar {
    display: none;
  }
  .nhlcal-main {
    height: auto;
    max-height: none;
    min-height: 100dvh;
  }
}


/* QA polish densify */
@media (max-height: 800px) {
  .nhlcal-brand-button { height: 72px; }
  .nhlcal-side-button { min-height: 52px; padding: 8px 4px; }
  .nhlcal-team-logo.size-large { width: 56px; height: 56px; }
  .nhlcal-team-logo.size-large img { width: 44px; height: 44px; }
}

/* ==========================================================================
   SECTION: styles/motion-control.css
   ========================================================================== */
@font-face {
  font-family: var(--dd-font-ui);
  src: url("./ArchivoBlack-Regular.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

:root {
  --font-motion-control: var(--dd-font-ui);
}

.hub-screen,
.hub-screen .game-footer,
.hub-screen .game-footer * {
  font-family: var(--font-motion-control);
}

/* ==========================================================================
   SECTION: styles/franchise-command.css
   ========================================================================== */
/* Shared franchise-command visual language across GM screens. */

.fc-proj {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  font-family: var(--font-mono-data, ui-monospace, monospace);
  letter-spacing: 0.02em;
  white-space: nowrap;
  filter: saturate(calc(0.45 + var(--fc-conf, 100%) * 0.0055));
}
.fc-proj strong {
  font-size: 1.45em;
