  height: 14px;
  border-right: 2px solid currentColor;
  border-top: 2px solid currentColor;
  transform: rotate(45deg);
  opacity: 0.85;
}
.fc-stock.is-down .fc-stock__shaft { transform: rotate(135deg); }
.fc-stock.is-flat .fc-stock__shaft {
