  width: 12px;
}
.fc-stock.is-up { color: #52df94; animation: fc-stock-pulse 1.4s ease-in-out infinite; }
.fc-stock.is-down { color: #ff8f9c; }
.fc-stock.is-flat { color: rgba(168, 186, 202, 0.75); }
@keyframes fc-stock-pulse {
