/* Paper / grid atmosphere */
.dc-root.dc-screen,
.trade-hub-root,
.cap-office-screen,
.nhlrost-root,
.linebuilder-root,
.statscentral-shell,
.nhlcal-sl-root,
.nhlcal-root {
  background-image:
    linear-gradient(rgba(14, 35, 79, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(14, 35, 79, 0.08) 1px, transparent 1px),
    radial-gradient(ellipse at 50% 0%, rgba(233, 168, 60, 0.06), transparent 42%),
    radial-gradient(ellipse at 12% 100%, rgba(46, 230, 214, 0.05), transparent 40%);
  background-size: 24px 24px, 24px 24px, 100% 100%, 100% 100%;
}

.dc-root.dc-screen {
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
}

.dc-topbar--war {
  grid-template-columns: auto minmax(0, 1fr) auto !important;
  min-height: 96px !important;
}
.dc-war-countdown {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
