}
.dc-war-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  justify-content: center;
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(226, 237, 246, 0.78);
}
.dc-war-meta strong { color: #2ee6d6; }

.dc-featured {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
