  flex-wrap: wrap;
  padding: 0 2px 8px;
}
.dc-board-lenses button {
  border: 1px solid rgba(118, 200, 245, 0.22);
  background: rgba(13, 35, 81, 0.7);
  color: rgba(226, 237, 246, 0.72);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
