}
.dc-board-lenses button.is-active {
  color: #0c214c;
  background: linear-gradient(180deg, #7fe4f0, #2ee6d6);
  border-color: transparent;
}

.dc-prospect-row {
  position: relative;
  overflow: hidden;
}
.dc-prospect-row.is-top5 {
  min-height: 72px;
  background: linear-gradient(90deg, rgba(233, 168, 60, 0.12), rgba(14, 36, 83, 0.4) 42%, transparent);
  box-shadow: inset 3px 0 0 #f4c66e;
}
.dc-prospect-row.is-top5 .dc-prospect-row__name {
  font-size: 1.08rem;
  letter-spacing: 0.03em;
}
.dc-prospect-row.is-selected {
  transform: translateX(6px);
  box-shadow:
    inset 0 0 0 1px rgba(244, 198, 110, 0.45),
