/* ==========================================================================
   SECTION: styles/perf-lite.css
   ========================================================================== */
/* Lite rendering: set on <html> by the office hub's low-power mode (manual, auto-detected,
   or tripped by a sagging frame rate). Drops the effects that cost integrated GPUs most
   without hiding content — only decorative loops and live blurs are removed. */

html.perf-lite *,
html.perf-lite *::before,
html.perf-lite *::after {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

html.perf-lite .game-canvas::before,
html.perf-lite .game-canvas::after,
html.perf-lite .player-headshot .ph-eyes::before,
html.perf-lite .player-headshot .ph-eyes::after,
html.perf-lite .player-headshot.animate-idle,
html.perf-lite .player-headshot.animate-broadcast,
html.perf-lite .player-headshot.animate-selected,
html.perf-lite .player-headshot.animate-injured,
html.perf-lite .player-headshot.animate-hot,
html.perf-lite .player-headshot.animate-cold {
  animation: none !important;
}

/* ==========================================================================
   SECTION: components/PlayerHeadshot.css
   ========================================================================== */
/* =========================================================
   player-headshots.css
   CSS-only player headshots for NHL Franchise Mode

   Usage:
   <div className="player-headshot headshot-1"></div>
   <div className="player-headshot headshot-2"></div>
   ...
   <div className="player-headshot headshot-15"></div>

   Optional sizes:
   <div className="player-headshot headshot-4 size-sm"></div>
   <div className="player-headshot headshot-4 size-lg"></div>
   ========================================================= */

   .player-headshot {
    --size: 92px;
    --skin: #c58b5f;
    --skin-shadow: #8d5b3d;
    --hair: #122859;
    --hair2: #0d1e46;
    --jersey: #63263b;
    --jersey2: #421827;
    --eye: #132346;
    --mouth: rgba(55, 22, 22, 0.55);
    --accent: rgba(255, 255, 255, 0.18);
  
    position: relative;
    width: var(--size);
    height: calc(var(--size) * 1.22);
    display: inline-block;
    isolation: isolate;
    filter: drop-shadow(0 12px 20px rgba(0, 0, 0, 0.45));
  }

  .player-headshot .ph-nhl-image {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    display: block;
    object-fit: contain;
    object-position: center bottom;
    pointer-events: none;
    user-select: none;
    z-index: 10;
  }

  .player-headshot.photo-only {
    filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.42));
  }

  .player-headshot.photo-only::before,
  .player-headshot.photo-only::after {
    display: none;
  }

  .player-headshot.photo-only .ph-nhl-image--solo {
    object-fit: cover;
    object-position: center 12%;
    border-radius: 12px;
    background: rgba(14, 35, 79, 0.92);
  }

  .player-headshot.size-sm.photo-only {
    --size: 52px;
  }

  .player-headshot.size-md.photo-only {
    --size: 72px;
  }

  .player-headshot.size-lg.photo-only {
    --size: 96px;
  }

  .player-headshot.size-xl.photo-only {
    --size: 128px;
  }
  
  /* -------------------------------
     Jersey / shoulders
  -------------------------------- */
  
  .player-headshot::before {
    content: "";
    position: absolute;
    left: 50%;
    bottom: 0;
    width: 112%;
    height: 48%;
    transform: translateX(-50%);
    background:
      linear-gradient(115deg, transparent 0 16%, rgba(255,255,255,0.08) 17% 18%, transparent 19%),
      linear-gradient(180deg, var(--jersey), var(--jersey2));
    clip-path: polygon(24% 0, 76% 0, 100% 100%, 0 100%);
    border-radius: 10px 10px 8px 8px;
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,0.12),
      inset 0 -18px 26px rgba(0,0,0,0.18);
    z-index: 1;
  }
  
  /* -------------------------------
     Neck
  -------------------------------- */
  
  .player-headshot::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 49%;
    width: 26%;
    height: 20%;
    transform: translateX(-50%);
    background: linear-gradient(180deg, var(--skin), var(--skin-shadow));
    border-radius: 0 0 999px 999px;
    z-index: 2;
  }
  
  /* -------------------------------
     Core face pieces
  -------------------------------- */
  
  .player-headshot .ph-face,
  .player-headshot .ph-hair,
  .player-headshot .ph-eyes,
  .player-headshot .ph-mouth,
  .player-headshot .ph-extra {
    position: absolute;
    pointer-events: none;
  }
  
  .player-headshot .ph-face {
    left: 50%;
    top: 16%;
    width: 58%;
    height: 48%;
    transform: translateX(-50%);
    background:
      radial-gradient(circle at 34% 26%, rgba(255,255,255,0.34), transparent 18%),
      linear-gradient(145deg, var(--skin), var(--skin-shadow));
    border-radius: 46% 46% 48% 48%;
    box-shadow:
      inset -10px -14px 18px rgba(0,0,0,0.13),
      inset 8px 7px 14px rgba(255,255,255,0.12);
    z-index: 4;
  }
  
  .player-headshot .ph-hair {
    left: 50%;
    top: 7%;
    width: 68%;
    height: 34%;
    transform: translateX(-50%);
    background: linear-gradient(160deg, var(--hair), var(--hair2));
    border-radius: 48% 52% 26% 30%;
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,0.12),
      0 2px 0 rgba(0,0,0,0.2);
    z-index: 5;
  }
  
  .player-headshot .ph-eyes {
    left: 50%;
    top: 37%;
    width: 38%;
    height: 9%;
    transform: translateX(-50%);
    z-index: 7;
  }
  
  .player-headshot .ph-eyes::before,
  .player-headshot .ph-eyes::after {
    content: "";
    position: absolute;
    top: 50%;
    width: 22%;
    height: 55%;
    background: var(--eye);
    border-radius: 50%;
    transform: translateY(-50%);
    animation: playerBlink 2s infinite;
    box-shadow: 0 0 0 1px rgba(255,255,255,0.06);
  }
  
  .player-headshot .ph-eyes::before {
    left: 8%;
  }
  
  .player-headshot .ph-eyes::after {
    right: 8%;
  }
  
  .player-headshot .ph-mouth {
    left: 50%;
    top: 52%;
    width: 22%;
    height: 6%;
    transform: translateX(-50%);
    border-bottom: 3px solid var(--mouth);
    border-radius: 50%;
    z-index: 7;
  }
  
  /* `scale` (not height) keeps the blink on the compositor and composes with mood transforms. */
  @keyframes playerBlink {
    0%, 88%, 100% {
      scale: 1 1;
    }

    91%, 94% {
      scale: 1 0.15;
    }
  }
  
  /* -------------------------------
     Convenience sizes
  -------------------------------- */
  
  .player-headshot.size-xs {
    --size: 48px;
  }
  
  .player-headshot.size-sm {
    --size: 68px;
  }
  
  .player-headshot.size-md {
    --size: 92px;
