/* =========================================================
   Team color overrides (CSS variables)
   ========================================================= */

.player-headshot {
  --team-primary: var(--jersey);
  --team-secondary: var(--jersey2);
  --team-accent: rgba(255, 255, 255, 0.18);
}

.player-headshot[style*="--team-primary"],
.player-headshot.team-branded {
  --jersey: var(--team-primary, var(--jersey));
  --jersey2: var(--team-secondary, var(--jersey2));
}

.player-headshot.glow,
.player-headshot.premium,
.headshot-32.player-headshot {
  --team-accent: rgba(255, 215, 120, 0.35);
}

/* =========================================================
   Presentation variants
   ========================================================= */

.player-headshot.variant-circle {
  border-radius: 50%;
  overflow: hidden;
  clip-path: circle(46% at 50% 38%);
}

.player-headshot.variant-card {
  border-radius: 12px;
  padding: 6px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02));
  box-shadow: 0 16px 34px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.player-headshot.variant-broadcast {
  filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.5)) saturate(1.08) contrast(1.05);
  transform: translateZ(0);
}

.player-headshot.variant-scouting {
  filter: drop-shadow(0 8px 16px rgba(0, 0, 0, 0.38));
  opacity: 0.96;
}

.player-headshot.variant-roster,
.player-headshot.size-roster {
  --size: 56px;
}

.player-headshot.variant-draft {
  filter: drop-shadow(0 0 14px rgba(248, 213, 138, 0.18));
}

.player-headshot.variant-trade {
  filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.45)) hue-rotate(-4deg);
}

.player-headshot.variant-injury {
  filter: grayscale(0.18) drop-shadow(0 10px 18px rgba(0, 0, 0, 0.45));
}

.player-headshot.variant-goalie .ph-face,
.player-headshot.role-goalie .ph-face {
  background: linear-gradient(145deg, #eef3f7, #8a97a5);
}

.player-headshot.variant-superstar,
.player-headshot.role-captain.glow {
  filter: drop-shadow(0 12px 20px rgba(0, 0, 0, 0.45)) drop-shadow(0 0 16px rgba(255, 215, 0, 0.24));
}

/* =========================================================
   Badges, numbers, flags
   ========================================================= */

.player-headshot .ph-badge,
.player-headshot .ph-number,
.player-headshot .ph-flag {
  position: absolute;
  z-index: 12;
  pointer-events: none;
  font-family: var(--dd-font-ui);
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.player-headshot .ph-badge {
  top: 4%;
  right: 2%;
  min-width: calc(var(--size) * 0.22);
  height: calc(var(--size) * 0.22);
  padding: 0 calc(var(--size) * 0.04);
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: rgba(14, 29, 67, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.18);
  color: #f5eedf;
  font-size: calc(var(--size) * 0.13);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.35);
}

.player-headshot .ph-badge.captain { background: rgba(248, 213, 138, 0.92); color: #17233d; border-color: rgba(255, 240, 200, 0.45); }
.player-headshot .ph-badge.alternate { background: rgba(30, 41, 59, 0.92); color: #dbeafe; }
.player-headshot .ph-badge.rookie { background: rgba(34, 197, 94, 0.88); color: #052e16; }
.player-headshot .ph-badge.injured { background: rgba(220, 38, 38, 0.88); color: #fff; }
.player-headshot .ph-badge.hot { background: rgba(249, 115, 22, 0.9); color: #171d36; }
.player-headshot .ph-badge.cold { background: rgba(56, 189, 248, 0.88); color: #082f49; }
.player-headshot .ph-badge.elite { background: linear-gradient(135deg, #fde68a, #f59e0b); color: #17233d; }
.player-headshot .ph-badge.prospect { background: rgba(46, 230, 214, 0.85); color: #0c234d; }
.player-headshot .ph-badge.goal { background: rgba(14, 165, 233, 0.9); color: #fff; font-size: calc(var(--size) * 0.11); }

/* Right-aligned so it never collides with the nationality flag at bottom-left
   on small portrait sizes. */
.player-headshot .ph-number {
  right: 6%;
  bottom: 7%;
  color: rgba(255, 255, 255, 0.92);
  font-size: calc(var(--size) * 0.24);
  line-height: 1;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.45), 0 0 8px rgba(0, 0, 0, 0.35);
  font-style: italic;
}

.player-headshot .ph-flag {
  left: 5%;
  bottom: 7%;
  display: inline-flex;
  align-items: center;
}
/* Text-code fallback chip (only when no flag image resolves). */
.player-headshot .ph-flag .ph-flag__code {
  padding: calc(var(--size) * 0.03) calc(var(--size) * 0.05);
  border-radius: 999px;
  background: rgba(14, 29, 67, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #dbeafe;
  font-size: calc(var(--size) * 0.09);
}
/* Real nation flag — prominent, clearly visible on the headshot. */
.player-headshot .ph-flag--img {
  left: 5%;
  bottom: 6%;
}
.player-headshot .ph-flag .ph-flag__img {
  display: block;
  width: calc(var(--size) * 0.36);
  height: calc(var(--size) * 0.24);
  object-fit: cover;
  border-radius: calc(var(--size) * 0.035);
  border: calc(var(--size) * 0.018) solid rgba(255, 255, 255, 0.9);
  box-shadow: 0 calc(var(--size) * 0.02) calc(var(--size) * 0.05) rgba(0, 0, 0, 0.55);
  background: rgba(14, 29, 67, 0.6);
}

/* =========================================================
   Extended sizes
   ========================================================= */

.player-headshot.size-tiny { --size: 36px; }
.player-headshot.size-xxl { --size: 220px; }
.player-headshot.size-card { --size: 112px; }
.player-headshot.size-profile { --size: 176px; }
.player-headshot.size-broadcast { --size: 144px; }

/* =========================================================
   Mood / expression modifiers
   ========================================================= */

.player-headshot.mood-smile .ph-mouth { border-bottom-color: rgba(120, 40, 40, 0.65); transform: translateX(-50%) scaleY(1.15); }
.player-headshot.mood-serious .ph-mouth { width: 18%; border-bottom-width: 2px; border-radius: 20%; }
.player-headshot.mood-angry .ph-eyes::before,
.player-headshot.mood-angry .ph-eyes::after { transform: translateY(-58%) rotate(12deg); box-shadow: 0 -2px 0 rgba(0, 0, 0, 0.25); }
.player-headshot.mood-angry .ph-eyes::after { transform: translateY(-58%) rotate(-12deg); }
.player-headshot.mood-focused .ph-eyes::before,
.player-headshot.mood-focused .ph-eyes::after { height: 48%; width: 20%; }
.player-headshot.mood-tired .ph-eyes::before,
.player-headshot.mood-tired .ph-eyes::after { height: 42%; opacity: 0.82; transform: translateY(-42%); }
.player-headshot.mood-confident .ph-face { box-shadow: inset -10px -14px 18px rgba(0, 0, 0, 0.13), inset 8px 7px 14px rgba(255, 255, 255, 0.16), 0 0 10px rgba(255, 255, 255, 0.08); }

/* =========================================================
   Age class modifiers
   ========================================================= */

.player-headshot.age-prospect .ph-face { border-radius: 50%; }
.player-headshot.age-rookie .ph-hair { filter: saturate(1.05); }
.player-headshot.age-veteran .ph-hair,
.player-headshot.age-legend .ph-hair { filter: saturate(0.82); }
.player-headshot.age-legend { filter: drop-shadow(0 12px 20px rgba(0, 0, 0, 0.45)) drop-shadow(0 0 10px rgba(248, 213, 138, 0.18)); }

/* =========================================================
   Role modifiers
   ========================================================= */

.player-headshot.role-forward::before { clip-path: polygon(22% 0, 78% 0, 100% 100%, 0 100%); }
.player-headshot.role-defense::before { clip-path: polygon(18% 0, 82% 0, 100% 100%, 0 100%); }
.player-headshot.role-enforcer .ph-face { border-radius: 42% 46% 48% 44%; }
.player-headshot.role-playmaker .ph-eyes::before,
.player-headshot.role-playmaker .ph-eyes::after { box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.18); }
.player-headshot.role-sniper .ph-eyes::before,
.player-headshot.role-sniper .ph-eyes::after { background: #12265c; }
.player-headshot.role-two-way::before { background: linear-gradient(180deg, var(--team-primary, var(--jersey)), color-mix(in srgb, var(--team-secondary, var(--jersey2)) 70%, #122245 30%)); }
.player-headshot.role-prospect { opacity: 0.98; }

/* =========================================================
   Interaction states
   ========================================================= */

.player-headshot:hover,
.player-headshot.animate-hover:hover {
  transform: translateY(-2px) scale(1.03);
  transition: transform 180ms ease, filter 180ms ease;
}

.player-headshot.is-selected {
  outline: 2px solid rgba(248, 213, 138, 0.75);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px rgba(248, 213, 138, 0.12);
}

.player-headshot.is-dimmed { opacity: 0.45; filter: grayscale(0.25); }
.player-headshot.is-scouted { box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.35); }

.player-headshot.is-hidden .ph-face,
.player-headshot.is-hidden .ph-hair,
.player-headshot.is-hidden .ph-eyes,
.player-headshot.is-hidden .ph-mouth,
.player-headshot.is-hidden .ph-extra {
  filter: blur(4px);
  opacity: 0.55;
}

.player-headshot.is-locked::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.28);
  z-index: 20;
  border-radius: inherit;
}

/* =========================================================
   Scouting visibility states
   ========================================================= */

.player-headshot.scout-unknown .ph-face,
.player-headshot.scout-unknown .ph-hair,
.player-headshot.scout-unknown .ph-eyes,
.player-headshot.scout-unknown .ph-mouth {
  filter: blur(5px) brightness(0.72);
}

.player-headshot.scout-unknown .ph-number,
.player-headshot.scout-unknown .ph-badge { opacity: 0; }

.player-headshot.scout-partial .ph-eyes,
.player-headshot.scout-partial .ph-mouth,
.player-headshot.scout-partial .ph-extra {
  filter: blur(2px) opacity(0.75);
}

.player-headshot.scout-known {
  filter: drop-shadow(0 12px 20px rgba(0, 0, 0, 0.45));
}

/* =========================================================
   Injury states
   ========================================================= */

.player-headshot.injury-day-to-day::before {
  box-shadow: inset 0 -18px 26px rgba(0, 0, 0, 0.18), inset 0 0 0 2px rgba(250, 204, 21, 0.35);
}

.player-headshot.injury-long-term {
  filter: grayscale(0.22) drop-shadow(0 12px 20px rgba(0, 0, 0, 0.45));
}

.player-headshot.injury-long-term::after {
  box-shadow: 0 0 0 2px rgba(220, 38, 38, 0.35);
}

.player-headshot.injury-returning { filter: saturate(0.92); }
.player-headshot.injury-returning .ph-badge.injured { background: rgba(34, 197, 94, 0.88); color: #052e16; }

/* =========================================================
   Draft board states
   ========================================================= */

.player-headshot.draft-top-pick { filter: drop-shadow(0 0 16px rgba(255, 215, 0, 0.28)); }
.player-headshot.draft-lottery { filter: drop-shadow(0 0 14px rgba(168, 85, 247, 0.22)); }
.player-headshot.draft-steal { box-shadow: 0 0 0 2px rgba(34, 197, 94, 0.35); }
.player-headshot.draft-bust-risk { box-shadow: 0 0 0 2px rgba(239, 68, 68, 0.28); }
.player-headshot.draft-sleeper { opacity: 0.94; filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.42)); }

/* =========================================================
   Utility classes
   ========================================================= */

.player-headshot.no-blink .ph-eyes::before,
.player-headshot.no-blink .ph-eyes::after { animation: none !important; }

.player-headshot.no-shadow,
.player-headshot.flat {
  filter: none;
  box-shadow: none;
  transform: none;
}

.player-headshot.glow {
  filter: drop-shadow(0 12px 20px rgba(0, 0, 0, 0.45)) drop-shadow(0 0 14px rgba(248, 213, 138, 0.22));
}

.player-headshot.premium {
  filter: drop-shadow(0 14px 24px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 18px rgba(255, 215, 0, 0.22));
}

.player-headshot.compact { --size: calc(var(--size) * 0.88); }
.player-headshot.high-contrast { filter: contrast(1.12) saturate(1.08) drop-shadow(0 12px 20px rgba(0, 0, 0, 0.5)); }

/* =========================================================
   Animations
   ========================================================= */

@keyframes phIdleFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-2px); }
}

@keyframes phBroadcastPulse {
  0%, 100% { filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.5)); }
  50% { filter: drop-shadow(0 12px 22px rgba(0, 0, 0, 0.55)) saturate(1.06); }
}

@keyframes phSelectedPulse {
  0%, 100% { box-shadow: 0 0 0 4px rgba(248, 213, 138, 0.12); }
  50% { box-shadow: 0 0 0 6px rgba(248, 213, 138, 0.2); }
}

@keyframes phInjuredPulse {
  0%, 100% { opacity: 0.88; }
  50% { opacity: 0.72; }
}

@keyframes phHotPulse {
  0%, 100% { filter: drop-shadow(0 0 8px rgba(249, 115, 22, 0.18)); }
  50% { filter: drop-shadow(0 0 14px rgba(249, 115, 22, 0.32)); }
}

@keyframes phColdPulse {
  0%, 100% { filter: drop-shadow(0 0 8px rgba(56, 189, 248, 0.12)); }
  50% { filter: drop-shadow(0 0 14px rgba(56, 189, 248, 0.24)); }
}

.player-headshot.animate-idle { animation: phIdleFloat 4.8s ease-in-out infinite; }
.player-headshot.animate-broadcast { animation: phBroadcastPulse 3.6s ease-in-out infinite; }
.player-headshot.is-selected.animate-selected,
.player-headshot.animate-selected { animation: phSelectedPulse 2.4s ease-in-out infinite; }
.player-headshot.animate-injured { animation: phInjuredPulse 2.8s ease-in-out infinite; }
.player-headshot.animate-hot { animation: phHotPulse 2.2s ease-in-out infinite; }
.player-headshot.animate-cold { animation: phColdPulse 2.8s ease-in-out infinite; }

/* =========================================================
   Dark UI compatibility
   ========================================================= */

.player-headshot { color-scheme: dark; }

.player-headshot.variant-card,
.player-headshot.variant-scouting,
.player-headshot.variant-roster {
