.burner-outcomes { display: grid; gap: 10px; align-content: start; }
.burner-tone {
  justify-self: start; padding: 4px 10px; border-radius: 999px; font-size: 11px; font-weight: 900;
  letter-spacing: 0.08em; text-transform: uppercase; border: 1px solid var(--bp-line);
}
.burner-tone.is-hype { color: var(--bp-green); border-color: rgba(61, 220, 151, 0.45); }
.burner-tone.is-criticism { color: var(--bp-red); border-color: rgba(255, 107, 107, 0.45); }
.burner-tone.is-trade_talk { color: var(--bp-gold); border-color: rgba(233, 168, 60, 0.45); }
.burner-outcome { padding: 10px 12px; border-radius: 10px; border: 1px solid var(--bp-line); background: rgba(0, 0, 0, 0.18); }
.burner-outcome span { font-size: 11px; font-weight: 900; letter-spacing: 0.12em; text-transform: uppercase; }
.burner-outcome p { margin: 4px 0 0; font-size: 14px; line-height: 1.45; }
.burner-outcome--ok { border-left: 3px solid var(--bp-green); }
.burner-outcome--ok span { color: var(--bp-green); }
.burner-outcome--bad { border-left: 3px solid var(--bp-red); }
.burner-outcome--bad span { color: var(--bp-red); }
.burner-error { margin: 0; color: var(--bp-red); font-weight: 700; }
.burner-post-btn {
  justify-self: start; padding: 11px 22px; border-radius: 10px; cursor: pointer;
  border: 1px solid rgba(233, 168, 60, 0.6); background: linear-gradient(180deg, #f0b44e, #c98a24);
  color: #17233b; font-weight: 900; font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase;
}
.burner-post-btn:disabled { opacity: 0.45; cursor: not-allowed; }
.burner-history h4 { margin: 4px 0 8px; font-size: 12px; font-weight: 900; letter-spacing: 0.12em; text-transform: uppercase; color: var(--bp-muted); }
.burner-history__row { padding: 10px 12px; border-radius: 10px; border: 1px solid var(--bp-line); margin-bottom: 8px; background: rgba(0, 0, 0, 0.15); }
.burner-history__row strong { color: var(--bp-green); }
.burner-history__row--caught strong { color: var(--bp-red); }
.burner-history__row span { color: var(--bp-muted); font-size: 12.5px; }
.burner-history__row p { margin: 6px 0 4px; }
.burner-history__row em { font-style: normal; font-size: 12.5px; color: var(--bp-muted); }
@media (max-width: 720px) {
  .burner-risk-row { grid-template-columns: 1fr; }
}

.burner-note { font-size: 12px; opacity: 0.75; margin: 4px 0 8px; }
.burner-count { font-size: 11px; opacity: 0.55; text-align: right; margin-top: 4px; }
.burner-field strong { font-weight: 600; }

/* ==========================================================================
   SECTION: components/franchise/social/PlayerSocial.css
   ========================================================================== */
/* Player social: posts, replies, quotes, burner watch */
.psx-post { text-align: left; width: 100%; cursor: default; }
.psx-post.is-clickable { cursor: pointer; }
.psx-post.is-player { border-left: 3px solid var(--gold, #d8b45a); }
.psx-post.is-rant { border-left-color: #e05a4f; background: linear-gradient(90deg, rgba(224, 90, 79, 0.08), transparent 40%); }
.psx-post.is-burner { border-left: 3px dashed rgba(156, 218, 236, 0.5); }
.psx-post.is-burner .sl-post__head strong { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: 0.02em; }
.psx-avatar { display: inline-flex; flex: 0 0 auto; }
.psx-avatar .player-headshot { border-radius: 50%; overflow: hidden; }
.psx-sub { font-size: 11px; opacity: 0.6; margin: -2px 0 6px 0; }
.psx-sub--burner { color: #9cdaec; opacity: 0.8; }
.psx-chip { font-size: 10px; padding: 1px 7px; border-radius: 999px; border: 1px solid currentColor; text-transform: uppercase; letter-spacing: 0.05em; white-space: nowrap; }
.psx-chip--hot { color: #ff7a6b; }
.psx-chip--hype { color: #ffb347; }
.psx-chip--cool { color: #8fc3ff; }
.psx-chip--warm { color: #f3c98b; }
.psx-chip--dim { color: rgba(220, 230, 240, 0.55); }
.psx-chip--del { color: #ff7a6b; }
.psx-ghost { opacity: 0.75; text-decoration: line-through; text-decoration-color: rgba(255, 122, 107, 0.6); }
.psx-deleted { display: flex; gap: 10px; align-items: center; justify-content: space-between; padding: 10px 12px; margin: 6px 0; border-radius: 8px; background: rgba(255, 255, 255, 0.04); border: 1px dashed rgba(255, 255, 255, 0.18); font-style: italic; opacity: 0.85; }
.psx-linkbtn { background: none; border: 0; color: var(--gold, #d8b45a); cursor: pointer; padding: 0; font: inherit; font-size: 12px; text-decoration: underline; }
.psx-quote { margin: 8px 0; padding: 10px 12px; border-radius: 10px; border: 1px solid rgba(255, 255, 255, 0.14); background: rgba(0, 0, 0, 0.18); }
.psx-quote.is-deleted { border-color: rgba(255, 122, 107, 0.45); box-shadow: inset 0 0 0 1px rgba(255, 122, 107, 0.12); }
.psx-quote__head, .psx-quote__liked { display: flex; gap: 6px; align-items: center; font-size: 12px; flex-wrap: wrap; }
.psx-quote__liked { color: #ff8fa3; margin-bottom: 6px; }
.psx-quote__head span, .psx-quote__head em { opacity: 0.6; }
.psx-quote p { margin: 6px 0 0; }
.psx-bio { display: flex; gap: 10px; align-items: center; margin: 8px 0; padding: 10px 12px; border-radius: 10px; background: rgba(0, 0, 0, 0.2); border: 1px solid rgba(255, 255, 255, 0.12); }
.psx-bio p { margin: 2px 0; }
.psx-bio__after { font-size: 20px; }
.psx-beef { font-size: 12px; color: #ffb347; margin: 4px 0; }
.psx-replies { margin-top: 8px; padding-left: 10px; border-left: 2px solid rgba(255, 255, 255, 0.1); display: grid; gap: 8px; }
.psx-reply { display: flex; gap: 8px; align-items: flex-start; font-size: 13px; }
.psx-reply p { margin: 2px 0; }
.psx-reply small { opacity: 0.5; font-size: 11px; }
.psx-reply.is-player .psx-reply__head strong { color: var(--gold, #d8b45a); }
.psx-reply__head { display: flex; gap: 5px; align-items: center; flex-wrap: wrap; }
.psx-reply__head span { opacity: 0.55; font-size: 12px; }
.psx-rail { display: grid; gap: 10px; }
.psx-tabs { display: flex; gap: 4px; flex-wrap: wrap; }
.psx-tabs button { flex: 1; font-size: 12px; padding: 6px 8px; border-radius: 8px; border: 1px solid rgba(255, 255, 255, 0.12); background: transparent; color: inherit; cursor: pointer; }
.psx-tabs button.is-active { background: rgba(216, 180, 90, 0.16); border-color: var(--gold, #d8b45a); }
.psx-list { display: grid; gap: 8px; max-height: 640px; overflow-y: auto; padding-right: 2px; }
.psx-note { font-size: 12px; opacity: 0.6; margin: 0; }
.psx-acct { border-radius: 10px; padding: 8px; background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.08); }
.psx-acct.has-incident { border-color: rgba(255, 122, 107, 0.55); }
.psx-acct.is-active { border-color: var(--gold, #d8b45a); }
.psx-acct__main { display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; width: 100%; background: none; border: 0; color: inherit; text-align: left; cursor: pointer; padding: 0; }
.psx-acct__main strong { display: block; font-size: 13px; }
.psx-acct__main small { font-size: 11px; opacity: 0.6; }
.psx-acct__bars { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 6px; font-size: 10px; opacity: 0.8; }
.psx-acct__bars label { display: grid; gap: 3px; }
.psx-meter { display: block; height: 5px; border-radius: 3px; background: rgba(255, 255, 255, 0.1); overflow: hidden; }
.psx-meter i { display: block; height: 100%; border-radius: 3px; transition: width 0.4s ease; }
.psx-meter--gold i { background: var(--gold, #d8b45a); }
.psx-meter--red i { background: #e05a4f; }
.psx-meter--green i { background: #4fbf85; }
.psx-ban { font-size: 11px; margin-top: 6px; opacity: 0.8; }
.psx-incident { margin-top: 8px; display: grid; gap: 4px; font-size: 12px; color: #ffb3a8; }
.psx-incident q { font-style: italic; opacity: 0.85; color: inherit; }
.psx-meet { justify-self: start; margin-top: 2px; font-size: 12px; padding: 4px 10px; border-radius: 999px; border: 1px solid #ff7a6b; background: rgba(255, 122, 107, 0.12); color: #ffd0c9; cursor: pointer; }
.psx-meet:hover { background: rgba(255, 122, 107, 0.25); }
.psx-burner { border-radius: 10px; padding: 10px; border: 1px dashed rgba(156, 218, 236, 0.35); background: rgba(156, 218, 236, 0.04); font-size: 12px; }
.psx-burner.is-mine { border-color: rgba(255, 122, 107, 0.6); }
.psx-burner.is-unmasked { border-style: solid; border-color: #e05a4f; background: rgba(224, 90, 79, 0.1); }
.psx-burner__head { display: flex; gap: 6px; align-items: center; }
.psx-burner__head strong { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
.psx-burner__head em { margin-left: auto; opacity: 0.55; }
.psx-burner__meter { display: grid; grid-template-columns: auto 1fr auto; gap: 6px; align-items: center; margin: 6px 0; }
.psx-burner__suspect { display: flex; gap: 6px; align-items: center; }
.psx-burner__verdict { margin: 6px 0; color: #ff7a6b; letter-spacing: 0.06em; }
.psx-burner ul { margin: 6px 0 0; padding-left: 16px; opacity: 0.8; }
.psx-burner li { margin: 2px 0; }
.psx-log { display: flex; gap: 8px; align-items: center; padding: 6px 8px; border-radius: 8px; background: rgba(255, 255, 255, 0.03); font-size: 12px; }
.psx-log.is-mine { border: 1px solid rgba(216, 180, 90, 0.5); }
.psx-log strong { display: block; }
.psx-log small { opacity: 0.6; }
.psx-sev { color: #ff7a6b; margin-left: 6px; font-size: 9px; letter-spacing: 2px; }
.psx-author-bar { display: flex; align-items: center; gap: 8px; font-size: 12px; margin: 4px 0 8px; opacity: 0.85; }
@media (prefers-reduced-motion: reduce) { .psx-meter i { transition: none; } }

/* ==========================================================================
   SECTION: components/dossier/PlayerDossier.css
   ========================================================================== */
/* =========================================================
   Player dossier modal (PlayerProfileModal in RosterScreen.js)
   Self-contained so the modal renders the same from any screen.
   Palette mirrors the roster screen tokens (ops navy + teal accent).
   ========================================================= */

.pdx-modal {
  --pdx-bg: var(--ops-navy, #0c214d);
  --pdx-panel: rgba(14, 38, 86, 0.98);
  --pdx-card: rgba(12, 33, 49, 0.72);
  --pdx-card-2: rgba(16, 42, 61, 0.55);
  --pdx-line: rgba(156, 218, 236, 0.12);
  --pdx-line-2: rgba(115, 229, 241, 0.26);
  --pdx-text: var(--ops-text, #e9f7fb);
  --pdx-muted: var(--ops-text-secondary, #8ea3b5);
  --pdx-muted-2: var(--ops-text-disabled, #6a8193);
  --pdx-cyan: var(--ops-cyan, #2ee6d6);
  --pdx-blue: var(--ops-info, #8ab4ff);
  --pdx-gold: var(--ops-gold, #e9a83c);
  --pdx-green: var(--ops-success, #52df94);
  --pdx-red: var(--ops-injury, #ff606d);
  --pdx-radius: 10px;
  --pdx-gap: 14px;
  --pdx-pad: 16px;

  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 20px;
  color: var(--pdx-text);
  font-family: var(--font-ops-ui, Inter, ui-sans-serif, system-ui, sans-serif);
  font-size: 14px;
  line-height: 1.4;
}

.pdx-modal *,
.pdx-modal *::before,
.pdx-modal *::after {
  box-sizing: border-box;
}

.pdx-modal button {
  font: inherit;
  color: inherit;
}

.pdx-modal h2,
.pdx-modal h3,
.pdx-modal p,
.pdx-modal ul,
.pdx-modal ol,
.pdx-modal blockquote {
  margin: 0;
}

.pdx-modal__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  padding: 0;
  background: rgba(11, 28, 67, 0.82);
  backdrop-filter: blur(8px);
  cursor: pointer;
}

.pdx-panel {
  position: relative;
  width: min(1180px, 100%);
  max-height: calc(100dvh - 40px);
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background:
    radial-gradient(circle at 12% 0%, rgba(46, 230, 214, 0.08), transparent 32%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.01)),
    var(--pdx-panel);
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.5);
  overflow: hidden;
}

/* ─── Top bar ─────────────────────────────────────────── */

.pdx-topbar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px 8px var(--pdx-pad);
  border-bottom: 1px solid var(--pdx-line);
  background: rgba(12, 32, 74, 0.6);
}

.pdx-topbar__label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--pdx-cyan);
}

.pdx-topbar__actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pdx-pager {
  display: flex;
  align-items: center;
  gap: 6px;
}

.pdx-pager span {
  min-width: 64px;
  text-align: center;
  font-size: 12px;
  font-weight: 700;
  color: var(--pdx-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.pdx-pager button,
.pdx-close {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease;
}

.pdx-pager button:hover:not(:disabled),
.pdx-close:hover {
  border-color: var(--pdx-line-2);
  background: rgba(46, 230, 214, 0.1);
}

.pdx-pager button:disabled {
  opacity: 0.35;
  cursor: default;
}

.pdx-close {
  font-size: 20px;
}

/* ─── Scroll body ─────────────────────────────────────── */

.pdx-scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

/* ─── Hero ────────────────────────────────────────────── */

.pdx-hero {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 20px;
  align-items: center;
  padding: 18px var(--pdx-pad) 16px;
}

.pdx-hero__photo {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 112px;
}

.pdx-modal .pdx-hero__headshot.player-headshot.size-xl {
  --size: 104px;
}

.pdx-hero__identity {
  min-width: 0;
  display: grid;
  gap: 8px;
}

.pdx-hero__name-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 10px;
  min-width: 0;
}

.pdx-hero__name-row h2 {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.01em;
  line-height: 1.15;
  overflow-wrap: anywhere;
}

.pdx-hero__jersey {
  font-size: 14px;
  font-weight: 700;
  color: var(--pdx-muted);
  font-variant-numeric: tabular-nums;
}

.pdx-flag:empty {
  display: none;
}

.pdx-flag img {
  display: block;
  width: 28px;
  height: 20px;
  object-fit: cover;
  border-radius: 3px;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.14);
}

.pdx-flag span {
  display: inline-block;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 800;
  background: rgba(255, 255, 255, 0.08);
}

.pdx-hero__meta {
  font-size: 14px;
  color: var(--pdx-muted);
}

.pdx-flags {
  list-style: none;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
}

.pdx-flags li {
  position: relative;
  padding-left: 12px;
  font-size: 13px;
  color: var(--pdx-text);
}

.pdx-flags li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--pdx-muted);
}

.pdx-flags li.is-good::before { background: var(--pdx-green); }
.pdx-flags li.is-warn::before { background: var(--pdx-gold); }
.pdx-flags li.is-bad::before { background: var(--pdx-red); }

.pdx-hero__ratings {
  display: flex;
  gap: 10px;
  align-self: center;
}

.pdx-rating {
  min-width: 96px;
  max-width: 132px;
  padding: 10px 12px 11px;
  display: grid;
  justify-items: center;
  gap: 2px;
  text-align: center;
  border-radius: var(--pdx-radius);
  border: 1px solid var(--pdx-line-2);
  background: linear-gradient(180deg, rgba(46, 230, 214, 0.14), rgba(46, 230, 214, 0.04));
}

.pdx-rating.is-pot {
  border-color: rgba(233, 168, 60, 0.38);
  background: linear-gradient(180deg, rgba(233, 168, 60, 0.16), rgba(233, 168, 60, 0.04));
}

.pdx-rating.is-pot.is-elite {
  border-color: rgba(82, 223, 148, 0.45);
  background: linear-gradient(180deg, rgba(82, 223, 148, 0.18), rgba(82, 223, 148, 0.04));
}

.pdx-rating.is-pot.is-neutral {
  border-color: rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.04);
}

.pdx-rating__label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--pdx-muted);
}

.pdx-rating__value {
  font-size: 34px;
  font-weight: 800;
  line-height: 1.05;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.pdx-rating.is-pot .pdx-rating__value {
  color: #ffd38a;
}

.pdx-rating.is-pot.is-elite .pdx-rating__value {
  color: #8ff0bd;
}

.pdx-rating__sub {
  font-size: 12px;
  font-weight: 600;
  color: var(--pdx-muted);
  line-height: 1.25;
}

.pdx-rating__sub.is-up { color: var(--pdx-green); }
.pdx-rating__sub.is-down { color: var(--pdx-red); }

/* ─── Tabs (sticky inside the scroll body) ────────────── */

.pdx-tabs-wrap {
  position: sticky;
  top: 0;
  z-index: 3;
  padding: 0 var(--pdx-pad);
  background: rgba(14, 36, 82, 0.97);
  backdrop-filter: blur(6px);
  border-top: 1px solid var(--pdx-line);
  border-bottom: 1px solid var(--pdx-line);
}

.pdx-tabs {
  display: flex;
  gap: 2px;
  overflow-x: auto;
  scrollbar-width: none;
}

.pdx-tabs::-webkit-scrollbar {
  display: none;
}

.pdx-tabs button {
  flex-shrink: 0;
  padding: 12px 14px 10px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--pdx-muted);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
  cursor: pointer;
  transition: color 120ms ease, border-color 120ms ease;
}

.pdx-tabs button:hover {
  color: var(--pdx-text);
}

.pdx-tabs button.is-active {
  color: var(--pdx-text);
  border-bottom-color: var(--pdx-cyan);
}

.pdx-tabs button:focus-visible {
  outline: 2px solid var(--pdx-cyan);
  outline-offset: -4px;
  border-radius: 6px;
}

/* ─── Content & layout ────────────────────────────────── */

.pdx-content {
  padding: var(--pdx-pad);
}

.pdx-stack {
  display: grid;
  gap: var(--pdx-gap);
}

.pdx-grid-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  gap: var(--pdx-gap);
  align-items: start;
}

.pdx-grid-2:empty {
  display: none;
}

/* ─── Card ────────────────────────────────────────────── */

.pdx-card {
  min-width: 0;
  display: grid;
  gap: 14px;
  align-content: start;
  padding: var(--pdx-pad);
  border-radius: var(--pdx-radius);
  border: 1px solid var(--pdx-line);
  background: var(--pdx-card);
}

.pdx-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.pdx-card__titles {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.pdx-card__eyebrow,
.pdx-tile__label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--pdx-muted);
}

.pdx-card__eyebrow {
  color: var(--pdx-cyan);
}

.pdx-card__title {
  font-size: 17px;
  font-weight: 750;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.pdx-card__aside {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* ─── Stat tiles (label above value, never truncated) ─── */

.pdx-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(132px, 1fr));
  gap: 10px;
}

.pdx-tiles.is-dense {
  grid-template-columns: repeat(auto-fill, minmax(108px, 1fr));
  gap: 8px;
}

.pdx-tile {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 4px;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: var(--pdx-card-2);
}

.pdx-tile.is-wide {
  grid-column: span 2;
}

.pdx-tile__value {
  font-size: 15px;
  font-weight: 750;
  line-height: 1.3;
  color: var(--pdx-text);
  font-variant-numeric: tabular-nums;
  white-space: normal;
  overflow-wrap: anywhere;
}

.pdx-tile__sub {
  font-size: 12px;
  color: var(--pdx-muted);
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.pdx-tile.is-good .pdx-tile__value { color: var(--pdx-green); }
.pdx-tile.is-warn .pdx-tile__value { color: var(--pdx-gold); }
.pdx-tile.is-bad .pdx-tile__value { color: var(--pdx-red); }

/* ─── Chips ───────────────────────────────────────────── */

.pdx-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.pdx-chip-row--spaced {
  margin-top: 2px;
}

.pdx-chip {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.05);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--pdx-text);
  white-space: normal;
  overflow-wrap: anywhere;
}

.pdx-chip.is-info {
  color: var(--pdx-cyan);
  border-color: rgba(46, 230, 214, 0.3);
  background: rgba(46, 230, 214, 0.08);
}

.pdx-chip.is-good {
  color: var(--pdx-green);
  border-color: rgba(82, 223, 148, 0.32);
  background: rgba(82, 223, 148, 0.08);
}

.pdx-chip.is-warn {
  color: var(--pdx-gold);
  border-color: rgba(233, 168, 60, 0.36);
  background: rgba(233, 168, 60, 0.08);
}

.pdx-chip.is-bad,
.pdx-chip.is-medical {
  color: var(--pdx-red);
  border-color: rgba(255, 96, 109, 0.36);
  background: rgba(255, 96, 109, 0.08);
}

.pdx-chip.is-premium {
  color: #ffd38a;
  border-color: rgba(233, 168, 60, 0.3);
  background: rgba(233, 168, 60, 0.07);
}

/* ─── Meter ───────────────────────────────────────────── */

.pdx-meter {
  display: grid;
  gap: 8px;
}

.pdx-meter__top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.pdx-meter__top strong {
  font-size: 22px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.pdx-meter__top em {
  margin-left: 8px;
  font-size: 13px;
  font-style: normal;
  font-weight: 700;
  color: var(--pdx-muted);
}

.pdx-meter__track,
.pdx-bar__track {
  height: 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.pdx-meter__track i,
.pdx-bar__track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #4ea2ff, #8fd0ff);
}

.pdx-meter.is-good .pdx-meter__track i,
.pdx-bar.is-good .pdx-bar__track i {
  background: linear-gradient(90deg, #1fd6a5, #7ef0c8);
}

.pdx-meter.is-warn .pdx-meter__track i,
.pdx-bar.is-warn .pdx-bar__track i {
  background: linear-gradient(90deg, #f0a23a, #ffd27a);
}

.pdx-meter.is-bad .pdx-meter__track i {
  background: linear-gradient(90deg, #e2414f, #ff8a94);
}

.pdx-meter.is-good .pdx-meter__top em { color: var(--pdx-green); }
.pdx-meter.is-warn .pdx-meter__top em { color: var(--pdx-gold); }
.pdx-meter.is-bad .pdx-meter__top em { color: var(--pdx-red); }

/* ─── Text helpers ────────────────────────────────────── */

.pdx-note {
  font-size: 13px;
  color: var(--pdx-muted);
  line-height: 1.5;
}

.pdx-note--spaced {
  margin-top: 2px;
}

.pdx-note strong {
  color: var(--pdx-text);
}

.pdx-note.is-bad {
  color: #f0a0a0;
}

.pdx-lead {
  font-size: 14px;
  line-height: 1.5;
  color: var(--pdx-text);
}

.pdx-bullets {
  padding-left: 18px;
  display: grid;
  gap: 4px;
  font-size: 13px;
}

.pdx-link-btn {
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid rgba(46, 230, 214, 0.28);
  background: rgba(46, 230, 214, 0.06);
  color: var(--pdx-cyan) !important;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.pdx-link-btn:hover {
  background: rgba(46, 230, 214, 0.14);
}

.pdx-btn {
  padding: 8px 14px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.05);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  white-space: nowrap;
}

.pdx-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.1);
}

.pdx-btn--primary {
  border-color: rgba(46, 230, 214, 0.45);
  background: rgba(46, 230, 214, 0.14);
  color: var(--pdx-cyan) !important;
}

.pdx-btn--primary:hover:not(:disabled) {
  background: rgba(46, 230, 214, 0.24);
}

.pdx-btn:disabled {
  opacity: 0.5;
  cursor: default;
}

.pdx-empty {
  padding: 28px var(--pdx-pad);
  text-align: center;
  border-radius: var(--pdx-radius);
  border: 1px dashed var(--pdx-line-2);
  display: grid;
  gap: 6px;
}

.pdx-empty strong {
  font-size: 15px;
}

.pdx-empty p {
  font-size: 13px;
  color: var(--pdx-muted);
}

/* ─── Overview: strengths/concerns + attributes ───────── */

.pdx-sc {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
}

.pdx-sc__col {
  display: grid;
  gap: 8px;
  align-content: start;
}

.pdx-sc__label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.pdx-sc__label.is-good { color: var(--pdx-green); }
.pdx-sc__label.is-warn { color: var(--pdx-gold); }

.pdx-sc ul {
  padding-left: 16px;
  display: grid;
  gap: 6px;
  font-size: 13px;
  line-height: 1.45;
}

.pdx-attributes .chapter-attribute-profile {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 12px 24px;
}

.pdx-attributes .chapter-attribute-profile__row {
  display: grid;
  gap: 5px;
}

.pdx-attributes .chapter-attribute-profile__meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 13px;
  color: var(--pdx-muted);
}

.pdx-attributes .chapter-attribute-profile__meta strong {
  font-size: 14px;
  font-weight: 800;
  color: var(--pdx-text);
  font-variant-numeric: tabular-nums;
}

.pdx-attributes .chapter-attribute-profile__track {
  height: 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.pdx-attributes .chapter-attribute-profile__track i {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.pdx-attributes .chapter-attribute-profile__track i.is-good { background: linear-gradient(90deg, #1fd6a5, #7ef0c8); }
.pdx-attributes .chapter-attribute-profile__track i.is-neutral { background: linear-gradient(90deg, #4ea2ff, #8fd0ff); }
.pdx-attributes .chapter-attribute-profile__track i.is-warn { background: linear-gradient(90deg, #f0a23a, #ffd27a); }

.pdx-granular {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 12px;
  padding-top: 14px;
  border-top: 1px solid var(--pdx-line);
}

.pdx-granular__group {
  display: grid;
  gap: 8px;
  align-content: start;
  padding: 12px;
  border-radius: 8px;
  background: var(--pdx-card-2);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.pdx-granular__group header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--pdx-muted);
}

.pdx-granular__group header strong {
  font-size: 18px;
  color: var(--pdx-text);
  letter-spacing: 0;
}

.pdx-bar {
  display: grid;
  gap: 4px;
}

.pdx-bar__top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: 13px;
}

.pdx-bar__top span {
  color: var(--pdx-muted);
  overflow-wrap: anywhere;
}

.pdx-bar__top strong {
  font-variant-numeric: tabular-nums;
}

.pdx-bar__track {
  height: 6px;
}

/* ─── Contract ────────────────────────────────────────── */

.pdx-contract-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.pdx-contract-hero__main {
  display: grid;
  gap: 2px;
}

.pdx-contract-hero__value {
  font-size: 32px;
  font-weight: 800;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.pdx-contract-hero__value.is-good { color: var(--pdx-green); }
.pdx-contract-hero__value.is-bad { color: var(--pdx-red); }

/* ─── Development ─────────────────────────────────────── */

.pdx-dev-chart {
  width: 100%;
  max-height: 200px;
}

.pdx-dev-chart__line {
  stroke: var(--pdx-cyan);
  stroke-width: 2.5;
}

.pdx-dev-chart__dot {
  fill: var(--pdx-cyan);
}

.pdx-dev-chart__value {
  fill: var(--pdx-text);
  font-size: 12px;
  font-weight: 700;
}

.pdx-dev-chart__label {
  fill: var(--pdx-muted);
  font-size: 11px;
}

.pdx-dev-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
}

.pdx-dev-list__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--pdx-card-2);
  font-size: 13px;
}

.pdx-dev-list__row span {
  color: var(--pdx-muted);
}

.pdx-dev-list__row strong {
  font-variant-numeric: tabular-nums;
}

.pdx-dev-list__row em {
  font-style: normal;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.pdx-dev-list__row em.is-up { color: var(--pdx-green); }
.pdx-dev-list__row em.is-down { color: var(--pdx-red); }
.pdx-dev-list__row em.is-flat { color: var(--pdx-muted); }

/* ─── Tables ──────────────────────────────────────────── */

.pdx-table-scroll {
  overflow-x: auto;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.pdx-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.pdx-table th,
.pdx-table td {
  padding: 9px 10px;
  text-align: right;
  white-space: nowrap;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.pdx-table th:first-child,
.pdx-table td:first-child,
.pdx-table .is-text {
  text-align: left;
}

.pdx-table th {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--pdx-muted);
  background: rgba(255, 255, 255, 0.03);
}

.pdx-table tbody tr:nth-child(even) {
  background: rgba(255, 255, 255, 0.015);
}

.pdx-table tbody tr.is-current {
  background: rgba(46, 230, 214, 0.07);
}

.pdx-table tbody tr.is-current td:first-child {
  box-shadow: inset 3px 0 0 var(--pdx-cyan);
}

.pdx-table tbody tr:last-child td {
  border-bottom: 0;
}

/* ─── Lists / feed / quotes ───────────────────────────── */

.pdx-list {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 6px;
}

.pdx-list li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--pdx-card-2);
  font-size: 13px;
}

.pdx-list li span {
  color: var(--pdx-muted);
  white-space: nowrap;
}

/* Trophy case (CareerAwardsCard): won-in-save | real NHL, gold for wins */
.pdx-trophies { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.pdx-trophies__col { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.pdx-trophies__head { font-size: 11px; font-weight: 900; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dd-gold-hi, #f8d58a); }
.pdx-trophies__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.pdx-trophies__list li {
  display: flex; justify-content: space-between; gap: 10px; padding: 6px 10px;
  border-left: 3px solid var(--dd-gold, #c98a3c); background: var(--pdx-card-2); font-size: 13px;
}
.pdx-trophies__list li strong { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pdx-trophies__list li span { color: var(--pdx-muted); white-space: nowrap; }
.pdx-trophies__list--near li { border-left-color: rgba(201, 138, 60, 0.4); }
@media (max-width: 900px) { .pdx-trophies { grid-template-columns: 1fr; } }

.pdx-feed {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 10px;
}

.pdx-feed > li {
  display: grid;
  gap: 6px;
  padding: 12px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: var(--pdx-card-2);
}

.pdx-feed__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.pdx-feed__head strong {
  font-size: 14px;
  font-weight: 750;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.pdx-feed__head time,
.pdx-feed__beat time {
  font-size: 12px;
  color: var(--pdx-muted-2);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.pdx-feed > li > p {
  font-size: 13px;
  color: var(--pdx-muted);
  line-height: 1.5;
}

.pdx-feed__beat {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: 10px;
  align-items: baseline;
}

.pdx-feed__beat p {
  font-size: 13px;
  line-height: 1.5;
  color: var(--pdx-muted);
}

.pdx-feed__beat p strong {
  color: var(--pdx-text);
  font-weight: 700;
}

.pdx-feed__beat em {
  font-style: normal;
  color: var(--pdx-muted-2);
}

.pdx-feed__more {
  font-size: 12px;
  color: var(--pdx-muted-2);
}

.pdx-quotes {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 10px;
}

.pdx-quotes blockquote {
  display: grid;
  gap: 8px;
  align-content: space-between;
  padding: 12px 14px;
  border-radius: 8px;
  border-left: 3px solid var(--pdx-cyan);
  background: var(--pdx-card-2);
}

.pdx-quotes blockquote p {
  font-size: 13px;
  line-height: 1.5;
}

.pdx-quotes footer {
  font-size: 12px;
  color: var(--pdx-muted);
}

.pdx-quotes footer strong {
  color: var(--pdx-text);
}

.pdx-inside {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px dashed rgba(233, 168, 60, 0.32);
  background: rgba(233, 168, 60, 0.05);
  font-size: 13px;
}

.pdx-inside ul {
  padding-left: 16px;
  display: grid;
  gap: 4px;
}

.pdx-inside li span {
  color: var(--pdx-muted);
}

/* ─── Moves ───────────────────────────────────────────── */

.pdx-move-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 8px;
}

.pdx-move-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  text-align: left;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: var(--pdx-card-2);
  cursor: pointer;
  transition: border-color 120ms ease, background 120ms ease;
}

.pdx-move-card:hover:not(:disabled) {
  border-color: var(--pdx-line-2);
  background: rgba(46, 230, 214, 0.08);
}

.pdx-move-card:disabled {
  opacity: 0.5;
  cursor: default;
}

.pdx-move-card__arrow {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 12px;
}

.pdx-move-card.is-up .pdx-move-card__arrow {
  color: var(--pdx-green);
  background: rgba(82, 223, 148, 0.12);
}

.pdx-move-card.is-down .pdx-move-card__arrow {
  color: var(--pdx-gold);
  background: rgba(233, 168, 60, 0.12);
}

.pdx-move-card__text {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.pdx-move-card__text strong {
  font-size: 14px;
  overflow-wrap: anywhere;
}

.pdx-move-card__text small {
  font-size: 12px;
  color: var(--pdx-muted);
}

.pdx-move-confirm {
  display: grid;
  gap: 8px;
  padding: 12px 14px;
  border-radius: 8px;
  border: 1px solid rgba(82, 223, 148, 0.32);
  background: rgba(82, 223, 148, 0.06);
}

.pdx-move-confirm.is-down {
  border-color: rgba(233, 168, 60, 0.36);
  background: rgba(233, 168, 60, 0.06);
}

.pdx-move-confirm__title {
  font-size: 14px;
  font-weight: 800;
}

.pdx-move-confirm__body {
  font-size: 13px;
  color: var(--pdx-muted);
}

.pdx-move-confirm__actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

/* ─── Responsive ──────────────────────────────────────── */

@media (max-width: 1100px) {
  .pdx-hero {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .pdx-hero__ratings {
    grid-column: 1 / -1;
  }
}

@media (max-width: 720px) {
  .pdx-modal {
    padding: 0;
  }

  .pdx-panel {
    max-height: 100dvh;
    height: 100dvh;
    border-radius: 0;
  }

  .pdx-hero {
    grid-template-columns: minmax(0, 1fr);
    gap: 14px;
  }

  .pdx-hero__photo {
    width: auto;
    justify-content: flex-start;
  }

  .pdx-grid-2 {
    grid-template-columns: minmax(0, 1fr);
  }

  .pdx-tile.is-wide {
    grid-column: 1 / -1;
  }

  .pdx-feed__beat {
    grid-template-columns: minmax(0, 1fr);
    gap: 2px;
  }
}


/* --- Box scores + game logs (bxs-*) ------------------------------------
   Same broadcast language as events/entryDraft/EntryDraft.css: ops navy
   panels, hairline grid, condensed display numerals, gold for the headline
   numbers, mono data columns. */

.bxs-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(11, 28, 67, 0.62);
}

.bxs-modal {
  width: min(980px, 100%);
  max-height: min(860px, calc(100vh - 32px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color: var(--ops-text, #e9f7fb);
  background: radial-gradient(circle at 20% 0%, rgba(46, 230, 214, 0.08), transparent 32%),
    radial-gradient(circle at 88% 12%, rgba(233, 168, 60, 0.06), transparent 28%),
    linear-gradient(180deg, var(--ops-black, #0d2555) 0%, var(--ops-navy-deep, #0b1d45) 100%);
  border: 1px solid var(--ops-grid, rgba(156, 218, 236, 0.14));
  border-radius: var(--radius-ops, 6px);
  font-family: var(--font-ops-ui, inherit);
}

.bxs-modal > header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--ops-grid, rgba(156, 218, 236, 0.14));
}

.bxs-modal > header p {
  margin: 0;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ops-gold, #e9a83c);
}

.bxs-modal > header h2 {
  margin: 2px 0 0;
  font-family: var(--dd-font-ui);
  font-size: 20px;
  font-weight: 700;
}

.bxs-close {
  border: 1px solid var(--ops-grid, rgba(156, 218, 236, 0.14));
  background: transparent;
  color: var(--ops-text-secondary, #8096a8);
  width: 30px;
  height: 30px;
  border-radius: var(--radius-ops, 6px);
  font-size: 18px;
  cursor: pointer;
}

.bxs-close:hover {
  color: var(--ops-text, #e9f7fb);
  border-color: var(--ops-cyan, #2ee6d6);
}

.bxs-modal-body {
  overflow-y: auto;
  padding: 12px 14px 16px;
}

.bxs-sheet,
.bxs-perf {
  display: flex;
  flex-direction: column;
  gap: 12px;
  color: var(--ops-text, #e9f7fb);
}

.bxs-hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 12px;
  background: var(--ops-panel, rgba(14, 40, 88, 0.94));
  border: 1px solid var(--ops-grid, rgba(156, 218, 236, 0.14));
  border-radius: var(--radius-ops, 6px);
}

.bxs-hero-team {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 10px;
  opacity: 0.72;
}

.bxs-hero-team.is-winner {
  opacity: 1;
}

.bxs-hero-abbr {
  font-family: var(--font-mono-data, "IBM Plex Mono", Consolas, monospace);
  font-size: 12px;
  color: var(--ops-text-secondary, #8096a8);
}

.bxs-hero-name {
  font-weight: 700;
  font-size: 14px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bxs-hero-score {
  font-family: var(--dd-font-ui);
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  line-height: 1;
  color: var(--ops-text, #e9f7fb);
}

.bxs-hero-team.is-winner .bxs-hero-score {
  color: var(--ops-gold, #e9a83c);
}

.bxs-hero-meta {
  grid-column: 1 / -1;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ops-text-secondary, #8096a8);
}

.bxs-grid-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}

.bxs-card {
  padding: 10px 12px;
  background: var(--ops-panel-2, rgba(12, 35, 52, 0.94));
  border: 1px solid var(--ops-grid, rgba(156, 218, 236, 0.14));
  border-radius: var(--radius-ops, 6px);
  min-width: 0;
}

.bxs-card h4,
.bxs-h {
  margin: 0 0 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ops-gold, #e9a83c);
}

.bxs-card h4 + table + h4 {
  margin-top: 10px;
}

.bxs-table-wrap {
  overflow-x: auto;
}

.bxs-log {
  max-height: 360px;
  overflow-y: auto;
}

.bxs-table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-mono-data, "IBM Plex Mono", Consolas, monospace);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.bxs-table th {
  position: sticky;
  top: 0;
  padding: 5px 6px;
  text-align: right;
  font-family: var(--font-ops-ui, inherit);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--ops-text-secondary, #8096a8);
  background: var(--ops-panel, rgba(14, 40, 88, 0.94));
  border-bottom: 1px solid var(--ops-grid-2, rgba(115, 229, 241, 0.25));
}

.bxs-table td {
  padding: 5px 6px;
  text-align: right;
  border-bottom: 1px solid rgba(156, 178, 196, 0.08);
  white-space: nowrap;
}

.bxs-table .bxs-l {
  text-align: left;
}

.bxs-table td.bxs-l em {
  margin-left: 6px;
  font-style: normal;
  font-size: 10px;
  color: var(--ops-text-secondary, #8096a8);
}

.bxs-table tr.is-scored td {
  background: rgba(233, 168, 60, 0.05);
}

.bxs-table tr.is-clickable {
  cursor: pointer;
}

.bxs-table tr.is-clickable:hover td {
  background: var(--ops-table-sel, rgba(46, 230, 214, 0.13));
}

.bxs-compact td,
.bxs-compact th {
  padding: 3px 6px;
}

.bxs-strong {
  font-weight: 700;
  color: var(--ops-gold, #e9a83c);
}

.bxs-good {
  color: #6fd39b;
}

.bxs-bad {
  color: var(--ops-injury, #ff606d);
}

.bxs-link {
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.bxs-link:hover {
  color: var(--ops-cyan, #2ee6d6);
}

.bxs-teamstats {
  display: flex;
  flex-direction: column;
}

.bxs-teamstats-head,
.bxs-teamstats-row {
  display: grid;
  grid-template-columns: 1fr 1.4fr 1fr;
  align-items: center;
  padding: 4px 0;
  border-bottom: 1px solid rgba(156, 178, 196, 0.08);
  font-size: 12px;
}

.bxs-teamstats-head {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--ops-text-secondary, #8096a8);
}

.bxs-teamstats-row span {
  text-align: center;
  color: var(--ops-text-secondary, #8096a8);
}

.bxs-teamstats-row b {
  font-family: var(--font-mono-data, "IBM Plex Mono", Consolas, monospace);
}

.bxs-teamstats-row b:last-child,
.bxs-teamstats-head span:last-child {
  text-align: right;
}

.bxs-period + .bxs-period {
  margin-top: 8px;
}

.bxs-period-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ops-cyan, #2ee6d6);
  margin-bottom: 2px;
}

.bxs-goal {
  display: grid;
  grid-template-columns: 44px 40px minmax(0, 1fr) auto auto;
  gap: 8px;
  align-items: baseline;
  padding: 5px 0;
  border-bottom: 1px solid rgba(156, 178, 196, 0.08);
  font-size: 12px;
}

.bxs-goal-time,
.bxs-goal-team,
.bxs-goal-score {
  font-family: var(--font-mono-data, "IBM Plex Mono", Consolas, monospace);
  color: var(--ops-text-secondary, #8096a8);
}

.bxs-goal-who small {
  color: var(--ops-text-secondary, #8096a8);
}

.bxs-goal-tags {
  display: inline-flex;
  gap: 4px;
}

.bxs-tag {
  display: inline-block;
  margin-left: 4px;
  padding: 0 5px;
  font-style: normal;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  border: 1px solid var(--ops-grid-2, rgba(115, 229, 241, 0.25));
  border-radius: 3px;
  color: var(--ops-cyan, #2ee6d6);
}

.bxs-tag.is-gold {
  color: var(--ops-gold, #e9a83c);
  border-color: rgba(233, 168, 60, 0.45);
}

.bxs-stars {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 8px;
}

.bxs-star {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  background: var(--ops-gold-soft, rgba(233, 168, 60, 0.14));
  border: 1px solid rgba(233, 168, 60, 0.3);
  border-radius: var(--radius-ops, 6px);
}

.bxs-star-rank {
  color: var(--ops-gold, #e9a83c);
  font-size: 12px;
  letter-spacing: 2px;
}

.bxs-star small {
  color: var(--ops-text-secondary, #8096a8);
  font-size: 11px;
}

.bxs-tabs {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.bxs-tabs button {
  border: 1px solid var(--ops-grid, rgba(156, 218, 236, 0.14));
  background: transparent;
  color: var(--ops-text-secondary, #8096a8);
  padding: 5px 10px;
  border-radius: var(--radius-ops, 6px);
  font-size: 12px;
  font-weight: 600;
  text-transform: capitalize;
  cursor: pointer;
  font-family: inherit;
}

.bxs-tabs button.is-active {
  color: var(--ops-text, #e9f7fb);
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--ops-grid-2, rgba(115, 229, 241, 0.25));
}

.bxs-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(104px, 1fr));
  gap: 6px;
}

.bxs-tile {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 7px 9px;
  background: var(--ops-panel-2, rgba(12, 35, 52, 0.94));
  border: 1px solid var(--ops-grid, rgba(156, 218, 236, 0.14));
  border-radius: var(--radius-ops, 6px);
  min-width: 0;
}

.bxs-tile span {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ops-text-secondary, #8096a8);
}

.bxs-tile strong {
  font-family: var(--dd-font-ui);
  font-size: 18px;
  line-height: 1.1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bxs-tile.is-gold strong {
  color: var(--ops-gold, #e9a83c);
}

.bxs-tile.is-good strong {
  color: #6fd39b;
}

.bxs-tile.is-bad strong {
  color: var(--ops-injury, #ff606d);
}

.bxs-note,
.bxs-empty {
  margin: 6px 0 0;
  font-size: 12px;
  color: var(--ops-text-secondary, #8096a8);
}

.nhlcal-game-boxscore-btn {
  margin-top: 8px;
  border: 1px solid rgba(233, 168, 60, 0.45);
  background: var(--ops-gold-soft, rgba(233, 168, 60, 0.14));
  color: var(--ops-gold, #e9a83c);
  padding: 5px 10px;
  border-radius: var(--radius-ops, 6px);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
}

@media (max-width: 640px) {
  .bxs-hero {
    grid-template-columns: 1fr;
  }

  .bxs-goal {
    grid-template-columns: 40px 36px minmax(0, 1fr);
  }

  .bxs-goal-tags,
  .bxs-goal-score {
    grid-column: 3;
  }
}

/* ==========================================================================
   SECTION: screens/ChemistryScreen.css
   ========================================================================== */
/* Chemistry — coaching-room analysis on Broadcast Ops base */

.chemistry-screen {
  --chem-warm: rgba(248, 213, 138, 0.12);
  --chem-warm-line: rgba(248, 213, 138, 0.28);
  --chem-panel: rgba(14, 40, 88, 0.92);
  --chem-line: var(--ops-grid);
  --chem-text: var(--ops-text);
  --chem-muted: var(--ops-text-secondary);

  min-width: 0;
  height: 100dvh;
  padding: 18px 22px 96px;
  color: var(--chem-text);
  background:
    radial-gradient(circle at 14% 6%, rgba(46, 230, 214, 0.07), transparent 38%),
    radial-gradient(circle at 88% 12%, var(--chem-warm), transparent 32%),
    linear-gradient(180deg, var(--ops-black) 0%, var(--ops-navy-deep) 100%);
  overflow-y: auto;
  font-family: var(--font-ops-ui);
}

.chemistry-hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--chem-line);
}

.chemistry-hero-identity {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.chemistry-team-logo {
  width: 64px;
  height: 64px;
  flex: 0 0 64px;
  display: grid;
  place-items: center;
}

.chemistry-team-logo img {
  width: 58px;
  height: 58px;
  object-fit: contain;
}

.chemistry-kicker {
  margin: 0 0 2px;
  color: var(--ops-cyan) !important;
  font-size: var(--type-phase-label-size) !important;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.chemistry-hero h1 {
  margin: 0 0 4px;
  font-family: var(--font-ops-head);
  font-size: 1.9rem;
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Projected-lines notice — the report is not describing the user's lineup. */
.chemistry-projection-note {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
  padding: 10px 14px;
  border: 1px solid rgba(233, 168, 60, 0.4);
  border-left: 3px solid var(--ops-gold);
  border-radius: var(--radius-hud);
  background: var(--ops-gold-soft);
  font-size: var(--type-compact-size);
  color: rgba(233, 247, 251, 0.88);
}

.chemistry-projection-note strong {
  color: var(--ops-gold);
}

.chemistry-projection-note button {
  flex-shrink: 0;
  border: 1px solid rgba(233, 168, 60, 0.55);
  background: rgba(233, 168, 60, 0.16);
  color: var(--ops-gold);
  border-radius: var(--radius-hud);
  padding: 7px 12px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
}

.chemistry-projection-note button:hover {
  background: rgba(233, 168, 60, 0.26);
}

.chemistry-hero p {
  margin: 0 0 4px;
  color: rgba(233, 247, 251, 0.88);
  font-size: var(--type-compact-size);
}

.chemistry-hero small {
  color: var(--chem-muted);
  font-size: var(--type-table-meta-size);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.chemistry-hero button {
  border: 1px solid var(--chem-line);
  background: rgba(14, 37, 86, 0.88);
  color: var(--chem-text);
  border-radius: var(--radius-hud);
  padding: 8px 14px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color var(--motion-micro), background var(--motion-micro);
}

.chemistry-hero button:hover {
  border-color: var(--ops-grid-strong);
  background: var(--ops-cyan-soft);
  color: var(--ops-cyan);
}

.chemistry-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 18px;
  margin-bottom: 14px;
  padding: 8px 12px;
  border: 1px solid var(--chem-line);
  border-radius: var(--radius-hud);
  background: rgba(13, 37, 85, 0.55);
}

.chemistry-legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--type-table-meta-size);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--chem-muted);
}

.chemistry-legend span::before {
  content: "";
  width: 14px;
  height: 2px;
  flex-shrink: 0;
}

.chemistry-legend .is-high::before { background: var(--ops-success); }
.chemistry-legend .is-mid::before { background: var(--ops-gold); }
.chemistry-legend .is-low::before { background: var(--ops-injury); }

.chemistry-room-card,
.chemistry-line-card {
  background: var(--chem-panel);
  border: 1px solid var(--chem-line);
  border-radius: var(--radius-control);
  padding: 12px 14px;
  box-shadow: var(--depth-registered);
}

.chemistry-room-card {
  border-left: 3px solid var(--ops-cyan);
}

.chemistry-group {
  margin-top: 14px;
}

.chemistry-room-header,
.chemistry-line-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
}

.chemistry-room-header h3,
.chemistry-line-top > span:first-child {
  font-family: var(--font-ops-head);
  font-size: 1.1rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.chemistry-section-title {
  margin: 0 0 8px;
  font-family: var(--font-ops-head);
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ops-cyan);
}

.chemistry-grid {
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.chemistry-meter {
  padding: 6px 0;
}

.chemistry-meter-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
  font-size: var(--type-table-meta-size);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--chem-muted);
}

/* Numerals in Inter, tabular — same as the Line Builder board. */
.chemistry-meter-row strong {
  color: var(--chem-text);
  font-weight: 900;
  font-variant-numeric: tabular-nums;
}

/* Five-notch strength notation. Tone states the verdict so the board can be
   scanned for friction without reading a single numeral. */
.chemistry-notation {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 3px;
  height: 3px;
}

.chemistry-notation i {
  background: rgba(255, 255, 255, 0.09);
}

.chemistry-meter[data-tone="high"] .chemistry-notation i.is-on { background: var(--ops-success); }
.chemistry-meter[data-tone="mid"] .chemistry-notation i.is-on { background: var(--ops-gold); }
.chemistry-meter[data-tone="low"] .chemistry-notation i.is-on { background: var(--ops-injury); }

.chemistry-meter[data-tone="low"] .chemistry-meter-row strong { color: var(--ops-injury); }

/* Link chain — spatial relationship between linemates */
.chemistry-line-players {
  display: grid;
  gap: 3px;
  margin: 4px 0 0;
  padding: 0;
  list-style: none;
}

.chemistry-node {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}



.chemistry-connection-card .chemistry-node {
  grid-template-columns: minmax(0, 1fr);
}

.chemistry-node strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--chem-text);
  font-weight: 700;
}

.chemistry-node em {
  font-style: normal;
  font-size: var(--type-table-meta-size);
  font-weight: 800;
  letter-spacing: 0.06em;
  color: var(--chem-muted);
}

/* Relationship linkage: a short tactical tape between nameplates. Low tone
   becomes dashed concern tape instead of a solid bar. */
.chemistry-link-mark {
  width: 18px;
  height: 2px;
  flex-shrink: 0;
  background: var(--chem-muted);
  box-shadow: 0 0 0 1px transparent;
  position: relative;
}

.chemistry-link-mark::before,
.chemistry-link-mark::after {
  content: "";
  position: absolute;
  top: -2px;
  width: 2px;
  height: 6px;
  background: inherit;
  opacity: 0.85;
}

.chemistry-link-mark::before { left: 0; }
.chemistry-link-mark::after { right: 0; }

.chemistry-line-card[data-tone="high"] .chemistry-link-mark { background: var(--ops-success); }
.chemistry-line-card[data-tone="mid"] .chemistry-link-mark { background: var(--ops-gold); }
.chemistry-line-card[data-tone="low"] {
  background: linear-gradient(90deg, rgba(255, 92, 92, 0.07), var(--chem-panel) 40%);
}
.chemistry-line-card[data-tone="low"] .chemistry-link-mark {
  background: repeating-linear-gradient(90deg, var(--ops-injury) 0 3px, transparent 3px 6px);
}

/* Unit cards are board entries, not floating cards: flat, ruled, with the
   verdict carried on a left rail. */
.chemistry-line-card {
  border-radius: var(--radius-ops);
  box-shadow: none;
  border-left: 3px solid var(--chem-muted);
}

.chemistry-line-card[data-tone="high"] { border-left-color: var(--ops-success); }
.chemistry-line-card[data-tone="mid"] { border-left-color: var(--ops-gold); }
.chemistry-line-card[data-tone="low"] { border-left-color: var(--ops-injury); }

.chemistry-line-top > span:first-child {
  font-family: var(--font-ops-head);
  font-size: 1.1rem;
  color: var(--ops-text);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Cards in a row share a height, and the worksheet sits on the bottom rule so
   meters line up across cards even when one unit has extra notes. */
.chemistry-grid--units > .chemistry-line-card,
.chemistry-connection-card {
  display: flex;
  flex-direction: column;
}



.chemistry-line-card .chemistry-chip-row {
  margin: 8px 0;
}

.chemistry-connection-card {
  gap: 8px;
  justify-content: space-between;
}

/* Scheme-fit notation reads as a two-column coaching worksheet under a rule. */
.chemistry-line-card .chemistry-worksheet {
  margin-top: auto;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 2px 18px;
  padding-top: 6px;
  border-top: 1px solid var(--chem-line);
}

.chemistry-line-card .chemistry-meter {
  padding: 3px 0;
}

/* Column rules so a value never reads as part of the next label. */
.chemistry-line-card .chemistry-meter:nth-child(even),
.chemistry-room-card .chemistry-meter {
  padding-left: 16px;
  border-left: 1px solid var(--chem-line);
}

.chemistry-room-card .chemistry-grid {
  column-gap: 22px;
}

/* Score marks — not pills */
.chemistry-score-mark,
.chemistry-score-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  border: 0;
  background: transparent;
  font-size: var(--type-table-meta-size);
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
}

.chemistry-score-mark::before,
.chemistry-score-badge::before {
  content: "";
  width: 10px;
  height: 2px;
  flex-shrink: 0;
}

.chemistry-score-elite { color: var(--ops-success); }
.chemistry-score-elite::before { background: var(--ops-success); width: 12px; }

/* Three colour bands, same as the legend and the Line Builder:
   green 75+ (Strong/Elite), gold 45–74 (Connected/Neutral), red <45. */
.chemistry-score-strong { color: var(--ops-success); }
.chemistry-score-strong::before { background: var(--ops-success); }

.chemistry-score-connected { color: var(--ops-gold); }
.chemistry-score-connected::before { background: var(--ops-gold); }

.chemistry-score-neutral { color: var(--ops-gold); }
.chemistry-score-neutral::before { background: var(--ops-gold); }

.chemistry-score-awkward { color: var(--ops-injury); }
.chemistry-score-awkward::before { background: var(--ops-injury); }

.chemistry-score-broken { color: var(--ops-injury); }
.chemistry-score-broken::before { background: var(--ops-injury); width: 12px; height: 10px; clip-path: polygon(50% 0, 100% 100%, 0 100%); }

.chemistry-line-players {
  margin-top: 4px;
  color: var(--chem-muted);
  font-size: var(--type-compact-size);
  line-height: 1.4;
}

.chemistry-line-card > p {
  margin: 6px 0 0;
  font-size: var(--type-compact-size);
  color: rgba(233, 247, 251, 0.78);
  line-height: 1.4;
}

.chemistry-risk {
  color: rgba(255, 160, 140, 0.92);
  font-weight: 700;
}

.chemistry-mark-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
  margin-top: 8px;
}

.chemistry-factor-mark,
.chemistry-concern-mark,
.chemistry-factor-chip,
.chemistry-concern-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: var(--type-table-meta-size);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--chem-muted);
  border: 0;
  background: transparent;
  padding: 0;
}

.chemistry-factor-mark::before,
.chemistry-factor-chip::before {
  content: "";
  width: 6px;
  height: 6px;
  background: var(--ops-success);
  flex-shrink: 0;
}

.chemistry-concern-mark::before,
.chemistry-concern-chip::before {
  content: "";
  width: 6px;
  height: 6px;
  background: var(--ops-injury);
  flex-shrink: 0;
}

.chemistry-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
}

.chemistry-empty {
  margin-top: 16px;
  border: 1px dashed var(--chem-line);
  border-radius: var(--radius-control);
  background: rgba(13, 37, 85, 0.55);
  padding: 16px 18px;
  color: var(--chem-muted);
  font-size: var(--type-compact-size);
  max-width: 420px;
}

.chemistry-empty::before {
  content: "CHEMISTRY BOARD · IDLE";
  display: block;
  margin-bottom: 6px;
  color: var(--ops-cyan);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.14em;
}

/* ==========================================================================
   SECTION: screens/CapLedger.css
   ========================================================================== */
.cap-ledger-screen {
  --cap-bg: var(--ops-navy-deep);
  --cap-panel: var(--ops-panel);
  --cap-panel-strong: rgba(13, 35, 80, 0.96);
  --cap-panel-soft: rgba(255, 255, 255, 0.03);
  --cap-line: var(--ops-grid);
  --cap-line-strong: var(--ops-grid-strong);
  --cap-cyan: var(--ops-cyan);
  --cap-cyan-bright: #7cf0ff;
  --cap-gold: var(--ops-gold);
  --cap-gold-bright: #f4c66e;
  --cap-text: var(--ops-text);
  --cap-muted: var(--ops-text-secondary);
  --cap-muted-strong: rgba(233, 246, 255, 0.74);
  --cap-danger: var(--ops-injury);
  --cap-danger-soft: var(--ops-injury-soft);
  --cap-warning: var(--ops-gold);
  --cap-warning-soft: var(--ops-gold-soft);
  --cap-good: var(--ops-success);
  --cap-good-soft: var(--ops-success-soft);
  --cap-blue: var(--ops-info);
  --cap-blue-soft: var(--ops-info-soft);

  min-height: 0;
  height: 100%;
  padding: 14px 20px 16px;
  color: var(--cap-text);
  background:
    radial-gradient(circle at 12% 0%, rgba(0, 216, 223, 0.12), transparent 32%),
    radial-gradient(circle at 88% 4%, rgba(124, 190, 231, 0.08), transparent 34%),
    linear-gradient(180deg, #0d224e 0%, #0c1c43 62%, #0b1a3e 100%);
  font-family: var(--font-ops-ui);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
  overflow: hidden;
}

.cap-ledger-screen *,
.cap-ledger-screen *::before,
.cap-ledger-screen *::after {
  box-sizing: border-box;
}

.cap-office-screen {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

/* TOP BAR */

.cap-ledger-hero,
.cap-office-topbar {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 0;
  min-height: 78px;
  padding: 0;
  border: 1px solid var(--cap-line);
  border-radius: var(--radius-control);
  background: var(--cap-panel);
  box-shadow: var(--depth-registered);
}

.cap-ledger-hero::after,
.cap-office-topbar::after {
  content: "";
  position: absolute;
  right: -24px;
  top: -36px;
  width: 210px;
  height: 210px;
  opacity: 0.055;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
  filter: saturate(1.1);
}

.cap-ledger-hero.has-logo::after,
.cap-office-topbar.has-logo::after {
  background-image: var(--team-logo-url);
}

.cap-office-team {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding: 12px 16px;
  border-right: 1px solid var(--cap-line);
}

.cap-office-back {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-hud);
  border: 1px solid var(--cap-line);
  background: rgba(255, 255, 255, 0.04);
  color: var(--cap-text);
  font-size: 18px;
  font-weight: 900;
  cursor: pointer;
  transition:
    border-color var(--motion-micro),
    background var(--motion-micro);
}

.cap-office-back:hover {
  border-color: var(--cap-line-strong);
  background: var(--ops-cyan-soft);
}

.cap-office-logo {
  width: 50px;
  height: 50px;
  flex: 0 0 auto;
  object-fit: contain;
  border-radius: 6px;
  padding: 6px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background:
    radial-gradient(circle at 50% 20%, rgba(255, 255, 255, 0.08), transparent 58%),
    rgba(255, 255, 255, 0.035);
  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.28);
}

.cap-office-logo-fallback {
  display: grid;
  place-items: center;
  color: var(--cap-cyan);
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.cap-ledger-hero-main {
  min-width: 0;
  padding: 12px 16px;
  flex: 1;
}

.cap-ledger-hero-main .eyebrow {
  margin: 0 0 4px;
  font-size: var(--type-phase-label-size);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--cap-cyan);
  font-weight: 900;
}

.cap-ledger-hero-main h1 {
  margin: 0;
  max-width: 360px;
  overflow: hidden;
  color: var(--cap-text);
  font-size: clamp(22px, 3vw, 34px);
  font-weight: 950;
  letter-spacing: -0.04em;
  line-height: 0.95;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cap-ledger-hero-main p {
  margin: 6px 0 0;
  color: var(--cap-muted);
  font-size: 13px;
}

.cap-ledger-hero-stats,
.cap-office-metrics {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(3, minmax(96px, 1fr));
  gap: 0;
  min-width: min(440px, 48vw);
  border-left: 1px solid var(--cap-line);
}

.cap-ledger-hero-stats > div,
.cap-office-metrics > div {
  min-height: 78px;
  padding: 10px 14px;
  border-radius: 0;
  border: 0;
  border-right: 1px solid var(--cap-line);
  background: rgba(13, 35, 80, 0.55);
  box-shadow: none;
}

.cap-ledger-hero-stats > div:last-child,
.cap-office-metrics > div:last-child {
  border-right: 0;
}

.cap-ledger-hero-stats > div.is-danger,
.cap-office-metrics > div.is-danger {
  border-color: rgba(255, 111, 126, 0.48);
  background:
    linear-gradient(180deg, rgba(255, 111, 126, 0.18), rgba(255, 111, 126, 0.06));
}

.cap-ledger-hero-stats span,
.cap-office-metrics span {
  display: block;
  margin-bottom: 4px;
  color: var(--cap-muted);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.cap-ledger-hero-stats strong,
.cap-office-metrics strong {
  display: block;
  color: var(--cap-gold-bright);
  font-family: var(--font-mono-data);
  font-size: clamp(17px, 2vw, 22px);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.cap-office-metrics > div.is-danger strong {
  color: #ffb4c0;
}

.cap-metric-roster em {
  display: block;
  margin-top: 5px;
  color: var(--cap-muted);
  font-size: 11px;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.03em;
  line-height: 1.25;
}

/* TABS */

.cap-ledger-tabs,
.cap-office-tabs {
  display: flex;
  align-items: stretch;
  gap: 0;
  width: fit-content;
  padding: 0;
  margin: 0;
  border: 1px solid var(--cap-line);
  border-radius: var(--radius-hud);
  background: rgba(0, 0, 0, 0.22);
  box-shadow: none;
}

.cap-ledger-tab {
  min-height: 36px;
  min-width: 82px;
  padding: 0 14px;
  border-radius: 0;
  border: 0;
  border-right: 1px solid var(--cap-line);
  background: transparent;
  color: var(--cap-muted);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition:
    color var(--motion-micro),
    background var(--motion-micro);
}

.cap-ledger-tab:last-child {
  border-right: 0;
}

.cap-ledger-tab:hover {
  color: var(--cap-text);
  background: rgba(255, 255, 255, 0.045);
}

.cap-ledger-tab-active {
  color: var(--cap-text);
  background: var(--ops-cyan-soft);
  box-shadow: inset 3px 0 0 var(--cap-cyan);
}

/* MAIN PANELS */

.cap-ledger-main,
.cap-office-main {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.cap-office-panel {
  border: 1px solid var(--cap-line);
  border-radius: var(--radius-control);
  background: var(--cap-panel);
  box-shadow: var(--depth-registered);
}

.cap-office-main > .cap-office-panel {
  flex: 1;
  min-height: 0;
  overflow: auto;
}

.cap-office-main > .cap-board-panel {
  overflow: hidden;
}

.cap-board-layout {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.cap-board-layout > .cap-board-panel {
  flex: 1;
  min-height: 0;
}

.cap-board-layout--desk > .cap-board-panel {
  flex: 0 1 36%;
  min-height: 200px;
  max-height: 38vh;
}

.cap-board-layout--desk .cap-nego-dock {
  flex: 1 1 64%;
  min-height: min(68vh, 680px);
}

/* TOOLBAR */

.cap-ledger-toolbar,
.cap-board-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
}

.cap-search,
.cap-select {
  min-height: 40px;
  border-radius: 10px;
  border: 1px solid var(--cap-line);
  background: rgba(0, 0, 0, 0.36);
  color: var(--cap-text);
  outline: none;
  padding: 0 13px;
  font-size: 13px;
  font-weight: 700;
}

.cap-search {
  flex: 1 1 250px;
  min-width: 170px;
}

.cap-search::placeholder {
  color: rgba(138, 160, 182, 0.72);
}

.cap-search:focus,
.cap-select:focus {
  border-color: rgba(0, 216, 223, 0.55);
  box-shadow: 0 0 0 3px rgba(0, 216, 223, 0.1);
}

.cap-filter-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.cap-filter-pill {
  min-height: 32px;
  padding: 0 10px;
  border-radius: var(--radius-hud);
  border: 1px solid var(--cap-line);
  background: rgba(255, 255, 255, 0.03);
  color: var(--cap-muted);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  cursor: pointer;
  transition:
    color var(--motion-micro),
    border-color var(--motion-micro),
    background var(--motion-micro);
}

.cap-filter-pill:hover {
  color: var(--cap-text);
  border-color: var(--cap-line-strong);
  transform: none;
}

.cap-filter-pill.is-active {
  color: var(--cap-text);
  border-color: var(--cap-cyan);
  background: var(--ops-cyan-soft);
}

/* CONTRACT BOARD */

.cap-board-panel {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.cap-board-head {
  display: grid;
  grid-template-columns: minmax(300px, 1fr) 84px 92px 132px 92px 200px;
  gap: 14px;
  align-items: center;
  padding: 12px 18px;
  color: rgba(138, 160, 182, 0.72);
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(255, 255, 255, 0.065);
}

.cap-contract-list,
.cap-board-list {
  display: grid;
  gap: 0;
  flex: 1;
  min-height: 0;
  padding: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: rgba(0, 216, 223, 0.32) rgba(12, 33, 77, 0.72);
}

.cap-contract-list::-webkit-scrollbar,
.cap-board-list::-webkit-scrollbar,
.cap-action-panel::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

.cap-contract-list::-webkit-scrollbar-track,
.cap-board-list::-webkit-scrollbar-track,
.cap-action-panel::-webkit-scrollbar-track {
  background: rgba(12, 33, 77, 0.72);
  border-radius: 999px;
}

.cap-contract-list::-webkit-scrollbar-thumb,
.cap-board-list::-webkit-scrollbar-thumb,
.cap-action-panel::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(0, 216, 223, 0.32);
  border: 1px solid rgba(0, 216, 223, 0.08);
}

.cap-contract-list::-webkit-scrollbar-thumb:hover,
.cap-board-list::-webkit-scrollbar-thumb:hover,
.cap-action-panel::-webkit-scrollbar-thumb:hover {
  background: rgba(0, 216, 223, 0.48);
}

/* Register lines, not contract cards: hairline-ruled rows so payroll can be
   read down the page and twice as many deals fit on a 768px screen. */
.cap-contract-card,
.cap-contract-row {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(300px, 1fr) 84px 92px 132px 92px 200px;
  gap: 14px;
  align-items: center;
  min-height: 54px;
  padding: 8px 16px;
  border-radius: 0;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.055);
  border-left: 3px solid transparent;
  background: transparent;
  color: var(--cap-text);
  cursor: pointer;
  text-align: left;
  box-shadow: none;
  transition:
    border-color var(--motion-micro),
    background var(--motion-micro);
}

.cap-contract-card:hover,
.cap-contract-row:hover {
  background: rgba(46, 230, 214, 0.05);
  box-shadow: none;
  transform: none;
}

.cap-contract-row.is-selected {
  background: var(--ops-cyan-soft);
  border-left-color: var(--cap-cyan);
}

/* Zebra banding carries the eye across a wide money row. */
.cap-contract-list .cap-contract-row:nth-child(even) {
  background: rgba(255, 255, 255, 0.014);
}

.cap-stripe-bad,
.cap-contract-card.cap-stripe-bad {
  border-left-color: var(--cap-danger);
}

.cap-stripe-bargain,
.cap-contract-card.cap-stripe-bargain {
  border-left-color: var(--cap-good);
}

.cap-stripe-core,
.cap-contract-card.cap-stripe-core {
  border-left-color: var(--cap-gold-bright);
}

.cap-stripe-neutral,
.cap-contract-card.cap-stripe-neutral {
  border-left-color: rgba(255, 255, 255, 0.14);
}

.cap-contract-card.stripe-ufa,
.cap-contract-card.cap-stripe-ufa {
  border-left-color: var(--cap-warning);
}

.cap-contract-card.stripe-rfa,
.cap-contract-card.cap-stripe-rfa {
  border-left-color: var(--cap-blue);
}

.cap-contract-card.stripe-overpaid,
.cap-contract-card.cap-stripe-overpaid {
  border-left-color: var(--cap-danger);
}

.cap-contract-player {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.cap-card-headshot,
.cap-contract-headshot {
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.06);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.07);
}

.cap-contract-meta,
.cap-contract-row__identity {
  min-width: 0;
}

.cap-contract-row__name,
.cap-contract-meta h3,
.cap-contract-meta .player-name {
  display: block;
  max-width: 100%;
  overflow: hidden;
  margin: 0;
  color: var(--cap-text);
  font-size: 15px;
  font-weight: 900;
  letter-spacing: -0.01em;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Identity reads on one register line: name, then position and age inline. */
.cap-contract-row .cap-contract-meta {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.cap-contract-row__sub,
.cap-contract-subline {
  display: block;
  margin-top: 0;
  color: var(--cap-muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.cap-contract-row__cell {
  min-width: 0;
}

.cap-contract-row__cell strong {
  display: block;
  color: var(--cap-text);
  font-family: var(--font-mono-data);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

/* The column header already names the figure; repeating OVR / AAV / YR on
   every row tripled the ink for no information. */
.cap-contract-row__cell em {
  display: none;
}

.cap-contract-row__ext {
  display: block;
  margin-top: 4px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #f0c86a;
  white-space: nowrap;
}

.cap-contract-row__pos {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border: 0;
  background: transparent;
  color: var(--cap-cyan);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.cap-contract-row__ovr strong {
  color: var(--cap-gold-bright);
  font-size: 14px;
  font-family: var(--font-mono-data);
  font-variant-numeric: tabular-nums;
}

.cap-contract-row__tags {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  min-width: 0;
}

/* Status marks: a rail-and-label pair, not a pill collection. */
.cap-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 18px;
  padding: 0;
  border-radius: 0;
  border: 0;
  background: transparent;
  color: var(--cap-muted-strong);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.07em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
}

.cap-chip::before {
  content: "";
  width: 8px;
  height: 2px;
  flex-shrink: 0;
  background: currentColor;
  opacity: 0.75;
}

.cap-chip-danger { color: #ff8f9c; }
.cap-chip-warning { color: #f4c66e; }
.cap-chip-good { color: rgba(160, 190, 205, 0.78); }

/* STAT CARDS */

.cap-ledger-stat-card {
  border-radius: 6px;
  border: 1px solid var(--cap-line);
  background:
    linear-gradient(180deg, rgba(16, 33, 76, 0.92), rgba(13, 28, 65, 0.88));
  box-shadow:
    0 16px 34px rgba(0, 0, 0, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.cap-ledger-stat-card span {
  display: block;
  color: var(--cap-muted);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* CAP TAB */

.cap-pressure-panel {
  padding: 14px;
}

.cap-meter-board {
  position: relative;
  overflow: hidden;
  display: grid;
  gap: 12px;
  min-height: 140px;
  padding: 18px 20px;
  margin-bottom: 10px;
  border-radius: var(--radius-control);
  border: 1px solid var(--cap-line);
  border-left: 3px solid var(--cap-cyan);
  background: rgba(13, 35, 80, 0.72);
  box-shadow: var(--depth-registered);
}

/* Over the ceiling is a filing condition, not a lightshow. */
.cap-meter-board.is-over {
  border-color: rgba(255, 111, 126, 0.42);
  border-left-color: #ff6f7e;
  background: rgba(29, 30, 69, 0.55);
}

.cap-meter-board__main {
  position: relative;
  z-index: 1;
}

.cap-meter-label {
  margin: 0;
  color: var(--cap-cyan);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.cap-meter-board.is-over .cap-meter-label {
  color: #ffb4b0;
}

.cap-meter-board h2 {
  margin: 4px 0 2px;
  color: var(--cap-text);
  font-family: var(--font-mono-data);
  font-size: clamp(36px, 6vw, 64px);
  font-weight: 800;
  letter-spacing: -0.06em;
  line-height: 0.9;
  font-variant-numeric: tabular-nums;
}

.cap-meter-pct {
  margin: 0;
  color: var(--cap-muted);
  font-size: 13px;
  font-weight: 750;
}

/* Department signature: the cap ceiling ruler. Payroll is read against a
   measured scale with quarter ticks and a hard ceiling at the right edge,
   rather than against a decorative progress gradient. */
.cap-bar {
  position: relative;
  height: 8px;
  overflow: hidden;
  margin: 0;
  border-radius: 0;
  background: rgba(255, 255, 255, 0.06);
  border-right: 2px solid var(--cap-gold);
  box-shadow: none;
}

.cap-bar::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.22) 0 1px,
    transparent 1px 25%
  );
}

.cap-bar-hero {
  position: relative;
  z-index: 1;
  height: 10px;
}

.cap-bar-fill {
  height: 100%;
  border-radius: 0;
  background: var(--cap-good);
  box-shadow: none;
}

.cap-bar-fill.is-danger {
  background: #ff6f7e;
}

.cap-bar-fill.is-tight {
  background: #f4c66e;
}

.cap-bar-fill.is-warning {
  background: #d9a441;
}

.cap-bar-fill.is-comfortable {
  background: var(--cap-good);
}

.cap-ledger-grid,
.cap-cap-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  margin-bottom: 0;
  border: 1px solid var(--cap-line);
  border-radius: var(--radius-control);
  overflow: hidden;
}

.cap-tile,
.cap-ledger-stat-card {
  min-height: 72px;
  padding: 12px 14px;
  border-right: 1px solid var(--cap-line);
  border-radius: 0;
  background: rgba(13, 35, 80, 0.55);
  box-shadow: none;
}

.cap-tile:last-child,
.cap-ledger-stat-card:last-child {
  border-right: 0;
}

.cap-tile strong,
.cap-ledger-stat-card strong {
  display: block;
  margin-top: 6px;
  color: var(--cap-gold-bright);
  font-family: var(--font-mono-data);
  font-size: clamp(17px, 2vw, 24px);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.cap-tile.is-danger strong {
  color: #ffb4b0;
}

.cap-ledger-attention,
.cap-warning-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

/* ACTION PANEL */

.cap-action-panel {
  position: relative;
  flex: 0 0 auto;
  min-height: clamp(220px, 30vh, 340px);
  display: grid;
  grid-template-columns: minmax(240px, 280px) 1fr minmax(200px, 260px);
  grid-template-rows: auto auto auto;
  gap: 12px 16px;
  align-items: stretch;
  padding: 16px 18px;
  border-radius: var(--radius-control);
  border: 1px solid var(--cap-line);
  border-left: 3px solid var(--cap-cyan);
  background:
    radial-gradient(120% 90% at 8% 0%, rgba(30, 58, 92, 0.28), transparent 58%),
    linear-gradient(180deg, rgba(12, 28, 46, 0.94), rgba(13, 33, 79, 0.98));
  box-shadow: var(--depth-registered), 0 0 24px rgba(46, 230, 214, 0.08);
}

.cap-action-panel--empty {
  flex: 0 0 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 18px;
  border-left-width: 1px;
}

.cap-action-panel--empty p {
  margin: 0;
  color: var(--cap-muted);
  font-size: 13px;
  font-weight: 750;
}

.cap-action-panel__close {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid var(--cap-line);
  border-radius: 2px;
  background: rgba(0, 0, 0, 0.32);
  color: var(--cap-text);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
}

.cap-action-panel__player {
  grid-column: 1;
  grid-row: 1 / span 3;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  min-width: 0;
  padding-right: 12px;
}

.cap-photo-well--lg {
  width: 72px;
  height: 72px;
}

.cap-action-panel__identity {
  min-width: 0;
}

.cap-action-panel__role {
  margin: 6px 0 0;
  color: var(--cap-muted);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.cap-action-panel__ratings {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 6px;
  margin: 8px 0 0;
  font-size: 15px;
}

.cap-action-panel__dot {
  color: var(--cap-muted);
}

.cap-action-panel__dossier {
  grid-column: 2;
  grid-row: 1 / span 2;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(118px, 1fr));
  gap: 10px;
  align-content: start;
}

.cap-dossier-tile {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 58px;
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid rgba(148, 185, 205, 0.16);
  background: rgba(12, 33, 77, 0.55);
  box-shadow: var(--depth-registered), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.cap-dossier-tile__label {
  font-family: var(--cap-ed-head, var(--font-broadcast-display));
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--cap-muted);
}

.cap-dossier-tile .cap-num-pop {
  font-size: 15px;
  line-height: 1.1;
  word-break: break-word;
}

.cap-action-panel__ineligible {
  display: block;
  max-width: 220px;
  color: var(--cap-muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.35;
  text-align: right;
}

.cap-action-panel__headshot {
  width: 56px;
  height: 56px;
  flex: 0 0 auto;
}

.cap-action-panel__player h3 {
  margin: 0;
  color: var(--cap-text);
  font-size: 22px;
  font-weight: 950;
  letter-spacing: -0.05em;
  line-height: 1;
}

.cap-action-panel__player p {
  margin: 6px 0 0;
  color: var(--cap-muted);
  font-size: 12px;
  font-weight: 750;
}

.cap-action-panel__stats {
  display: none;
  flex-wrap: wrap;
  gap: 10px;
}

/* Contract facts are register lines on a ruled sheet: ten equal tiles read as a
   dashboard and pushed the free-agent board down to six rows. */
.cap-action-panel__stats div {
  min-width: 84px;
  display: flex;
  align-items: baseline;
  justify-content: flex-start;
  gap: 7px;
  padding: 3px 12px 3px 0;
  border-radius: 0;
  border: 0;
  border-bottom: 1px solid var(--cap-line);
  background: transparent;
}

.cap-action-panel__stats span {
  display: block;
  margin-bottom: 0;
  color: var(--cap-muted);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.cap-action-panel__stats strong {
  color: var(--cap-text);
  font-size: 13px;
  font-weight: 950;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.cap-action-panel__tags {
  grid-column: 2;
  grid-row: 3;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.cap-action-panel__actions {
  grid-column: 3;
  grid-row: 1 / span 2;
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  align-content: stretch;
  justify-content: flex-start;
  gap: 8px;
  max-width: none;
}

.cap-edraft-action-btn {
  min-height: 40px;
  border-radius: 0;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  font-family: var(--cap-ed-head, var(--font-broadcast-display));
  font-size: 11px;
  font-weight: 1000;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  box-shadow: var(--depth-registered);
}

.cap-action-panel__moves {
  grid-column: 1 / -1;
  margin-top: 10px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.cap-action-panel__moves h4 {
  margin: 0 0 6px;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cap-muted, #9aa3b2);
}

.cap-action-panel__moves-meta,
.cap-action-panel__moves-note,
.cap-action-panel__moves-error {
  margin: 0 0 8px;
  font-size: 12px;
  color: var(--cap-muted, #9aa3b2);
}

.cap-action-panel__moves-error {
  color: #f0a0a0;
}

.cap-action-panel__moves .cap-action-panel__actions {
  grid-column: auto;
  grid-row: auto;
  justify-content: flex-start;
  max-width: none;
}

.cap-action-btn {
  min-height: 40px;
  padding: 0 16px;
  border-radius: var(--radius-hud, 4px);
  border: 1px solid rgba(0, 216, 223, 0.35);
  background:
    linear-gradient(180deg, rgba(0, 216, 223, 0.16), rgba(0, 216, 223, 0.08));
  color: var(--cap-text);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  cursor: pointer;
  transition:
    transform 0.16s ease,
    border-color 0.16s ease,
    background 0.16s ease;
}

.cap-action-btn:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: rgba(0, 216, 223, 0.56);
  background:
    linear-gradient(180deg, rgba(0, 216, 223, 0.23), rgba(0, 216, 223, 0.11));
}

.cap-action-btn:disabled {
  opacity: 0.48;
  cursor: not-allowed;
}

.cap-action-btn--danger {
  border-color: rgba(255, 111, 126, 0.46);
  background:
    linear-gradient(180deg, rgba(255, 111, 126, 0.18), rgba(255, 111, 126, 0.08));
  color: #ffd0d6;
}

.cap-action-btn--danger:hover:not(:disabled) {
  border-color: rgba(255, 111, 126, 0.62);
  background:
    linear-gradient(180deg, rgba(255, 111, 126, 0.26), rgba(255, 111, 126, 0.12));
}

/* EMPTY / ERROR */

.cap-empty-state {
  padding: 14px 18px;
  border-radius: var(--radius-hud);
  border: 1px dashed var(--cap-line);
  background: rgba(255, 255, 255, 0.02);
  color: var(--cap-muted);
  text-align: center;
  font-size: 12px;
  font-weight: 700;
}

.cap-error {
  border-color: rgba(255, 111, 126, 0.42);
  background: rgba(255, 111, 126, 0.08);
  color: #ffb4b0;
}

/* LEGACY SUPPORT */

.cap-ledger-back {
  display: none;
}

.cap-contract-topline,
.cap-contract-actions,
.cap-breakdown-grid,
.cap-breakdown-row {
  display: none;
}

.cap-ovr-badge {
  min-width: 46px;
  text-align: center;
  padding: 4px 8px;
  border-radius: 10px;
  border: 1px solid rgba(0, 216, 223, 0.28);
  background: rgba(0, 216, 223, 0.08);
}

.cap-contract-money {
  margin: 5px 0 0;
  color: rgba(233, 246, 255, 0.82);
  font-size: 13px;
  font-weight: 700;
}

.player-name.elite-name {
  color: #f8d46b;
  text-shadow: 0 0 14px rgba(248, 212, 107, 0.2);
}

.player-name.star-name {
  color: #78d7ff;
}

.player-name.core-name {
  color: #f4f7fb;
}

.player-name.depth-name {
  color: #aeb6c2;
}

.player-name.prospect-name {
  color: #9ed8b8;
}

.player-name.ufa-name {
  color: #ffb86b;
}

.player-name.rfa-name {
  color: #9eb7ff;
}

/* RESPONSIVE */

@media (max-width: 1100px) {
  .cap-ledger-hero,
  .cap-office-topbar {
    align-items: stretch;
    flex-direction: column;
  }

  .cap-ledger-hero-stats,
  .cap-office-metrics {
    width: 100%;
    min-width: 0;
  }

  .cap-board-head,
  .cap-contract-card,
  .cap-contract-row {
    grid-template-columns: minmax(240px, 1fr) 72px 80px 110px 72px 170px;
  }

  .cap-ledger-grid,
  .cap-cap-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  .cap-ledger-screen {
    padding: 12px;
  }

  .cap-ledger-toolbar,
  .cap-board-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .cap-search {
    width: 100%;
    flex: none;
  }

  .cap-board-head {
    display: none;
  }

  .cap-contract-list,
  .cap-board-list {
    flex: 1;
    min-height: 0;
  }

  .cap-contract-card,
  .cap-contract-row {
    grid-template-columns: 1fr auto;
    gap: 10px;
    min-height: 96px;
  }

  .cap-contract-row__pos,
  .cap-contract-row__cell {
    display: none;
  }

  .cap-contract-row__tags {
    justify-content: flex-end;
    flex-direction: column;
    align-items: flex-end;
  }

  .cap-ledger-grid,
  .cap-cap-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cap-action-panel {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
    flex-basis: auto;
    max-height: 42vh;
    overflow-y: auto;
  }

  .cap-action-panel__player,
  .cap-action-panel__stats,
  .cap-action-panel__tags,
  .cap-action-panel__actions {
    grid-column: 1;
    grid-row: auto;
  }

  .cap-action-panel__actions {
    justify-content: flex-start;
    max-width: none;
  }
}

@media (max-width: 620px) {
  .cap-office-team {
    width: 100%;
  }

  .cap-ledger-hero-main h1 {
    max-width: 180px;
    font-size: 22px;
  }

  .cap-ledger-hero-stats,
  .cap-office-metrics {
    grid-template-columns: 1fr;
  }

  .cap-ledger-tabs,
  .cap-office-tabs {
    width: 100%;
  }

  .cap-ledger-tab {
    flex: 1;
    min-width: 0;
  }

  .cap-ledger-grid,
  .cap-cap-grid {
    grid-template-columns: 1fr;
  }

  .cap-meter-board {
    min-height: 160px;
    padding: 22px;
  }

  .cap-meter-board h2 {
    font-size: 52px;
  }
}

/* ------------------------------------------------------------------ */
/* FREE AGENTS TAB                                                     */
/* ------------------------------------------------------------------ */

.cap-fa-toolbar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
}

.cap-fa-select {
  min-height: 34px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(15, 37, 81, 0.85);
  color: var(--cap-text);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.cap-fa-head,
.cap-fa-list .cap-fa-row {
  grid-template-columns:
    minmax(190px, 1fr) 46px 46px 92px 44px 74px 60px 62px 96px;
}

.cap-fa-league {
  font-weight: 700;
  color: var(--cap-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cap-fa-trend {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-weight: 900;
  font-size: 15px;
}

.cap-fa-trend em {
  font-style: normal;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.cap-fa-trend--rising,
.cap-fa-trend--breakout {
  color: #52e0a0;
}

.cap-fa-trend--falling {
  color: #ff8a97;
}

.cap-fa-trend--stable {
  color: #93a4b3;
}

.cap-action-btn--sign {
  border-color: rgba(82, 224, 160, 0.5);
  background:
    linear-gradient(180deg, rgba(82, 224, 160, 0.22), rgba(82, 224, 160, 0.1));
  color: #d3ffe9;
}

.cap-action-btn--sign:hover:not(:disabled) {
  border-color: rgba(82, 224, 160, 0.72);
  background:
    linear-gradient(180deg, rgba(82, 224, 160, 0.3), rgba(82, 224, 160, 0.14));
}

/* Free-agent detail panel: purpose-built 3-region layout (identity | body | CTA)
   that overrides the Board panel's rigid grid so sections never overlap. */
.cap-fa-detail.cap-action-panel {
  display: grid;
  grid-template-columns: minmax(200px, 236px) minmax(0, 1fr) auto;
  grid-template-rows: auto;
  align-items: stretch;
  gap: 12px 22px;
  flex-basis: clamp(150px, 24vh, 210px);
}

@media (max-width: 1120px) {
  .cap-fa-detail.cap-action-panel {
    grid-template-columns: 1fr auto;
    gap: 12px 16px;
  }
  .cap-fa-detail__id { grid-column: 1 / -1; border-right: none; padding-right: 0; }
  .cap-fa-detail__body { grid-column: 1; }
  .cap-fa-detail__cta { grid-column: 2; }
}

.cap-fa-detail__id {
  grid-column: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  padding-right: 8px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.cap-fa-detail__idhead {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.cap-fa-detail__idtext {
  min-width: 0;
}

.cap-fa-detail__idtext h3 {
  margin: 0;
  color: var(--cap-text);
  font-size: 20px;
  font-weight: 950;
  letter-spacing: -0.04em;
  line-height: 1.05;
}

.cap-fa-detail__idtext p {
  margin: 4px 0 0;
  color: var(--cap-muted);
  font-size: 12px;
  font-weight: 750;
}

.cap-fa-detail__where {
  font-size: 11px;
  color: #93a4b3;
  margin-top: 2px !important;
}

.cap-fa-detail__trendline {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  font-size: 12px;
}

.cap-fa-detail__reason {
  color: #b9c6d2;
  font-size: 12px;
  font-style: italic;
}

.cap-fa-proj-tag {
  margin-left: auto;
  padding: 2px 7px;
  border-radius: 2px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.05);
  color: #9fb0be;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  cursor: help;
}

.cap-fa-detail__body {
  grid-column: 2;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  justify-content: center;
}

.cap-fa-detail__block {
  min-width: 0;
}

.cap-fa-detail__blocktitle {
  margin: 0 0 7px;
  color: #7f909e;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.cap-fa-detail__stats,
.cap-fa-detail__terms {
  grid-column: auto;
}

.cap-fa-detail__stats div,
.cap-fa-detail__terms div {
  min-width: 108px;
  flex: 1 1 108px;
  max-width: 190px;
}

.cap-fa-detail__loading {
  padding: 10px 0;
  color: #93a4b3;
  font-size: 12px;
}

.cap-fa-detail__prev {
  margin: 8px 0 0;
  font-size: 11px;
  color: #93a4b3;
}

.cap-fa-detail__risk {
  margin: 8px 0 0;
  font-size: 12px;
  color: #b9c6d2;
}

.cap-fa-detail__risk span {
  color: #7f909e;
  text-transform: uppercase;
  font-size: 11px;
  letter-spacing: 0.04em;
  font-weight: 800;
}

.cap-fa-detail__cta {
  grid-column: 3;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  gap: 8px;
}

.cap-fa-detail__cta .cap-action-btn {
  min-height: 46px;
  padding: 0 26px;
  font-size: 12px;
}

.cap-fa-detail__blocker {
  color: #e79a9a;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: right;
  max-width: 130px;
}

/* Full-width negotiation dock (Contract Office — matches Entry Draft / re-sign desk) */
.cap-nego-dock {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-radius: var(--radius-control);
  border: 1px solid var(--cap-line);
  border-left: 3px solid var(--cap-cyan);
  background:
    radial-gradient(120% 90% at 8% 0%, rgba(30, 58, 92, 0.32), transparent 58%),
    linear-gradient(180deg, rgba(12, 28, 46, 0.96), rgba(13, 33, 79, 0.99));
  box-shadow: var(--depth-registered), 0 0 28px rgba(46, 230, 214, 0.1);
  overflow: hidden;
}

.cap-nego-desk {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 14px 18px 18px;
  gap: 14px;
}

.cap-nego-desk__bar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 14px 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.cap-nego-desk__title {
  flex: 1 1 200px;
  min-width: 160px;
}

.cap-nego-desk__title h3 {
  margin: 4px 0 0;
  font-size: 1.25rem;
  font-weight: 950;
  letter-spacing: 0.02em;
}

.cap-nego-desk__title em {
  font-size: 11px;
  color: var(--cap-muted);
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cap-nego-desk__wells {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  flex: 1 1 320px;
  justify-content: flex-end;
}

.cap-nego-desk__wells .cap-dossier-tile {
  min-width: 108px;
  padding: 10px 12px;
}

.cap-nego-desk__grid {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(240px, 300px) 1fr;
  gap: 18px;
  overflow: auto;
}

.cap-nego-desk__hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  margin-bottom: 4px;
}

.cap-nego-desk__hero-meta {
  width: 100%;
  text-align: center;
}

.cap-nego-desk__hero-meta strong {
  display: block;
  font-size: 17px;
}

.cap-nego-desk__hero-meta p {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--cap-muted);
}

.cap-nego-desk__agent {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.cap-nego-desk__player {
  display: flex;
  gap: 12px;
  align-items: center;
}

.cap-nego-desk__player strong {
  display: block;
  font-size: 15px;
}

.cap-nego-desk__player p {
  margin: 4px 0 0;
  font-size: 12px;
  color: var(--cap-muted);
}

.cap-nego-desk__ask {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--cap-line);
  background: rgba(0, 0, 0, 0.22);
}

.cap-nego-desk__ask span {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--cap-muted);
}

.cap-nego-desk__controls {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}

.cap-nego-desk__controls-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 16px;
  align-content: start;
}

.cap-nego-desk__cap-note--span {
  grid-column: 1 / -1;
}

.cap-nego__term--inline {
  margin: 0;
}

.cap-dossier-tile--highlight {
  border-color: rgba(240, 200, 106, 0.55);
  box-shadow: inset 0 0 0 1px rgba(240, 200, 106, 0.12);
}

@media (max-width: 900px) {
  .cap-nego-desk__controls-grid {
    grid-template-columns: 1fr;
  }
}

.cap-nego-desk__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.cap-nego-desk__actions .cap-action-btn {
  flex: 1 1 160px;
  min-height: 44px;
}

.cap-nego-desk__cap-note {
  margin: 0;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: rgba(160, 200, 220, 0.82);
}

.cap-nego__sync {
  font-size: 11px;
  font-weight: 800;
  color: var(--cap-cyan);
  margin-left: 8px;
  font-style: normal;
}



.cap-nego-meter-mark {
  position: absolute;
  top: -2px;
  width: 2px;
  height: 12px;
  background: rgba(255, 255, 255, 0.55);
  transform: translateX(-50%);
  pointer-events: none;
}

.cap-nego-meter-mark.is-instant {
  background: var(--cap-gold, #f4bd52);
}

@media (max-width: 960px) {
  .cap-nego-desk__grid {
    grid-template-columns: 1fr;
  }
  .cap-board-layout--desk > .cap-board-panel {
    max-height: 38vh;
  }
}

.cap-nego__head {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 4px;
}

.cap-nego__head h4 {
  margin: 0;
  font-size: 13px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(180, 220, 240, 0.9);
}

.cap-nego__back {
  border: 1px solid rgba(80, 140, 180, 0.35);
  background: rgba(14, 39, 90, 0.6);
  color: #9ed4f0;
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

.cap-nego__agent {
  padding: 12px 14px;
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(12, 40, 62, 0.85), rgba(14, 37, 88, 0.92));
  border: 1px solid rgba(60, 140, 200, 0.25);
}

.cap-nego__agent-id {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 10px;
}

.cap-nego__agent-meta {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.cap-nego__agent-badge {
  width: 34px;
  height: 34px;
  font-size: 13px;
  border-radius: 10px;
  flex: none;
}

.cap-nego__agent-style {
  font-size: 11px;
  font-weight: 750;
  color: rgba(160, 200, 220, 0.82);
  letter-spacing: 0.04em;
}

.cap-nego__agent-tier {
  display: inline-block;
  margin-top: 4px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.cap-nego__agent-tier.tone-hard {
  color: var(--cap-gold-bright, #f0c86a);
}

.cap-nego__agent-tier.tone-easy {
  color: var(--ops-success, #52df94);
}

.cap-nego__agent-tier.tone-medium {
  color: var(--cap-cyan);
}

.cap-nego__agent-id strong {
  font-size: 14px;
  color: #e8f7ff;
}

.cap-nego__agent-id em {
  font-size: 11px;
  color: rgba(160, 200, 220, 0.75);
  font-style: normal;
}

.cap-nego__agent-line,
.cap-nego__agent-mood {
  margin: 0;
  font-size: 16px;
  line-height: 1.45;
  color: rgba(220, 240, 250, 0.88);
}

.cap-nego__agent-mood {
  margin-top: 6px;
  color: #f0c86a;
  font-weight: 700;
}

.cap-nego-thread {
  margin-top: 12px;
  padding: 12px 14px;
  border-radius: 8px;
  border: 1px solid rgba(80, 140, 180, 0.35);
  background: rgba(13, 35, 83, 0.72);
}

.cap-nego-thread.tone-counter {
  border-color: rgba(244, 189, 82, 0.45);
  box-shadow: inset 0 0 0 1px rgba(244, 189, 82, 0.08);
}

.cap-nego-thread.tone-reject {
  border-color: rgba(255, 120, 120, 0.4);
}

.cap-nego-thread.tone-pending {
  border-color: rgba(90, 220, 240, 0.4);
}

.cap-nego-thread__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.cap-nego-thread__badge {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--cap-cyan, #5adcf0);
}

.cap-nego-thread.tone-counter .cap-nego-thread__badge {
  color: var(--cap-gold-bright, #f0c86a);
}

.cap-nego-thread.tone-reject .cap-nego-thread__badge {
  color: #ff9a9a;
}

.cap-nego-thread__round {
  font-size: 11px;
  font-weight: 800;
  color: rgba(160, 200, 220, 0.7);
  font-style: normal;
}

.cap-nego-thread__body,
.cap-nego-thread__terms,
.cap-nego-thread__hint {
  margin: 0;
  font-size: 12px;
  line-height: 1.45;
  color: rgba(220, 240, 250, 0.9);
}

.cap-nego-thread__terms {
  margin-top: 8px;
}

.cap-nego-thread__hint {
  margin-top: 8px;
  font-size: 11px;
  color: rgba(160, 200, 220, 0.82);
}

.cap-nego__cap-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  font-size: 11px;
}

.cap-nego__cap-row span {
  display: block;
  color: rgba(150, 190, 210, 0.8);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 800;
}

.cap-nego__cap-row strong {
  display: block;
  margin-top: 4px;
  font-size: 13px;
}

.cap-nego__cap-row strong.is-warn {
  color: #ff8a8a;
}

.cap-nego-meter {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.cap-nego-meter-head {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(160, 200, 220, 0.85);
}

.cap-nego-meter-track {
  position: relative;
  height: 8px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.35);
  overflow: hidden;
}

.cap-nego-meter-fill {
  display: block;
  height: 100%;
  border-radius: 4px;
}

.cap-nego-meter-fill.tone-bad {
  background: linear-gradient(90deg, #ff606d, #f0a35a);
}
.cap-nego-meter-fill.tone-mid {
  background: linear-gradient(90deg, #f0a35a, #e9a83c);
}
.cap-nego-meter-fill.tone-good {
  background: linear-gradient(90deg, #52df94, #2ee6d6);
}
.cap-nego-meter-fill.tone-instant {
  background: linear-gradient(90deg, #f4bd52, #fff0c2);
}

.cap-nego-meter-note {
  margin: 0;
  font-size: 11px;
  color: rgba(200, 225, 235, 0.75);
}

.cap-nego__slider-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 6px;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(160, 200, 220, 0.85);
}

.cap-nego__range {
  width: 100%;
}

.cap-nego__term {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.cap-nego__term > span {
  font-weight: 800;
  text-transform: uppercase;
  color: rgba(160, 200, 220, 0.85);
}

.cap-nego__term-btns {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.cap-nego__term-btns button {
  min-width: 32px;
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid rgba(80, 140, 180, 0.35);
  background: rgba(14, 39, 90, 0.5);
  color: #b8dce8;
  font-weight: 800;
  font-size: 11px;
  cursor: pointer;
}

.cap-nego__term-btns button.is-active {
  border-color: rgba(80, 200, 255, 0.6);
  background: rgba(20, 80, 120, 0.55);
  color: #fff;
}

.cap-nego__error {
  margin: 0;
  color: #ff9a9a;
  font-size: 12px;
  font-weight: 700;
}

.cap-nego__actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

@media (max-width: 1440px) {
  .cap-fa-head,
  .cap-fa-list .cap-fa-row {
    /* League names such as "Czech Extraliga" must survive the 1366px board. */
    grid-template-columns:
      minmax(140px, 1fr) 38px 38px 104px 38px 62px 50px 54px 82px;
    gap: 7px;
  }
}

@media (max-width: 1100px) {
  .cap-fa-head {
    display: none;
  }

  .cap-fa-list .cap-fa-row {
    grid-template-columns: 1fr auto;
    gap: 10px;
  }
}

/* ---------- Entry Draft visual parity (scoped) ---------- */

.cap-office-edraft {
  --cap-ed-head: var(--dd-font-ui);
  --cap-ed-number: var(--cap-ed-head);
  --cap-nego-num: clamp(22px, 2.8vw, 32px);
  --cap-nego-num-lg: clamp(28px, 3.4vw, 40px);
  font-size: 15px;
  letter-spacing: 0.01em;
}

.cap-office-edraft h1,
.cap-office-edraft h2,
.cap-office-edraft h3 {
  font-family: var(--cap-ed-head);
  letter-spacing: 0.04em;
}

.cap-office-edraft .cap-ledger-hero,
.cap-office-edraft .cap-office-topbar {
  min-height: 88px;
  border-radius: var(--radius-ops);
  background:
    radial-gradient(circle at 0% 0%, rgba(46, 230, 214, 0.08), transparent 42%),
    var(--cap-panel);
  box-shadow: var(--depth-registered);
}

.cap-office-edraft .cap-insignia {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--ops-grid-strong);
  border-radius: var(--radius-hud);
  background:
    linear-gradient(145deg, rgba(46, 230, 214, 0.16), rgba(233, 168, 60, 0.12)),
    var(--ops-panel);
  font-family: var(--font-broadcast-display);
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0.08em;
  line-height: 1.05;
  text-transform: uppercase;
  color: var(--cap-gold);
  box-shadow: var(--depth-registered);
}

.cap-office-edraft .cap-office-titles .cap-office-kicker,
.cap-office-edraft .cap-ledger-hero-main p.cap-office-kicker {
  margin: 0 0 2px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--cap-muted);
}

.cap-office-edraft .cap-ledger-hero-main h1 {
  font-family: var(--cap-ed-head);
  font-size: clamp(20px, 2.2vw, 26px);
  font-weight: 900;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  line-height: 1.05;
}

.cap-office-edraft .cap-edraft-ghost-btn {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-ops);
  border: 1px solid var(--cap-line);
  background: rgba(12, 31, 47, 0.85);
  font-size: 16px;
  box-shadow: var(--depth-registered);
}

.cap-office-edraft .cap-edraft-ghost-btn:hover {
  border-color: rgba(46, 230, 214, 0.45);
  background: rgba(46, 230, 214, 0.12);
  color: var(--cap-cyan);
}

.cap-office-edraft .cap-metric-label {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px !important;
}

.cap-office-edraft .cap-office-metrics strong.cap-num-pop {
  font-family: var(--cap-ed-number);
  font-size: clamp(20px, 2.4vw, 26px);
  font-weight: 800;
  background: none;
  color: inherit;
}

.cap-office-edraft .cap-icon-well {
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  flex: none;
  border-radius: 8px;
  background: rgba(148, 185, 205, 0.12);
  border: 1px solid rgba(148, 185, 205, 0.14);
  color: var(--cap-text);
  font-family: var(--cap-ed-number);
  font-size: 11px;
  font-weight: 1000;
  line-height: 1;
  box-shadow: var(--depth-registered);
}

.cap-office-edraft .cap-icon-well.tone-cyan {
  color: var(--cap-cyan);
  background: var(--ops-cyan-soft);
  border-color: rgba(46, 230, 214, 0.32);
  box-shadow: 0 0 8px rgba(46, 230, 214, 0.28);
}

.cap-office-edraft .cap-icon-well.tone-gold {
  color: var(--cap-gold);
  background: var(--ops-gold-soft);
  border-color: rgba(233, 168, 60, 0.32);
  box-shadow: 0 0 8px rgba(233, 168, 60, 0.24);
}

.cap-office-edraft .cap-icon-well.tone-green {
  color: var(--ops-success);
  background: var(--ops-success-soft);
  border-color: rgba(82, 223, 148, 0.32);
  box-shadow: 0 0 8px rgba(82, 223, 148, 0.22);
}

.cap-office-edraft .cap-num-pop {
  display: inline-block;
  font-family: var(--cap-ed-number);
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  filter: drop-shadow(0 1px 3px rgba(0, 0, 0, 0.75)) drop-shadow(0 0 12px rgba(46, 230, 214, 0.28));
}

.cap-office-edraft .cap-num-pop.tone-cyan {
  background: linear-gradient(180deg, #f4feff 0%, #3ae9f5 45%, #0d8f9c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.cap-office-edraft .cap-num-pop.tone-gold {
  background: linear-gradient(180deg, #fff4d6 0%, #f0b44a 48%, #b87412 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 3px rgba(0, 0, 0, 0.75)) drop-shadow(0 0 12px rgba(233, 168, 60, 0.32));
}



.cap-office-edraft .cap-num-pop.tone-blue {
  background: linear-gradient(180deg, #eef4ff 0%, #8ab4ff 48%, #3d6fbf 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.72)) drop-shadow(0 0 10px rgba(138, 180, 255, 0.24));
}



.cap-office-edraft .cap-num-pop.tone-muted {
  background: linear-gradient(180deg, #f0f6fa 0%, #9eb4c4 48%, #5a7080 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.65));
}

.cap-office-edraft .cap-num-pop.tone-orange {
  background: linear-gradient(180deg, #fff0e6 0%, #ff8a4c 48%, #c44e12 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.72)) drop-shadow(0 0 10px rgba(255, 138, 76, 0.28));
}

.cap-office-edraft .cap-num-pop.tone-danger {
  background: linear-gradient(180deg, #ffe8ea 0%, #ff606d 48%, #b81e2c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.72)) drop-shadow(0 0 10px rgba(255, 96, 109, 0.26));
}

.cap-office-edraft .cap-num-pop.tone-green {
  background: linear-gradient(180deg, #e8fff2 0%, #52df94 48%, #1f9a5c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.72)) drop-shadow(0 0 10px rgba(82, 223, 148, 0.28));
}

.cap-office-edraft .cap-office-seg {
  border-radius: var(--radius-ops);
  overflow: hidden;
  box-shadow: var(--depth-registered);
}

.cap-office-edraft .cap-ledger-tab {
  min-height: 42px;
  min-width: 96px;
  padding: 0 18px;
  font-family: var(--cap-ed-head);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.cap-office-edraft .cap-ledger-tab-active,
.cap-office-edraft .cap-ledger-tab.is-active {
  background: rgba(46, 230, 214, 0.14);
  color: var(--cap-text);
  box-shadow: inset 0 -2px 0 var(--cap-cyan), 0 0 12px rgba(46, 230, 214, 0.12);
}

.cap-office-edraft .cap-filter-pill {
  min-height: 36px;
  padding: 0 14px;
  border-radius: 4px;
  font-family: var(--cap-ed-head);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
  box-shadow: var(--depth-registered);
  transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease, color 0.2s ease;
}

.cap-office-edraft .cap-filter-pill:hover {
  border-color: var(--cap-line-strong);
  background: rgba(46, 230, 214, 0.12);
  color: var(--cap-cyan);
  transform: translateY(-1px);
}

.cap-office-edraft .cap-filter-pill.is-active {
  border-color: rgba(46, 230, 214, 0.55);
  background: rgba(46, 230, 214, 0.16);
  color: var(--cap-cyan);
  box-shadow: 0 0 10px rgba(46, 230, 214, 0.18);
}

.cap-office-edraft .cap-search {
  min-height: 42px;
  font-size: 14px;
  border-radius: var(--radius-ops);
