/* ==========================================================================
   SECTION: screens/FirstPersonOfficeHub.css
   ========================================================================== */
.office-hub {
    --office-bg: var(--office-charcoal, #12234c);
    --office-panel: var(--office-desk, rgba(17, 33, 74, 0.9));
    --office-panel-strong: var(--office-desk-strong, rgba(15, 30, 70, 0.94));
    --office-line: var(--office-line, rgba(255, 255, 255, 0.08));
    --office-line-strong: rgba(248, 213, 138, 0.32);
    --office-text: var(--office-text, #ece8e0);
    --office-muted: var(--office-text-secondary, rgba(220, 216, 208, 0.58));
    --office-faint: rgba(220, 216, 208, 0.32);
    --office-gold: var(--office-brass, #f8d58a);
    --office-blue: #6a9ab8;
    --office-red: #a84a44;
    --office-green: #6a9a82;
    --office-font: var(--font-office-display, var(--font-motion-control));
  
    position: relative;
    width: 100%;
    min-height: 100vh;
    min-height: 100dvh;
    overflow: hidden;
    background:
      radial-gradient(circle at 50% 42%, rgba(106, 154, 184, 0.14), transparent 42%),
      radial-gradient(circle at 50% 18%, rgba(248, 213, 138, 0.1), transparent 36%),
      linear-gradient(180deg, #142753 0%, #102048 100%);
    color: var(--office-text);
    font-family: var(--office-font);
    letter-spacing: 0.03em;
  }
  
  .office-hub *,
  .office-hub *::before,
  .office-hub *::after {
    box-sizing: border-box;
    font-family: inherit;
  }
  
  .office-canvas {
    position: absolute;
    inset: 0;
    z-index: 1;
  }
  
  .office-canvas canvas {
    display: block;
    width: 100% !important;
    height: 100% !important;
  }
  
  .office-vignette {
    position: absolute;
    inset: 0;
    z-index: 2;
    pointer-events: none;
    background:
      radial-gradient(ellipse at 50% 48%, transparent 52%, rgba(0, 0, 0, 0.04) 86%, rgba(0, 0, 0, 0.12) 100%),
      linear-gradient(180deg, rgba(0, 0, 0, 0.02), transparent 28%, rgba(0, 0, 0, 0.06));
  }

  .office-vignette::after {
    content: "";
    position: absolute;
    inset: 0;
    opacity: 0.012;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
    pointer-events: none;
  }
  
  .office-hud {
    position: absolute;
    inset: 0;
    z-index: 4;
    pointer-events: none;
  }

  .office-broadcast {
    position: absolute;
    top: 12px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 10px;
    max-width: min(1100px, calc(100vw - 24px));
    padding: 6px 12px;
    border: 1px solid rgba(248, 213, 138, 0.28);
    background: rgba(14, 29, 67, 0.78);
    color: var(--office-text);
    pointer-events: none;
    white-space: nowrap;
    overflow: hidden;
  }

  .office-broadcast__where,
  .office-broadcast span,
  .office-broadcast em {
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--office-muted);
    font-style: normal;
  }

  .office-broadcast strong {
    font-size: 13px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }

  .office-wire-ticker {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 6;
    display: flex;
    align-items: stretch;
    height: 36px;
    pointer-events: auto;
    border-top: 1px solid rgba(248, 213, 138, 0.35);
    background: rgba(13, 28, 65, 0.88);
  }

  .office-wire-ticker__flag {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    padding: 0 12px;
    background: #8b1e28;
    color: #f4d9c6;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.16em;
    text-transform: uppercase;
  }

  .office-wire-ticker__viewport {
    overflow: hidden;
    flex: 1;
    display: flex;
    align-items: center;
  }

  .office-wire-ticker__track {
    display: flex;
    align-items: center;
    gap: 28px;
    width: max-content;
    animation: office-wire-scroll 48s linear infinite;
  }

  .office-wire-ticker:hover .office-wire-ticker__track {
    animation-play-state: paused;
  }

  .office-wire-ticker.is-static .office-wire-ticker__track {
    animation: none;
    overflow-x: auto;
  }

  .office-wire-ticker__item {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: 0;
    background: transparent;
    color: #d7cbb8;
    cursor: pointer;
    font: inherit;
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
    padding: 0;
  }

  .office-wire-ticker__item em {
    font-style: normal;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #f8d58a;
  }

  .office-wire-ticker__item span {
    color: rgba(248, 213, 138, 0.35);
  }

  .office-wire-ticker__empty {
    padding: 0 14px;
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--office-muted);
  }

  @keyframes office-wire-scroll {
    from { transform: translateX(0); }
    to { transform: translateX(-50%); }
  }

  .office-reticle {
    position: absolute;
    left: 50%;
    top: 48%;
    width: 10px;
    height: 10px;
    margin: -5px 0 0 -5px;
    border: 1px solid rgba(248, 213, 138, 0.55);
    pointer-events: none;
    opacity: 0.45;
  }

  .office-proximity {
    min-width: 180px;
    padding: 8px 10px;
    border: 1px solid rgba(248, 213, 138, 0.55);
    background: rgba(14, 29, 67, 0.92);
    color: #f0e8dc;
    text-align: left;
    pointer-events: none;
  }

  .office-proximity strong {
    display: block;
    font-size: 13px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #f0e4c8;
  }

  .office-proximity span {
    display: block;
    margin-top: 4px;
    font-size: 11px;
    color: rgba(232, 224, 208, 0.72);
  }

  .office-proximity--compact {
    min-width: 0;
    padding: 6px 12px;
    text-align: center;
  }

  .office-proximity--compact strong {
    font-size: 11px;
  }

  .office-proximity--compact em {
    margin-top: 4px;
  }

  .league-ops-html-layer,
  .league-ops-html-layer * {
    pointer-events: none !important;
  }

  .league-ops-icon {
    --league-ops-hover: 0;
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    gap: 2px;
    /* Matches MENU_LANDMARK.artPx + padding so League Operations sits on the
       same footprint as every other destination. */
    width: 242px;
    padding: 8px 17px 12px;
    pointer-events: none;
    user-select: none;
    transform: translate3d(0, calc(var(--league-ops-hover) * -2px), 0);
    transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  }

  /* The executive is fitted inside the shared 208px art box like every other
     landmark; it used to scale past its own frame, which made League Operations
     read half again as large as its neighbours. */
  .league-ops-icon__scene {
    display: block;
    width: 163px;
    height: 208px;
    overflow: hidden;
    filter: brightness(calc(1 + var(--league-ops-hover) * 0.12));
    transition: filter 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .league-ops-icon__figure-layer {
    transform-box: view-box;
    transform-origin: 250px 320px;
    transform: scale(calc(1 + var(--league-ops-hover) * 0.02));
    transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .league-ops-icon__rim {
    opacity: calc(0.72 + var(--league-ops-hover) * 0.28);
    transition:
      transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.3s ease;
  }

  @media (prefers-reduced-motion: reduce) {
    .league-ops-icon,
    .league-ops-icon__scene,
    .league-ops-icon__figure-layer,
    .league-ops-icon__title::after,
    .league-ops-icon__corner {
      transition: none;
    }
  }

  .league-ops-icon__corner {
    position: absolute;
    width: 18px;
    height: 18px;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.32s ease;
  }

  .league-ops-icon__corner--tl {
    top: 4px;
    left: 8px;
    border-top: 1px solid rgba(248, 213, 138, 0.55);
    border-left: 1px solid rgba(248, 213, 138, 0.55);
  }

  .league-ops-icon__corner--tr {
    top: 4px;
    right: 8px;
    border-top: 1px solid rgba(248, 213, 138, 0.55);
    border-right: 1px solid rgba(248, 213, 138, 0.55);
  }

  .league-ops-icon__corner--bl {
    bottom: 6px;
    left: 8px;
    border-bottom: 1px solid rgba(248, 213, 138, 0.55);
    border-left: 1px solid rgba(248, 213, 138, 0.55);
  }

  .league-ops-icon__corner--br {
    bottom: 6px;
    right: 8px;
    border-bottom: 1px solid rgba(248, 213, 138, 0.55);
    border-right: 1px solid rgba(248, 213, 138, 0.55);
  }

  .league-ops-icon--hover .league-ops-icon__corner {
    opacity: calc(0.35 + var(--league-ops-hover) * 0.5);
  }

  .league-ops-icon__title {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex-direction: row;
    gap: 6px;
    margin: 3px 0 0;
    padding: 0;
