  .office-menu-icon--label-only .office-menu-icon__title {
    margin: 0;
  }

  .office-menu-icon__scene {
    display: block;
    overflow: visible;
    font-family: var(--font-office-display, var(--font-motion-control, sans-serif));
    filter: drop-shadow(0 6px 18px rgba(0, 0, 0, 0.72))
      brightness(calc(0.88 + var(--menu-hover) * 0.26));
  }

  .office-menu-icon__corner {
    position: absolute;
    width: 16px;
    height: 16px;
    opacity: 0;
    transition: opacity 0.32s ease;
  }

  .office-menu-icon__corner--tl {
    top: 2px;
    left: 4px;
    border-top: 1px solid rgba(248, 213, 138, 0.55);
    border-left: 1px solid rgba(248, 213, 138, 0.55);
  }

  .office-menu-icon__corner--tr {
    top: 2px;
    right: 4px;
    border-top: 1px solid rgba(248, 213, 138, 0.55);
    border-right: 1px solid rgba(248, 213, 138, 0.55);
  }

  .office-menu-icon__corner--bl {
    bottom: 4px;
    left: 4px;
    border-bottom: 1px solid rgba(248, 213, 138, 0.55);
    border-left: 1px solid rgba(248, 213, 138, 0.55);
  }

  .office-menu-icon__corner--br {
    bottom: 4px;
    right: 4px;
    border-bottom: 1px solid rgba(248, 213, 138, 0.55);
    border-right: 1px solid rgba(248, 213, 138, 0.55);
  }

  .office-menu-icon--hover .office-menu-icon__corner {
    opacity: calc(0.3 + var(--menu-hover) * 0.5);
  }

  .office-menu-icon__title {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1px;
    margin: 6px 0 0;
    font-family: var(--font-office-display, var(--font-motion-control, sans-serif));
    text-transform: uppercase;
    text-align: center;
    white-space: nowrap;
    text-shadow: 0 1px 10px rgba(0, 0, 0, 0.92);
  }

  .office-menu-icon__kicker {
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.2em;
    line-height: 1.2;
    color: rgba(248, 213, 138, 0.78);
  }

  .office-menu-icon__name {
    font-size: 15px;
    font-weight: 800;
    letter-spacing: 0.1em;
    line-height: 1.15;
    color: #e6eef3;
  }

  .office-menu-icon__title::after {
    content: "";
    display: block;
    width: calc(14% + var(--menu-hover) * 34%);
    height: 2px;
    margin: 5px auto 0;
    background: linear-gradient(
      90deg,
      transparent,
      var(--menu-accent),
      transparent
    );
    box-shadow: 0 0 8px rgba(200, 230, 255, calc(0.15 + var(--menu-hover) * 0.4));
    transition: width 0.3s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .office-menu-icon--hover .office-menu-icon__kicker {
    color: rgba(230, 205, 152, 0.95);
  }

  .office-menu-icon--hover .office-menu-icon__name {
    color: #ffffff;
  }

  /* --- Per-scene hover choreography, all driven by --menu-hover --- */

  .office-menu-icon .menu-glow {
    opacity: calc(0.3 + var(--menu-hover) * 0.7);
  }

  .office-menu-icon .menu-route {
    stroke-dashoffset: calc(380 - var(--menu-hover) * 380);
  }

  .office-menu-icon .menu-dot {
    transform-box: fill-box;
    transform-origin: center;
    opacity: calc(0.55 + var(--menu-hover) * 0.45);
    transform: scale(calc(1 + var(--menu-hover) * 0.4));
  }

  .office-menu-icon .menu-dot--a {
    transform: translate(calc(var(--menu-hover) * 24px), calc(var(--menu-hover) * -16px));
  }

  .office-menu-icon .menu-dot--b {
    transform: translate(calc(var(--menu-hover) * 10px), calc(var(--menu-hover) * -6px));
  }

  .office-menu-icon .menu-dot--c {
    transform: translate(calc(var(--menu-hover) * -8px), calc(var(--menu-hover) * -4px));
  }

  .office-menu-icon .menu-beam {
    transform-box: fill-box;
    transform-origin: center;
    opacity: calc(0.22 + var(--menu-hover) * 0.78);
    transform: scaleX(calc(0.55 + var(--menu-hover) * 0.45));
  }

  /* Trade Hub — the two asset groups lean toward the exchange point */
  .office-menu-icon .menu-mass--l {
    transform: translateX(calc(var(--menu-hover) * 9px));
  }

  .office-menu-icon .menu-mass--r {
    transform: translateX(calc(var(--menu-hover) * -9px));
  }

  .office-menu-icon .menu-path {
    stroke-opacity: calc(0.18 + var(--menu-hover) * 0.55);
  }

  .office-menu-icon .menu-token {
    transform-box: fill-box;
    transform-origin: center;
    transform: translateY(calc(var(--menu-hover) * -6px))
      scale(calc(1 + var(--menu-hover) * 0.08));
  }

  /* Stats — analytics ring completes and the trend line rises */
  .office-menu-icon .menu-ring {
    stroke-dashoffset: calc(830 - (0.32 + var(--menu-hover) * 0.48) * 830);
    opacity: calc(0.68 + var(--menu-hover) * 0.32);
  }

  .office-menu-icon .menu-graph {
    transform: translateY(calc(var(--menu-hover) * -7px));
    opacity: calc(0.55 + var(--menu-hover) * 0.45);
  }

  .office-menu-icon .menu-figure {
    opacity: calc(0.66 + var(--menu-hover) * 0.34);
  }

  .office-menu-icon .menu-sign {
    stroke-dashoffset: calc(240 - var(--menu-hover) * 240);
  }

  .office-menu-icon .menu-hero {
    transform-box: fill-box;
    transform-origin: center bottom;
    transform: translateY(calc(var(--menu-hover) * -5px));
  }

  .office-menu-icon .menu-wing {
    opacity: calc(0.45 + var(--menu-hover) * 0.55);
  }

  .office-menu-icon .menu-wing--l {
    transform: translateX(calc(var(--menu-hover) * -7px));
  }

  .office-menu-icon .menu-wing--r {
    transform: translateX(calc(var(--menu-hover) * 7px));
  }

  .office-menu-icon .menu-bar {
    opacity: calc(0.6 + var(--menu-hover) * 0.4);
    transform: translateX(calc(var(--menu-hover) * var(--i) * 4px));
  }

  .office-menu-icon .menu-strip {
    opacity: calc(0.5 + var(--menu-hover) * 0.5);
    transform: translateX(calc(var(--menu-hover) * (3px + var(--i) * 7px)));
  }

  .office-menu-icon .menu-card {
    opacity: calc(0.55 + var(--menu-hover) * 0.45);
    transform: translateY(calc(var(--menu-hover) * (-2px - var(--i) * 2px)));
  }

  .office-menu-icon .menu-spot {
    opacity: calc(0.28 + var(--menu-hover) * 0.72);
  }

  .office-menu-icon .menu-alert {
    transform-box: fill-box;
    transform-origin: center;
    opacity: calc(0.45 + var(--menu-hover) * 0.55);
  }

  .office-menu-icon--hover .menu-alert {
    animation: officeMenuAlert 900ms ease-out 1;
  }

  .office-menu-icon .menu-sweep {
    opacity: 0;
  }

  .office-menu-icon--hover .menu-sweep {
    animation: officeMenuSweep 820ms cubic-bezier(0.22, 1, 0.36, 1) 1;
  }

  @keyframes officeMenuAlert {
    0% {
      transform: scale(0.7);
      opacity: 0.4;
    }
    45% {
      transform: scale(1.35);
      opacity: 1;
    }
    100% {
      transform: scale(1);
      opacity: 0.9;
    }
  }

  @keyframes officeMenuSweep {
    0% {
      opacity: 0;
      transform: translateX(0);
    }
    35% {
      opacity: 0.6;
    }
    100% {
      opacity: 0;
      transform: translateX(420px);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .office-menu-icon,
    .office-menu-icon__title::after,
    .office-menu-icon__corner {
      transition: none;
    }

    .office-menu-icon--hover .menu-alert,
    .office-menu-icon--hover .menu-sweep {
      animation: none;
    }
  }

