    gap: 12px;
    align-items: center;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--office-line);
  }
  
  .office-panel-header h2 {
    margin: 5px 0 0;
    color: var(--office-text);
    font-size: 27px;
    line-height: 0.95;
    text-transform: uppercase;
  }
  
  .office-panel-close,
  .office-quick-menu-head button {
    width: 36px;
    height: 36px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
    color: var(--office-text);
    cursor: pointer;
    font-size: 24px;
    line-height: 1;
  }
  
  .office-panel > p {
    margin: 14px 0;
    color: var(--office-muted);
    font-size: 15px;
    line-height: 1.5;
    font-weight: 650;
  }
  
  .office-panel-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 9px;
    margin: 14px 0;
  }
  
  .office-panel-stats div,
  .office-panel-next {
    padding: 10px;
    border: 1px solid var(--office-line);
    border-radius: var(--radius-hud, 4px);
    background: rgba(0, 0, 0, 0.22);
  }
  
  .office-panel-stats strong,
  .office-panel-next strong {
    display: block;
    margin-top: 4px;
    color: var(--office-text);
    font-size: 14px;
    font-weight: 900;
  }
  
  .office-panel-next {
    margin-bottom: 14px;
  }
  
  .office-panel-actions {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 9px;
  }
  
  .office-panel-actions button {
    min-height: 46px;
    padding: 10px;
    border-radius: var(--radius-control, 6px);
  }
  
  .office-quick-menu {
    position: absolute;
    inset: 0;
    z-index: 10;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    padding: 0 clamp(12px, 2vw, 22px) 92px;
    background:
      linear-gradient(180deg, transparent 42%, rgba(0, 0, 0, 0.38) 72%, rgba(0, 0, 0, 0.62) 100%),
      radial-gradient(circle at 50% 88%, rgba(248, 213, 138, 0.06), transparent 38%);
    backdrop-filter: blur(4px);
    pointer-events: none;
  }

  .office-quick-menu-card {
    pointer-events: auto;
    width: min(680px, 100%);
    max-height: min(58vh, 520px);
    overflow: auto;
    padding: 0;
    border: 1px solid rgba(248, 213, 138, 0.28);
    border-radius: var(--radius-hud, 4px);
    background:
      linear-gradient(180deg, rgba(13, 28, 65, 0.97), rgba(12, 26, 61, 0.98));
    box-shadow:
      0 24px 60px rgba(0, 0, 0, 0.62),
      inset 0 1px 0 rgba(255, 255, 255, 0.04),
      inset 0 -1px 0 rgba(248, 213, 138, 0.12);
  }

  .office-quick-menu-card::before {
    content: "";
    display: block;
    height: 2px;
    background: linear-gradient(90deg, transparent, var(--office-gold), transparent);
    opacity: 0.5;
  }

  .office-quick-menu-head {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    align-items: flex-start;
    padding: 12px 14px 10px;
    border-bottom: 1px solid var(--office-line);
    background: rgba(0, 0, 0, 0.24);
  }

  .office-quick-menu-kicker {
    display: block;
    color: var(--office-gold);
    font-size: 11px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    font-weight: 800;
    font-family: var(--font-mono-data, "IBM Plex Mono", monospace);
  }

  .office-quick-menu-head h3 {
    margin: 4px 0 0;
    color: var(--office-text);
    font-size: clamp(15px, 1.8vw, 18px);
    line-height: 1.15;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }

  .office-quick-menu-close {
    min-width: 36px;
    min-height: 36px;
    border-radius: var(--radius-hud, 4px);
    border: 1px solid var(--office-line);
    background: rgba(255, 255, 255, 0.03);
    color: var(--office-text);
    font-size: 20px;
    line-height: 1;
    cursor: pointer;
  }

  .office-quick-menu-close:hover {
    border-color: rgba(248, 213, 138, 0.45);
    background: rgba(248, 213, 138, 0.08);
  }

  .office-quick-menu-sim {
    margin: 0;
    padding: 10px 14px;
    border-bottom: 1px solid var(--office-line);
    background: rgba(248, 213, 138, 0.04);
  }

  .office-quick-menu-sim-btn {
    width: 100%;
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 10px 12px;
    align-items: center;
    text-align: left;
    padding: 10px 12px;
    border-radius: var(--radius-hud, 4px);
    border: 1px solid rgba(248, 213, 138, 0.45);
    background:
      linear-gradient(90deg, rgba(248, 213, 138, 0.14), rgba(248, 213, 138, 0.03)),
      rgba(255, 255, 255, 0.02);
    color: var(--office-text);
    cursor: pointer;
  }

  .office-quick-menu-sim-btn::before {
    content: "ADV";
    font-family: var(--font-mono-data, "IBM Plex Mono", monospace);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.12em;
    color: var(--office-gold);
    padding: 4px 6px;
    border: 1px solid rgba(248, 213, 138, 0.35);
    border-radius: var(--radius-ops, 2px);
    background: rgba(0, 0, 0, 0.28);
  }

  .office-quick-menu-sim-btn strong {
    font-size: 13px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    grid-column: 2;
  }

  .office-quick-menu-sim-btn small {
    color: var(--office-muted);
    font-size: 11px;
    line-height: 1.35;
    grid-column: 2;
    font-family: var(--font-ops-ui, Inter, sans-serif);
    font-weight: 500;
    letter-spacing: normal;
    text-transform: none;
  }

  .office-quick-menu-sim-btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }

  .office-quick-menu-section {
    margin: 0;
    padding: 0 14px 10px;
  }

  .office-quick-menu-section-head {
    margin: 0;
    padding: 8px 0 6px;
    border-bottom: 1px dashed rgba(248, 213, 138, 0.18);
  }

  .office-quick-menu-section-head span {
    color: var(--office-muted);
    font-size: 11px;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    font-weight: 800;
    font-family: var(--font-mono-data, "IBM Plex Mono", monospace);
  }

  .office-quick-menu-grid,
  .office-fallback-grid {
    display: flex;
    flex-direction: column;
    gap: 0;
    counter-reset: office-cmd;
    border: 1px solid var(--office-line);
    border-radius: var(--radius-hud, 4px);
    background: rgba(0, 0, 0, 0.22);
    overflow: hidden;
  }

  .office-quick-menu-item,
  .office-quick-menu-grid button,
  .office-fallback-grid button {
    position: relative;
    display: grid;
    grid-template-columns: 34px minmax(0, 1fr);
    grid-template-rows: auto auto;
    column-gap: 10px;
    row-gap: 2px;
    align-items: start;
    min-height: 0;
    padding: 9px 12px 9px 10px;
    border-radius: 0;
    border: none;
    border-bottom: 1px solid var(--office-line);
    background: transparent;
    text-align: left;
    color: var(--office-text);
    cursor: pointer;
    transition:
      border-color var(--motion-micro, 110ms) ease,
      background var(--motion-micro, 110ms) ease;
  }

  .office-quick-menu-item::before,
  .office-quick-menu-grid button::before,
  .office-fallback-grid button::before {
    content: counter(office-cmd, decimal-leading-zero);
    counter-increment: office-cmd;
    grid-row: 1 / span 2;
    align-self: center;
    font-family: var(--font-mono-data, "IBM Plex Mono", monospace);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.06em;
    color: rgba(248, 213, 138, 0.62);
  }

  .office-quick-menu-grid > *:last-child,
  .office-fallback-grid > *:last-child {
    border-bottom: none;
  }

  .office-quick-menu-item:hover,
  .office-quick-menu-grid button:hover,
  .office-fallback-grid button:hover {
    border-color: transparent;
    background: rgba(248, 213, 138, 0.07);
    transform: none;
    box-shadow: inset 3px 0 0 rgba(248, 213, 138, 0.55);
  }

  .office-quick-menu-item.is-highlight,
  .office-fallback-grid button.is-highlight {
    background: rgba(248, 213, 138, 0.08);
    box-shadow: inset 3px 0 0 rgba(248, 213, 138, 0.72);
  }

  .office-quick-menu-item.is-placeholder,
  .office-fallback-grid button.is-placeholder {
    border-bottom-style: dashed;
    opacity: 0.72;
  }

  .office-quick-menu-item.is-disabled {
    opacity: 0.42;
    cursor: not-allowed;
    transform: none;
  }

  .office-quick-menu-item-eyebrow,
  .office-quick-menu-grid button span,
  .office-fallback-grid button span {
    display: block;
    grid-column: 2;
    color: var(--office-gold);
    font-size: 11px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    font-weight: 800;
  }

  .office-quick-menu-item strong,
  .office-quick-menu-grid button strong,
  .office-fallback-grid button strong {
    display: block;
    grid-column: 2;
    margin-top: 0;
    font-size: 13px;
    line-height: 1.15;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .office-quick-menu-item small,
  .office-fallback-grid button small {
    display: block;
    grid-column: 2;
    margin-top: 0;
    color: var(--office-muted);
    font-size: 11px;
    line-height: 1.35;
    font-family: var(--font-ops-ui, Inter, sans-serif);
    font-weight: 500;
    letter-spacing: normal;
    text-transform: none;
  }

  .office-quick-menu-item-note {
    display: block;
    grid-column: 2;
    margin-top: 2px;
    color: rgba(248, 213, 138, 0.75);
    font-size: 11px;
    font-style: normal;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .office-fallback-section {
    display: grid;
    gap: 10px;
  }

  .office-fallback-sim {
    max-width: 720px;
  }
  
  .office-fallback {
    min-height: 100vh;
    min-height: 100dvh;
    display: grid;
    align-content: center;
    gap: 20px;
    padding: 32px;
    background:
      radial-gradient(circle at 22% 20%, rgba(246, 211, 129, 0.16), transparent 30%),
      linear-gradient(180deg, #12234d, #0e1c41);
    color: var(--office-text);
  }
  
  .office-fallback h2 {
    margin: 8px 0;
    font-size: clamp(32px, 5vw, 68px);
    line-height: 0.95;
    text-transform: uppercase;
  }
  
  .office-fallback p {
    max-width: 780px;
    color: var(--office-muted);
    font-size: 18px;
    line-height: 1.45;
  }
  
  .office-cursor-active {
    cursor: pointer;
  }

  /* Team logo badge (shared with TeamLogoBadge.js) */
  .team-logo-badge {
    width: var(--team-logo-size, 48px);
    height: var(--team-logo-size, 48px);
    flex-shrink: 0;
    display: grid;
    place-items: center;
    overflow: hidden;
    line-height: 1;
  }

  .team-logo-badge img {
    width: 88%;
    height: 88%;
    object-fit: contain;
    display: block;
  }

  .team-logo-badge span {
    color: var(--office-text);
    font-size: calc(var(--team-logo-size, 48px) * 0.34);
    font-weight: 950;
    letter-spacing: 0.06em;
  }

  .team-logo-badge--badge,
  .team-logo-badge--circle {
    border-radius: 50%;
    border: 1px solid rgba(246, 211, 129, 0.38);
    background:
      radial-gradient(circle at 28% 18%, rgba(255, 255, 255, 0.16), rgba(14, 30, 70, 0.92));
    box-shadow:
      0 0 18px rgba(248, 213, 138, 0.28),
      0 6px 16px rgba(0, 0, 0, 0.35),
      inset 0 1px 0 rgba(255, 255, 255, 0.12);
  }

  .team-logo-badge--framed {
    border-radius: 6px;
    border: 2px solid rgba(248, 213, 138, 0.55);
    background:
      linear-gradient(145deg, rgba(24, 44, 92, 0.95), rgba(15, 30, 70, 0.98));
    box-shadow:
      0 0 28px rgba(248, 213, 138, 0.35),
      0 12px 28px rgba(0, 0, 0, 0.45),
      inset 0 0 24px rgba(248, 213, 138, 0.08);
  }

  .team-logo-badge--watermark {
    border: none;
    background: transparent;
    box-shadow: none;
    filter: saturate(0.85);
  }

  .team-logo-badge--watermark img,
  .team-logo-badge--watermark span {
    opacity: 0.9;
  }

  .team-logo-badge--initials.team-logo-badge--badge span,
  .team-logo-badge--initials.team-logo-badge--circle span {
    color: var(--office-gold);
  }
  
  .office-hud--panel-open .office-hud-card--right {
    opacity: 0.35;
    transform: translateY(-4px);
    transition:
      opacity 180ms ease,
      transform 180ms ease;
  }
  
  .office-hub[data-hovered="dashboard"] .office-vignette {
    background:
      radial-gradient(circle at center, transparent 44%, rgba(0, 0, 0, 0.32) 77%, rgba(0, 0, 0, 0.72) 100%),
      radial-gradient(circle at 52% 52%, rgba(91, 192, 255, 0.08), transparent 34%),
      linear-gradient(180deg, rgba(0, 0, 0, 0.14), transparent 25%, rgba(0, 0, 0, 0.35));
  }
  
  .office-hub[data-hovered="messages"] .office-vignette {
    background:
      radial-gradient(circle at center, transparent 40%, rgba(0, 0, 0, 0.34) 76%, rgba(0, 0, 0, 0.74) 100%),
      radial-gradient(circle at 28% 55%, rgba(227, 76, 69, 0.08), transparent 28%),
      linear-gradient(180deg, rgba(0, 0, 0, 0.16), transparent 25%, rgba(0, 0, 0, 0.35));
  }
  
  .office-hub[data-hovered="contracts"] .office-vignette,
  .office-hub[data-hovered="stats"] .office-vignette {
    background:
      radial-gradient(circle at center, transparent 40%, rgba(0, 0, 0, 0.34) 76%, rgba(0, 0, 0, 0.74) 100%),
      radial-gradient(circle at 62% 55%, rgba(147, 214, 163, 0.07), transparent 30%),
      linear-gradient(180deg, rgba(0, 0, 0, 0.16), transparent 25%, rgba(0, 0, 0, 0.35));
  }
  
  @media (max-width: 1020px) {
    .office-hub {
      min-height: 100svh;
    }
  
    .office-hud-card {
      max-width: calc(100vw - 44px);
    }
  
    .office-hud-card--right {
      top: 116px;
      left: 22px;
      right: auto;
      text-align: left;
    }
  
    .office-panel {
      top: auto;
      left: 16px;
      right: 16px;
      bottom: 86px;
      width: auto;
      max-height: 52vh;
    }
  
    .office-instructions {
      display: none;
    }
  
    .office-control-bar {
      bottom: 44px;
      width: calc(100vw - 32px);
      flex-wrap: wrap;
      justify-content: center;
      border-radius: 6px;
    }

    .office-control-bar__utilities {
      border-right: none;
      padding-right: 0;
      width: 100%;
      justify-content: center;
    }
  
    .office-control-bar__primary {
      width: 100%;
    }

    .office-quick-menu {
      padding-bottom: 108px;
    }

    .office-quick-menu-card {
      max-height: min(52vh, 460px);
    }
  }

  @media (max-width: 640px) {
    .office-hud-card {
      padding: 11px 12px;
      border-radius: var(--radius-hud, 4px);
    }
  
    .office-hud-card strong {
      font-size: 22px;
    }
  
    .office-hud-card small,
    .office-hud-card em {
      font-size: 11px;
    }
  
    .office-panel-header {
      grid-template-columns: 56px 1fr auto;
    }

    .team-logo-badge--framed {
      --team-logo-size: 56px;
    }
  
    .office-panel-header h2 {
      font-size: 22px;
    }
  
    .office-panel-stats,
    .office-panel-actions {
      grid-template-columns: 1fr;
    }

    .office-control-bar {
      display: grid;
      grid-template-columns: 1fr 1fr;
    }
  
    .office-control-bar button {
      min-height: 42px;
    }
  }

  .office-wall-portrait {
    width: 196px;
    height: 96px;
    overflow: hidden;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    background: linear-gradient(180deg, #1a2940 0%, #12275a 100%);
    border-radius: 2px;
  }

  .office-wall-portrait .player-headshot {
    --size: 168px;
    margin-top: -18px;
    filter: drop-shadow(0 8px 14px rgba(0, 0, 0, 0.35));
  }

  .office-hud-mode {
    margin-top: 4px;
    color: var(--office-faint);
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.12em;
  }

  .office-urgent-desk {
    position: absolute;
    top: 56px;
    left: 12px;
    bottom: auto;
    z-index: 5;
    width: auto;
    min-width: 120px;
    max-width: min(240px, calc(40vw - 24px));
    padding: 6px 8px;
    border: 1px solid rgba(248, 213, 138, 0.35);
    border-radius: 1px;
    background: rgba(14, 29, 67, 0.72);
    box-shadow: none;
    backdrop-filter: none;
    pointer-events: auto;
    color: inherit;
    font: inherit;
    text-align: left;
    cursor: pointer;
  }

  .office-urgent-desk::before {
    display: none;
  }

  .office-urgent-desk > span {
    display: block;
    color: var(--office-gold);
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.14em;
    text-transform: uppercase;
  }

  .office-urgent-desk__list {
    margin: 10px 0 0;
    padding: 0;
    list-style: none;
    display: grid;
    gap: 8px;
  }

  .office-urgent-desk__item button {
    width: 100%;
    padding: 8px 10px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: var(--radius-hud, 4px);
    background: rgba(255, 255, 255, 0.03);
    color: var(--office-text);
    text-align: left;
    cursor: pointer;
    font: inherit;
  }

  .office-urgent-desk__item button strong {
    display: block;
    font-size: 13px;
    font-weight: 900;
  }

  .office-urgent-desk__item button small {
    display: block;
    margin-top: 3px;
    color: var(--office-muted);
    font-size: 11px;
    line-height: 1.35;
    font-weight: 650;
  }

  .office-urgent-desk__item--critical button {
    border-color: rgba(201, 74, 68, 0.55);
    background: rgba(120, 20, 20, 0.22);
  }

  .office-urgent-desk__item--high button {
    border-color: rgba(248, 213, 138, 0.42);
  }

  .office-urgent-desk__empty {
