  .office-panel-briefing,
  .office-panel-staff-note,
  .office-panel-pressure,
  .office-panel-urgent {
    margin: 12px 0;
    padding: 10px 12px;
    border: 1px solid var(--office-line);
    border-radius: var(--radius-hud, 4px);
    background: rgba(0, 0, 0, 0.2);
  }

  .office-panel-staff-note span,
  .office-panel-urgent span {
    display: block;
    color: var(--office-gold);
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.12em;
    text-transform: uppercase;
  }

  .office-panel-staff-note p,
  .office-panel-briefing {
    margin: 6px 0 0;
    color: var(--office-muted);
    font-size: 13px;
    line-height: 1.45;
    font-weight: 650;
  }

  .office-panel-pressure {
    color: #f0c8c4;
    font-size: 12px;
    line-height: 1.4;
  }

  .office-panel-pressure strong {
    color: #ffb4ae;
  }

  .office-panel-urgent ul {
    margin: 8px 0 0;
    padding: 0;
    list-style: none;
    display: grid;
    gap: 6px;
  }

  .office-panel-urgent button {
    width: 100%;
    min-height: 36px;
    padding: 8px 10px;
    border-radius: var(--radius-hud, 4px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.04);
    color: var(--office-text);
    text-align: left;
    cursor: pointer;
    font: inherit;
    font-size: 12px;
    font-weight: 800;
  }

  .office-fallback-hero {
    display: flex;
    align-items: center;
    gap: 18px;
  }

  .office-fallback-briefing {
    padding: 16px 18px;
    border: 1px solid var(--office-line);
    border-radius: var(--radius-control, 6px);
    background: rgba(14, 30, 68, 0.72);
  }

  .office-hub[data-deadline="true"] .office-vignette {
    background:
      radial-gradient(circle at center, transparent 40%, rgba(0, 0, 0, 0.36) 76%, rgba(0, 0, 0, 0.76) 100%),
      radial-gradient(circle at 24% 58%, rgba(201, 74, 68, 0.12), transparent 30%),
      radial-gradient(circle at 72% 42%, rgba(248, 213, 138, 0.1), transparent 28%),
      linear-gradient(180deg, rgba(0, 0, 0, 0.18), transparent 25%, rgba(0, 0, 0, 0.38));
  }

  .office-hub[data-draft-week="true"] .office-vignette {
    background:
      radial-gradient(circle at center, transparent 42%, rgba(0, 0, 0, 0.34) 78%, rgba(0, 0, 0, 0.72) 100%),
      radial-gradient(circle at 78% 36%, rgba(248, 213, 138, 0.14), transparent 32%),
      linear-gradient(180deg, rgba(248, 213, 138, 0.05), transparent 22%, rgba(0, 0, 0, 0.34));
  }

  .office-hub[data-playoffs="true"] .office-vignette {
    background:
      radial-gradient(circle at center, transparent 40%, rgba(0, 0, 0, 0.38) 78%, rgba(0, 0, 0, 0.78) 100%),
      radial-gradient(circle at 50% 30%, rgba(126, 184, 212, 0.12), transparent 34%),
      radial-gradient(circle at 62% 62%, rgba(248, 213, 138, 0.08), transparent 28%),
      linear-gradient(180deg, rgba(0, 0, 0, 0.2), transparent 24%, rgba(0, 0, 0, 0.4));
  }

  .office-hub[data-offseason="true"] .office-vignette,
  .office-hub[data-free-agency="true"] .office-vignette {
    background:
      radial-gradient(circle at center, transparent 42%, rgba(0, 0, 0, 0.32) 78%, rgba(0, 0, 0, 0.7) 100%),
      radial-gradient(circle at 58% 52%, rgba(126, 184, 150, 0.1), transparent 30%),
      linear-gradient(180deg, rgba(0, 0, 0, 0.14), transparent 24%, rgba(0, 0, 0, 0.34));
  }

  .office-hub[data-pressure="high"] .office-vignette,
  .office-hub[data-pressure="critical"] .office-vignette,
  .office-hub[data-owner-pressure="true"] .office-vignette {
    background:
      radial-gradient(circle at center, transparent 36%, rgba(0, 0, 0, 0.42) 74%, rgba(0, 0, 0, 0.82) 100%),
      radial-gradient(circle at 18% 72%, rgba(201, 74, 68, 0.1), transparent 28%),
