}
.wr-office-pips {
  display: flex;
  gap: 3px;
}
.wr-office-pips i {
  width: 7px;
  height: 10px;
  background: rgba(118, 200, 245, 0.18);
  /* No --wr-cut-sm here: its 8px corner cuts exceed this element's 7px width,
     which collapses the polygon into a sliver. */
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 3px), calc(100% - 3px) 100%, 0 100%);
}
.wr-office-pips i.is-on {
  background: var(--wr-fill-cyan);
}

.dc-board-sources button.is-active,
.dc-workspace-tabs button.is-active,
.dc-shortlist-icon,
.wr-now-peak__chip {
