}

@media (prefers-reduced-motion: reduce) {
  .wr-ceiling-chip.is-exact.is-glow,
  .wr-now-peak__chip.is-peak {
    animation: none;
    filter: none;
  }
}

.dc-workspace-tabs {
  display: flex;
  align-items: stretch;
  gap: 0;
  height: 28px;
  min-height: 28px;
  border: 1px solid var(--dc-line);
  border-radius: 6px;
  overflow: hidden;
  background: var(--dc-panel);
}
