  padding: 4px 14px;
}
.dc-workspace-tabs button:last-child { border-right: 0; }
.dc-workspace-tabs button.is-active {
  color: #0c214c;
  background: linear-gradient(180deg, #7ee7ff, #2be4ff);
}

.dc-board-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 5px 10px;
