}
.dc-board-filters { display: flex; gap: 4px; }
.dc-board-sources {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.dc-board-sources button {
  border: 1px solid var(--dc-line);
  background: rgba(13, 35, 81, 0.7);
  color: var(--dc-muted);
  font: inherit;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 8px;
