  border-color: var(--dc-cyan);
}
.dc-consensus-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px dashed rgba(148, 163, 184, 0.45);
  background: rgba(14, 33, 77, 0.55);
  color: #8aa0b8;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 8px;
  border-radius: 4px;
  cursor: pointer;
}
.dc-consensus-chip.is-on {
  color: #f4e7c8;
  border-color: rgba(244, 198, 110, 0.55);
}

.dc-tier-band {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 12px 6px;
