  flex-shrink: 0;
  clip-path: var(--wr-cut-sm);
  border-radius: 0;
}
.dc-prospect-row__pot {
  font-family: var(--dc-font-number);
  font-size: 1.35rem !important;
  font-weight: 900;
  letter-spacing: -0.03em;
  text-align: right;
}
.dc-prospect-row__pot .fc-proj strong {
