}
.dc-intel-feed--weekly ul {
  mask-image: linear-gradient(90deg, transparent, #000 12px, #000 calc(100% - 12px), transparent);
  scrollbar-width: thin;
  scrollbar-color: rgba(43, 228, 255, 0.55) rgba(14, 37, 85, 0.55);
}
.dc-intel-feed--weekly ul::-webkit-scrollbar { height: 8px; }
