  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.dc-stats-workspace .dc-lm-row-stack { flex: 1; min-height: 0; }

/* Brochure dossier — deep immersion (tabbed shell; must beat legacy .dc-brochure grid) */
.dc-brochure.dc-brochure--deep,
.dc-dossier-shell.dc-brochure--deep {
  display: flex;
  flex-direction: column;
