  background: linear-gradient(180deg, rgba(13, 35, 83, 0.55), rgba(12, 30, 74, 0.2));
}

.dc-archetype-head__copy {
  min-width: 0;
}
.dc-archetype-head__metrics {
  min-width: 260px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
