  overflow: visible;
}
.dc-signal-chart--single {
  padding: 8px 10px;
  border: 1px solid rgba(118, 200, 245, 0.14);
  background: rgba(12, 30, 74, 0.45);
}
.dc-signal-chart__single-rank {
  display: grid;
