.dc-signal-actionbar--dossier {
  flex-shrink: 0;
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-top: 1px solid rgba(118, 200, 245, 0.18);
  background: rgba(12, 33, 77, 0.72);
}
.dc-signal-actionbar--dossier .dc-shortlist-icon {
  flex: 0 0 auto;
