.dc-file-id,
.dc-file-lead {
  font-family: var(--dc-font-mono);
  font-size: 0.62rem;
  color: #7fa3bd;
  white-space: nowrap;
}
.dc-brochure-hero:not(.dc-brochure-hero--rail) {
  display: grid;
  grid-template-columns: minmax(200px, 240px) minmax(0, 1fr);
  gap: 12px 16px;
  padding: 12px 16px 8px;
  border-bottom: 1px solid rgba(118, 200, 245, 0.14);
  align-items: start;
}
.dc-signal-identity--compact {
  padding: 0;
  overflow: visible;
}
.dc-archetype-head {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: stretch;
}
.dc-brochure-hero--rail .dc-archetype-head {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(260px, 0.95fr);
  gap: 14px 20px;
  align-items: start;
}
.dc-archetype-head__title {
  margin: 2px 0 4px;
  font-family: var(--dc-font-title);
  font-size: clamp(1.35rem, 2.4vw, 2rem);
  line-height: 0.95;
  letter-spacing: 0.03em;
}
.dc-archetype-head__blurb {
  margin: 0 0 8px;
  font-size: 0.88rem;
  color: #7fa3bd;
  line-height: 1.45;
  max-width: 72ch;
  word-break: normal;
  overflow-wrap: break-word;
  white-space: normal;
}
.dc-archetype-head__report {
  margin: 0 0 10px;
  font-size: 0.82rem;
  color: #9eb8cc;
  line-height: 1.5;
  max-width: 72ch;
}
.dc-archetype-head__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  align-items: center;
}
/* Information-dense file tab: top row uses width, dashboard uses a 3-column grid,
   every card sizes to its content. No fixed heights, no dead bands. */
.dc-dossier-pane--file > * {
  min-height: 0;
}
.dc-dossier-pane--file {
  display: flex;
  flex-direction: column;
  gap: var(--ds-gap, 12px);
  padding: clamp(8px, 1.4vh, 16px) clamp(12px, 1.2vw, 22px) clamp(10px, 1.6vh, 18px);
  overflow-y: auto;
}
.dc-dossier-topgrid {
  display: grid;
  grid-template-columns: minmax(300px, 0.92fr) minmax(0, 1.08fr);
  gap: var(--ds-gap, 12px);
  align-items: stretch;
}
.dc-dossier-topgrid > * {
  min-width: 0;
  margin: 0;
}
.dc-outcome-block {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: clamp(6px, 1vh, 12px);
}
.dc-dossier-dashboard {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--ds-gap, 12px);
  align-items: start;
}
.dc-dash-col {
  display: flex;
  flex-direction: column;
  gap: var(--ds-gap, 12px);
  min-width: 0;
}
.dc-dash-col > * {
  margin: 0;
}
.dc-dash-col .wr-office-strip,
.dc-dash-col .wr-office-strip--frame {
  margin: 0;
}

/* Intel tab has fewer blocks; let its analytics section take the slack. */
.dc-dossier-pane--intel {
  flex: 1 1 auto;
}
.dc-dossier-pane--intel > .dc-brochure-analytics {
  flex: 1 1 auto;
  min-height: 0;
}
.dc-dossier-pane--intel > .wr-scout-desk {
  flex: 0 0 auto;
}

/* Metric cards (readiness, confidence, dev path, projection) */
.dc-metric-card {
  display: flex;
  flex-direction: column;
  gap: clamp(3px, 0.6vh, 7px);
}
.dc-metric-card .dc-meter {
  height: clamp(6px, 1vh, 11px);
  background: rgba(118, 200, 245, 0.14);
  border: 1px solid rgba(118, 200, 245, 0.2);
  overflow: hidden;
}
.dc-metric-card .dc-meter i {
  display: block;
  height: 100%;
  background: var(--wr-fill-cyan);
}
.dc-metric-card__lead {
  margin: 0;
  font-family: var(--dc-font-title);
  font-size: var(--ds-head, 0.9rem);
  letter-spacing: 0.04em;
  color: #dbeafe;
}
.dc-metric-card__note {
  color: #6d8ba3;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-size: var(--ds-label, 0.62rem);
}
.dc-kv {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: clamp(3px, 0.6vh, 7px);
}
.dc-kv li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}
.dc-kv li span {
  color: #6d8ba3;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: var(--ds-label, 0.62rem);
  white-space: nowrap;
}
.dc-kv li strong {
  color: #dbeafe;
  text-align: right;
  font-size: var(--ds-body, 0.9rem);
}

@media (max-width: 1240px) {
  .dc-dossier-topgrid { grid-template-columns: 1fr; }
  .dc-dossier-dashboard { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 820px) {
  .dc-dossier-dashboard { grid-template-columns: 1fr; }
}
.dc-archetype-head .wr-now-peak--wide {
  align-self: flex-start;
  flex-wrap: wrap;
}
.wr-now-peak--wide {
  flex-shrink: 0;
  gap: 10px;
}
.wr-now-peak__label {
  display: block;
  font-size: 0.56rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: #7fa3bd;
  white-space: nowrap;
}
.wr-now-peak__arrow {
  display: grid;
  justify-items: center;
  gap: 1px;
  color: #f4c66e;
  font-size: 1rem;
  line-height: 1;
}
.wr-now-peak__arrow em {
  font-style: normal;
  font-family: var(--dc-font-mono);
  font-size: 0.68rem;
  color: #6cf7a6;
}
.dc-dev-trajectory {
  margin: 8px 0 0;
  padding: 8px 10px;
  border: 1px solid rgba(118, 200, 245, 0.14);
  background: rgba(12, 30, 74, 0.45);
  font-size: 0.78rem;
  line-height: 1.45;
  color: #c9dce8;
  max-width: none;
}
.dc-char-traits {
  margin: 8px 0 0;
  padding-left: 1.1rem;
  font-size: 0.72rem;
  color: #9db8cc;
}
.dc-char-traits li + li { margin-top: 2px; }
.dc-prospect-row__sub em.dc-char-pill {
  margin-right: 6px;
}
.dc-prospect-row__sub em.wr-reason-chip {
  margin-right: 6px;
}
.dc-file-depth {
  margin-top: 8px;
  padding: 7px 9px;
  border: 1px solid rgba(118, 200, 245, 0.14);
  background: rgba(255, 255, 255, 0.02);
}
.dc-file-depth__bar {
  height: 12px;
  display: flex;
  gap: 3px;
  margin: 6px 0 8px;
  background: rgba(8, 28, 44, 0.95);
  border: 1px solid rgba(43, 228, 255, 0.28);
  border-radius: 2px;
  overflow: hidden;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.35);
}
.dc-file-depth__bar i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #2be4ff 0%, #1aa0c4 55%, #0d7a94 100%);
  box-shadow: 0 0 10px rgba(43, 228, 255, 0.35);
}
.dc-file-depth strong {
  display: block;
  font-family: var(--dc-font-mono);
  font-size: 0.72rem;
  color: #2be4ff;
}
.dc-file-depth em {
  display: block;
  margin-top: 4px;
  font-style: normal;
  font-size: 0.68rem;
  color: #f4c66e;
}
.dc-file-depth small {
  display: block;
  margin-top: 3px;
  font-size: 0.62rem;
  color: #7fa3bd;
}
.dc-brochure-block {
  padding: 10px 16px;
  border-bottom: 1px solid rgba(118, 200, 245, 0.1);
}
.dc-brochure-block .wr-rink {
  max-width: none;
}
.dc-brochure-split-panels {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(240px, 0.95fr);
  gap: 10px;
  padding: 10px 16px;
  border-bottom: 1px solid rgba(118, 200, 245, 0.1);
  align-items: start;
}
.wr-muted { color: #2c4a60; font-weight: 400; }
.wr-rink--crease { padding: 12px 18px 6px; }
.wr-rink__svg--crease { width: 100%; display: block; }
.wr-svg-num { font-family: var(--dc-font-title); }
.wr-office-strip--frame { padding: 0; }
.wr-office-strip__grid { display: grid; gap: 9px; }
.wr-office-strip__row {
  display: grid;
  grid-template-columns: 84px auto minmax(0, 1fr) 34px;
  gap: 10px;
  align-items: center;
}
.wr-office-strip__label {
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #a8c4d8;
}
.wr-office-strip__row em {
  font-style: normal;
  font-size: 0.72rem;
  color: #9db8cc;
}
.wr-office-strip__row strong {
  font-family: var(--dc-font-number);
  font-size: 1.45rem;
  text-align: right;
}
.wr-office-strip__row.is-locked .wr-hatch {
  height: 11px;
  border: 1px solid #24455e;
}
.wr-hatch {
  background-image: repeating-linear-gradient(135deg, rgba(120, 150, 175, 0.14) 0 4px, transparent 4px 9px);
}
.is-locked-grade { color: #3a5c75 !important; }
.wr-scout-desk {
  padding: 12px 18px;
  border-bottom: 1px solid rgba(118, 200, 245, 0.1);
}
.wr-scout-desk__list { display: grid; gap: 6px; }
.wr-scout-desk__row {
  display: grid;
  grid-template-columns: 112px minmax(0, 1fr) 54px;
  gap: 10px;
  align-items: start;
  padding: 8px 10px;
  border: 1px solid rgba(118, 200, 245, 0.14);
  background: rgba(255, 255, 255, 0.02);
  border-left-width: 3px;
}
.wr-scout-desk__row.is-green { border-left-color: #6cf7a6; background: rgba(108, 247, 166, 0.04); }
.wr-scout-desk__row.is-amber { border-left-color: #f4b467; background: rgba(244, 180, 103, 0.04); }
.wr-scout-desk__row.is-cyan { border-left-color: #2be4ff; }
.wr-scout-desk__row.is-muted,
.wr-scout-desk__row.is-locked {
  border-style: dashed;
  border-left-color: #4a5a6b;
  opacity: 0.85;
}
.wr-scout-desk__name { font-size: 0.72rem; color: #e7f4ff; }
.wr-scout-desk__sub { font-size: 0.58rem; color: #7fa3bd; margin-top: 1px; }
.wr-scout-desk__hit {
  font-family: var(--dc-font-mono);
  font-size: 0.56rem;
  color: #6cf7a6;
  margin-top: 3px;
}
.wr-scout-desk__quote p {
  margin: 0;
  font-size: 0.72rem;
  line-height: 1.5;
  color: #cfe6da;
  font-style: italic;
}
.wr-scout-desk__redact {
  display: block;
  height: 12px;
  width: 100%;
}
.wr-scout-desk__grade {
  text-align: right;
}
.wr-scout-desk__grade strong {
  display: block;
  font-family: var(--dc-font-mono);
  font-size: 1.1rem;
}
.wr-scout-desk__grade span {
  font-size: 0.5rem;
  letter-spacing: 0.08em;
  color: #7fa3bd;
}
.wr-scout-desk__conf {
  display: block;
  margin-top: 8px;
  font-size: 0.62rem;
  color: #7fa3bd;
}
.wr-stat-strip {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: #16354a;
  border-top: 1px solid rgba(118, 200, 245, 0.18);
  border-bottom: 1px solid rgba(118, 200, 245, 0.1);
}
.wr-stat-strip__cell {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 8px;
  padding: 7px 10px;
  text-align: left;
  background: linear-gradient(180deg, #0d2556, #0c1f4a);
  transition: background 120ms ease, box-shadow 120ms ease;
  border: 0;
  color: inherit;
  font: inherit;
}
.wr-stat-strip.is-toggleable .wr-stat-strip__cell {
  cursor: pointer;
}
.wr-stat-strip__cell:disabled {
  cursor: default;
}
.wr-stat-strip__cell:hover:not(:disabled),
.wr-stat-strip__cell:focus-visible {
  background: linear-gradient(180deg, #0a2032, #0c2352);
  box-shadow: inset 0 -2px 0 rgba(43, 228, 255, 0.5);
  outline: none;
}
.wr-stat-strip__cell span {
  font-size: 0.58rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #6d8ba3;
  white-space: nowrap;
}
.wr-stat-strip__cell strong {
  font-family: var(--dc-font-title);
  font-size: 1.32rem;
  line-height: 1;
  letter-spacing: 0.02em;
}
.dc-brochure-analytics--inline {
  display: grid;
  grid-template-columns: minmax(200px, 0.75fr) minmax(0, 1.25fr);
  gap: 10px;
  padding: 10px 16px;
  overflow: visible;
  min-height: unset;
  align-items: start;
}
.dc-signal-chart.is-compact .dc-signal-chart__svg,
.dc-signal-chart--weekly.is-compact .dc-signal-chart__svg {
  height: 72px;
  min-height: 72px;
}
.dc-signal-chart.is-compact {
  padding: 0;
}
.dc-dossier-gaps {
  margin: 0 18px 8px;
  padding: 8px 10px;
  border: 1px dashed rgba(255, 143, 156, 0.35);
  background: rgba(255, 143, 156, 0.05);
}
.dc-dossier-gaps p {
  margin: 0;
  font-size: 0.62rem;
  line-height: 1.4;
  color: #c8a0a8;
}

@media (max-width: 860px) {
  .dc-dossier-split {
    flex-direction: column;
  }
  .dc-dossier-identity-rail {
    flex: 0 0 auto;
    max-width: none;
    min-width: 0;
    border-right: none;
    border-bottom: 1px solid rgba(118, 200, 245, 0.12);
  }
  .dc-brochure-hero--rail .dc-archetype-head,
  .dc-brochure-hero,
  .dc-brochure-split-panels,
  .dc-brochure-analytics--inline,
  .dc-archetype-head,
  .dc-dossier-pane--file {
    grid-template-columns: 1fr;
  }
  .wr-now-peak--wide { justify-content: flex-start; }
}

/* Brochure dossier (legacy grid — kept for other surfaces; not the tabbed dossier shell) */
.dc-brochure:not(.dc-brochure--deep) {
  display: grid;
  grid-template-columns: minmax(220px, 250px) minmax(0, 1.4fr) minmax(260px, 320px);
  grid-template-rows: auto minmax(0, 1.05fr) minmax(220px, 0.85fr) auto;
  grid-template-areas:
    "banner banner banner"
    "identity dna reports"
    "identity analytics analytics"
    "media media media";
  width: min(1480px, 98vw);
  height: min(96vh, 980px);
  height: min(96dvh, 980px);
}
.dc-brochure .dc-signal-banner { grid-area: banner; }
.dc-brochure:not(.dc-brochure--deep) .dc-signal-identity { grid-area: identity; overflow: auto; }
.dc-brochure .dc-brochure-dna { grid-area: dna; min-height: 0; overflow: auto; }
.dc-brochure .dc-brochure-reports { grid-area: reports; min-height: 0; overflow: auto; }
.dc-brochure .dc-brochure-analytics { grid-area: analytics; min-height: 0; overflow: hidden; }
.dc-brochure .dc-brochure-media { grid-area: media; min-height: 0; overflow: auto; }

.dc-brochure-dna,
.dc-brochure-reports,
.dc-brochure-analytics {
  padding: 10px 12px;
  border-left: 1px solid rgba(118, 200, 245, 0.14);
}
.dc-brochure-dna {
  display: grid;
  grid-template-columns: minmax(280px, 1.1fr) minmax(220px, 0.9fr);
  gap: 10px;
}
.dc-skill-dna--xl { width: 100%; }
.dc-skill-dna--xl .dc-skill-dna__stage {
  width: min(100%, 360px);
}
.dc-skill-dna__dev {
  margin: 0;
  font-size: 0.72rem;
  color: #cfe6f6;
  line-height: 1.35;
}
.dc-skill-dna__ranges div.is-weak strong { color: #ff8f9c; }
.dc-skill-dna__ranges div.is-plus strong { color: #34d399; }
.dc-proj-plain {
  display: grid;
  gap: 8px;
  align-content: start;
}
.dc-proj-plain__row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid rgba(118, 200, 245, 0.16);
  background: rgba(12, 30, 74, 0.55);
}
.dc-proj-plain__row span {
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--dc-muted);
}
.dc-proj-plain__row strong {
  font-family: var(--dc-font-number);
  font-size: 1.45rem;
  line-height: 1;
  color: #f4e7c8;
}
.dc-proj-plain__row em {
  grid-column: 1 / -1;
  font-style: normal;
  font-size: 0.68rem;
  color: #9db8cc;
}
.dc-proj-plain__row.is-peak strong { color: #ffd24a; }
.dc-proj-plain__row.is-worst strong { color: #ff8f9c; }

.dc-report-stack { display: grid; gap: 8px; align-content: start; }
.dc-report-card {
  padding: 8px 10px;
  border: 1px solid rgba(118, 200, 245, 0.14);
  background: rgba(12, 30, 74, 0.5);
}
.dc-report-card h4 {
  margin: 0 0 6px;
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--dc-cyan);
}
.dc-report-card.is-concern h4 { color: #ff8f9c; }
.dc-report-card.is-overage h4 { color: #a78b6a; }
.dc-report-card p,
.dc-report-card li {
  margin: 0;
  font-size: 0.78rem;
  line-height: 1.4;
  color: #d5e7f4;
}
.dc-report-card ul { margin: 0; padding-left: 16px; display: grid; gap: 4px; }

.dc-brochure-analytics {
  display: grid;
  grid-template-columns: minmax(280px, 0.9fr) minmax(0, 1.3fr);
  gap: 10px;
}
.dc-signal-metrics--focus {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
}
.dc-signal-chart--weekly .dc-signal-chart__svg {
  height: 150px;
  min-height: 150px;
  width: 100%;
}
.dc-signal-chart--weekly.is-compact .dc-signal-chart__svg {
  height: 72px;
  min-height: 72px;
}

.dc-headshot--bloom {
  filter: drop-shadow(0 0 16px rgba(255, 210, 74, 0.55)) brightness(1.16) saturate(1.12);
}
.dc-headshot--zoom {
  overflow: hidden;
}
.dc-headshot--zoom .ph-nhl-image,
.dc-headshot--zoom.player-headshot {
  transform: scale(1.28);
  transform-origin: 50% 18%;
}
.dc-headshot--crop .ph-nhl-image {
  object-fit: cover;
  object-position: center 22%;
  transform: scale(1.12);
}

.dc-brochure-media {
  padding: 8px 16px 8px;
  border-top: 1px solid rgba(118, 200, 245, 0.18);
  background: linear-gradient(180deg, rgba(12, 30, 74, 0.55), rgba(11, 28, 67, 0.82));
}
.dc-brochure-media .dc-media-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
  gap: 8px;
}
.dc-brochure-media .dc-media-card {
  min-height: 0;
}
.dc-brochure-media .dc-media-card--wide {
  grid-column: 1 / -1;
}
.dc-media-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}
.dc-media-head span {
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dc-muted);
}
.dc-media-head strong {
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #c9e8ff;
}
.dc-media-head em {
  margin-left: auto;
  font-style: normal;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #e9a83c;
}
.dc-media-empty {
  margin: 0;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #9db8cc;
}
.dc-media-social-profile {
  display: grid;
  gap: 4px;
  margin-bottom: 8px;
}
.dc-media-social-profile strong {
  font-size: 0.82rem;
  color: #d8f4ff;
}
.dc-media-social-profile span,
.dc-media-social-profile em {
  font-size: 0.68rem;
  color: #9db8cc;
  font-style: normal;
}
.dc-media-social-profile p {
  margin: 0;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #c7dde8;
}
.dc-media-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.dc-media-card {
  border: 1px solid rgba(118, 200, 245, 0.14);
  background: rgba(12, 30, 74, 0.62);
  padding: 8px 10px;
  min-height: 0;
}
.dc-media-card--wide { grid-column: span 2; }
.dc-media-card h4 {
  margin: 0 0 6px;
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--dc-cyan);
}
.dc-media-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
.dc-media-tag {
  font-size: 0.62rem;
  font-weight: 800;
  padding: 3px 7px;
  border: 1px solid rgba(233, 168, 60, 0.28);
  background: rgba(233, 168, 60, 0.08);
  color: #f4d9a6;
}
.dc-media-note {
  margin: 6px 0 0;
  font-size: 0.68rem;
  color: #b8d4e8;
  line-height: 1.35;
}
.dc-media-pubs,
.dc-media-wire {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 6px;
}
.dc-media-pubs li,
.dc-media-wire li {
  display: grid;
  gap: 2px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(118, 200, 245, 0.1);
}
.dc-media-pubs li:last-child,
.dc-media-wire li:last-child { border-bottom: 0; padding-bottom: 0; }
.dc-media-pubs strong,
.dc-media-wire strong {
  font-size: 0.72rem;
  color: #e8f4fc;
}
.dc-media-pubs span {
  font-family: var(--dc-font-number);
  font-size: 0.85rem;
  color: #e9a83c;
}
.dc-media-pubs p,
.dc-media-wire p {
  margin: 0;
  font-size: 0.66rem;
  color: #8aa8be;
  line-height: 1.35;
}
.dc-media-arcs { display: grid; gap: 8px; }
.dc-media-arc {
  border: 1px solid rgba(118, 200, 245, 0.12);
  padding: 6px 8px;
  background: rgba(11, 28, 67, 0.45);
}
.dc-media-arc__head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: baseline;
  margin-bottom: 4px;
}
.dc-media-arc__head strong {
  font-size: 0.72rem;
  line-height: 1.3;
}
.dc-media-arc__head span {
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #7aa4bc;
  white-space: nowrap;
}
.dc-media-timeline {
  margin: 0;
  padding: 0 0 0 14px;
  display: grid;
  gap: 4px;
}
.dc-media-timeline li {
  font-size: 0.66rem;
  line-height: 1.35;
  color: #b8d0e0;
}
.dc-media-timeline time {
  display: block;
  font-family: var(--dc-font-mono);
  font-size: 0.58rem;
  color: #6d8ea3;
}
.dc-media-timeline em {
  display: inline-block;
  margin-left: 6px;
  font-style: normal;
  font-size: 0.56rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #e9a83c;
}
.dc-media-wire time {
  font-family: var(--dc-font-mono);
  font-size: 0.58rem;
  color: #6d8ea3;
}

@media (max-width: 1200px) {
  .dc-brochure:not(.dc-brochure--deep) {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto auto auto auto;
    grid-template-areas:
      "banner"
      "identity"
      "dna"
      "reports"
      "analytics"
      "media";
    height: 96vh;
    overflow: auto;
  }
  .dc-brochure-dna,
  .dc-brochure-analytics { grid-template-columns: 1fr; }
  .dc-media-grid { grid-template-columns: 1fr; }
  .dc-media-card--wide { grid-column: span 1; }
}

/* ==========================================================================
   Full-screen dossier — scale with the viewport, centre inside the panels.
   The shell fills the screen, so panel content must grow with it and sit in
   the middle of its box. Otherwise the panels stretch while the text stays
   small in the top-left corner and the screen reads empty.
   ========================================================================== */
.dc-profile-modal--prospect .dc-dossier-shell {
  --ds-label: clamp(0.6rem, 0.95vh + 0.16rem, 0.86rem);
  --ds-head: clamp(0.74rem, 1.05vh + 0.22rem, 1rem);
  --ds-body: clamp(0.8rem, 1.15vh + 0.28rem, 1.12rem);
  --ds-num: clamp(1.3rem, 3vh, 2.2rem);
  --ds-gap: clamp(8px, 1.5vh, 20px);
}

.dc-profile-modal--prospect .dc-profile-tags__label {
  font-size: var(--ds-label);
  letter-spacing: 0.18em;
}

/* Hero copy */
.dc-profile-modal--prospect .dc-archetype-head__blurb,
.dc-profile-modal--prospect .dc-archetype-head__report,
.dc-profile-modal--prospect .dc-archetype-head__metrics .dc-dev-trajectory {
  font-size: var(--ds-body);
  line-height: 1.5;
}

/* Give the written report the room and the zone map less dead width */
.dc-profile-modal--prospect .dc-dossier-pane--file > .dc-brochure-split-panels {
  grid-template-columns: minmax(0, 0.85fr) minmax(320px, 1.15fr);
  gap: var(--ds-gap);
}

/* Report panels: centre the content, scale the type */
.dc-profile-modal--prospect .dc-dossier-pane--file .dc-report-stack--compact {
  align-content: stretch;
  gap: var(--ds-gap);
}
.dc-profile-modal--prospect .dc-dossier-pane--file .dc-report-stack--compact .dc-report-card {
  justify-content: center;
  padding: clamp(10px, 1.7vh, 24px) clamp(12px, 1.3vw, 26px);
}
.dc-profile-modal--prospect .dc-report-stack--compact .dc-report-card h4 {
  font-size: var(--ds-head);
  margin-bottom: clamp(5px, 1vh, 12px);
}
.dc-profile-modal--prospect .dc-report-stack--compact .dc-report-card li,
.dc-profile-modal--prospect .dc-report-stack--compact .dc-report-card p {
  font-size: var(--ds-body);
  line-height: 1.5;
}
.dc-profile-modal--prospect .dc-report-stack--compact .dc-report-card ul {
  display: grid;
  gap: clamp(4px, 0.8vh, 11px);
  margin: 0;
}
.dc-profile-modal--prospect .dc-char-traits {
  margin-top: clamp(5px, 1vh, 12px);
}

/* Off-ice & chapter scores: centre in its column and use the width */
.dc-profile-modal--prospect .wr-office-strip--frame {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: var(--ds-gap);
}
.dc-profile-modal--prospect .wr-office-strip__grid {
  gap: clamp(8px, 1.4vh, 18px);
}
.dc-profile-modal--prospect .wr-office-strip__row {
  grid-template-columns: minmax(92px, 0.7fr) auto minmax(0, 1.3fr) 46px;
  gap: clamp(8px, 1vw, 18px);
}
.dc-profile-modal--prospect .wr-office-strip__label {
  font-size: var(--ds-head);
}
.dc-profile-modal--prospect .wr-office-strip__row em {
  font-size: var(--ds-body);
}
.dc-profile-modal--prospect .wr-office-strip__row strong {
  font-size: var(--ds-num);
}
.dc-profile-modal--prospect .wr-office-pips i {
  width: clamp(7px, 0.65vw, 12px);
  height: clamp(10px, 1.5vh, 19px);
}

/* Zone map + outcome ribbon span their row */
.dc-profile-modal--prospect .wr-rink__board,
.dc-profile-modal--prospect .wr-rink__svg {
  width: 100%;
}
.dc-profile-modal--prospect .wr-outcome-ribbon {
  height: clamp(16px, 2.6vh, 30px);
}
.dc-profile-modal--prospect .wr-outcome-legend {
  font-size: var(--ds-label);
}

/* Tool grades scale with the screen */
.dc-profile-modal--prospect .wr-stat-strip__cell {
  padding: clamp(8px, 1.5vh, 20px) 12px;
  gap: clamp(6px, 0.8vw, 14px);
}
.dc-profile-modal--prospect .wr-stat-strip__cell span {
  font-size: var(--ds-label);
}
.dc-profile-modal--prospect .wr-stat-strip__cell strong {
  font-size: var(--ds-num);
}

/* Identity rail keeps pace */
.dc-profile-modal--prospect .dc-signal-bio li div span {
  font-size: var(--ds-label);
}
.dc-profile-modal--prospect .dc-signal-bio li div strong {
  font-size: var(--ds-body);
}
.dc-profile-modal--prospect .dc-file-depth strong,
.dc-profile-modal--prospect .dc-file-depth em,
.dc-profile-modal--prospect .dc-file-depth small {
  font-size: var(--ds-label);
}

/* Intel tab: centre its analytics so it does not leave a tall gap */
.dc-profile-modal--prospect .dc-dossier-pane--intel > .dc-brochure-analytics {
  display: grid;
  align-content: center;
  gap: var(--ds-gap);
}
.dc-profile-modal--prospect .dc-signal-metrics--dossier {
  gap: var(--ds-gap);
}
.dc-profile-modal--prospect .wr-scout-desk__row {
  padding: clamp(6px, 1.1vh, 14px) clamp(8px, 0.9vw, 16px);
}
.dc-profile-modal--prospect .wr-scout-desk__quote p,
.dc-profile-modal--prospect .wr-scout-desk__name {
  font-size: var(--ds-body);
}
.dc-pot-trend { margin-left: 4px; font-size: 0.72em; font-weight: 700; letter-spacing: 0.02em; }
.dc-pot-trend.is-rising { color: #3fb27f; }
.dc-pot-trend.is-falling { color: #d9534f; }

/* ==========================================================================
   SECTION: styles/storylinesTokens.css
   ========================================================================== */
/* Storylines design tokens + shared controls (source: StorylinesScreen.js) */

.storylines-skin {
  --bg-deep: #0c1e47;
  --panel: rgba(15, 40, 90, 0.82);
  --panel-2: rgba(14, 35, 81, 0.78);
  --panel-3: rgba(12, 32, 75, 0.94);
  --line: rgba(150, 214, 235, 0.13);
  --line-2: rgba(150, 214, 235, 0.24);
  --line-strong: rgba(46, 230, 214, 0.55);
  --text: #eaf7fc;
  --muted: #7e94a6;
  --muted-2: #9fb4c4;
  --cyan: #2ee6d6;
  --cyan-dim: rgba(46, 230, 214, 0.14);
  --gold: #e9a83c;
  --brass: #c9a227;
  --gold-dim: rgba(233, 168, 60, 0.14);
  --green: #52df94;
  --red: #ff5f6d;
  --red-dim: rgba(255, 95, 109, 0.14);
  --ember: #ff8a4c;
  --purple: #c992ff;

  color: var(--text);
  font-family: var(--dd-font-ui);
}

.storylines-skin .sl-back {
  border: 1px solid var(--line-2);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.03);
  cursor: pointer;
  color: var(--cyan);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 11px;
}
.storylines-skin .sl-back:hover {
  border-color: var(--line-strong);
  background: var(--cyan-dim);
}

.storylines-skin .sl-nav-btn {
  height: 34px;
  padding: 0 15px;
  border-radius: 8px;
  cursor: pointer;
  border: 1px solid var(--line-2);
  background: rgba(14, 36, 52, 0.8);
  color: var(--text);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.12s ease;
}
.storylines-skin .sl-nav-btn:hover:not(:disabled) {
  border-color: var(--line-strong);
  background: rgba(46, 230, 214, 0.12);
  transform: translateY(-1px);
}
.storylines-skin .sl-nav-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.storylines-skin .sl-choice--lead {
  position: relative;
  overflow: hidden;
  text-align: center;
  cursor: pointer;
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 10px;
  border: 1px solid rgba(201, 162, 39, 0.4);
  background: linear-gradient(180deg, rgba(233, 168, 60, 0.13), rgba(255, 255, 255, 0.02));
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.12s ease;
}
.storylines-skin .sl-choice--lead::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--gold);
  opacity: 0.85;
}
.storylines-skin .sl-choice--lead:hover:not(:disabled) {
  border-color: rgba(233, 168, 60, 0.75);
  background: linear-gradient(180deg, rgba(233, 168, 60, 0.24), rgba(255, 255, 255, 0.04));
  transform: translateY(-1px);
}
.storylines-skin .sl-choice--lead:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.storylines-skin .sl-chips {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}
.storylines-skin .sl-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(15, 42, 92, 0.6);
  color: rgba(234, 247, 252, 0.7);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.storylines-skin .sl-chip.is-active {
  border-color: var(--line-strong);
  background: var(--cyan-dim);
  color: var(--text);
}

.storylines-skin .sl-panel {
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px 16px;
  background: linear-gradient(180deg, rgba(15, 41, 91, 0.86), rgba(12, 32, 75, 0.9));
}
.storylines-skin .sl-panel h3 {
  margin: 0 0 12px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--cyan);
}

.storylines-skin .sl-muted {
  color: var(--muted-2);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.45;
}

.storylines-skin .sl-alert {
  margin: 10px 0 0;
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid rgba(255, 95, 109, 0.35);
  background: var(--red-dim);
  color: #ffb4bb;
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.35;
}

/* ==========================================================================
   SECTION: styles/meetingsDesk.css
   ========================================================================== */
/* Player Meetings — relationship desk (issues / good news / roster). Uses storylinesTokens vars. */

.storylines-skin .md-desk {
  --md-critical: var(--red, #ff5f6d);
  --md-warning: var(--gold, #e9a83c);
  --md-watch: var(--muted-2, #9fb4c4);
  --md-good: var(--green, #52df94);
  --md-request: var(--cyan, #2ee6d6);
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* header + tally ---------------------------------------------------------- */
.storylines-skin .md-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  flex-wrap: wrap;
}
.storylines-skin .md-kicker {
  margin: 0 0 4px;
  color: var(--gold);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.storylines-skin .md-head h2 {
  margin: 0;
  font-size: 22px;
  font-weight: 900;
}
.storylines-skin .md-sub {
  margin: 4px 0 0;
  color: var(--muted-2);
  font-size: 13px;
}
.storylines-skin .md-tally {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.storylines-skin .md-tally__item {
  min-width: 92px;
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid var(--line-2);
  background: var(--panel-2);
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.storylines-skin .md-tally__item strong {
  font-size: 22px;
  font-weight: 900;
  line-height: 1;
}
.storylines-skin .md-tally__item span {
  color: var(--muted-2);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.storylines-skin .md-tally__item.is-critical strong { color: var(--md-critical); }
.storylines-skin .md-tally__item.is-warning strong { color: var(--md-warning); }
.storylines-skin .md-tally__item.is-request strong { color: var(--md-request); }
.storylines-skin .md-tally__item.is-good strong { color: var(--md-good); }
.storylines-skin .md-tally__item.is-calm strong { color: var(--text); }
.storylines-skin .md-tally__item.is-critical:not(.is-zero) { border-color: rgba(255, 95, 109, 0.45); background: var(--red-dim); }
.storylines-skin .md-tally__item.is-zero { opacity: 0.55; }

/* sections ---------------------------------------------------------------- */
.storylines-skin .md-section { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.storylines-skin .md-section__bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.storylines-skin .md-section__title {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--cyan);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.storylines-skin .md-section__title em {
  font-style: normal;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--cyan-dim);
  color: var(--text);
  font-size: 11px;
}
.storylines-skin .md-section__title--bad { color: var(--md-warning); }
.storylines-skin .md-section__title--bad em { background: var(--gold-dim); }
.storylines-skin .md-section__title--good { color: var(--md-good); }
.storylines-skin .md-section__title--good em { background: rgba(82, 223, 148, 0.14); }

.storylines-skin .md-columns {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}
@media (max-width: 1100px) {
  .storylines-skin .md-columns { grid-template-columns: minmax(0, 1fr); }
}

/* requests ---------------------------------------------------------------- */
.storylines-skin .md-requests {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
  gap: 10px;
}
.storylines-skin .md-request {
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--md-request);
  border-radius: 10px;
  padding: 12px 14px;
  background: var(--panel);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.storylines-skin .md-request.is-positive { border-left-color: var(--md-good); }
.storylines-skin .md-request.is-negative { border-left-color: var(--md-warning); }
.storylines-skin .md-request__who { display: flex; gap: 10px; align-items: center; }
.storylines-skin .md-request__who div { display: flex; flex-direction: column; gap: 2px; }
.storylines-skin .md-request__who strong { font-size: 14px; }
.storylines-skin .md-request h4 { margin: 2px 0 0; font-size: 13px; font-weight: 800; }
.storylines-skin .md-request p { margin: 0; color: var(--muted-2); font-size: 12.5px; line-height: 1.4; }
.storylines-skin .md-tone {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--md-request);
}
.storylines-skin .md-tone--positive { color: var(--md-good); }
.storylines-skin .md-tone--negative { color: var(--md-warning); }
.storylines-skin .md-request__choices {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 6px;
  margin-top: 4px;
}
.storylines-skin .md-choice {
  text-align: left;
  cursor: pointer;
  border: 1px solid var(--line-2);
  border-radius: 8px;
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--text);
  display: flex;
  flex-direction: column;
  gap: 3px;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.storylines-skin .md-choice strong { font-size: 11.5px; font-weight: 900; }
.storylines-skin .md-choice span { color: var(--muted); font-size: 11px; line-height: 1.35; }
.storylines-skin .md-choice:hover:not(:disabled) { border-color: var(--line-strong); background: var(--cyan-dim); }
.storylines-skin .md-choice:disabled { opacity: 0.5; cursor: not-allowed; }

/* cards ------------------------------------------------------------------- */
.storylines-skin .md-cards { display: flex; flex-direction: column; gap: 10px; }
.storylines-skin .md-card {
  border: 1px solid var(--line);
  border-left: 3px solid var(--md-watch);
  border-radius: 10px;
  padding: 12px 14px;
  background: var(--panel);
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.storylines-skin .md-card.is-critical { border-left-color: var(--md-critical); }
.storylines-skin .md-card.is-warning { border-left-color: var(--md-warning); }
.storylines-skin .md-card.is-good { border-left-color: var(--md-good); }
.storylines-skin .md-card__head { display: flex; align-items: center; gap: 12px; }
.storylines-skin .md-card__id { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.storylines-skin .md-card__id span { color: var(--muted); font-size: 11.5px; font-weight: 700; }
.storylines-skin .md-link {
  all: unset;
  cursor: pointer;
  font-size: 15px;
  font-weight: 900;
  color: var(--text);
}
.storylines-skin .md-link:hover { color: var(--cyan); text-decoration: underline; }

.storylines-skin .md-pill {
  flex-shrink: 0;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 1px solid currentColor;
}
.storylines-skin .md-pill--critical { color: var(--md-critical); background: var(--red-dim); }
.storylines-skin .md-pill--warning { color: var(--md-warning); background: var(--gold-dim); }
.storylines-skin .md-pill--watch { color: var(--md-watch); }
.storylines-skin .md-pill--good { color: var(--md-good); background: rgba(82, 223, 148, 0.12); }

/* meters ------------------------------------------------------------------ */
.storylines-skin .md-meters { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.storylines-skin .md-meter { display: flex; flex-direction: column; gap: 4px; }
.storylines-skin .md-meter > span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.storylines-skin .md-mini {
  display: flex;
  align-items: center;
  gap: 8px;
}
.storylines-skin .md-mini__track {
  flex: 1;
  height: 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
}
.storylines-skin .md-mini i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--md-watch);
}
.storylines-skin .md-mini b { width: 26px; text-align: right; font-size: 11.5px; font-weight: 900; }
.storylines-skin .md-mini.is-critical i { background: var(--md-critical); }
.storylines-skin .md-mini.is-critical b { color: var(--md-critical); }
.storylines-skin .md-mini.is-warning i { background: var(--md-warning); }
.storylines-skin .md-mini.is-warning b { color: var(--md-warning); }
.storylines-skin .md-mini.is-good i { background: var(--md-good); }

/* issues ------------------------------------------------------------------ */
.storylines-skin .md-issues { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.storylines-skin .md-issue {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.025);
  border-left: 2px solid var(--md-watch);
}
.storylines-skin .md-issue.is-critical { border-left-color: var(--md-critical); background: rgba(255, 95, 109, 0.06); }
.storylines-skin .md-issue.is-warning { border-left-color: var(--md-warning); background: rgba(233, 168, 60, 0.05); }
.storylines-skin .md-issue.is-good { border-left-color: var(--md-good); background: rgba(82, 223, 148, 0.05); }
.storylines-skin .md-issue strong { display: block; font-size: 12.5px; font-weight: 800; }
.storylines-skin .md-issue p { margin: 2px 0 0; color: var(--muted-2); font-size: 11.5px; line-height: 1.35; }
.storylines-skin .md-fix {
  flex-shrink: 0;
  max-width: 46%;
  cursor: pointer;
  border: 1px solid rgba(233, 168, 60, 0.45);
  border-radius: 7px;
  padding: 6px 10px;
  background: var(--gold-dim);
  color: var(--text);
  font-size: 11px;
  font-weight: 800;
  text-align: left;
}
.storylines-skin .md-fix:hover:not(:disabled) { border-color: var(--gold); }
.storylines-skin .md-fix.is-good { border-color: rgba(82, 223, 148, 0.45); background: rgba(82, 223, 148, 0.1); }
.storylines-skin .md-fix.is-good:hover:not(:disabled) { border-color: var(--md-good); }
.storylines-skin .md-fix:disabled { opacity: 0.5; cursor: not-allowed; }
.storylines-skin .md-fix--none {
  cursor: default;
  border-color: var(--line);
  background: transparent;
  color: var(--muted);
  font-weight: 700;
}

.storylines-skin .md-empty {
  border: 1px dashed var(--line-2);
  border-radius: 10px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.storylines-skin .md-empty strong { font-size: 13px; }
.storylines-skin .md-empty span { color: var(--muted-2); font-size: 12px; }

/* promises ---------------------------------------------------------------- */
.storylines-skin .md-promises { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 8px; }
.storylines-skin .md-promise {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px 12px;
  background: var(--panel-2);
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2px 10px;
}
.storylines-skin .md-promise strong { font-size: 12.5px; }
.storylines-skin .md-promise span { grid-column: 1; color: var(--muted-2); font-size: 11.5px; }
.storylines-skin .md-promise em {
  grid-column: 2;
  grid-row: 1 / span 2;
  align-self: center;
  font-style: normal;
  font-size: 11px;
  font-weight: 900;
  color: var(--cyan);
}
.storylines-skin .md-promise.is-due { border-color: rgba(233, 168, 60, 0.5); }
.storylines-skin .md-promise.is-due em { color: var(--md-warning); }

/* roster table ------------------------------------------------------------ */
.storylines-skin .md-table { display: flex; flex-direction: column; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; }
.storylines-skin .md-table__row {
  all: unset;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: minmax(180px, 2fr) 60px repeat(3, minmax(90px, 1fr)) minmax(160px, 2fr);
  gap: 12px;
  align-items: center;
  padding: 8px 14px;
  border-top: 1px solid var(--line);
  font-size: 12.5px;
  cursor: pointer;
}
.storylines-skin .md-table__row:hover { background: rgba(46, 230, 214, 0.05); }
.storylines-skin .md-table__row--head {
  cursor: default;
  border-top: 0;
  background: var(--panel-3);
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.storylines-skin .md-table__row--head:hover { background: var(--panel-3); }
.storylines-skin .md-table__who { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.storylines-skin .md-table__who strong { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.storylines-skin .md-table__who em { font-style: normal; color: var(--muted); font-size: 11px; white-space: nowrap; }
.storylines-skin .md-table__status { color: var(--muted-2); font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.storylines-skin .md-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
  align-self: center;
  background: var(--md-watch);
}
.storylines-skin .md-table__row.mood-negative .md-dot { background: var(--md-warning); }
.storylines-skin .md-table__row.mood-negative .md-table__status { color: var(--md-warning); }
.storylines-skin .md-table__row.mood-positive .md-dot { background: var(--md-good); }
.storylines-skin .md-table__row.mood-positive .md-table__status { color: var(--md-good); }

.storylines-skin .md-player-issues {
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 14px;
  background: var(--panel);
  gap: 10px;
}

/* post-meeting result overlay --------------------------------------------- */
.md-result {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(11, 28, 67, 0.72);
  backdrop-filter: blur(4px);
  animation: md-fade 0.18s ease-out;
}
.md-result__card {
  --md-tone: #e9a83c;
  width: min(560px, 100%);
  max-height: 90vh;
  overflow: auto;
  border-radius: 16px;
  border: 1px solid rgba(150, 214, 235, 0.24);
  border-top: 5px solid var(--md-tone);
  background: linear-gradient(180deg, rgba(12, 30, 46, 0.98), rgba(12, 32, 75, 0.98));
  color: #eaf7fc;
  padding: 22px 24px 20px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.55);
  display: flex;
  flex-direction: column;
  gap: 14px;
  animation: md-pop 0.22s cubic-bezier(0.2, 0.9, 0.3, 1.2);
  font-family: var(--dd-font-ui);
}
.md-result__card.is-positive { --md-tone: #52df94; }
.md-result__card.is-negative { --md-tone: #ff5f6d; }
.md-result__verdict {
  margin: 0;
  color: var(--md-tone);
  font-size: 20px;
  font-weight: 900;
  letter-spacing: 0.02em;
}
.md-result__who { display: flex; align-items: center; gap: 14px; }
.md-result__who div { display: flex; flex-direction: column; gap: 3px; }
.md-result__who strong { font-size: 18px; font-weight: 900; }
.md-result__who span { color: #9fb4c4; font-size: 12.5px; }
.md-result__quote {
  margin: 0;
  padding: 12px 16px;
  border-left: 3px solid var(--md-tone);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  font-size: 16px;
  font-style: italic;
  line-height: 1.45;
}
.md-result__impacts {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.md-result__impacts li {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2px 8px;
  padding: 10px 12px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(150, 214, 235, 0.13);
}
.md-result__impacts li span { font-size: 11px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #9fb4c4; }
.md-result__impacts li strong { grid-row: 1 / span 2; grid-column: 2; align-self: center; font-size: 18px; font-weight: 900; }
.md-result__impacts li em { font-style: normal; font-size: 12px; color: #7e94a6; }
.md-result__impacts li.is-good strong { color: #52df94; }
.md-result__impacts li.is-bad strong { color: #ff5f6d; }
.md-result__impacts li.is-good { border-color: rgba(82, 223, 148, 0.3); }
.md-result__impacts li.is-bad { border-color: rgba(255, 95, 109, 0.3); }
.md-result__note {
  margin: 0;
  padding: 9px 12px;
  border-radius: 8px;
  background: rgba(233, 168, 60, 0.12);
  color: #f3c77a;
  font-size: 12.5px;
  font-weight: 700;
}
.md-result__close {
  align-self: flex-end;
  cursor: pointer;
  border: 1px solid var(--md-tone);
  border-radius: 9px;
  padding: 10px 18px;
  background: transparent;
  color: #eaf7fc;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.md-result__close:hover { background: rgba(255, 255, 255, 0.06); }
@keyframes md-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes md-pop { from { transform: translateY(12px) scale(0.96); opacity: 0; } to { transform: none; opacity: 1; } }
@media (max-width: 560px) { .md-result__impacts { grid-template-columns: minmax(0, 1fr); } }

/* ==========================================================================
   SECTION: events/shared/edraftSkin.css
   ========================================================================== */
/* Entry Draft visual language shared by offseason event screens (Combine, Lottery).
   Same tokens, fonts, panels and buttons as the Entry Draft (.edraft-root). */
.edraft-skin {
  --ops-navy: #0c214d;
  --ops-navy-deep: #0b1d45;
  --ops-black: #0d2352;
  --ops-panel: rgba(14, 40, 88, 0.94);
  --ops-panel-2: rgba(12, 35, 52, 0.94);
  --ops-panel-3: rgba(15, 46, 66, 0.78);
  --ops-grid: rgba(156, 218, 236, 0.14);
  --ops-grid-2: rgba(115, 229, 241, 0.25);
  --ops-grid-strong: rgba(46, 230, 214, 0.5);
  --ops-text: #e9f7fb;
  --ops-text-secondary: #8096a8;
  --ops-text-disabled: #607789;
  --ops-cyan: #2ee6d6;
  --ops-cyan-soft: rgba(46, 230, 214, 0.13);
  --ops-gold: #e9a83c;
  --ops-gold-soft: rgba(233, 168, 60, 0.14);
  --ops-success: #52df94;
  --ops-injury: #ff606d;
  --ed-head: var(--dd-font-ui);
  background:
    radial-gradient(circle at 24% 0%, rgba(46, 230, 214, 0.12), transparent 30%),
    radial-gradient(circle at 92% 18%, rgba(233, 168, 60, 0.08), transparent 26%),
    linear-gradient(180deg, #0d2352 0%, #0b1d45 100%) !important;
  color: #e9f7fb;
  font-size: 14px;
  letter-spacing: 0.01em;
}
.edraft-skin h1,
.edraft-skin h2,
.edraft-skin h3,
.edraft-skin h4,
.edraft-skin .dlot-title,
.edraft-skin .dlot-eyebrow,
.edraft-skin .dcb-panel-head {
  font-family: var(--ed-head);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
/* Combine: no calendar side rail — full-width like the Entry Draft floor. */
.edraft-skin.nhlcal-root {
  grid-template-columns: minmax(0, 1fr);
}
.edraft-skin .nhlcal-sidebar {
  display: none;
}
.edraft-skin .nhlcal-topbar {
  border-bottom: 1px solid rgba(156, 218, 236, 0.14);
  background: linear-gradient(180deg, rgba(14, 40, 88, 0.94), rgba(12, 33, 77, 0.6));
}
.edraft-skin .dcb-panel-card,
.edraft-skin .dlot-panel,
.edraft-skin .dlot-board-col,
.edraft-skin .dlot-results {
  border: 1px solid rgba(156, 218, 236, 0.14);
  border-radius: 10px;
  background: rgba(14, 40, 88, 0.94);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}
.edraft-skin .dcb-tab-bar button,
.edraft-skin .dlot-chip {
  font-family: var(--ed-head);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.edraft-skin .dlot-cta-btn,
.edraft-skin .dlot-secondary-btn,
.edraft-skin .dlot-skip-btn,
.edraft-skin .dlot-ghost-btn {
  font-family: var(--ed-head);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border-radius: 8px;
}
.edraft-skin .dlot-cta-btn {
  background: linear-gradient(180deg, #f3b94f, #e9a83c);
  color: #17233b;
  border: 1px solid #e9a83c;
  font-weight: 900;
}
.edraft-skin .dlot-secondary-btn,
.edraft-skin .dlot-skip-btn,
.edraft-skin .dlot-ghost-btn {
  background: rgba(46, 230, 214, 0.08);
  color: #2ee6d6;
  border: 1px solid rgba(46, 230, 214, 0.35);
}
/* Combine testing table */
.dcb-testing { overflow: auto; }
.dcb-test-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.dcb-test-table th {
  position: sticky; top: 0; z-index: 1;
  background: #0d2555; color: #8096a8;
  font-family: var(--dd-font-ui); font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase;
  padding: 7px 8px; text-align: right; cursor: pointer; white-space: nowrap;
  border-bottom: 1px solid rgba(156, 218, 236, 0.14);
}
.dcb-test-table th:first-child { text-align: left; }
.dcb-test-table th.is-sorted { color: #2ee6d6; }
.dcb-test-table td {
  padding: 6px 8px; text-align: right; white-space: nowrap;
  border-bottom: 1px solid rgba(156, 218, 236, 0.07);
  font-variant-numeric: tabular-nums;
}
.dcb-test-table td span { display: block; font-size: 11px; color: #607789; }
.dcb-test-table td.who { text-align: left; }
.dcb-test-table td.who strong { display: block; }
.dcb-test-table td.hi { color: #52df94; }
.dcb-test-table td.lo { color: #ff606d; }

/* ==========================================================================
   SECTION: events/draftCombine/DraftCombine.css
   ========================================================================== */
/* Draft Combine — single screen, Entry Draft visual language (ops tokens, plain text, no icon boxes) */

.dcb-root {
  --dcb-line: var(--ops-grid);
  --dcb-muted: var(--ops-text-secondary, var(--muted));
  --dcb-up: var(--ops-success, #52df94);
  --dcb-down: var(--ops-injury, #ff606d);
  --dcb-head: var(--dd-font-ui);
}

.nhlcal-root.dcb-root {
  grid-template-columns: minmax(0, 1fr);
}

.dcb-main {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  overflow: hidden;
}

.dcb-layout {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 12px;
  height: calc(100dvh - 190px);
}

.dcb-col {
  min-height: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.dcb-h {
  margin: 0 0 6px;
  font-family: var(--dcb-head);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ops-gold, var(--gold));
}

/* Risers / fallers */
.dcb-movers {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  max-height: 34%;
  overflow-y: auto;
}

.dcb-mover {
  width: 100%;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 5px 4px;
  border: 0;
  border-bottom: 1px solid var(--dcb-line);
  background: transparent;
  color: var(--ops-text, var(--text));
  text-align: left;
  cursor: pointer;
}

.dcb-mover:hover,
.dcb-mover.is-selected {
  background: var(--ops-cyan-soft);
}

.dcb-arrow {
  font-family: var(--font-mono-data);
  font-size: 13px;
  font-weight: 700;
}

.dcb-arrow.up { color: var(--dcb-up); }
.dcb-arrow.down { color: var(--dcb-down); }

.dcb-mover-main { min-width: 0; }

.dcb-mover-main strong,
.dcb-mover-main em {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dcb-mover-main strong { font-size: 13px; }

.dcb-mover-main em {
  font-style: normal;
  font-size: 11px;
  color: var(--dcb-muted);
}

.dcb-mover-rank {
  font-family: var(--font-mono-data);
  font-size: 11px;
  color: var(--dcb-muted);
  white-space: nowrap;
}

/* Top performer strip */
.dcb-leaders {
  display: flex;
  gap: 0;
  overflow-x: auto;
  border-top: 1px solid var(--dcb-line);
  border-bottom: 1px solid var(--dcb-line);
}

.dcb-leader {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 112px;
  padding: 6px 10px;
  border: 0;
  border-right: 1px solid var(--dcb-line);
  background: transparent;
  color: var(--ops-text, var(--text));
  text-align: left;
  cursor: pointer;
}

.dcb-leader:hover { background: var(--ops-cyan-soft); }

.dcb-leader span {
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--dcb-muted);
}

.dcb-leader strong { font-size: 12px; white-space: nowrap; }

.dcb-leader em {
  font-style: normal;
  font-family: var(--font-mono-data);
  font-size: 11px;
  color: var(--dcb-up);
}

/* Results table */
.dcb-table-wrap {
  flex: 1;
  min-height: 0;
  overflow: auto;
}

.dcb-root .dcb-test-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--ops-panel-2, var(--ops-panel));
  cursor: pointer;
  white-space: nowrap;
}

.dcb-root .dcb-test-table th.who { text-align: left; cursor: default; }

.dcb-root .dcb-test-table tbody tr { cursor: pointer; }

.dcb-root .dcb-test-table tbody tr:hover,
.dcb-root .dcb-test-table tbody tr.is-selected {
  background: var(--ops-cyan-soft);
}

.dcb-root .dcb-test-table td.who span { display: block; text-align: left; }

.dcb-legend {
  margin: 6px 0 0;
  font-size: 11px;
  color: var(--dcb-muted);
}

.dcb-legend .hi { color: var(--dcb-up); }
.dcb-legend .lo { color: var(--dcb-down); }

/* Inline detail */
.dcb-detail {
  min-height: 0;
  overflow-y: auto;
  padding-left: 12px;
  border-left: 1px solid var(--dcb-line);
}

.dcb-detail-head h3 {
  margin: 0;
  font-family: var(--dcb-head);
  font-size: 22px;
  letter-spacing: 0.04em;
}

.dcb-detail-head p {
  margin: 2px 0 8px;
  font-size: 12px;
  color: var(--dcb-muted);
}

.dcb-kv { margin: 0 0 8px; }

.dcb-kv div {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 3px 0;
  border-bottom: 1px solid var(--dcb-line);
  font-size: 12px;
}

.dcb-kv dt { color: var(--dcb-muted); }
.dcb-kv dd { margin: 0; font-weight: 700; }

.dcb-mini { width: 100%; border-collapse: collapse; font-size: 12px; }

.dcb-mini th {
  text-align: left;
  font-weight: 500;
  color: var(--dcb-muted);
  padding: 2px 0;
}

.dcb-mini td {
  text-align: right;
  font-family: var(--font-mono-data);
  padding: 2px 0 2px 8px;
}

.dcb-root .hi { color: var(--dcb-up); }
.dcb-root .lo { color: var(--dcb-down); }

.dcb-note {
  margin: 6px 0;
  font-size: 12px;
  color: var(--dcb-muted);
}

.dcb-meet {
  display: flex;
  gap: 6px;
  margin-top: 10px;
}

.dcb-meet button {
  flex: 1;
  padding: 6px 8px;
  border: 1px solid var(--dcb-line);
  border-radius: var(--radius-hud);
  background: transparent;
  color: var(--ops-text, var(--text));
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
}

.dcb-meet button:hover:not(:disabled) { background: var(--ops-cyan-soft); }
.dcb-meet button:disabled { opacity: 0.5; cursor: not-allowed; }

.dcb-empty {
  margin: 0;
  padding: 8px 0;
  color: var(--dcb-muted);
  font-size: 12px;
}

.dcb-error {
  margin: 6px 0;
  color: var(--dcb-down);
  font-size: 12px;
  font-weight: 700;
}

