}

@media (max-width: 760px) {
  .dlot-board-row {
    grid-template-columns: 56px 48px 1fr;
    grid-template-areas:
      "pick logo team"
      "pick logo meta";
  }

  .dlot-board-pick {
    grid-area: pick;
  }

  .dlot-board-row .dlot-logo {
    grid-area: logo;
  }

  .dlot-board-team {
    grid-area: team;
  }

  .dlot-board-col:nth-child(4),
  .dlot-board-col:nth-child(5) {
    grid-area: meta;
    grid-column: 2 / -1;
  }
}

/* ==========================================================================
