/* Free Agency board — Entry Draft broadcast-floor register (flat ops panels, grid lines, gold CTA).
   Double-class scope outweighs the injected cinematic base stylesheet. */

.fa-root.fa-root--market {
  --panel: var(--ops-panel);
  --panel-2: var(--ops-panel-2);
  --line: var(--ops-grid);
  --text: var(--ops-text);
  --muted: var(--ops-text-secondary);
  --gold: var(--ops-gold);
  --cyan: var(--ops-cyan);
  --fa-radius: var(--radius-ops);
  font-family: var(--font-ops-ui);
  background:
    radial-gradient(circle at 20% 0%, rgba(46, 230, 214, 0.1), transparent 32%),
    radial-gradient(circle at 88% 12%, rgba(233, 168, 60, 0.07), transparent 28%),
    linear-gradient(180deg, var(--ops-black) 0%, var(--ops-navy-deep) 100%);
}

.fa-root.fa-root--market .fa-bg-noise,
.fa-root.fa-root--market .fa-spotlight {
