}

/* Top bar */
.fa-root.fa-root--market .fa-topbar {
  min-height: 48px;
  padding: 6px 12px;
  border-bottom: 1px solid var(--line);
  background: var(--ops-panel-2);
}
.fa-root.fa-root--market .fa-phase-text {
  font-family: var(--font-broadcast-display);
  font-size: var(--type-broadcast-display-size);
  font-weight: 400;
  letter-spacing: 0.06em;
  color: var(--text);
}
.fa-root.fa-root--market .fa-season {
  font-size: 12px;
  font-weight: 500;
  color: var(--muted);
}

/* Shared controls */
.fa-root.fa-root--market .fa-ghost-btn,
.fa-root.fa-root--market .fa-sim-btn {
  border: 1px solid var(--line);
  background: rgba(12, 31, 47, 0.85);
  color: var(--text);
  border-radius: var(--fa-radius);
  padding: 6px 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
