.fa-root.fa-root--market.edraft-skin .fa-wire-item.is-lost {
  border-color: rgba(255, 96, 109, 0.45);
  color: #ffd2d6;
}

/* Social tab: Puckr cards */
.fa-root.fa-root--market.edraft-skin .fa-social-post {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 8px;
  padding: 8px 9px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--ops-panel-2);
}
.fa-root.fa-root--market.edraft-skin .fa-social-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #24465c;
  color: #fff;
  font-family: var(--ed-head);
  font-size: 13px;
  font-weight: 800;
}
.fa-root.fa-root--market.edraft-skin .fa-social-post header {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: baseline;
  font-size: 11.5px;
  color: var(--muted);
}
.fa-root.fa-root--market.edraft-skin .fa-social-post header strong {
  color: var(--text);
  font-size: 13px;
}
.fa-root.fa-root--market.edraft-skin .fa-social-check {
  font-style: normal;
  color: var(--cyan);
  font-size: 11px;
}
.fa-root.fa-root--market.edraft-skin .fa-social-post p {
  margin: 3px 0 0;
  font-size: 13px;
  line-height: 1.4;
  color: var(--text);
}

/* ==========================================================================
   SECTION: events/prospectDevelopment/ProspectDevelopment.css
   ========================================================================== */
/* Organizational Development Review — compact calendar-matched layout */

.nhldev-root {
  --nhldev-panel-h: calc(100dvh - 200px);
}

.nhldev-main {
  overflow: hidden;
}

.nhldev-topbar {
  padding-bottom: 6px;
}

.nhldev-topbar--logo {
  grid-template-columns: auto 1fr;
  min-height: 84px;
}

.nhldev-brand-only {
  display: flex;
  align-items: center;
}

.nhldev-logo-fallback {
  display: grid;
  place-items: center;
  color: var(--cyan);
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.nhldev-avatar {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: var(--radius-control);
  border: 2px solid rgba(46, 230, 214, 0.32);
  background: rgba(46, 230, 214, 0.1);
  color: rgba(233, 247, 251, 0.95);
  font-weight: 900;
  letter-spacing: 0.04em;
  box-shadow: none;
}

/* Distinct kicker: org dev scan label */
.nhldev-summary-line {
  margin: 0 16px 8px;
  padding: 8px 12px;
  border: 1px solid var(--ops-grid);
  border-left: 3px solid var(--ops-gold);
  border-radius: var(--radius-hud);
  background: rgba(14, 37, 85, 0.55);
  color: rgba(233, 247, 251, 0.88);
  font-size: var(--type-compact-size);
  font-weight: 800;
  letter-spacing: 0.03em;
}

.nhldev-summary-line::before {
  content: "ORG DEV · ";
  color: var(--ops-gold);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.12em;
}

.nhldev-brand-title {
  margin: 0;
  font-family: var(--font-broadcast-display);
  font-size: clamp(1.1rem, 2vw, 1.45rem);
  font-weight: 400;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ops-text);
}

.nhldev-brand-title::after {
  content: "";
  display: block;
  width: 48px;
  height: 2px;
  margin-top: 4px;
  background: linear-gradient(90deg, var(--ops-cyan), var(--ops-gold));
}

.nhldev-tab-bar {
  display: flex;
  gap: 6px;
  padding: 0 16px 8px;
}

.nhldev-tab-bar .nhlcal-quick-link.is-active {
  border-color: var(--ops-grid-strong);
  color: var(--cyan);
  background: var(--ops-cyan-soft);
  box-shadow: inset 2px 0 0 var(--cyan);
}

.nhldev-league-note {
  margin: 0 0 8px;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

.nhldev-grid {
  min-height: 0;
  max-height: var(--nhldev-panel-h);
}

.nhldev-panel {
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.nhldev-scroll,
.nhldev-prospect-list,
.nhldev-org-groups {
  overflow-y: auto;
  max-height: calc(var(--nhldev-panel-h) - 52px);
  padding: 0 10px 10px;
  scrollbar-width: thin;
  scrollbar-color: rgba(110, 173, 191, 0.28) transparent;
}

.nhldev-scroll::-webkit-scrollbar,
.nhldev-prospect-list::-webkit-scrollbar,
.nhldev-org-groups::-webkit-scrollbar {
  width: 8px;
}

.nhldev-scroll::-webkit-scrollbar-thumb,
.nhldev-prospect-list::-webkit-scrollbar-thumb,
.nhldev-org-groups::-webkit-scrollbar-thumb {
  background: rgba(110, 173, 191, 0.28);
  border-radius: var(--radius-ops);
}

.nhldev-prospect-row {
  width: 100%;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  border: 1px solid var(--ops-grid);
  border-radius: var(--radius-hud);
  background: rgba(14, 37, 85, 0.72);
  color: var(--text);
  text-align: left;
  padding: 10px 12px;
  margin-bottom: 6px;
  cursor: pointer;
  transition: border-color var(--motion-micro), background var(--motion-micro);
}

.nhldev-prospect-row:hover,
.nhldev-prospect-row.is-selected {
  border-color: var(--ops-grid-strong);
  background: var(--ops-cyan-soft);
  box-shadow: inset 3px 0 0 var(--cyan);
}

.nhldev-row-main {
  min-width: 0;
  flex: 1;
}

.nhldev-row-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.nhldev-row-ovr {
  color: var(--cyan);
  font-family: var(--font-mono-data);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.nhldev-row-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 2px;
  font-size: 11px;
  font-weight: 800;
  color: var(--muted);
}

.nhldev-row-main strong {
  display: block;
  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.02em;
}

.nhldev-row-line,
.nhldev-row-reason {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-top: 4px;
  font-size: 11px;
  font-weight: 800;
  color: var(--muted);
}

.nhldev-ovr-shift {
  color: var(--cyan);
  font-family: var(--font-mono-data);
  font-variant-numeric: tabular-nums;
}

.nhldev-reason-text {
  color: rgba(233, 247, 251, 0.78);
  font-weight: 700;
  text-transform: none;
}

.nhldev-org-group {
  margin-bottom: 5px;
}

.nhldev-group-head {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 10px;
  border: 1px solid var(--ops-grid);
  border-radius: var(--radius-hud);
  background: rgba(11, 31, 45, 0.5);
  color: var(--text);
  cursor: pointer;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.nhldev-group-count {
  color: var(--cyan);
  font-family: var(--font-mono-data);
  font-variant-numeric: tabular-nums;
}

.nhldev-detail {
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
}

.nhldev-detail-head {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nhldev-detail-block {
  padding: 8px 14px;
  border-top: 1px solid rgba(156, 218, 236, 0.08);
}

.nhldev-detail-block h4 {
  margin: 0 0 5px;
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.nhldev-attr-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 5px;
}

.nhldev-attr-list li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
  font-weight: 800;
  color: rgba(233, 247, 251, 0.9);
}

.nhldev-attr-list li.is-up strong { color: var(--green); }
.nhldev-attr-list li.is-down strong { color: var(--red); }

.nhldev-attr-list li strong {
  font-family: var(--font-mono-data);
  font-variant-numeric: tabular-nums;
}

.nhldev-bullet-line {
  margin: 0 0 4px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.35;
  color: rgba(233, 247, 251, 0.88);
}

.nhldev-stats-line {
  margin: 0;
  font-size: 11px;
  font-weight: 800;
  color: rgba(233, 247, 251, 0.85);
}

.nhldev-delta-pill {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 5px;
  border-radius: var(--radius-ops);
  font-family: var(--font-mono-data);
  font-size: 11px;
  font-weight: 900;
  font-style: normal;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
}

.nhldev-delta-pill.up {
  color: var(--green);
  background: var(--green-soft);
}

.nhldev-delta-pill.down {
  color: var(--red);
  background: var(--red-soft);
}

.nhldev-delta-pill.neutral {
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
}

.nhldev-delta-pill.large {
  font-size: 13px;
  padding: 3px 7px;
}

.nhldev-detail-hero {
  padding: 10px 14px 4px;
  border-bottom: 1px solid rgba(156, 218, 236, 0.08);
}

.nhldev-detail-ovr-block {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 8px;
}

.nhldev-detail-ovr-label {
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.nhldev-detail-ovr-value {
  font-family: var(--font-mono-data);
  font-size: 22px;
  font-weight: 900;
  color: var(--cyan);
  font-variant-numeric: tabular-nums;
}

.nhldev-detail-ovr-value em {
  margin: 0 6px;
  color: var(--muted);
  font-style: normal;
}

.nhldev-detail-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  border: 1px solid var(--ops-grid);
  border-radius: var(--radius-hud);
  overflow: hidden;
}

.nhldev-detail-stat-grid > div {
  padding: 8px 10px;
  border-right: 1px solid var(--ops-grid);
  background: rgba(13, 35, 80, 0.45);
}

.nhldev-detail-stat-grid > div:last-child {
  border-right: 0;
}

.nhldev-detail-stat-grid span {
  display: block;
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

.nhldev-detail-stat-grid strong {
  display: block;
  margin-top: 2px;
  font-family: var(--font-mono-data);
  font-size: 13px;
  font-weight: 900;
  color: rgba(233, 247, 251, 0.92);
  font-variant-numeric: tabular-nums;
}

.nhldev-empty {
  padding: 16px;
  border: 1px dashed var(--ops-grid);
  border-radius: var(--radius-control);
  color: var(--muted);
  font-size: var(--type-compact-size);
}

@media (max-width: 1366px) {
  .nhldev-root {
    --nhldev-panel-h: calc(100dvh - 180px);
  }

  .nhldev-grid {
    grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
  }
}

@media (max-width: 900px) {
  .nhldev-detail-stat-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .nhldev-detail-stat-grid > div:nth-child(2) {
    border-right: 0;
  }

  .nhldev-detail-stat-grid > div:nth-child(n+3) {
    border-top: 1px solid var(--ops-grid);
  }
}

/* ==========================================================================
   SECTION: events/retirements/RetirementsBoard.css
   ========================================================================== */
/* Retirements — league wire / career archive register */

.retirement-page {
  --panel: var(--ops-panel);
  --line: var(--ops-grid);
  --cyan: var(--ops-cyan);
  --gold: var(--ops-gold);
  --text: var(--ops-text);
  --muted: var(--ops-text-secondary);

  position: relative;
  min-height: 100dvh;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  color: var(--text);
  background: linear-gradient(180deg, var(--ops-black) 0%, var(--ops-navy-deep) 100%);
  font-family: var(--font-ops-ui);
  overflow: hidden;
}

.retirement-page__bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 24% 0%, rgba(46, 230, 214, 0.06), transparent 30%),
    radial-gradient(circle at 92% 18%, rgba(233, 168, 60, 0.05), transparent 26%);
}

.retirement-header {
  position: relative;
  z-index: var(--z-sticky);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 1rem;
  padding: 0.85rem 1.25rem;
  border-bottom: 1px solid var(--line);
  background: rgba(11, 30, 72, 0.92);
}

/* Distinct title: gold memorial rule + editorial kicker */
.retirement-header h1 {
  margin: 0;
  padding-top: 6px;
  font-family: var(--font-broadcast-display);
  font-size: clamp(1rem, 2vw, 1.25rem);
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-align: center;
  position: relative;
}

.retirement-header h1::before {
  content: "CAREER ARCHIVE";
  display: block;
  margin-bottom: 4px;
  font-family: var(--font-ops-ui);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.18em;
  color: var(--gold);
}

.retirement-header h1::after {
  content: "";
  display: block;
  width: 64px;
  height: 2px;
  margin: 6px auto 0;
  background: linear-gradient(90deg, transparent, var(--gold), transparent);
}

.retirement-back-btn {
  justify-self: start;
  background: rgba(12, 31, 47, 0.72);
  border: 1px solid var(--line);
  color: var(--text);
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-hud);
  cursor: pointer;
  font-weight: 800;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transition: border-color var(--motion-micro);
}

.retirement-back-btn:hover {
  border-color: var(--ops-grid-strong);
  background: var(--ops-cyan-soft);
}

.retirement-season {
  justify-self: end;
  font-family: var(--font-mono-data);
  font-size: 12px;
  color: var(--muted);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.retirement-list {
  position: relative;
  z-index: 2;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 0.75rem 1.25rem 5rem;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.retirement-row {
  display: grid;
  grid-template-columns: minmax(220px, 1.4fr) 72px minmax(280px, 2fr);
  gap: 0.75rem 1rem;
  align-items: center;
  padding: 0.65rem 0.8rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-control);
  background: rgba(14, 37, 85, 0.72);
  box-shadow: var(--depth-registered);
}

.retirement-player-cell {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
}

.retirement-headshot {
  flex: 0 0 auto;
  width: 48px;
  height: 48px;
}

.retirement-headshot .player-headshot {
  width: 48px;
  height: 48px;
}

.retirement-player-meta {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.retirement-player-name {
  font-size: 0.95rem;
  font-weight: 800;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.retirement-player-team {
  font-size: 11px;
  color: var(--cyan);
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.retirement-player-tags {
  font-size: var(--type-phase-label-size);
  color: var(--muted);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.retirement-ovr {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 68px;
  padding: 0.35rem 0.3rem;
  border: 1px solid rgba(233, 168, 60, 0.32);
  border-radius: var(--radius-hud);
  background: var(--ops-gold-soft);
}

.retirement-ovr span {
  font-size: var(--type-phase-label-size);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 900;
}

.retirement-ovr strong {
  font-family: var(--font-mono-data);
  font-size: 1.25rem;
  line-height: 1;
  font-weight: 900;
  color: var(--gold);
  font-variant-numeric: tabular-nums;
}

.retirement-stats-wrap {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem;
  min-width: 0;
}

.retirement-stat-group h3 {
  margin: 0 0 0.3rem;
  font-size: var(--type-phase-label-size);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 900;
}

.retirement-stat-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 3px;
}

.retirement-stat-grid.is-goalie {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.retirement-stat-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 0.22rem 0.15rem;
  border-radius: var(--radius-ops);
  background: rgba(0, 0, 0, 0.2);
  border: 1px solid rgba(156, 218, 236, 0.08);
  text-align: center;
  min-width: 0;
}

.retirement-stat-cell span {
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 800;
}

.retirement-stat-cell strong {
  font-family: var(--font-mono-data);
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--text);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.retirement-empty-state {
  margin: auto;
  padding: 2rem 1rem;
  text-align: center;
  color: var(--muted);
  font-size: var(--type-compact-size);
  border: 1px dashed var(--line);
  border-radius: var(--radius-control);
  max-width: 360px;
}

.retirement-empty-state::before {
  content: "NO RETIREMENTS";
  display: block;
  margin-bottom: 6px;
  color: var(--cyan);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.14em;
}

.retirement-actions {
  position: relative;
  z-index: var(--z-sticky);
  flex: 0 0 auto;
  display: flex;
  justify-content: center;
  padding: 0.75rem 1.25rem 0.85rem;
  border-top: 1px solid var(--line);
  background: rgba(11, 29, 69, 0.98);
}

.retirement-continue-btn {
  border: 0;
  border-radius: var(--radius-hud);
  padding: 0.75rem 1.75rem;
  min-width: 200px;
  background: linear-gradient(180deg, #f4bd52, #d99023);
  color: #182138;
  cursor: pointer;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  box-shadow: var(--depth-registered);
  transition: filter var(--motion-micro);
}

.retirement-continue-btn:hover {
  filter: brightness(1.04);
}

@media (max-width: 980px) {
  .retirement-page {
    height: auto;
    min-height: 100dvh;
  }

  .retirement-row {
    grid-template-columns: 1fr 64px;
    grid-template-areas:
      "player ovr"
      "stats stats";
  }

  .retirement-player-cell { grid-area: player; }
  .retirement-ovr { grid-area: ovr; }
  .retirement-stats-wrap { grid-area: stats; grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  .retirement-header {
    grid-template-columns: auto 1fr;
    grid-template-areas:
      "back season"
      "title title";
  }

  .retirement-back-btn { grid-area: back; }
  .retirement-header h1 { grid-area: title; margin-top: 0.25rem; }
  .retirement-season { grid-area: season; }

  .retirement-stat-grid,
  .retirement-stat-grid.is-goalie {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

/* ==========================================================================
   SECTION: events/salaryCap/CapReportBoard.css
   ========================================================================== */
/* Cap Report — league financial wire broadcast */

.cap-report-page {
  --cap-bg: var(--ops-navy);
  --cap-bg-2: var(--ops-black);
  --cap-panel: var(--ops-panel);
  --cap-panel-2: var(--ops-panel-2);
  --cap-panel-3: var(--ops-panel-3);
  --cap-line: var(--ops-grid);
  --cap-line-2: var(--ops-grid-2);
  --cap-line-strong: var(--ops-grid-strong);
  --cap-text: var(--ops-text);
  --cap-muted: var(--ops-text-secondary);
  --cap-muted-2: var(--ops-text-disabled);
  --cap-cyan: var(--ops-cyan);
  --cap-cyan-soft: var(--ops-cyan-soft);
  --cap-gold: var(--ops-gold);
  --cap-gold-soft: var(--ops-gold-soft);
  --cap-green: var(--ops-success);
  --cap-green-soft: var(--ops-success-soft);
  --cap-red: var(--ops-injury);
  --cap-red-soft: var(--ops-injury-soft);
  --cap-blue: var(--ops-info);
  --cap-blue-soft: var(--ops-info-soft);

  width: 100%;
  min-width: 0;
  min-height: 100dvh;
  height: 100dvh;
  display: grid;
  grid-template-rows: 68px minmax(0, 1fr) 76px;
  overflow: hidden;
  color: var(--cap-text);
  background:
    radial-gradient(circle at 18% 0%, rgba(46, 230, 214, 0.08), transparent 31%),
    radial-gradient(circle at 92% 12%, rgba(233, 168, 60, 0.04), transparent 26%),
    linear-gradient(145deg, var(--cap-bg) 0%, var(--ops-navy-deep) 100%);
  font-family: var(--font-ops-ui);
  font-variant-numeric: tabular-nums;
}

.cap-report-page,
.cap-report-page * {
  box-sizing: border-box;
}

.cap-report-page button {
  font: inherit;
}

.cap-report-topbar {
  position: relative;
  z-index: var(--z-sticky);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  min-width: 0;
  padding: 0 24px;
  border-bottom: 1px solid var(--cap-line);
  background: rgba(11, 30, 72, 0.94);
}

.cap-report-back-button {
  justify-self: start;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid var(--cap-line-2);
  border-radius: var(--radius-hud);
  color: var(--cap-text);
  background: rgba(12, 35, 52, 0.66);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color var(--motion-micro), background var(--motion-micro);
}

.cap-report-back-button:hover {
  border-color: var(--cap-line-strong);
  background: var(--cap-cyan-soft);
}

.cap-report-back-button span {
  color: var(--cap-cyan);
  font-size: 15px;
}

/* Distinct title: wire kicker + broadcast display */
.cap-report-title {
  text-align: center;
  position: relative;
  padding-bottom: 4px;
}

.cap-report-title::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 0;
  width: 48px;
  height: 2px;
  transform: translateX(-50%);
  background: var(--cap-gold);
}

.cap-report-title span,
.cap-report-season span,
.cap-report-section-heading > div > span,
.cap-report-club-header > div > span,
.cap-report-metrics-header > div > span,
.cap-report-next-stage span {
  display: block;
  margin-bottom: 3px;
  color: var(--cap-cyan);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.cap-report-title h1 {
  margin: 0;
  font-family: var(--font-broadcast-display);
  color: var(--cap-text);
  font-size: 20px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.cap-report-season {
  justify-self: end;
  text-align: right;
}

.cap-report-season strong {
  color: var(--cap-text);
  font-family: var(--font-mono-data);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.cap-report-content {
  min-height: 0;
  width: min(1280px, calc(100% - 48px));
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 12px;
  margin: 0 auto;
  padding: 16px 0;
  overflow: auto;
}

.cap-report-primary-panel {
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) minmax(380px, 0.82fr);
  overflow: hidden;
  border: 1px solid var(--cap-line-2);
  border-radius: var(--radius-card);
  background: var(--cap-panel);
  box-shadow: var(--depth-registered);
}

.cap-report-league-summary {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(24px, 4vw, 48px);
  border-right: 1px solid var(--cap-line);
}

.cap-report-league-summary::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 3px;
  background: var(--cap-cyan);
}

.cap-report-section-heading,
.cap-report-club-header,
.cap-report-metrics-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.cap-report-section-heading h2,
.cap-report-club-header h2,
.cap-report-metrics-header h2 {
  margin: 0;
  color: var(--cap-text);
  font-size: 18px;
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.cap-report-movement-badge,
.cap-report-status {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 26px;
  padding: 0 8px;
  border: 1px solid var(--cap-line-2);
  border-radius: var(--radius-ops);
  color: var(--cap-cyan);
  background: var(--cap-cyan-soft);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.cap-report-movement-badge.is-positive,
.cap-report-status.is-positive,
.cap-report-status.is-success {
  border-color: rgba(82, 223, 148, 0.38);
  color: var(--cap-green);
  background: var(--cap-green-soft);
}

.cap-report-movement-badge.is-negative,
.cap-report-movement-badge.is-danger,
.cap-report-status.is-negative,
.cap-report-status.is-danger {
  border-color: rgba(255, 96, 109, 0.38);
  color: var(--cap-red);
  background: var(--cap-red-soft);
}

.cap-report-movement-badge.is-neutral,
.cap-report-status.is-neutral,
.cap-report-status.is-warning {
  border-color: rgba(233, 168, 60, 0.4);
  color: var(--cap-gold);
  background: var(--cap-gold-soft);
}

.cap-report-cap-display {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-top: 22px;
}

.cap-report-cap-display > strong {
  color: var(--cap-text);
  font-family: var(--font-mono-data);
  font-size: clamp(56px, 7vw, 96px);
  font-weight: 900;
  line-height: 0.88;
  letter-spacing: -0.06em;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.cap-report-change-badge {
  margin-top: 6px;
  padding: 6px 8px;
  border: 1px solid var(--cap-line-2);
  border-radius: var(--radius-ops);
  color: var(--cap-cyan);
  background: var(--cap-cyan-soft);
  font-family: var(--font-mono-data);
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.cap-report-change-badge.is-positive {
  border-color: rgba(82, 223, 148, 0.4);
  color: var(--cap-green);
  background: var(--cap-green-soft);
}

.cap-report-change-badge.is-negative,
.cap-report-change-badge.is-danger {
  border-color: rgba(255, 96, 109, 0.4);
  color: var(--cap-red);
  background: var(--cap-red-soft);
}

.cap-report-change-badge.is-neutral {
  border-color: rgba(138, 180, 255, 0.35);
  color: var(--cap-blue);
  background: var(--cap-blue-soft);
}

.cap-report-reason {
  max-width: 670px;
  margin: 18px 0 0;
  color: var(--cap-muted);
  font-size: var(--type-compact-size);
  font-weight: 600;
  line-height: 1.5;
}

.cap-report-change-strip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: auto;
  padding-top: 22px;
  border-top: 1px solid var(--cap-line);
}

.cap-report-change-strip > div {
  min-width: 0;
  padding: 0 16px;
  border-left: 1px solid var(--cap-line);
}

.cap-report-change-strip > div:first-child {
  padding-left: 0;
  border-left: 0;
}

.cap-report-change-strip span {
  display: block;
  margin-bottom: 5px;
  color: var(--cap-muted);
  font-size: var(--type-phase-label-size);
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.cap-report-change-strip strong {
  display: block;
  overflow: hidden;
  color: var(--cap-text);
  font-family: var(--font-mono-data);
  font-size: 16px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cap-report-club-summary {
  min-width: 0;
  display: flex;
  flex-direction: column;
  padding: clamp(24px, 3.2vw, 40px);
  background: rgba(12, 36, 82, 0.45);
}

.cap-report-space-block {
  margin-top: clamp(28px, 5vh, 48px);
}

.cap-report-space-block > span {
  display: block;
  margin-bottom: 6px;
  color: var(--cap-muted);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.cap-report-space-block > strong {
  display: block;
  color: var(--cap-gold);
  font-family: var(--font-mono-data);
  font-size: clamp(42px, 5vw, 68px);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
}

.cap-report-space-block > strong.is-negative {
  color: var(--cap-red);
}

.cap-report-space-block p {
  margin: 8px 0 0;
  color: var(--cap-muted);
  font-size: 12px;
  font-weight: 650;
}

.cap-report-utilization {
  margin-top: clamp(24px, 5vh, 40px);
}

.cap-report-utilization-header,
.cap-report-utilization-labels {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.cap-report-utilization-header {
  margin-bottom: 7px;
}

.cap-report-utilization-header span {
  color: var(--cap-muted);
  font-size: var(--type-phase-label-size);
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.cap-report-utilization-header strong {
  color: var(--cap-text);
  font-family: var(--font-mono-data);
  font-size: 13px;
  font-weight: 900;
}

.cap-report-utilization-track {
  height: 6px;
  overflow: hidden;
  border: 1px solid var(--cap-line);
  border-radius: var(--radius-ops);
  background: rgba(10, 28, 66, 0.72);
}

.cap-report-utilization-track span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--cap-cyan), var(--cap-gold));
  transition: opacity 180ms ease;
}

.cap-report-utilization-labels {
  margin-top: 6px;
}

.cap-report-utilization-labels span {
  color: var(--cap-muted-2);
  font-size: var(--type-phase-label-size);
  font-weight: 750;
}

.cap-report-club-footer {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  margin-top: auto;
  padding-top: 20px;
  border-top: 1px solid var(--cap-line);
}

.cap-report-club-footer > div {
  padding-left: 16px;
  border-left: 1px solid var(--cap-line);
}

.cap-report-club-footer > div:first-child {
  padding-left: 0;
  border-left: 0;
}

.cap-report-club-footer span {
  display: block;
  margin-bottom: 4px;
  color: var(--cap-muted);
  font-size: var(--type-phase-label-size);
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.cap-report-club-footer strong {
  color: var(--cap-text);
  font-family: var(--font-mono-data);
  font-size: 17px;
  font-weight: 900;
}

/* Metrics — flat strip, not card grid */
.cap-report-metrics-panel {
  border: 1px solid var(--cap-line);
  border-radius: var(--radius-card);
  background: var(--cap-panel);
  box-shadow: var(--depth-registered);
}

.cap-report-metrics-header {
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--cap-line);
}

.cap-report-metrics-header h2 {
  font-size: 14px;
}

.cap-report-metrics-header p {
  margin: 0;
  color: var(--cap-muted);
  font-size: 11px;
  font-weight: 650;
}

.cap-report-metrics-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.cap-report-metric {
  min-width: 0;
  min-height: 84px;
  padding: 14px 16px;
  border-left: 1px solid var(--cap-line);
  background: rgba(13, 35, 80, 0.45);
}

.cap-report-metric:first-child {
  border-left: 0;
}

.cap-report-metric > span {
  display: block;
  margin-bottom: 6px;
  color: var(--cap-muted);
  font-size: var(--type-phase-label-size);
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.cap-report-metric > strong {
  display: block;
  overflow: hidden;
  color: var(--cap-text);
  font-family: var(--font-mono-data);
  font-size: 20px;
  font-weight: 900;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cap-report-metric > small {
  display: block;
  overflow: hidden;
  margin-top: 5px;
  color: var(--cap-muted-2);
  font-size: var(--type-phase-label-size);
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cap-report-metric.is-positive > strong {
  color: var(--cap-green);
}

.cap-report-metric.is-danger > strong {
  color: var(--cap-red);
}

.cap-report-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-width: 0;
  padding: 0 max(24px, calc((100vw - 1280px) / 2));
  border-top: 1px solid var(--cap-line);
  background: rgba(11, 30, 72, 0.96);
  z-index: var(--z-sticky);
}

.cap-report-next-stage strong {
  color: var(--cap-text);
  font-size: 12px;
  font-weight: 850;
}

.cap-report-continue-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  min-width: 200px;
  min-height: 40px;
  padding: 0 18px;
  border: 1px solid var(--cap-gold);
  border-radius: var(--radius-hud);
  color: #122753;
  background: linear-gradient(180deg, #f8c858, #e5a527);
  box-shadow: var(--depth-registered);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  transition: filter var(--motion-micro);
}

.cap-report-continue-button:hover {
  filter: brightness(1.05);
}

.cap-report-continue-button span {
  font-size: 15px;
}

@media (max-width: 1050px) {
  .cap-report-page {
    height: auto;
    min-height: 100dvh;
    overflow: auto;
  }

  .cap-report-content {
    width: min(920px, calc(100% - 32px));
  }

  .cap-report-primary-panel {
    grid-template-columns: 1fr;
  }

  .cap-report-league-summary {
    min-height: 360px;
    border-right: 0;
    border-bottom: 1px solid var(--cap-line);
  }

  .cap-report-club-summary {
    min-height: 320px;
  }

  .cap-report-metrics-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .cap-report-metric {
    border-top: 1px solid var(--cap-line);
  }

  .cap-report-metric:nth-child(1),
  .cap-report-metric:nth-child(2),
  .cap-report-metric:nth-child(3) {
    border-top: 0;
  }

  .cap-report-metric:nth-child(4) {
    border-left: 0;
  }
}

@media (max-width: 700px) {
  .cap-report-page {
    grid-template-rows: 60px auto 72px;
  }

  .cap-report-topbar {
    padding: 0 12px;
  }

  .cap-report-title span {
    display: none;
  }

  .cap-report-title h1 {
    font-size: 16px;
  }

  .cap-report-season span {
    display: none;
  }

  .cap-report-content {
    width: calc(100% - 20px);
    padding: 10px 0;
  }

  .cap-report-metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cap-report-next-stage {
    display: none;
  }

  .cap-report-continue-button {
    width: 100%;
    min-width: 0;
  }
}

@media (max-height: 780px) and (min-width: 1051px) {
  .cap-report-page {
    grid-template-rows: 60px minmax(0, 1fr) 68px;
  }

  .cap-report-content {
    gap: 10px;
    padding: 10px 0;
  }

  .cap-report-metric {
    min-height: 72px;
    padding-top: 12px;
    padding-bottom: 12px;
  }
}

/* ==========================================================================
   SECTION: events/awardsNight/AwardsNight.css
   ========================================================================== */
/* =====================================================================
   AWARDS NIGHT — Entry Draft broadcast floor model
   Mirrors EntryDraft.css (.edraft-broadcast) rule for rule; source selector in comments.
   Every theme var has a fallback: an undefined var inside a font stack
   invalidates the whole declaration, which is what dropped the fonts.
   ===================================================================== */

/* .edraft-broadcast.edraft-root */
.an-root.an-broadcast {
  --an-panel: var(--ops-panel, #10295c);
  --an-panel-quiet: var(--ops-panel-2, #0e2555);
  --an-line: var(--ops-grid, rgba(156, 178, 196, 0.16));
  --an-text: var(--ops-text, #e8f0f4);
  --an-muted: var(--ops-text-secondary, rgba(200, 214, 224, 0.62));
  --an-gold: var(--ops-gold, #e9a83c);
  --an-gold-soft: var(--ops-gold-soft, rgba(233, 168, 60, 0.14));
  --an-focus: var(--ops-cyan, #2ee6d6);
  --an-radius: var(--radius-ops, 3px);
  --an-gap: var(--space-2, 8px);
  --an-head: var(--dd-font-ui);
  --an-display: var(--font-broadcast-display, "Barlow Condensed"), "Arial Narrow", sans-serif;
  --an-mono: var(--font-mono-data, "IBM Plex Mono"), Consolas, "Courier New", monospace;
  --an-body: var(--font-ops-ui, "Inter"), system-ui, sans-serif;

  position: relative;
  height: 100dvh;
  max-height: 100dvh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  color: var(--an-text);
  background:
    radial-gradient(circle at 20% 0%, rgba(46, 230, 214, 0.1), transparent 32%),
    radial-gradient(circle at 88% 12%, rgba(233, 168, 60, 0.07), transparent 28%),
    linear-gradient(180deg, var(--ops-black, #0b1b41) 0%, var(--ops-navy-deep, #0d2555) 100%);
  font-family: var(--an-body);
  isolation: isolate;
}

.an-root.an-broadcast *,
.an-root.an-broadcast *::before,
.an-root.an-broadcast *::after {
  box-sizing: border-box;
}

/* .edraft-broadcast h1–h4 */
.an-broadcast h1,
.an-broadcast h2,
.an-broadcast h3,
.an-broadcast h4 {
  font-family: var(--an-head);
  letter-spacing: 0.04em;
}

/* .edraft-broadcast .edraft-tabular */
.an-broadcast .an-num {
  font-family: var(--an-mono);
  font-variant-numeric: tabular-nums;
}

/* .edraft-broadcast .edraft-muted */
.an-broadcast .an-muted {
  color: var(--an-muted);
  font-size: 12px;
  margin: 8px 0;
}

/* ── Top bar — .edraft-topbar (+ 40px authoritative override) ── */
.an-broadcast .an-topbar {
  position: relative;
  z-index: 10;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 40px;
  padding: 4px 14px;
  border-bottom: 1px solid var(--an-line);
  background: var(--an-panel-quiet);
}

.an-broadcast .an-topbar-main {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex: 1;
  min-width: 0;
}

/* .edraft-page-title */
.an-broadcast .an-page-title {
  margin: 0;
  font-family: var(--an-display);
  font-size: var(--type-broadcast-display-size, 22px);
  font-weight: 400;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--an-text);
  text-shadow: none;
}

/* .edraft-season */
.an-broadcast .an-season {
  font-size: 12px;
  font-weight: 500;
  color: var(--an-muted);
}

/* season timeline — .edraft-order-item dividers, no tiles */
.an-broadcast .an-milestones {
  display: flex;
  align-items: center;
  min-width: 0;
  overflow: hidden;
  font-size: 11px;
  font-weight: 600;
  color: var(--an-muted);
  white-space: nowrap;
}

.an-broadcast .an-milestones span {
  padding: 0 8px;
  border-right: 1px solid rgba(156, 178, 196, 0.12);
}

.an-broadcast .an-milestones span:last-child {
  border-right: 0;
}

.an-broadcast .an-milestones span.is-current {
  color: var(--an-gold);
}

.an-broadcast .an-topbar-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

/* ── Controls — .edraft-ghost-btn / .edraft-cta-btn / .edraft-back-btn ── */
.an-broadcast .an-ghost-btn {
  border: 1px solid var(--an-line);
  background: rgba(12, 31, 47, 0.85);
  color: var(--an-text);
  border-radius: var(--an-radius);
  padding: 7px 12px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  letter-spacing: 0;
  text-transform: none;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.an-broadcast .an-ghost-btn:hover:not(:disabled) {
  border-color: rgba(156, 178, 196, 0.35);
  background: rgba(18, 40, 58, 0.95);
}

.an-broadcast .an-ghost-btn.is-on {
  background: rgba(255, 255, 255, 0.1);
}

.an-broadcast .an-back-btn {
  padding: 5px 10px;
  font-size: 11px;
  opacity: 0.82;
  background: transparent;
}

.an-broadcast .an-back-btn:hover:not(:disabled) {
  opacity: 1;
}

.an-broadcast .an-cta-btn {
  border: 0;
  border-radius: var(--an-radius);
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  color: #182138;
  background: var(--an-gold);
  box-shadow: none;
  cursor: pointer;
  font-family: inherit;
}

.an-broadcast .an-cta-btn:hover:not(:disabled) {
  filter: brightness(1.05);
}

.an-broadcast .an-ghost-btn:disabled,
.an-broadcast .an-cta-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.an-broadcast .an-ghost-btn:focus-visible,
.an-broadcast .an-cta-btn:focus-visible,
.an-broadcast .an-log-row:focus-visible {
  outline: 2px solid var(--an-focus);
  outline-offset: 1px;
}

/* ── Floor — .edraft-live-floor + .edraft-floor-grid (authoritative) ── */
.an-broadcast .an-floor {
  position: relative;
  z-index: 5;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 8px 10px 0;
  overflow: hidden;
}

.an-broadcast .an-floor-grid {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: clamp(210px, 14vw, 250px) minmax(0, 1fr) clamp(300px, 21vw, 380px);
  grid-template-rows: minmax(0, 1fr);
  gap: var(--an-gap);
  align-items: stretch;
  border: 1px solid var(--an-line);
  background: var(--an-panel);
  overflow: hidden;
}

.an-broadcast .an-floor-grid > * {
  min-width: 0;
  min-height: 0;
}

/* .edraft-log / .edraft-board */
.an-broadcast .an-log,
.an-broadcast .an-board {
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 10px;
}

.an-broadcast .an-log {
  border-right: 1px solid var(--an-line);
  background: var(--an-panel-quiet);
  color: rgba(232, 240, 244, 0.82);
}

.an-broadcast .an-board {
  background: var(--an-panel);
}

/* .edraft-section-head / -title / -meta */
.an-broadcast .an-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  min-height: 28px;
  margin-bottom: 6px;
  flex-shrink: 0;
}

.an-broadcast .an-section-title {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  color: var(--an-text);
  letter-spacing: 0;
  text-transform: none;
}

.an-broadcast .an-section-meta {
  margin: 2px 0 0;
  font-size: 11px;
  color: var(--an-muted);
}

/* ── Ceremony order — .edraft-log-* ── */
.an-broadcast .an-log-scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.22) transparent;
  padding-bottom: 4px;
}

.an-broadcast .an-log-scroll::-webkit-scrollbar {
  width: 10px;
}

.an-broadcast .an-log-scroll::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.22);
  border-radius: 4px;
}

.an-broadcast .an-log-round {
  font-size: 11px;
  font-weight: 700;
  color: var(--an-muted);
  padding: 8px 0 4px;
  border-bottom: 1px solid rgba(156, 178, 196, 0.1);
  margin-bottom: 2px;
}

.an-broadcast .an-log-row {
  display: grid;
  grid-template-columns: 26px 22px minmax(0, 1fr);
  gap: 6px;
  align-items: center;
  width: 100%;
  padding: 6px 4px;
  border: 0;
  border-bottom: 1px solid rgba(156, 178, 196, 0.08);
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
  font-family: inherit;
  border-radius: 0;
}

.an-broadcast .an-log-row:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.04);
}

.an-broadcast .an-log-row:disabled {
  cursor: default;
}

/* .edraft-board-row.is-selected */
.an-broadcast .an-log-row.is-selected {
  background: rgba(126, 184, 212, 0.16);
  box-shadow: inset 3px 0 0 var(--an-focus);
}

.an-broadcast .an-log-num {
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--an-muted);
}

.an-broadcast .an-log-logo {
  display: flex;
  align-items: center;
  justify-content: center;
}

.an-broadcast .an-log-body {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.an-broadcast .an-log-body strong {
  font-size: 12px;
  font-weight: 700;
  color: var(--an-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.an-broadcast .an-log-body span {
  font-size: 11px;
  color: var(--an-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.an-broadcast .an-log-row.is-revealed .an-log-body span {
  color: rgba(232, 240, 244, 0.85);
}

.an-broadcast .an-log-row.is-live .an-log-body span {
  color: var(--an-gold);
}

/* ── Stage — .edraft-broadcast .edraft-stage (authoritative grid) ── */
.an-broadcast .an-stage {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas:
    "head"
    "body"
    "dock";
  gap: 8px;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  padding: 10px;
  border-right: 1px solid var(--an-line);
  background: var(--an-panel);
}

/* .edraft-pickhead */
.an-broadcast .an-stagehead {
  grid-area: head;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  min-height: 0;
  overflow: hidden;
  padding: 8px 12px;
  border: 1px solid var(--an-line);
  border-radius: 6px;
  background: linear-gradient(180deg, rgba(12, 28, 46, 0.92), rgba(13, 33, 79, 0.96));
}

.an-broadcast .an-stagehead-num {
  font-size: clamp(1.6rem, 2.4vw, 2.15rem);
  font-weight: 800;
  color: var(--an-gold);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.an-broadcast .an-stagehead-identity {
  min-width: 0;
}

.an-broadcast .an-stagehead-state {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--an-muted);
}

.an-broadcast .an-stagehead-state.is-live {
  color: var(--an-gold);
}

.an-broadcast .an-stagehead-title {
  margin: 1px 0 3px;
  font-size: clamp(1.2rem, 1.6vw, 1.5rem);
  font-weight: 800;
  color: #fff;
  line-height: 1.1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.an-broadcast .an-stagehead-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 12px;
  font-size: 11px;
  color: var(--an-muted);
  line-height: 1.35;
}

.an-broadcast .an-stagehead-meta .is-strong {
  color: rgba(232, 240, 244, 0.85);
}

.an-broadcast .an-stagehead-meta .is-gold {
  color: var(--an-gold);
  font-weight: 700;
}

/* .edraft-order-strip — label + plain list */
.an-broadcast .an-stagehead-next {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  width: clamp(160px, 18vw, 260px);
}

.an-broadcast .an-order-label {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--an-muted);
}

.an-broadcast .an-next-item {
  font-size: 11px;
  color: rgba(232, 240, 244, 0.78);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.an-broadcast .an-next-item b {
  margin-right: 6px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--an-muted);
}

/* .edraft-stage-prospect */
.an-broadcast .an-stage-body {
  grid-area: body;
  display: flex;
  min-width: 0;
  min-height: 0;
}

/* .edraft-stage-prospect .edraft-pcard */
.an-broadcast .an-card {
  flex: 1 1 auto;
  width: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  overflow: hidden;
  border: 1px solid var(--an-line);
  border-radius: 8px;
  background:
    radial-gradient(120% 90% at 12% 0%, rgba(30, 58, 92, 0.28), transparent 60%),
    linear-gradient(180deg, rgba(12, 28, 46, 0.9), rgba(13, 33, 79, 0.96));
  animation: anFade 260ms ease-out backwards;
}

/* .edraft-pcard-grid — identity / evaluation / projection */
.an-broadcast .an-card-grid {
  display: grid;
  grid-template-columns: clamp(200px, 24%, 280px) minmax(280px, 1fr) clamp(258px, 30%, 372px);
  grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "identity evaluation projection";
  gap: 10px;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.an-broadcast .an-card-grid.is-two {
  grid-template-columns: clamp(200px, 26%, 300px) minmax(0, 1fr);
  grid-template-areas: "identity evaluation";
}

.an-broadcast .an-card-grid > * {
  min-width: 0;
  min-height: 0;
}

/* .edraft-pz-identity */
.an-broadcast .an-z-identity {
  grid-area: identity;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border: 1px solid var(--an-line);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(10, 26, 44, 0.7), rgba(13, 33, 79, 0.85));
  overflow: hidden;
}

/* .edraft-pz-eval */
.an-broadcast .an-z-eval {
  grid-area: evaluation;
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 4px;
  scrollbar-width: thin;
}

.an-broadcast .an-z-eval::-webkit-scrollbar {
  width: 7px;
}

.an-broadcast .an-z-eval::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.16);
  border-radius: 4px;
}

.an-broadcast .an-z-eval h4,
.an-broadcast .an-z-result h4 {
  margin: 0 0 4px;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #9fb7c9;
}

/* .edraft-pz-proj */
.an-broadcast .an-z-result {
  grid-area: projection;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border: 1px solid rgba(80, 200, 220, 0.28);
  border-radius: 10px;
  background:
    radial-gradient(120% 80% at 100% 0%, rgba(46, 86, 120, 0.38), transparent 62%),
    linear-gradient(180deg, rgba(10, 26, 44, 0.96), rgba(13, 33, 79, 0.98));
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.32);
  overflow: hidden;
}

/* .edraft-pcard-name (+ pz-identity override) */
.an-broadcast .an-name {
  margin: 2px 0 0;
  font-size: clamp(22px, 2vw, 32px);
  font-weight: 800;
  line-height: 1.04;
  color: #f2f7fa;
}

.an-broadcast .an-name.is-sm {
  font-size: clamp(18px, 1.5vw, 24px);
}

/* .edraft-pcard-pos */
.an-broadcast .an-pos {
  margin: 0;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #9fe4ef;
}

/* .edraft-pcard-vitals */
.an-broadcast .an-vitals {
  margin: 2px 0 0;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 12px;
  color: var(--an-muted);
}

.an-broadcast .an-vitals span {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* .edraft-pcard-club */
.an-broadcast .an-club {
  margin: 0;
  font-size: 12px;
  line-height: 1.45;
  color: rgba(232, 240, 244, 0.7);
}

/* .edraft-pcard-summary p */
.an-broadcast .an-why p {
  margin: 0 0 4px;
  font-size: 13px;
  line-height: 1.55;
  color: rgba(232, 240, 244, 0.92);
}

/* .edraft-pcard-stat-table */
.an-broadcast .an-stat-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.an-broadcast .an-stat-table th {
  text-align: left;
  font-size: 11px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--an-muted);
  padding: 0 6px 4px 0;
  font-weight: 600;
}

.an-broadcast .an-stat-table td {
  padding: 3px 6px 0 0;
  color: rgba(232, 240, 244, 0.9);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 140px;
}

.an-broadcast .an-stat-table td:first-child {
  color: var(--an-muted);
}

.an-broadcast .an-stat-table th:not(:first-child),
.an-broadcast .an-stat-table td:not(:first-child) {
  text-align: right;
}

.an-broadcast .an-stat-table td.an-rank {
  color: #a7e8f2;
}

/* .edraft-pcard-facts + .edraft-attr-track */
.an-broadcast .an-facts {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.an-broadcast .an-fact-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: 12px;
}

.an-broadcast .an-fact-head span {
  min-width: 0;
  color: var(--an-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.an-broadcast .an-fact-head strong {
  color: #f2f7fa;
  font-weight: 600;
  text-align: right;
  white-space: nowrap;
}

.an-broadcast .an-track {
  height: 5px;
  margin-top: 3px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 1px;
  overflow: hidden;
}

.an-broadcast .an-track i {
  display: block;
  height: 100%;
  background: rgba(200, 214, 224, 0.55);
  transform-origin: left center;
  animation: anGrow 0.7s ease-out backwards;
}

.an-broadcast .an-excluded {
  margin: 4px 0 0;
  font-size: 11px;
  color: var(--an-muted);
}

/* .edraft-proj-title / -peak / -meta / -notes */
.an-broadcast .an-result-title {
  margin: 0;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #a7e8f2;
  font-weight: 800;
}

.an-broadcast .an-result-peak {
  display: flex;
  flex-direction: column;
}

.an-broadcast .an-result-peak > span {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--an-muted);
}

.an-broadcast .an-result-peak > strong {
  font-size: clamp(30px, 3vw, 48px);
  line-height: 1;
  font-weight: 800;
  color: var(--an-gold);
}

.an-broadcast .an-result-peak small {
  margin-left: 4px;
  font-size: 14px;
  font-weight: 600;
  color: var(--an-muted);
}

.an-broadcast .an-result-meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}

.an-broadcast .an-result-meta > div {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.an-broadcast .an-result-meta span {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--an-muted);
}

.an-broadcast .an-result-meta strong {
  font-size: 13px;
  color: #eaf3f7;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.an-broadcast .an-result-note {
  margin: 0;
  font-size: 11px;
  line-height: 1.35;
  color: var(--an-muted);
}

.an-broadcast .an-order {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: auto;
}

.an-broadcast .an-order-row {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  gap: 8px;
  align-items: baseline;
  font-size: 12px;
}

.an-broadcast .an-order-row span {
  color: var(--an-muted);
  font-variant-numeric: tabular-nums;
}

.an-broadcast .an-order-row strong {
  color: #f2f7fa;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.an-broadcast .an-order-row em {
  font-style: normal;
  color: var(--an-muted);
}

.an-broadcast .an-order-row.is-winner span,
.an-broadcast .an-order-row.is-winner strong {
  color: var(--an-gold);
}

/* ── Finalists — .edraft-pz-identity panels ── */
.an-broadcast .an-finalists {
  display: grid;
  gap: 10px;
  flex: 1 1 auto;
  min-height: 0;
}

.an-broadcast .an-finalist {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  min-height: 0;
  padding: 10px;
  border: 1px solid var(--an-line);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(10, 26, 44, 0.7), rgba(13, 33, 79, 0.85));
  overflow: hidden;
  transition: opacity 0.35s ease, filter 0.35s ease, border-color 0.35s ease, box-shadow 0.35s ease;
}

.an-broadcast .an-finalist.is-pending {
  visibility: hidden;
}

.an-broadcast .an-finalist.is-in {
  animation: anRise 0.18s ease-out backwards;
}

.an-broadcast .an-finalist.is-sealed {
  opacity: 0.7;
}

.an-broadcast .an-finalist.is-dim {
  opacity: 0.5;
  filter: grayscale(0.6);
}

/* .edraft-order-item.is-user + .edraft-stage.is-user */
.an-broadcast .an-finalist.is-winner {
  border-color: rgba(212, 175, 55, 0.55);
  box-shadow: inset 0 2px 0 var(--an-gold);
}

.an-broadcast .an-finalist__label {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--an-muted);
}

.an-broadcast .an-finalist.is-winner .an-finalist__label {
  color: var(--an-gold);
}

/* .edraft-proj-rail / -fill — ballot tally */
.an-broadcast .an-ballot {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: auto;
}

.an-broadcast .an-rail {
  position: relative;
  height: 12px;
  border-radius: 1px;
  background:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.12) 0 1px, transparent 1px 12.5%),
    rgba(255, 255, 255, 0.06);
  border: 1px solid var(--an-line);
}

.an-broadcast .an-rail__fill {
  position: absolute;
  left: 0;
  top: 2px;
  bottom: 2px;
  border-radius: 0;
  background: linear-gradient(90deg, var(--an-focus), var(--an-gold));
  transform-origin: left center;
  animation: anGrow 0.7s ease-out backwards;
}

.an-broadcast .an-ballot__cap {
  font-size: 11px;
  color: var(--an-muted);
}

/* ── Tables — .edraft-rc-table / -thead / -trow ── */
.an-broadcast .an-table {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
}

.an-broadcast .an-table-head,
.an-broadcast .an-table-row {
  display: grid;
  grid-template-columns: var(--an-cols, 32px minmax(0, 1.3fr) minmax(0, 1.2fr) minmax(0, 1fr));
  align-items: center;
  gap: 8px;
}

.an-broadcast .an-table-head {
  font-size: 11px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--an-muted);
  padding: 0 6px 6px;
  border-bottom: 1px solid var(--an-line);
}

.an-broadcast .an-table-body {
  overflow-y: auto;
  min-height: 0;
  scrollbar-width: thin;
}

.an-broadcast .an-table-row {
  font-size: 12px;
  padding: 5px 6px;
  border-bottom: 1px solid rgba(156, 178, 196, 0.08);
  border-left: 3px solid transparent;
}

.an-broadcast .an-table-row:hover {
  background: rgba(255, 255, 255, 0.025);
}

/* .edraft-rc-trow.is-best */
.an-broadcast .an-table-row.is-best {
  background: var(--an-gold-soft);
  border-left-color: var(--an-gold);
}

.an-broadcast .an-table-row.is-in {
  animation: anRise 0.18s ease-out backwards;
}

.an-broadcast .an-table-row > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.an-broadcast .an-cell-name {
  font-weight: 600;
  color: var(--an-text);
}

.an-broadcast .an-cell-muted {
  color: var(--an-muted);
  font-variant-numeric: tabular-nums;
}

.an-broadcast .an-cell-team {
  display: flex;
  align-items: center;
  gap: 6px;
  color: rgba(232, 240, 244, 0.8);
}

.an-broadcast .an-cell-team span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Logos + headshots — .edraft-logo / .edraft-pcard-photo ── */
.an-broadcast .an-logo {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: transparent;
  border: 0;
  border-radius: 0;
}

.an-broadcast .an-logo.sm { width: 20px; height: 20px; }
.an-broadcast .an-logo.md { width: 36px; height: 36px; }
.an-broadcast .an-logo.lg { width: 52px; height: 52px; }
.an-broadcast .an-logo.xl { width: 64px; height: 64px; }
.an-broadcast .an-logo.hero { width: 120px; height: 120px; }

.an-broadcast .an-logo img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.an-broadcast .an-headshot {
  display: flex;
  align-items: flex-start;
  width: auto;
  height: auto;
  padding: 0;
  border: 0;
  background: none;
}

/* ── Dock — .edraft-dock ── */
.an-broadcast .an-dock {
  grid-area: dock;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "state actions";
  align-items: center;
  gap: 10px 12px;
  padding: 8px 12px;
  border: 1px solid var(--an-line);
  border-radius: 6px;
  background: var(--an-panel-quiet);
  min-height: 0;
}

.an-broadcast .an-dock-state {
  grid-area: state;
  min-width: 0;
  font-size: 12px;
  font-weight: 600;
  color: rgba(232, 240, 244, 0.82);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.an-broadcast .an-dock-state b {
  color: var(--an-gold);
  font-weight: 700;
}

.an-broadcast .an-dock-actions {
  grid-area: actions;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
  align-items: center;
}

.an-broadcast .an-dock-primary {
  min-height: 38px;
  padding: 9px 18px;
  font-size: 13px;
  font-weight: 800;
}

.an-broadcast .an-dock-error {
  grid-column: 1 / -1;
  margin: 0;
  color: #f0a0a0;
  font-size: 12px;
}

/* ── Fan Pulse — .edraft-social-lane / .edraft-social-feed (vertical) ── */
.an-broadcast .an-pulse-lane {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  overflow: hidden;
  font-family: var(--an-body);
}

/* one font for the whole feed, whatever the feed component sets */
.an-broadcast .an-pulse-lane * {
  font-family: inherit !important;
}

.an-broadcast .an-pulse-lane .an-social-feed {
  position: relative !important;
  inset: auto !important;
  width: 100%;
  max-width: none;
  height: 100%;
  margin: 0;
  padding: 0;
  background: transparent;
  border: none;
  box-shadow: none;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.an-broadcast .an-pulse-lane .an-social-feed__shell {
  gap: 8px;
  height: 100%;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.an-broadcast .an-pulse-lane .an-social-feed__header {
  display: none;
}

.an-broadcast .an-pulse-lane .an-social-feed__stack {
  flex: 1 1 auto;
  min-height: 0;
  max-height: none;
  overflow-y: auto;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}

.an-broadcast .an-pulse-lane .an-fan-tweet,
.an-broadcast .an-pulse-lane .an-live-tweet,
.an-broadcast .an-pulse-lane .an-social-feed__card {
  font-size: clamp(0.72rem, 0.6rem + 0.2vw, 0.84rem);
  line-height: 1.3;
  max-height: none;
  overflow: hidden;
  flex: 0 0 auto;
  width: 100%;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  align-content: start;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--an-line);
  border-radius: 7px;
  padding: 8px 10px;
  transition: background 0.15s ease;
  animation: anRise 0.18s ease-out backwards;
}

.an-broadcast .an-pulse-lane .an-fan-tweet:hover {
  background: rgba(255, 255, 255, 0.07);
}

.an-broadcast .an-pulse-lane .an-fan-tweet__avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  overflow: hidden;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, rgba(80, 200, 220, 0.35), rgba(212, 175, 55, 0.28));
  color: #eaf4f8;
  font-size: 11px;
  font-weight: 700;
}

.an-broadcast .an-pulse-lane .an-fan-tweet__avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.an-broadcast .an-pulse-lane .an-fan-tweet__content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.an-broadcast .an-pulse-lane .an-fan-tweet__top {
  display: flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
  flex-wrap: wrap;
}

.an-broadcast .an-pulse-lane .an-fan-tweet__name {
  font-weight: 700;
  color: #eef5f9;
  font-size: 12.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 60%;
}

.an-broadcast .an-pulse-lane .an-fan-tweet__handle,
.an-broadcast .an-pulse-lane .an-fan-tweet__time {
  color: var(--an-muted);
  font-size: 11px;
}

.an-broadcast .an-pulse-lane .an-fan-tweet__text {
  margin: 0;
  color: rgba(232, 240, 244, 0.94);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Entry Draft hides these in its feed */
.an-broadcast .an-pulse-lane .an-fan-tweet__metrics,
.an-broadcast .an-pulse-lane .an-fan-tweet__context {
  display: none;
}

/* ── Motion — edraft-rc-fade / pdRise / edraftProjGrow ── */
@keyframes anFade {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: none; }
}

@keyframes anRise {
  from { transform: translateY(10px); opacity: 0; }
  to { transform: none; opacity: 1; }
}

@keyframes anGrow {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}

@media (prefers-reduced-motion: reduce) {
  .an-broadcast *,
  .an-broadcast *::before,
  .an-broadcast *::after {
    animation: none !important;
    transition: none !important;
  }
}

/* ── Responsive — Entry Draft targets ── */
@media (max-width: 1600px) {
  .an-broadcast .an-floor-grid {
    grid-template-columns: clamp(200px, 13vw, 236px) minmax(0, 1fr) clamp(290px, 20vw, 344px);
  }
}

@media (max-width: 1400px) {
  .an-broadcast .an-floor-grid {
    grid-template-columns: clamp(184px, 12vw, 210px) minmax(0, 1fr) clamp(260px, 20vw, 300px);
  }

  .an-broadcast .an-card-grid {
    grid-template-columns: clamp(176px, 22%, 214px) minmax(0, 1fr) clamp(228px, 28%, 296px);
    gap: 8px;
  }

  .an-broadcast .an-card-grid.is-two {
    grid-template-columns: clamp(176px, 24%, 230px) minmax(0, 1fr);
  }

  .an-broadcast .an-stagehead-next {
    width: clamp(140px, 16vw, 200px);
  }
}

@media (max-width: 1200px) {
  .an-broadcast .an-milestones,
  .an-broadcast .an-stagehead-next {
    display: none;
  }

  .an-broadcast .an-stagehead {
    grid-template-columns: auto minmax(0, 1fr);
  }
}

@media (max-height: 860px) {
  .an-broadcast .an-stage {
    gap: 6px;
  }
}

@media (max-height: 760px) {
  .an-broadcast .an-stagehead {
    padding: 6px 10px;
  }

  .an-broadcast .an-stagehead-num {
    font-size: 1.5rem;
  }

  .an-broadcast .an-dock-primary {
    min-height: 34px;
  }

  .an-broadcast .an-logo.hero {
    width: 96px;
    height: 96px;
  }
}
/* Voting results table (ballot breakdown) */
.an-broadcast .an-votes__fmt {
  margin: 0 0 4px;
  font-size: 11px;
  opacity: 0.7;
}
.an-broadcast .an-votes__row {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) 40px 56px;
  gap: 8px;
  align-items: center;
  font-size: 12.5px;
  padding: 4px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.an-broadcast .an-votes__head {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.6;
  border-bottom-color: rgba(255, 255, 255, 0.14);
}
.an-broadcast .an-votes__row em {
  font-style: normal;
  text-align: right;
}
.an-broadcast .an-votes__who {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.an-broadcast .an-votes__name {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.an-broadcast .an-votes__name strong,
.an-broadcast .an-votes__name small {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.an-broadcast .an-votes__name small {
  font-size: 11px;
  opacity: 0.65;
}
.an-broadcast .an-votes__row.is-winner strong {
  color: var(--ops-gold, #f5b942);
}

