  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 24px;
  border-bottom: 1px solid var(--wjc-border);
  background: rgba(12, 33, 77, 0.96);
  backdrop-filter: blur(18px);
  z-index: 20;
