.sc-standings-block > :first-child{font-size:17px!important}
.trade-intel-hero strong{font-size:26px!important}
.th-read-head strong{font-size:20px!important}

/* Numbers: big and heavy, no glow; colour only when it means something */
.nhlrost-hud-tile > *:nth-child(2),.nhlrost-hud-tile strong,.lb-pill strong,.lb-pill > *:last-child,.sc-team-profile-headline > div > *:first-child{
