.nhlrost-pot-mini{color:var(--ds-label)!important;font-weight:700!important}
.nhlrost-board-row__contract{color:var(--ds-text)!important}
.sc-standings-table td.is-pts{color:var(--ds-text)!important;text-shadow:none!important}
.nhlrost-hud-tile.is-good > *:nth-child(2){color:var(--ds-good)!important}

/* Roster rows: compact portrait, avail shown only when it is not the default */
