.nhlrost-sidebar > button:first-child,.lb-sidebar > :first-child,.nhlrost-side-nav + *{box-shadow:none!important}
[class*="sidebar"] [class*="home"],[class*="sidebar"] > a:first-child{border:0!important;box-shadow:none!important;background:none!important}

/* Generic secondary buttons: no gold frame (lacquer reserved for primaries) */
