  box-shadow:none!important;border:2px solid rgba(255,255,255,.18)!important;background:rgba(255,255,255,.05)!important;text-shadow:none!important;
  font-family:var(--dd-font-ui)!important;font-weight:800!important;text-transform:none!important;letter-spacing:.02em!important}
/* Roster: gold = franchise tier only; calm labels; one quiet active-tab style; table sized to content */
.nhlrost-ovr-pill.is-elite .nhlrost-ovr-pill__value,.nhlrost-ovr-pill.is-good .nhlrost-ovr-pill__value{color:var(--ds-text)!important}
.nhlrost-hud-tile__body small{text-transform:none!important;letter-spacing:.02em!important;font-size:13px!important;color:var(--ds-label)!important}
.nhlrost-hud-tile__body strong{font-size:26px!important}
.nhlrost-brand{border:0!important;box-shadow:none!important;background:none!important}
.nhlrost-filters-primary button{text-transform:none!important;letter-spacing:.02em!important;font-size:14px!important}
.nhlrost-filters-primary button.is-active{background:rgba(46,230,214,.14)!important;color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
.nhlrost-board-sheet__head,.nhlrost-board-row{grid-template-columns:340px 56px 72px 56px 120px 150px 110px!important;justify-content:start!important}
.nhlrost-ovr-pill.is-franchise .nhlrost-ovr-pill__value{color:var(--ds-text)!important}
.nhlrost-ovr-pill.is-franchise .nhlrost-ovr-pill__value::after{content:"★";font-size:12px;color:var(--ds-elite);margin-left:3px;vertical-align:super}
.nhlrost-ovr-pill__mod,.ovr-mod-badge{display:block;margin-top:2px;font-size:11px;font-weight:800;letter-spacing:0;color:#d4a24c;line-height:1.2}
.nhlrost-filters-primary button,.nhlrost-filters-primary select{font-size:13px!important;white-space:nowrap!important}
.nhlrost-filters-primary button{flex:0 0 auto!important;width:auto!important;min-width:0!important;padding-left:14px!important;padding-right:14px!important}
/* Trade Desk: one UI face (no monospace values), calm labels, single primary */
.trade-hub-root .trade-intel-value,.trade-hub-root .trade-roster-capacity__pill,.trade-hub-root [class*=cap-strip],.trade-hub-root .th-pulse{font-family:var(--dd-font-ui)!important;font-weight:800!important}
.trade-hub-root .th-read-grid span,.trade-hub-root .th-read-needs > span,.trade-hub-root .th-read-needs b,.trade-hub-root .th-pulse span,
.trade-hub-root .trade-package-header-main > span,.trade-hub-root .trade-slot-placeholder,.trade-hub-root .trade-clear-value-head strong,.trade-hub-root .trade-fan-vitriol-head{
