.trade-intel-view-players{background:none!important;color:var(--ds-active)!important;border:2px solid rgba(46,230,214,.5)!important;box-shadow:none!important;text-transform:none!important;letter-spacing:.02em!important;font-weight:800!important}
.trade-intel-view-players:hover{background:rgba(46,230,214,.12)!important}
.trade-package-col{box-shadow:0 0 0 2px var(--dd-gold-lo),0 0 0 4px var(--dd-gold-hi),0 0 0 6px var(--dd-gold-lo)!important}
.trade-hub-root *:not(.trade-hub-propose-btn):not(.trade-hub-propose-btn *){text-transform:none!important}
.trade-hub-root .trade-package-cap-strip,.trade-hub-root .trade-package-cap-strip *{font-family:var(--dd-font-ui)!important;-webkit-text-stroke:0!important;text-shadow:none!important;font-weight:800!important}
.th-read [class*="side-pill"]{display:none!important}
.trade-intel-row.gold .trade-intel-value{color:var(--ds-text)!important}

/* ==========================================================================
   SECTION: Page titles (the only Luckiest Guy headings) + Calendar pass
   ========================================================================== */
.lb-title,.nhlcal-month-title-block h2,.th-title-block strong{font-family:var(--dd-font-display)!important;font-weight:400!important;color:var(--dd-yellow)!important;
  -webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline),0 0 16px rgba(255,226,58,.3)!important;letter-spacing:.03em!important}
.nhlcal-month-title-block h2{background:none!important;-webkit-background-clip:border-box!important;-webkit-text-fill-color:var(--dd-yellow)!important}
.nhlcal-empty-day-line,.nhlcal-side-code{display:none!important}
.nhlcal-brand-button{border:0!important;box-shadow:none!important;background:none!important;filter:none!important;transform:none!important}
.nhlcal-side-label{text-transform:none!important;letter-spacing:.02em!important;font-size:13px!important}
.nhlcal-stat-pill{background:none!important;border:0!important;box-shadow:none!important}
.nhlcal-stat-pill > :first-child:not(div:has(span)){display:none}
.nhlcal-card-header h3,.nhlcal-card-header h2,.nhlcal-root h3{font-family:var(--dd-font-ui)!important;-webkit-text-stroke:0!important;text-shadow:none!important;text-transform:none!important;letter-spacing:.01em!important;color:var(--ds-text)!important}
.nhlcal-empty-orb{display:none!important}
.nhlcal-advance-button:not(.nhlcal-advance-button-secondary){font-family:var(--dd-font-display)!important}
.nhlcal-advance-button-secondary{background:none!important;box-shadow:none!important;border:2px solid rgba(255,255,255,.18)!important;font-family:var(--dd-font-ui)!important;font-weight:800!important;text-shadow:none!important;color:var(--ds-text)!important}
.nhlcal-root th,.nhlcal-root [class*=weekday],.nhlcal-root [class*=legend]{text-transform:none!important;letter-spacing:.02em!important}
.nhlcal-stat-strip{background:none!important;border:0!important;box-shadow:none!important;padding:0 4px!important;min-height:0!important}
.nhlcal-advance-button:not(.nhlcal-advance-button-secondary){clip-path:none!important;color:var(--dd-cream)!important;border:3px solid!important;border-color:var(--dd-gold-hi) var(--dd-gold) var(--dd-gold-lo) var(--dd-gold)!important;border-radius:8px!important;
  background:linear-gradient(180deg,var(--dd-lacquer-hi),var(--dd-lacquer) 55%,var(--dd-lacquer-lo))!important;text-shadow:0 2px 0 var(--dd-lacquer-lo)!important;
  box-shadow:0 0 0 2px var(--dd-gold-lo),0 0 0 4px var(--dd-gold-hi),0 0 0 6px var(--dd-gold-lo),0 8px 14px rgba(0,0,0,.45)!important}
.nhlcal-advance-button:not(.nhlcal-advance-button-secondary) *{color:inherit!important}

/* ==========================================================================
   SECTION: Draft War Room / Draft Class pass
   One countdown (header), quiet rank + identity, no per-row reason chips or
   duplicate league badges, one UI face for data.
   ========================================================================== */
.dc-root.dc-screen{background:radial-gradient(ellipse 55% 50% at 10% 6%,rgba(46,230,214,.16),transparent 70%),radial-gradient(ellipse 50% 45% at 94% 96%,rgba(255,180,138,.16),transparent 70%),linear-gradient(165deg,#2a4c9e 0%,#1b3576 45%,#122a5e 100%)!important}
.dc-root [class*="dc-"]:not(button){font-family:var(--dd-font-ui)}
.dc-root,.dc-root *{text-transform:none!important}
.dc-topbar,.dc-hud-strip,.dc-hud-strip__item,.dc-prospect-board,.dc-prospect-board__head,.dc-intel-feed{background:transparent!important;border:0!important;box-shadow:none!important}
.dc-hud-strip__item:has(small:only-of-type) svg,.dc-hud-strip__item > :first-child:not(.dc-hud-strip__text){display:none!important}
.dc-war-countdown b{font-family:var(--dd-font-display)!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important}
.dc-prospect-row__rank,.dc-prospect-row__rank *{font-family:var(--dd-font-ui)!important;font-weight:900!important;-webkit-text-stroke:0!important;text-shadow:none!important;color:var(--ds-text)!important}
.dc-prospect-row__rank s{color:var(--ds-label)!important;font-weight:700!important;font-size:.75em}
.wr-reason-chip,.fc-league i{display:none!important}
.dc-prospect-row__identity strong + *,.dc-prospect-row__identity [class*=ovr],.dc-prospect-row__identity b{font-family:var(--dd-font-ui)!important;-webkit-text-stroke:0!important;text-shadow:none!important;color:var(--ds-label)!important;font-weight:800!important}
.dc-prospect-row__identity strong{font-family:var(--dd-font-ui)!important;font-size:16px!important;font-weight:900!important;color:var(--ds-text)!important;text-shadow:none!important}
.dc-prospect-row__cell,.dc-intel-feed,.dc-intel-feed *{font-family:var(--dd-font-ui)!important}
.dc-prospect-board__head button,.dc-prospect-board__head [role=tab]{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important;font-weight:800!important}
.dc-prospect-board__head button.is-active,.dc-prospect-board__head [aria-selected=true]{color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
.dc-board-nav__item{border:0!important;background:none!important;box-shadow:none!important}
.dc-board-nav__item.is-active{box-shadow:inset 3px 0 0 var(--ds-active)!important;background:rgba(46,230,214,.08)!important}

/* ==========================================================================
   SECTION: Contracts / Cap Ledger pass
   No word-in-a-box insignia, no icon tiles on labels, no glowing numbers,
   quiet filter chips, hero and panels unboxed; empty action panel collapses.
   ========================================================================== */
.cap-office-screen{background:radial-gradient(ellipse 55% 50% at 10% 6%,rgba(46,230,214,.16),transparent 70%),radial-gradient(ellipse 50% 45% at 94% 96%,rgba(255,180,138,.16),transparent 70%),linear-gradient(165deg,#2a4c9e 0%,#1b3576 45%,#122a5e 100%)!important}
