.cap-insignia{display:none!important}
.cap-ledger-hero,.cap-ledger-hero-stats > div,.cap-office-panel,.cap-board-panel{background:transparent!important;border:0!important;box-shadow:none!important}
.cap-metric-label i,.cap-metric-label svg,.cap-metric-label > span:first-child:empty,.cap-metric-label [class*=icon]{display:none!important}
.cap-metric-label{color:var(--ds-label)!important;letter-spacing:.02em!important}
.cap-num-pop{text-shadow:none!important;font-family:var(--dd-font-ui)!important;font-weight:900!important;font-size:28px!important}
.cap-num-pop.tone-gold,.cap-num-pop.tone-cyan{color:var(--ds-text)!important}
.cap-office-titles h1,.cap-office-titles h2,.cap-office-titles strong{font-family:var(--dd-font-display)!important;font-weight:400!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important;letter-spacing:.03em!important}
.cap-office-kicker{color:var(--ds-label)!important}
.cap-filter-pill{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important;font-weight:800!important}
.cap-filter-pill.is-active{color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
.cap-empty-state{border:0!important;background:none!important}
.cap-action-panel--empty{min-height:0!important;padding:14px!important;background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important}
.cap-ledger-tab{background:none!important;border:0!important;box-shadow:none!important;font-weight:800!important;color:var(--ds-label)!important}
.cap-ledger-tab.cap-ledger-tab-active{color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
.cap-office-back{border:2px solid rgba(255,255,255,.18)!important;background:none!important;box-shadow:none!important;border-radius:999px!important}
.cap-num-pop,.cap-num-pop *{text-shadow:none!important}

/* ==========================================================================
   SECTION: Scouting pass
   Top strip: five tiles -> one unboxed number row. Bottom desk metrics drop
   the duplicates (files / budget already in the header pills). Tutorial list
   leaves the default view. Numbers white; gold only for the projected pick.
   ========================================================================== */
.scout-root{background:radial-gradient(ellipse 55% 50% at 10% 6%,rgba(46,230,214,.16),transparent 70%),radial-gradient(ellipse 50% 45% at 94% 96%,rgba(255,180,138,.16),transparent 70%),linear-gradient(165deg,#2a4c9e 0%,#1b3576 45%,#122a5e 100%)!important}
.scout-root,.scout-root *{text-transform:none!important}
.scout-top-strip{display:flex!important;flex-wrap:wrap;gap:8px 40px!important;background:none!important;border:0!important;box-shadow:none!important;padding:10px 4px!important}
.scout-top-strip .scout-ops-metric{background:none!important;border:0!important;box-shadow:none!important;padding:0!important;min-height:0!important;flex:0 0 auto}
.scout-intel-banner{flex-basis:100%;order:2;background:none!important;border:0!important;box-shadow:none!important;padding:0!important;color:var(--ds-label)!important}
.scout-intel-banner strong{color:var(--ds-active)!important}
.scout-ops-metric__label{color:var(--ds-label)!important;letter-spacing:.02em!important}
.scout-ops-metric__value{color:var(--ds-text)!important;font-weight:900!important;font-size:28px!important;text-shadow:none!important}
.scout-ops-metric.tone-gold .scout-ops-metric__value{color:var(--ds-elite)!important}
.desk-metrics .scout-ops-metric:nth-child(2){display:none!important}
.desk-metrics .scout-ops-metric{background:none!important;border:0!important;box-shadow:none!important}
.desk-hero{background:none!important;border:0!important;box-shadow:none!important}
.desk-hero-copy ol{display:none!important}
.desk-hero-copy h2{font-size:28px!important;font-weight:900!important;letter-spacing:.01em!important}
.desk-hero-actions .nhlcal-advance-button{font-size:20px!important;min-height:52px}
.scout-command .nhlcal-quick-link{background:none!important;border:2px solid rgba(255,255,255,.18)!important;box-shadow:none!important}
.scout-command h1,.scout-command h2,.scout-command strong:first-child{font-family:var(--dd-font-display)!important;font-weight:400!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important;letter-spacing:.03em!important}
/* Scouting rows: one primary (Auto-assign); per-row Assign is a quiet secondary */
.desk-row .nhlcal-advance-button{font-family:var(--dd-font-ui)!important;font-weight:800!important;font-size:13px!important;color:var(--ds-active)!important;background:none!important;
  border:2px solid rgba(46,230,214,.5)!important;box-shadow:none!important;text-shadow:none!important;border-radius:999px!important;padding:6px 14px!important;clip-path:none!important}
.desk-row .nhlcal-advance-button:hover{background:rgba(46,230,214,.12)!important}
.scout-top-strip .scout-ops-metric:not(:first-child) .scout-ops-metric__value{color:var(--ds-text)!important}
.scout-top-strip .scout-ops-metric:last-of-type{display:none!important}

/* ==========================================================================
   SECTION: Team Needs pass — one title, plain rows, the score leads
   ========================================================================== */
.teamneeds-main,.teamneeds-main *{text-transform:none!important}
.teamneeds-team-identity p,.teamneeds-draft-board-title,.teamneeds-section-title p,.teamneeds-section-title > span{display:none!important}
.teamneeds-team-identity h1{font-family:var(--dd-font-display)!important;font-weight:400!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important;letter-spacing:.03em!important}
.teamneeds-ops-context,.teamneeds-context-cell,.teamneeds-board-panel,.teamneeds-section-title{background:none!important;border:0!important;box-shadow:none!important}
.teamneeds-context-cell > :first-child:not(div),.teamneeds-context-cell svg,.teamneeds-context-cell [class*=icon]{display:none!important}
.teamneeds-context-cell__label{color:var(--ds-label)!important}
.teamneeds-depth-row{background:none!important;border:0!important;border-bottom:1px solid var(--ds-hair)!important;border-radius:0!important;box-shadow:none!important}
.teamneeds-depth-row:hover,.teamneeds-depth-row.is-active,.teamneeds-depth-row[aria-pressed=true]{background:rgba(46,230,214,.08)!important;box-shadow:inset 3px 0 0 var(--ds-active)!important}
.teamneeds-depth-score{font-size:28px!important;font-weight:900!important;color:var(--ds-text)!important}
.teamneeds-section-title h2,.teamneeds-section-title h3{font-size:20px!important;font-weight:900!important;letter-spacing:.01em!important}
.teamneeds-main th,.teamneeds-main [class*=board-head]{color:var(--ds-label)!important;letter-spacing:.02em!important}
.teamneeds-context-cell strong,.teamneeds-context-cell b{font-size:20px!important;font-weight:900!important}
.teamneeds-team-identity img,.teamneeds-team-identity [class*=logo]{background:none!important;border:0!important;box-shadow:none!important}
[class*="-sidebar"] [class*="brand"],[class*="-rail"] [class*="brand"]{border:0!important;box-shadow:none!important;background:none!important}

/* ==========================================================================
   SECTION: Stats Central (player views) pass
   ========================================================================== */
.statscentral-shell,.statscentral-shell *{text-transform:none!important}
.sc-player-table-header > div > span:first-child{display:none!important}
.sc-player-table-header,.sc-overview-module,.sc-overview-team-header,.sc-table-wrap,.sc-overview-featured-row,.sc-overview-featured-row > button,.sc-overview-team-header-chips > div{
  background:transparent!important;border:0!important;box-shadow:none!important}
.sc-overview-featured-row{gap:36px!important}
.sc-overview-featured-row > button span:first-child,.sc-overview-team-header-chips > div > span:first-child{color:var(--ds-label)!important;letter-spacing:.02em!important}
.sc-overview-team-header-chips > div > *:last-child,.sc-overview-featured-row > button strong{font-size:22px!important;font-weight:900!important;color:var(--ds-text)!important}
.statscentral-shell [class*=chip] button.is-active,.statscentral-shell [class*=segment] button.is-active,.statscentral-shell [class*=filter] button.is-active{background:rgba(46,230,214,.14)!important;color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
