.fa-fa-layout{flex:1 1 auto!important}
.fa-fa-list,.fa-fa-desk{max-height:none!important;height:auto!important;flex:1 1 auto!important}
.fa-root,.fa-root *{text-transform:none!important}
.fa-footer{display:none!important}
.fa-phase-text{font-family:var(--dd-font-display)!important;font-weight:400!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important;letter-spacing:.03em!important}
