.settings-shell{background:none!important;border:0!important;box-shadow:none!important}
.settings-scale-btn{background:none!important;border:2px solid rgba(255,255,255,.16)!important;color:var(--ds-text)!important;box-shadow:none!important;font-weight:800!important}
