.game-header__teamMark > :first-child:empty,.game-header__teamMark > [class*=logo]:not(:has(img)){display:none!important}
.lb-subtitle,.lb-shell [class*=inspector] *{text-transform:none!important;letter-spacing:.02em!important}

/* ==========================================================================
   SECTION: Event menus (offseason + playoffs) — shared rules
   h1 is the one page title per screen -> Double Dash display title.
   Each event's "next step" button is the single lacquer primary.
   ========================================================================== */
h1:not([class*="replay"] *){font-family:var(--dd-font-display)!important;font-weight:400!important;color:var(--dd-yellow)!important;
  -webkit-text-fill-color:var(--dd-yellow)!important;background:none!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important;letter-spacing:.03em!important;text-transform:none!important}
:is(.an-cta-btn,.retirement-continue-btn,.dlot-cta-btn,.resign-cta-btn,.cleanup-cta-btn,.nextseason-cta-btn,.bog-cta-btn,.cap-report-cta,[class*="continue-btn"],[class*="-cta-btn"]):not(.trade-hub-propose-btn){
  font-family:var(--dd-font-display)!important;font-weight:400!important;font-size:18px!important;letter-spacing:.04em!important;text-transform:none!important;color:var(--dd-cream)!important;
  border:3px solid!important;border-color:var(--dd-gold-hi) var(--dd-gold) var(--dd-gold-lo) var(--dd-gold)!important;border-radius:8px!important;clip-path:none!important;
  background:linear-gradient(180deg,var(--dd-lacquer-hi),var(--dd-lacquer) 55%,var(--dd-lacquer-lo))!important;text-shadow:0 2px 0 var(--dd-lacquer-lo)!important;
  box-shadow:0 0 0 2px var(--dd-gold-lo),0 0 0 4px var(--dd-gold-hi),0 0 0 6px var(--dd-gold-lo),0 8px 14px rgba(0,0,0,.45)!important}
:is(.an-cta-btn,.retirement-continue-btn,.dlot-cta-btn,.resign-cta-btn,.cleanup-cta-btn,.nextseason-cta-btn,[class*="continue-btn"],[class*="-cta-btn"]) *{color:inherit!important}
/* Awards: one title (stage head repeats it), quiet empty counter, clear current milestone */
.an-stagehead-num{color:var(--ds-text)!important;font-family:var(--dd-font-ui)!important;font-weight:900!important}
.an-stagehead,.an-card,.an-dock{background:rgba(14,30,72,.55)!important;border:0!important;box-shadow:none!important}
.an-milestones span{color:var(--ds-label)!important}
.an-milestones .is-current{color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
.an-root *,.retirement-page *,[class*="dlot-"] *,[class*="resign-"] *,[class*="cleanup-"] *,[class*="nextseason-"] *,[class*="bog-"] *,[class*="cap-report"] *{text-transform:none!important}
/* Board of Governors: one title (intro), no word-badge seal, rules trimmed to the two the player acts on */
.bog-root:has(.bog-intro) .bog-titles h1{display:none!important}
.bog-seal{display:none!important}
.bog-intro-lines > :is(:nth-child(1),:nth-child(4)){display:none!important}
.bog-intro-lines > *{background:none!important;border-left-color:rgba(255,255,255,.18)!important}
/* Cap Report: calm labels, no restating sublines, no state badge box, lacquer next step */
.cap-report-section-heading span:first-child,.cap-report-next-stage span,.cap-report-content [class*=kicker]{color:var(--ds-label)!important;letter-spacing:.02em!important}
.cap-report-metric small{display:none!important}
.cap-report-metric{background:none!important;border:0!important;box-shadow:none!important}
.cap-report-metric strong,.cap-report-metric b{font-size:22px!important;font-weight:900!important}
.cap-report-movement-badge{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important;font-weight:800!important}
.cap-report-continue-button{font-family:var(--dd-font-display)!important;font-size:18px!important;color:var(--dd-cream)!important;border:3px solid!important;border-color:var(--dd-gold-hi) var(--dd-gold) var(--dd-gold-lo) var(--dd-gold)!important;border-radius:8px!important;
  background:linear-gradient(180deg,var(--dd-lacquer-hi),var(--dd-lacquer) 55%,var(--dd-lacquer-lo))!important;text-shadow:0 2px 0 var(--dd-lacquer-lo)!important;box-shadow:0 0 0 2px var(--dd-gold-lo),0 0 0 4px var(--dd-gold-hi),0 0 0 6px var(--dd-gold-lo)!important}
.cap-report-continue-button *{color:inherit!important}
/* Re-sign Contract Table: page title, quiet filters, no nested dashed boxes, palette-consistent desk */
.resign-page-title{font-size:26px!important;margin:0 0 6px!important}
.resign-panel h2{color:var(--ds-text)!important;font-weight:900!important}
.resign-filter-chip{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important;font-weight:800!important}
.resign-filter-chip.is-active,.resign-filter-chip[aria-pressed=true]{color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
.resign-empty{border:0!important;background:none!important;color:var(--ds-label)!important}
.resign-detail-panel{background:rgba(14,30,72,.6)!important}
.resign-sim-day-btn{background:none!important;border:2px solid rgba(255,255,255,.18)!important;color:var(--ds-text)!important;box-shadow:none!important;font-weight:800!important}
/* Event shells with layered bg (cleanup / resign / nextseason / dlot): same bright stage as every other screen */
:is(.cleanup-root,.resign-root,.nextseason-root,.dlot-root,.retirement-page,.bog-root,.an-root){
  background:radial-gradient(ellipse 55% 50% at 10% 6%,rgba(46,230,214,.16),transparent 70%),radial-gradient(ellipse 50% 45% at 94% 96%,rgba(255,180,138,.16),transparent 70%),linear-gradient(165deg,#2a4c9e 0%,#1b3576 45%,#122a5e 100%)!important}
:is(.cleanup-bg,.resign-bg,.nextseason-bg,.dlot-bg){background:transparent!important}
:is(.cleanup-bg-scrim,.resign-bg-scrim,.nextseason-bg-scrim,.dlot-bg-scrim){opacity:.18!important}
.cleanup-chip{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-text)!important;font-weight:800!important;font-size:15px!important;padding:0 14px 0 0!important}
.cleanup-meta{gap:6px 18px!important}
/* New Season: drop decorative SEASON pseudo-labels around the title; chip unboxed */
.nextseason-title::before,.nextseason-title::after{display:none!important}
.nextseason-meta,.nextseason-meta *{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-good)!important;font-weight:800!important}

/* ==========================================================================
   SECTION: Calendar month grid — logo-led day cells
   Six week rows share the grid height (cells used to demand 128px inside a
   78px row and spill into the next week). Game days: opponent crest fills
   the cell, score is a bold result-coloured pill, vs / @ is a corner tag.
   The truncated text column (0px wide) and the tile chrome leave.
   ========================================================================== */
.nhlcal-root h1{font-family:var(--dd-font-ui)!important;-webkit-text-stroke:0!important;text-shadow:none!important;color:var(--ds-text)!important;-webkit-text-fill-color:var(--ds-text)!important;font-weight:900!important}
.nhlcal-month-grid{grid-template-rows:repeat(6,minmax(0,1fr))!important;grid-auto-rows:minmax(0,1fr)!important;overflow:hidden!important}
.nhlcal-day-cell{min-height:0!important;height:auto!important;overflow:hidden!important;position:relative!important;padding:0!important}
.nhlcal-day-number-row{position:absolute!important;top:5px;left:8px;z-index:3;pointer-events:none}
.nhlcal-day-number{font-size:14px!important;font-weight:900!important;color:var(--ds-label)!important;text-shadow:0 1px 2px rgba(0,0,0,.6)}
.nhlcal-day-content,.nhlcal-day-games{position:absolute!important;inset:0!important;height:auto!important;width:auto!important;margin:0!important;padding:0!important}
.nhlcal-day-games:has(.nhlcal-game-tile){display:block!important}
.nhlcal-game-tile{position:absolute!important;inset:0!important;width:auto!important;height:auto!important;display:grid!important;place-items:center!important;
  background:none!important;border:0!important;box-shadow:none!important;padding:0!important;margin:0!important;border-radius:0!important;cursor:pointer}
.nhlcal-game-tile.is-home{background:rgba(46,230,214,.07)!important}
.nhlcal-game-tile-accent,.nhlcal-game-tile-main,.nhlcal-game-chevron{display:none!important}
.nhlcal-game-tile-logo{width:auto!important;height:auto!important;background:none!important;border:0!important;box-shadow:none!important;padding:0!important}
.nhlcal-game-tile-logo .nhlcal-team-logo{width:clamp(34px,62%,58px)!important;height:auto!important;aspect-ratio:1;background:none!important;border:0!important;box-shadow:none!important;display:grid;place-items:center}
.nhlcal-game-tile .nhlcal-team-logo{width:52px!important}
.nhlcal-game-tile-logo img{width:100%!important;height:100%!important;object-fit:contain;filter:drop-shadow(0 3px 5px rgba(0,0,0,.55))}
.nhlcal-game-tile:hover .nhlcal-game-tile-logo img{transform:scale(1.08);transition:transform .15s}
.nhlcal-game-tile::after{position:absolute;top:5px;right:7px;font-size:11px;font-weight:900;color:var(--ds-label);letter-spacing:.02em}
.nhlcal-game-tile.is-home::after{content:"vs"}
.nhlcal-game-tile.is-away::after{content:"@"}
.nhlcal-game-tile-side{position:absolute!important;right:5px;bottom:5px;width:auto!important;height:auto!important}
.nhlcal-game-score-mini{display:flex!important;gap:2px;align-items:center;padding:3px 7px!important;border-radius:999px!important;font-size:14px!important;font-weight:900!important;
  background:rgba(8,18,46,.85)!important;border:0!important;color:#fff!important;font-variant-numeric:tabular-nums}
.nhlcal-game-score-mini *{color:inherit!important;font-style:normal!important}
.nhlcal-game-tile.result-win .nhlcal-game-score-mini{background:var(--ds-good)!important;color:#06261a!important}
.nhlcal-game-tile.result-loss .nhlcal-game-score-mini{background:var(--ds-bad)!important;color:#2a0508!important}
.nhlcal-game-tile.result-otl .nhlcal-game-score-mini,.nhlcal-game-tile.result-ot .nhlcal-game-score-mini{background:#ffc94a!important;color:#2a1a02!important}
.nhlcal-game-tile.result-win .nhlcal-game-score-mini::before{content:"W ";font-size:11px}
.nhlcal-game-tile.result-loss .nhlcal-game-score-mini::before{content:"L ";font-size:11px}
.nhlcal-corner-cut{display:none!important}
/* Event chips (preseason, opening night…) wrap instead of truncating */
.nhlcal-day-content [class*=event],.nhlcal-day-content [class*=chip]{white-space:normal!important;overflow:visible!important;text-overflow:clip!important;font-size:11px!important;line-height:1.15!important}
.nhlcal-day-games:not(:has(.nhlcal-game-tile)){top:24px!important;padding:0 5px!important}
.nhlcal-game-tile{grid-template-columns:1fr!important;grid-template-rows:1fr!important}
.nhlcal-game-tile > *{grid-area:1/1!important}
/* home tiles list away-first; reverse so every pill reads "your score - theirs" */
.nhlcal-game-tile.is-home .nhlcal-game-score-mini{flex-direction:row-reverse!important}
.nhlcal-game-tile.is-home .nhlcal-game-score-mini::before{order:9}
/* special events on game days: a small tag under the day number, never over the crest */
.nhlcal-day-cell:has(.nhlcal-game-tile) .nhlcal-day-special-events{position:absolute!important;left:6px;bottom:5px;z-index:3;max-width:50%}
.nhlcal-day-cell:has(.nhlcal-game-tile) .nhlcal-special-event-tile{padding:2px 6px!important;font-size:10px!important;background:rgba(8,18,46,.85)!important;border-radius:999px!important}
.nhlcal-day-cell:has(.nhlcal-game-tile) .nhlcal-special-event-tile > :not(.nhlcal-special-event-copy){display:none!important}
.nhlcal-day-cell:has(.nhlcal-game-tile) .nhlcal-special-event-copy *{white-space:nowrap!important;overflow:hidden;text-overflow:ellipsis;font-size:10px!important}
.nhlcal-day-special-events{position:relative;z-index:2}
/* Game days: the crest + score own the cell; an event on that day becomes a small dot by the date (details in the day panel) */
.nhlcal-day-cell:has(.nhlcal-game-tile) .nhlcal-day-special-events{display:none!important}
.nhlcal-day-cell:has(.nhlcal-game-tile):has(.nhlcal-special-event-tile) .nhlcal-day-number::after{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:#ffc94a;margin-left:5px;vertical-align:middle}
/* Non-game event days: no icon box, two-line wrap, quiet tile */
.nhlcal-special-event-tile{background:rgba(255,201,74,.10)!important;border:0!important;border-left:3px solid #ffc94a!important;box-shadow:none!important;border-radius:6px!important;padding:4px 6px!important}
.nhlcal-special-event-tile > :not(.nhlcal-special-event-copy){display:none!important}
.nhlcal-special-event-copy{display:block!important;min-width:0;width:100%}
.nhlcal-special-event-copy strong{display:-webkit-box!important;-webkit-line-clamp:2;-webkit-box-orient:vertical;white-space:normal!important;overflow:hidden!important;text-overflow:clip!important;font-size:11px!important;line-height:1.2!important;max-width:none!important}
.nhlcal-special-event-copy > :not(strong){display:none!important}
.nhlcal-special-event-tile{width:100%!important;max-width:none!important}
.nhlcal-day-cell:not(:has(.nhlcal-game-tile)) .nhlcal-day-special-events{position:absolute!important;left:5px;right:5px;bottom:5px}
/* Calm labels across the calendar; crests-only side standings */
.nhlcal-root *:not(.nhlcal-month-title-block h2){text-transform:none!important}

.nhlcal-day-marker-row{display:none!important}
.nhlcal-day-cell:has(.nhlcal-special-event-tile) .nhlcal-day-number::after{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:#ffc94a;margin-left:5px;vertical-align:middle}
.nhlcal-special-event-tile{grid-template-columns:1fr!important}.nhlcal-special-event-copy{grid-column:1/-1!important}

/* Side standings: crest + code fit the column (code was clipped to one letter) */
.nhlcal-standings-row > span:nth-child(2){display:flex!important;align-items:center;gap:4px;min-width:64px!important;overflow:visible!important}
.nhlcal-standings-row > span:nth-child(2) strong{font-size:12px!important;font-weight:900!important;overflow:visible!important;text-overflow:clip!important}
.nhlcal-standings-row{grid-template-columns:18px 70px repeat(5,minmax(0,1fr)) 40px!important}
/* Played games: crest lifts so the score pill sits clear below it */
.nhlcal-game-tile.is-final .nhlcal-game-tile-logo{transform:translateY(-7px)}
.nhlcal-game-tile.is-final .nhlcal-team-logo{width:44px!important}

/* ==========================================================================
   SECTION: Roster second pass (in-season data)
   ========================================================================== */
/* Season stats are real now -> bring the column back; status badges become text */
.nhlrost-board-sheet__head > :nth-child(11),.nhlrost-board-row > :nth-child(11){display:block!important}
.nhlrost-board-sheet__head,.nhlrost-board-row{grid-template-columns:300px 48px 64px 48px 110px 120px minmax(220px,1fr) 100px!important}
.nhlrost-board-sheet__head > *,.nhlrost-board-row > *{min-width:0}
.nhlrost-board-row__stats{font-size:13px!important;font-weight:700!important;color:var(--ds-muted)!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}
.nhlrost-mini-badge{background:none!important;border:0!important;box-shadow:none!important;padding:0!important;font-size:12px!important;font-weight:800!important}
.nhlrost-mini-badge.is-warn{color:#ffc94a!important}
.nhlrost-mini-badge.is-bad,.nhlrost-mini-badge.is-danger{color:var(--ds-bad)!important}
/* compact identity: 40px portrait, 50px rows */
.nhlrost-board-row{min-height:50px!important}
/* team selector text + sidebar labels */
.nhlrost-filters-primary select{color:#fff!important;-webkit-text-fill-color:#fff!important;text-indent:0!important;padding:0 30px 0 12px!important;min-width:170px!important}
.nhlrost-sidebar,.nhlrost-sidebar *{text-transform:none!important;letter-spacing:.02em!important}
.nhlrost-filters-primary select{min-width:0!important;max-width:160px}
.nhlrost-filters-primary button{padding-left:10px!important;padding-right:10px!important}
.nhlrost-filters-primary{gap:6px!important}
.nhlrost-board-row .nhlrost-headshot{transform:scale(.72)!important;transform-origin:left center!important}
.nhlrost-filters-primary input{height:38px!important;max-height:38px!important;min-width:0!important;width:150px!important;flex:0 1 150px!important;align-self:center}

/* ==========================================================================
   SECTION: Trade Hub second pass — player drawer
   Value bar is one colour (length = value); OVR leads the row; header intel
   pills become plain inline numbers; helper line + duplicate capacity go.
   ========================================================================== */
.trade-drawer-players,.trade-drawer-players *{text-transform:none!important}
.trade-players-header-main > span:not(.tid-tag){display:none!important}
.trade-players-intel-strip{gap:22px!important}
.trade-players-intel-pill{background:none!important;border:0!important;box-shadow:none!important;padding:0!important;font-size:15px!important;font-weight:900!important;color:var(--ds-text)!important}
.trade-players-intel-pill > span:first-child{color:var(--ds-label)!important;font-weight:700!important;font-size:12px!important;margin-right:5px;letter-spacing:.02em!important}
.trade-drawer-head .trade-roster-capacity{display:none!important}
.trade-pool-row{min-height:52px!important;border-bottom:1px solid var(--ds-hair)!important;background:none!important}
.trade-pool-row:hover{background:rgba(46,230,214,.07)!important}
.trade-player-list-name-row strong{font-size:16px!important;font-weight:900!important}
.trade-player-value-head > :first-child{display:none!important}
.trade-player-value-head > *{font-size:15px!important;font-weight:900!important;color:var(--ds-text)!important}
.trade-player-value-track{height:6px!important;border-radius:999px!important;background:rgba(255,255,255,.08)!important;border:0!important}
.trade-player-value-track > *{background:var(--ds-active)!important;border-radius:999px!important;box-shadow:none!important}
.trade-player-value-focus.value-elite .trade-player-value-track > *{background:var(--ds-elite)!important}
.trade-pool-season-line{color:var(--ds-muted)!important;font-size:12px!important}
.trade-player-ovr-tower > span{display:none!important}
.trade-player-ovr-tower strong{font-size:26px!important;font-weight:900!important;color:var(--ds-text)!important}

/* League Ops markets: profit column was 35px wide and collided with Market */
.lo-markets-body table{table-layout:fixed!important;width:100%!important}
.lo-markets-body th.lo-col-team,.lo-markets-body td.lo-col-team{width:28%}
.lo-markets-body .lo-col-rev,.lo-markets-body .lo-col-trend,.lo-markets-body .lo-col-profit,.lo-markets-body .lo-col-market,.lo-markets-body .lo-col-risk{width:14.4%;text-align:right;padding-right:18px!important;font-variant-numeric:tabular-nums;white-space:nowrap}
.lo-markets-body .lo-col-market,.lo-markets-body .lo-col-risk{text-align:left}
.lo-markets-body td.lo-col-rev{font-size:15px!important;font-weight:900!important}
.lo-markets-body .lo-col-team img{width:26px!important;height:26px!important}
.lo-markets-body [class*=chip],.lo-markets-body [class*=filter] button{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important}
.lo-markets-body [class*=filter] button.is-active,.lo-workspace [class*=filter] button.is-active{color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important;background:none!important}

/* Scouting second pass: files are all assigned -> Auto-assign is no longer the
   task; demote it. Row actions quiet. Range rows: rank + name lead. */
.desk-hero-actions .nhlcal-advance-button{font-family:var(--dd-font-ui)!important;font-weight:800!important;font-size:15px!important;min-height:44px!important;color:var(--ds-active)!important;
  background:none!important;border:2px solid rgba(46,230,214,.5)!important;box-shadow:none!important;text-shadow:none!important;border-radius:999px!important}
.desk-hero-actions > :not(.nhlcal-advance-button):not(p){background:none!important;border:0!important;color:var(--ds-label)!important;box-shadow:none!important}
.desk-hero-actions p{display:none!important}
.desk-row button:not(.nhlcal-advance-button){background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important;font-weight:800!important}
.desk-row button:not(.nhlcal-advance-button):hover{color:#fff!important}
.desk-row{border-left:0!important}
.desk-row strong{font-size:16px!important;font-weight:900!important}
.desk-row [class*=rank],.desk-row > :first-child{font-weight:900!important;color:var(--ds-text)!important}
.scout-card h2 + span,.scout-card [class*=kicker]:empty{display:none}
.scout-card .scout-card__head span:first-child,.scout-root [class*=section-title] > span:first-child{display:none!important}

/* Hub second pass */
.office-urgent-desk,.office-urgent-desk *{font-family:var(--dd-font-ui)!important;text-transform:none!important;letter-spacing:.01em!important;font-weight:800!important}
.office-urgent-desk{max-width:300px}
.office-hud .office-broadcast,.office-hud .office-broadcast *{text-transform:none!important;letter-spacing:.01em!important}
.office-hud .office-broadcast em{display:none!important}
.office-control-bar__primary,.office-control-bar__primary *{color:#fff!important;-webkit-text-fill-color:#fff!important;text-shadow:0 2px 0 #071440!important}
.office-control-bar__hint{display:none!important}
.office-control-bar{left:22px!important;right:auto!important;transform:none!important;bottom:58px!important;background:none!important;border:0!important;box-shadow:none!important}
.hub-console__quiet{font-family:var(--dd-font-ui)!important;font-weight:800!important}

/* ==========================================================================
   SECTION: Storylines second pass
   sl-app is a fixed-height flex column -> every section was being squashed
   (lead story 46px, ticker 2px). Sections keep their natural height and the
   app scrolls. Rink Oddities had no styles at all (raw browser buttons).
   ========================================================================== */
.sl-app{overflow-y:auto!important}
.sl-app > *{flex-shrink:0!important}
.sl-odd{display:flex;flex-direction:column;gap:6px;padding:4px 0 8px}
.sl-odd__head{display:flex;align-items:baseline;gap:12px}
.sl-odd__head h3{margin:0;font-size:18px;font-weight:900;color:var(--ds-text)}
.sl-odd__sub{font-size:13px;color:var(--ds-label)}
.sl-odd__all{margin-left:auto;background:none;border:0;color:var(--ds-active);font-weight:800;cursor:pointer;font-family:var(--dd-font-ui)}
.sl-odd__list{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:6px 18px}
.sl-odd__item{display:flex;flex-direction:column;gap:6px;border-bottom:1px solid var(--ds-hair);padding:6px 0}
.sl-odd__item.is-ours{box-shadow:inset 3px 0 0 var(--ds-active);padding-left:10px}
.sl-odd__main{all:unset;cursor:pointer;display:block;min-width:0}
.sl-odd__main:hover strong{color:var(--ds-active)}
.sl-odd__main:focus-visible{outline:2px solid var(--ds-active);outline-offset:2px}
.sl-odd__emoji{display:none}
.sl-odd__text{display:flex;flex-direction:column;gap:2px;min-width:0}
.sl-odd__text strong{font-size:15px;font-weight:900;color:var(--ds-text)}
.sl-odd__text em{font-style:normal;font-size:13px;color:var(--ds-muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.sl-odd__text small{font-size:12px;color:var(--ds-label)}
.sl-odd__replies{display:flex;flex-wrap:wrap;gap:6px}
.sl-odd__reply{background:none;border:2px solid rgba(46,230,214,.45);color:var(--ds-active);border-radius:999px;padding:4px 12px;font-weight:800;font-family:var(--dd-font-ui);cursor:pointer}
.sl-week__head + *::before,.sl-week__head > :not(h4){display:none}
.sl-chip{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important;font-weight:800!important}
.sl-chip.is-active,.sl-chip[aria-pressed=true]{color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
.sl-gridhead h3{font-size:16px!important;font-weight:900!important;color:var(--ds-text)!important;letter-spacing:.01em!important}

/* ==========================================================================
   SECTION: Draft Class / War Room second pass
   POT is the decision number: bright, big; range ends quiet, arrows gone.
   Pub/You is legible; "you vs public" rank chip loses its box.
   ========================================================================== */
.dc-record-mini{font-family:var(--dd-font-display)!important;font-size:24px!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important;letter-spacing:.03em!important}
.dc-hud-strip small{color:var(--ds-label)!important;letter-spacing:.02em!important}
.dc-prospect-row__pot .fc-proj__arrow{display:none!important}
.dc-prospect-row__pot strong{font-size:26px!important;font-weight:900!important;color:var(--ds-text)!important;opacity:1!important;margin:0 6px}
.dc-prospect-row__pot.is-pot-generational strong,.dc-prospect-row__pot.is-pot-elite strong{color:var(--ds-elite)!important}
.dc-prospect-row__pot em{font-style:normal!important;font-size:12px!important;color:var(--ds-label)!important;opacity:.85}
.dc-scout-file-split em{font-style:normal!important;font-size:11px!important;color:var(--ds-label)!important}
.dc-scout-file-split strong{font-size:14px!important;font-weight:900!important;color:var(--ds-text)!important}
.dc-prospect-row [class*=chip],.dc-prospect-row__identity em{background:none!important;border:0!important;box-shadow:none!important;padding:0!important;font-style:normal!important;color:var(--ds-label)!important;font-size:12px!important}
.dc-prospect-row__league b{font-weight:700!important;color:var(--ds-muted)!important}
.dc-prospect-board__head [class*=tab],.dc-prospect-board__head [class*=source] button,.dc-prospect-board button{clip-path:none!important}
.dc-prospect-board__head [class*=source] button,.dc-source-tabs button,.dc-prospect-board__head nav button{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-label)!important}
.dc-prospect-row{min-height:64px!important}

/* ==========================================================================
   SECTION: Draft War Room third pass — the board is the room
   Header + dates collapse into one band so the board gets the height.
   The board sits in one red-rim DD box (no inner cards); the top five wear
   gold rank tokens; Deploy coverage is the one lacquer action; toggles show
   their state with a check, not with "off" in the label.
   ========================================================================== */
.dc-root.dc-screen{display:flex!important;flex-direction:column;gap:10px!important;padding:12px 16px 0!important}
.dc-root.dc-screen > *{flex-shrink:0}
.dc-root.dc-screen > .dc-command-grid{flex:1 1 0;min-height:0}
.dc-topbar--war{padding:4px 0 0!important;min-height:0!important;align-items:center!important;grid-template-columns:1fr auto 1fr!important}
.dc-topbar--war .dc-topbar__left{gap:16px!important;align-items:center!important}
.dc-topbar--war .dc-topbar__center-logo{gap:2px!important}
.dc-topbar--war .dc-team-logo{width:56px!important;height:56px!important;filter:drop-shadow(0 3px 0 var(--dd-outline))}
.dc-topbar--war .dc-date-mini{color:var(--ds-label)!important;font-size:12px!important;font-weight:800!important}
.dc-war-meta{gap:14px!important;margin-top:4px;color:var(--ds-label)!important;font-size:13px!important;font-weight:700}
.dc-war-meta strong{color:var(--ds-text)!important;font-weight:900}
.dc-war-countdown{justify-self:end;text-align:right}
.dc-war-countdown b{font-size:40px!important;line-height:1!important;letter-spacing:.02em!important}
.dc-war-countdown small{display:block;margin-top:2px;color:var(--ds-label)!important;font-size:12px!important;font-weight:800!important}
.dc-back-btn--hud{border:2px solid rgba(255,255,255,.2)!important;background:none!important;box-shadow:none!important;border-radius:999px!important;padding:6px 14px!important;font-weight:800!important;font-size:13px!important}
.dc-back-btn--hud:hover{border-color:var(--dd-gold-hi)!important;color:var(--dd-yellow)!important}

/* Dates: one quiet line under the title, not a two-column slab */
.dc-hud-strip{display:flex!important;flex-wrap:wrap;gap:6px 32px!important;padding:0 2px!important;min-height:0!important;height:auto!important}
.dc-hud-strip__item{display:flex!important;align-items:baseline;padding:0!important;min-height:0!important;color:inherit!important;font:inherit!important}
.dc-hud-strip__text{display:flex!important;flex-direction:row!important;align-items:baseline;gap:8px}
.dc-hud-strip small{font-size:12px!important;font-weight:800!important;margin-right:8px}
.dc-hud-strip strong{font-size:15px!important;font-weight:900!important;color:var(--ds-text)!important}
.dc-hud-strip__item--clickable{cursor:pointer}
.dc-hud-strip__item--clickable strong{color:var(--ds-active)!important}
.dc-hud-strip__item--clickable strong::after{content:" ›"}
.dc-hud-strip__item--clickable:hover strong{text-decoration:underline;text-underline-offset:3px}

/* Workspace tabs: chunky DD tabs sitting on the board's rim */
.dc-workspace-tabs{height:auto!important;min-height:0!important;align-items:flex-end!important;background:none!important;border:0!important;box-shadow:none!important;gap:6px!important;padding:0 0 0 92px!important;margin-bottom:-10px;position:relative;z-index:2}
.dc-workspace-tabs button{height:auto!important;line-height:1.1!important;font-family:var(--dd-font-display)!important;font-size:17px!important;letter-spacing:.04em!important;padding:9px 20px 7px!important;min-height:0!important;border-radius:10px 10px 0 0!important;clip-path:none!important;
  border:3px solid var(--dd-outline)!important;border-bottom:0!important;background:linear-gradient(180deg,#24479e,#16306f)!important;color:rgba(255,231,196,.65)!important;box-shadow:none!important;text-shadow:0 2px 0 var(--dd-outline)!important}
.dc-workspace-tabs button:hover{color:var(--dd-cream)!important}
.dc-workspace-tabs button.is-active{background:linear-gradient(180deg,var(--dd-gold-hi),var(--dd-gold))!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important}

/* The board: one DD frame, everything inside is rows and rules */
.dc-command-grid{gap:8px!important}
@media (max-width:1200px){.dc-workspace-tabs{padding-left:0!important}.dc-command-grid{grid-template-rows:auto minmax(0,1fr)}
  /* The inline stacked-card layout targets classes the row no longer renders;
     keep the table, drop League and Window (both live in the dossier). */
  .dc-prospect-board .dc-prospect-board__columns{display:grid!important}
  .dc-prospect-board .dc-prospect-board__columns,.dc-prospect-board .dc-prospect-row{grid-template-areas:none!important;grid-template-columns:76px minmax(160px,1fr) 34px 96px 80px 60px!important;gap:8px!important;padding:0 10px!important}
  .dc-prospect-board .dc-prospect-row{padding:6px 10px!important}
  .dc-prospect-board .dc-prospect-row > *{grid-area:auto!important}
  .dc-prospect-board__col--league,.dc-prospect-board__col--proj,.dc-prospect-row__league,.dc-prospect-row__proj{display:none!important}
  .dc-board-nav__item{padding:6px!important}
}
.dc-prospect-board{display:flex!important;flex-direction:column;min-height:0;border:3px solid var(--dd-outline)!important;border-radius:14px!important;
  background:var(--dd-box-fill)!important;box-shadow:0 0 0 3px var(--dd-box-rim),0 0 0 6px var(--dd-outline),0 10px 22px rgba(0,0,0,.4)!important;overflow:hidden;margin:6px 6px 0 6px}
.dc-prospect-board__head{display:flex!important;justify-content:space-between;align-items:baseline;gap:16px;padding:12px 16px 4px!important}
.dc-prospect-board__head .dc-public-intel-note{flex:1 1 auto;max-width:none!important;margin:0!important;color:var(--ds-label)!important;font-size:12px!important}
.dc-prospect-board__head > span{color:var(--ds-label)!important;font-size:12px!important;font-weight:800!important;white-space:nowrap}
.dc-board-toolbar{display:flex!important;justify-content:space-between;align-items:center;gap:12px;padding:6px 12px 10px!important;border-bottom:2px solid rgba(0,0,0,.35)!important;background:none!important}
.dc-board-sources{display:flex;flex-wrap:wrap;gap:4px!important;min-width:0}
.dc-board-filters > *,.dc-board-filters button{white-space:nowrap!important;flex:0 0 auto}
.dc-prospect-board .dc-board-sources button{background:none!important;border:2px solid transparent!important;border-radius:999px!important;padding:5px 10px!important;letter-spacing:0!important;min-width:0!important;font-size:13px!important;font-weight:800!important;color:var(--ds-label)!important;box-shadow:none!important}
.dc-prospect-board .dc-board-sources button:hover{color:var(--ds-text)!important;border-color:rgba(255,255,255,.18)!important}
.dc-prospect-board .dc-board-sources button.is-active{background:linear-gradient(180deg,var(--dd-yellow),var(--dd-yellow-deep))!important;color:var(--dd-outline)!important;border-color:var(--dd-outline)!important;box-shadow:0 3px 0 var(--dd-outline)!important;font-weight:900!important}
.dc-board-filters{display:flex;align-items:center;gap:8px!important}
.dc-prospect-board .dc-consensus-chip{background:none!important;border:2px solid rgba(255,255,255,.2)!important;border-radius:999px!important;padding:5px 12px!important;font-size:13px!important;font-weight:800!important;color:var(--ds-label)!important;box-shadow:none!important}
.dc-prospect-board .dc-consensus-chip::before{content:"";display:inline-block;width:10px;height:10px;margin-right:7px;border-radius:3px;border:2px solid currentColor;vertical-align:-1px}
.dc-prospect-board .dc-consensus-chip.is-on{color:var(--ds-text)!important;border-color:var(--ds-active)!important;background:rgba(46,230,214,.12)!important}
.dc-prospect-board .dc-consensus-chip.is-on::before{background:var(--ds-active);border-color:var(--ds-active);box-shadow:inset 0 0 0 2px var(--dd-box-fill)}
.dc-prospect-board .dc-coverage-deploy__toggle{font-family:var(--dd-font-display)!important;font-size:14px!important;white-space:nowrap!important;letter-spacing:.04em!important;color:var(--dd-cream)!important;padding:7px 16px 5px!important;border-radius:8px!important;
  border:3px solid!important;border-color:var(--dd-gold-hi) var(--dd-gold) var(--dd-gold-lo) var(--dd-gold)!important;background:linear-gradient(180deg,var(--dd-lacquer-hi),var(--dd-lacquer) 55%,var(--dd-lacquer-lo))!important;
  text-shadow:0 2px 0 var(--dd-lacquer-lo)!important;box-shadow:0 0 0 2px var(--dd-gold-lo),0 4px 0 var(--dd-outline)!important;transition:transform .1s,filter .1s}
.dc-prospect-board .dc-coverage-deploy__toggle:hover{filter:brightness(1.1)}
.dc-prospect-board .dc-coverage-deploy__toggle:active{transform:translateY(2px)}
.dc-prospect-board__list{flex:1 1 auto;min-height:0}
.dc-prospect-board__list > :first-child{position:sticky;top:0;z-index:1;background:#0d1d4f!important;color:var(--ds-label)!important;font-size:12px!important;font-weight:800!important}

/* Rows: dividers only. Top five get a gold rank token and a warm wash */
.dc-prospect-row{border-left:0!important;border-bottom:1px solid rgba(255,255,255,.07)!important;background:none!important;box-shadow:none!important}
.dc-prospect-row:hover{background:rgba(46,230,214,.07)!important}
.dc-prospect-row.is-selected,.dc-prospect-row[aria-pressed=true]{background:rgba(46,230,214,.12)!important;box-shadow:inset 4px 0 0 var(--ds-active)!important}
.dc-prospect-row.is-top5{background:linear-gradient(90deg,rgba(255,226,58,.1),transparent 45%)!important}
.dc-prospect-row.is-top5:hover{background:linear-gradient(90deg,rgba(255,226,58,.16),rgba(46,230,214,.05) 45%)!important}
.dc-prospect-row__rank{display:flex!important;align-items:center;gap:6px;padding-left:12px!important}
.dc-prospect-row__rank .fc-rank-delta{display:inline-flex!important;flex-direction:row-reverse;align-items:baseline;gap:6px}
.dc-prospect-row__rank .fc-rank-delta > span[aria-hidden]{display:none!important}
.dc-prospect-row__rank strong,.dc-prospect-row__rank .fc-rank{font-size:20px!important;min-width:2.2em}
.dc-prospect-row__rank s{text-decoration:none!important;font-size:11px!important}
.dc-prospect-row__rank s::before{content:"was "}
.dc-prospect-row.is-top5 .dc-prospect-row__rank strong,.dc-prospect-row.is-top5 .dc-prospect-row__rank .fc-rank{display:inline-grid;place-items:center;min-width:0;width:38px;height:38px;border-radius:50%;font-family:var(--dd-font-display)!important;font-weight:400!important;font-size:18px!important;
  color:var(--dd-yellow)!important;-webkit-text-stroke:1.2px var(--dd-outline)!important;paint-order:stroke fill;text-shadow:0 2px 0 var(--dd-outline)!important;
  background:radial-gradient(circle at 35% 30%,#3a64c8,#16306f)!important;border:3px solid var(--dd-gold)!important;box-shadow:0 0 0 2px var(--dd-outline),0 3px 0 var(--dd-outline)}
.dc-prospect-row__ovr{margin-left:8px;font-size:13px!important}
.dc-prospect-row__sub{color:var(--ds-label)!important;font-size:13px!important}
.dc-scout-file-split{display:flex!important;flex-direction:column;gap:1px}
.dc-scout-file-split__line{display:flex!important;justify-content:flex-end;align-items:baseline;gap:6px}
.dc-scout-file-split em{font-size:11px!important;font-weight:800}
.dc-scout-file-split .is-empty strong{color:var(--ds-muted)!important;font-weight:700!important}
.dc-prospect-row__proj{font-weight:800!important;font-size:13px!important}

/* Rail: words you can read, active item in DD yellow */
.dc-board-nav-rail{padding-top:6px}
.dc-board-nav__item{border-radius:10px!important;padding:10px 4px!important;color:var(--ds-label)!important}
.dc-board-nav__item:hover{color:var(--ds-text)!important;background:rgba(255,255,255,.05)!important}
.dc-board-nav__item.is-active{color:var(--dd-yellow)!important;background:rgba(255,226,58,.1)!important;box-shadow:inset 3px 0 0 var(--dd-yellow)!important}
.dc-board-nav__label{font-size:12px!important;font-weight:800!important;letter-spacing:.01em!important}

/* Weekly stock: a ticker bar with a gold rail, like the office wire */
.dc-intel-feed--weekly{display:flex!important;align-items:center;gap:14px;height:40px!important;margin:0 -16px!important;padding:0 16px!important;background:rgba(6,14,36,.92)!important;border-top:3px solid var(--dd-gold)!important;overflow:hidden}
.dc-intel-feed--weekly h3{flex:0 0 auto;margin:0!important;font-family:var(--dd-font-display)!important;font-size:14px!important;font-weight:400!important;letter-spacing:.04em!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1px var(--dd-outline);paint-order:stroke fill;text-shadow:0 2px 0 var(--dd-outline)!important}
.dc-intel-feed--weekly ul{gap:22px!important;font-size:13px!important;font-weight:700}
.dc-intel-feed--weekly li{color:var(--ds-text)!important;white-space:nowrap}
.dc-intel-feed--weekly li.is-down{color:#ff9b8a!important}
.dc-intel-feed--weekly li.is-up{color:#8ff0b0!important}

.dc-root button:focus-visible{outline:3px solid var(--dd-yellow)!important;outline-offset:2px}

/* ==========================================================================
   SECTION: Stats Central — skater / goalie ledgers
   Numbers are white (cyan = interactive only); elite gets gold, nothing else
   tinted. PTS is the bold anchor. Row actions appear on hover. Empty
   selected-player summary row leaves the skaters page.
   ========================================================================== */
.sc-skater-stat,.sc-skater-stat *{color:var(--ds-text)!important;text-shadow:none!important}
.sc-skater-stat.is-elite,.sc-skater-stat.is-elite *{color:var(--ds-elite)!important}
.sc-skater-stat.is-poor,.sc-skater-stat.is-bad{color:var(--ds-muted)!important}
.sc-table-wrap td,.sc-table-wrap th{font-variant-numeric:tabular-nums}
.sc-table-wrap td.is-sorted,.sc-table-wrap td[class*=sort]{background:rgba(46,230,214,.05)!important}
.sc-table-wrap td small,.sc-table-wrap td .sc-rank-sub,.sc-table-wrap td span[class*=rank]{display:none!important}
.sc-skaters-page-v3 .sc-goalie-summary-row{display:none!important}
.sc-player-row-actions{opacity:0;transition:opacity .12s}
.sc-table-wrap tr:hover .sc-player-row-actions,.sc-player-row-actions:focus-within{opacity:1}
.sc-player-row-actions button{background:none!important;border:0!important;box-shadow:none!important;color:var(--ds-active)!important;font-weight:800!important}
.sc-player-name-copy{min-width:0}
.sc-player-name-copy strong{font-size:15px!important;font-weight:900!important}
.sc-table-wrap td:has(.sc-skater-stat) small,.sc-table-wrap td [class*=tier],.sc-table-wrap td [class*=archetype]{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:140px;display:block}
.statscentral-shell [class*=filter] button.is-active,.statscentral-shell [class*=pos] button.is-active,.statscentral-shell [class*=density] button.is-active{background:rgba(46,230,214,.14)!important;color:#fff!important;box-shadow:inset 0 -3px 0 var(--ds-active)!important}
.sc-skater-stat.is-elite,.sc-skater-stat.is-elite *{color:var(--ds-text)!important}
.sc-table-wrap td.is-sorted .sc-skater-stat,.sc-table-wrap td.is-sorted{font-size:18px!important;font-weight:900!important}
.sc-table-wrap td.is-sorted .sc-skater-stat > :not(:first-child),.sc-table-wrap .sc-skater-stat > small,.sc-table-wrap .sc-skater-stat > em{display:none!important}
.sc-player-name-cell-simple [class*=ovr],.sc-player-name-cell-simple b,.sc-player-name-cell-simple em{color:var(--ds-muted)!important;font-style:normal!important}
.sc-legend-bar{display:none!important}
.sc-skater-stat > span{display:none!important}.sc-skater-stat strong{font-weight:900!important}
.th-read .th-side-pill{display:none!important}

/* ==========================================================================
   SECTION: Scrollbars — one Double Dash scrollbar everywhere
   ~200 scattered per-panel scrollbar rules (white Windows arrows on some,
   cyan slivers on others). One standard colour pair wins on every element;
   elements that hide their scrollbar (scrollbar-width:none) stay hidden.
   ========================================================================== */
*{scrollbar-color:var(--dd-gold,#c98a3c) rgba(5,12,44,.75)!important}

/* ==========================================================================
   SECTION: Trade Desk overhaul — the deal is the hero
   [ GM strip ...................................................... ]
   [ your roster rail ][ YOU SEND  ⇄  THEY SEND ][ their roster rail ]
   [                  ][ value · fans · PROPOSE ][                   ]
   Rails are the asset lists (was a stat card + "View Players" drawer),
   packages show every slot without an inner scroll, the GM read is one strip.
   ========================================================================== */
.nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{display:grid!important;
  grid-template-columns:minmax(280px,.95fr) minmax(560px,1.5fr) minmax(280px,.95fr)!important;
  grid-template-rows:auto minmax(0,1fr)!important;grid-template-areas:"read read read" "lrail deal rrail"!important;
  gap:14px 16px!important;padding:10px 16px 14px!important;flex:1 1 auto;min-height:0!important;height:auto!important;
  border:0!important;background:none!important;box-shadow:none!important;overflow:hidden}
.nhlcal-root.trade-hub-root .th-deal-layout > * + *{border-left:0!important}
.th-deal-layout > .th-read{grid-area:read}
.th-deal-layout > .trade-team-panel-left{grid-area:lrail}
.th-deal-layout > .trade-team-panel-right{grid-area:rrail}
.th-deal-layout > .th-deal-table{grid-area:deal}

/* GM strip */
.th-read.th-read--strip{display:flex!important;align-items:center;flex-wrap:wrap;gap:8px 28px;padding:10px 16px!important;position:relative}
.th-read--strip .th-read-who{display:flex;align-items:baseline;gap:10px}
.th-read--strip .th-read-who strong{font-size:24px!important}
.th-read-facts{display:flex;flex-wrap:wrap;gap:6px 26px;margin:0}
.th-read-facts > div{display:flex;align-items:baseline;gap:8px}
.th-read-facts dt{color:var(--ds-label,#9fb3d9);font-size:12px;font-weight:800}
.th-read-facts dd{margin:0;color:var(--ds-text,#fff);font-size:15px;font-weight:900}
.th-read-facts .is-interest dd{color:var(--dd-yellow)}
.th-read--strip .th-read-needs{display:flex;flex-wrap:wrap;gap:6px}
.th-read--strip .th-read-needs em{font-style:normal;font-size:12px;font-weight:800;padding:3px 10px;border-radius:999px;background:none;border:2px solid rgba(255,255,255,.18);color:var(--ds-text,#fff)}
.th-read--strip .th-read-needs em.is-need{border-color:rgba(255,155,138,.6);color:#ffc2b6}
.th-read--strip .th-read-needs em.is-surplus{border-color:rgba(143,240,176,.55);color:#bff7d3}
.th-read-how{margin-left:auto;position:relative}
.th-read-how summary{cursor:pointer;list-style:none;font-size:13px;font-weight:800;color:var(--ds-active,#2ee6d6);padding:4px 2px}
.th-read-how summary::-webkit-details-marker{display:none}
.th-read-how summary::after{content:" ▾"}
.th-read-how[open] summary::after{content:" ▴"}
.th-read--strip .th-read-steps,.th-read--strip:hover .th-read-steps{display:none!important}
.th-read--strip .th-read-how[open] .th-read-steps{display:grid!important;position:absolute;right:0;top:calc(100% + 6px);z-index:30;width:min(420px,80vw);gap:8px;margin:0;padding:14px 16px 14px 34px;
  background:rgba(10,22,54,.98)!important;border:3px solid var(--dd-outline);border-radius:12px;box-shadow:0 0 0 3px var(--dd-gold),0 12px 24px rgba(0,0,0,.5)}
.th-read-steps li span{display:block;color:var(--ds-label,#9fb3d9);font-size:13px}

/* Roster rails: DD red-rim box, same frame as the War Room board */
.nhlcal-root.trade-hub-root .trade-roster-rail{display:flex!important;flex-direction:column;min-height:0;overflow:hidden;padding:0!important;
  background:var(--dd-box-fill)!important;border:3px solid var(--dd-outline)!important;border-radius:14px!important;
  box-shadow:0 0 0 3px var(--dd-box-rim),0 0 0 6px var(--dd-outline),0 10px 22px rgba(0,0,0,.4)!important;margin:6px}
.trade-roster-rail__head{display:grid;grid-template-columns:1fr auto;align-items:center;gap:8px 10px;padding:12px 14px 10px;border-bottom:2px solid rgba(0,0,0,.35)}
.trade-roster-rail__team{display:flex;align-items:center;gap:10px;min-width:0;background:none;border:0;padding:0;color:inherit;cursor:pointer;text-align:left}
.trade-roster-rail__name{display:flex;flex-direction:column;min-width:0}
.trade-roster-rail__name strong{font-family:var(--dd-font-display);font-weight:400;font-size:26px;line-height:1;letter-spacing:.03em;color:var(--dd-yellow);-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)}
.trade-roster-rail__name em{font-style:normal;font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.trade-roster-rail__team:hover strong{filter:brightness(1.1)}
.trade-roster-rail__expand{background:none;border:2px solid rgba(255,255,255,.2);border-radius:999px;padding:5px 12px;color:var(--ds-text,#fff);font-size:12px;font-weight:800;cursor:pointer;white-space:nowrap}
.trade-roster-rail__expand:hover{border-color:var(--dd-gold-hi);color:var(--dd-yellow)}
.trade-roster-rail__facts{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:4px 20px;margin:0}
.trade-roster-rail__facts > div{display:flex;align-items:baseline;gap:6px}
.trade-roster-rail__facts dt{font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.trade-roster-rail__facts dd{margin:0;font-size:15px;font-weight:900;color:var(--ds-text,#fff);font-variant-numeric:tabular-nums}
.trade-roster-rail__facts dd small{margin-left:5px;font-size:12px;font-weight:800}
.trade-roster-rail__facts .tone-ok dd,.trade-roster-rail__facts .tone-ok small{color:#8ff0b0}
.trade-roster-rail__facts .tone-warn dd small{color:#ffcf6b}
.trade-roster-rail__facts .tone-bad dd{color:#ff9b8a}
.trade-roster-rail .trade-asset-pool{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;background:none!important;border:0!important}
.trade-roster-rail .trade-pool-tabs{display:flex;gap:4px;padding:8px 10px!important;border:0!important;background:none!important}
.trade-roster-rail .trade-pool-tabs button{flex:0 0 auto;background:none!important;border:2px solid transparent!important;border-radius:999px!important;padding:4px 12px!important;font-size:12px!important;font-weight:800!important;letter-spacing:0!important;color:var(--ds-label,#9fb3d9)!important;box-shadow:none!important;text-transform:none!important}
.trade-roster-rail .trade-pool-tabs button.active{background:linear-gradient(180deg,var(--dd-yellow),var(--dd-yellow-deep))!important;color:var(--dd-outline)!important;border-color:var(--dd-outline)!important;box-shadow:0 3px 0 var(--dd-outline)!important}
.trade-roster-rail .trade-pool-list{flex:1 1 auto;min-height:0;overflow-y:auto;max-height:none!important;padding:0 4px 8px!important}

/* Deal table: the two packages, full height, every slot visible */
.th-deal-table{display:flex!important;flex-direction:column;gap:12px;min-height:0;padding:6px 2px 0!important;overflow:visible!important;background:none!important}
.th-deal-table .trade-construction-grid{flex:1 1 auto;min-height:0;display:grid!important;grid-template-columns:minmax(0,1fr) 34px minmax(0,1fr)!important;gap:0!important;align-items:stretch}
.th-deal-table .trade-package-col{display:flex!important;flex-direction:column;gap:8px;padding:12px!important;min-height:0;overflow-y:auto!important;max-height:none!important;height:auto!important}
.th-deal-table .trade-package-header{display:flex!important;align-items:center;gap:10px;padding:0 2px 6px!important;border:0!important;background:none!important;min-height:0!important}
.th-deal-table .trade-package-header-main{display:flex!important;flex-direction:row!important;align-items:baseline;justify-content:space-between;flex:1;gap:8px}
.th-deal-table .trade-package-header-main > span{font-size:24px!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important;letter-spacing:.03em}
.th-deal-table .trade-package-header-main > small{font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.th-deal-table .trade-slot{flex:1 1 0;min-height:64px!important;max-height:120px;height:auto!important;margin:0!important}
.th-deal-table .trade-slot-placeholder span{font-family:var(--dd-font-display);font-size:15px;letter-spacing:.05em;color:rgba(255,231,196,.75)}
.th-deal-table .trade-package-divider{display:flex!important;align-items:center;justify-content:center;background:none!important;border:0!important;width:auto!important}
.th-deal-table .trade-package-divider span{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;font-size:16px;font-weight:900;color:var(--dd-outline);
  background:linear-gradient(180deg,var(--dd-yellow),var(--dd-yellow-deep));border:3px solid var(--dd-outline);box-shadow:0 3px 0 var(--dd-outline)}

/* Deal bar: value balance + fans on the left, the one action on the right */
.th-deal-table .trade-hub-centre-foot{flex:0 0 auto;display:grid!important;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"analysis propose" "reason reason" "rumors rumors";align-items:center;gap:8px 18px;
  padding:12px 16px!important;background:rgba(6,14,36,.72)!important;border-radius:14px;border-top:3px solid var(--dd-gold)!important}
.th-deal-table .trade-analysis-panel{grid-area:analysis;padding:0!important;margin:0!important;min-width:0}
.th-deal-table .trade-hub-propose-wrap{grid-area:propose;margin:0!important;padding:0!important;display:flex;flex-direction:column;align-items:flex-end;gap:6px}
.th-deal-table .trade-hub-propose-btn{min-width:240px;padding:10px 26px!important}
.th-deal-table .trade-hub-block-reason{grid-area:reason;margin:0!important}
.th-deal-table .trade-rumor-groups{grid-area:rumors;margin:0!important}
.th-deal-table .trade-clear-value-body{display:grid!important;grid-template-columns:1fr 1fr;gap:16px}
.th-deal-table .trade-clear-side-label{display:flex;justify-content:space-between;font-size:12px;font-weight:800}
.th-deal-table .trade-analysis-rink-head{display:flex!important;justify-content:flex-end;margin:0!important;padding:0!important;background:none!important;border:0!important}
.th-deal-table .trade-analysis-review-btn{background:none!important;border:2px solid var(--ds-active,#2ee6d6)!important;border-radius:999px!important;color:var(--ds-active,#2ee6d6)!important;font-weight:800!important;padding:4px 14px!important}

/* Big monitors: let the room breathe */
@media (min-width:1800px){
  .nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:minmax(340px,1fr) minmax(760px,1.7fr) minmax(340px,1fr)!important;gap:18px 24px!important;padding:14px 28px 18px!important;max-width:2600px;margin:0 auto;width:100%}
  .th-deal-table .trade-slot{min-height:80px!important;max-height:140px}
  .th-deal-table .trade-package-header-main > span{font-size:30px!important}
}
/* Small laptops: deal table on top, both rosters side by side underneath */
@media (max-width:1280px){
  .nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:1fr 1fr!important;grid-template-rows:auto auto minmax(380px,1fr)!important;
    grid-template-areas:"read read" "deal deal" "lrail rrail"!important;overflow-y:auto!important}
  .th-deal-table .trade-slot{flex:0 0 auto;min-height:58px!important}
