@media (max-width:820px){
  .nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:1fr!important;grid-template-areas:"read" "deal" "lrail" "rrail"!important;grid-template-rows:auto!important}
  .nhlcal-root.trade-hub-root .trade-roster-rail{height:440px}
  .th-deal-table .trade-construction-grid{grid-template-columns:1fr!important}
  .th-deal-table .trade-package-divider span{transform:rotate(90deg)}
  .th-deal-table .trade-hub-centre-foot{grid-template-columns:1fr;grid-template-areas:"analysis" "propose" "reason" "rumors"}
}

/* Roster rails: one compact row — photo · name/details/value · OVR */
.trade-roster-rail .trade-pool-row{display:grid!important;grid-template-columns:40px minmax(0,1fr) 40px!important;grid-template-rows:auto!important;align-items:center;gap:0 10px!important;
  min-height:58px!important;padding:6px 8px!important;position:relative;cursor:pointer;border-radius:8px}
.trade-roster-rail .trade-pool-row > *{grid-row:1!important;min-width:0}
.trade-roster-rail .trade-player-list-photo{grid-column:1!important;width:40px!important;height:40px!important;overflow:hidden}
.trade-roster-rail .trade-player-list-photo .player-headshot{--size:40px!important;width:40px!important;height:40px!important}
.trade-roster-rail .trade-player-list-main{grid-column:2!important;display:flex!important;flex-direction:column;gap:3px;min-width:0}
.trade-roster-rail .trade-player-list-name-row{display:flex!important;align-items:center;gap:6px;min-width:0}
.trade-roster-rail .trade-player-list-name-row strong{font-size:14px!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.trade-roster-rail .trade-player-list-mid{display:flex!important;flex-direction:column;gap:3px;min-width:0}
.trade-roster-rail .trade-player-list-details{display:flex!important;gap:8px;font-size:11px!important;font-weight:800;color:var(--ds-label,#9fb3d9)}
.trade-roster-rail .trade-player-list-details > *{background:none!important;border:0!important;padding:0!important;min-width:0!important;font-size:11px!important}
.trade-roster-rail .trade-player-value-focus{display:flex!important;align-items:center;gap:6px;min-width:0}
.trade-roster-rail .trade-player-value-head{flex:0 0 auto}
.trade-roster-rail .trade-player-value-head > *{font-size:11px!important}
.trade-roster-rail .trade-player-value-track{flex:1 1 auto;height:5px!important}
.trade-roster-rail .trade-pool-season-line,.trade-roster-rail .trade-icehole-buzz,.trade-roster-rail .trade-player-ovr-tower small{display:none!important}
.trade-roster-rail .trade-player-ovr-tower{grid-column:3!important;text-align:right}
.trade-roster-rail .trade-player-ovr-tower strong{font-size:22px!important}
.trade-roster-rail .trade-pool-status-pill{position:absolute;right:52px;top:6px;font-size:10px!important;padding:1px 6px!important}
.trade-roster-rail .trade-pool-row.used{opacity:.45}
.trade-roster-rail .trade-pick-origin-line{display:none!important}
.th-deal-table .trade-slot.empty{display:block!important}
.th-deal-table .trade-slot.empty .trade-slot-placeholder{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center}
.th-deal-table .trade-slot.empty + .trade-slot.empty .trade-slot-placeholder > *{opacity:.55}
.trade-roster-rail__expand{grid-row:1;grid-column:2}
.trade-roster-rail .trade-flag-badge{display:none!important}
.trade-roster-rail .trade-player-value-focus{flex-wrap:nowrap!important}
.trade-roster-rail .trade-player-value-track{order:-1;min-width:0}
.th-deal-table .trade-package-header-main > span{font-size:clamp(18px,1.5vw,30px)!important;white-space:nowrap}
.th-deal-table .trade-package-header-main > small{white-space:nowrap}
.trade-roster-rail .trade-player-value-focus{display:grid!important;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px}
.trade-roster-rail .trade-player-value-track{order:0;grid-column:1;grid-row:1}
.trade-roster-rail .trade-player-value-head{grid-column:2;grid-row:1}
@media (max-height:860px){
  .th-deal-table .trade-slot{min-height:50px!important}
  .th-deal-table .trade-package-col{gap:6px;padding:10px!important}
  .th-read.th-read--strip{padding:6px 14px!important}
}

/* Deal table gets the width; rails stay readable */
.nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:minmax(270px,.85fr) minmax(600px,1.8fr) minmax(270px,.85fr)!important}
@media (min-width:1800px){.nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:minmax(340px,1fr) minmax(820px,2fr) minmax(340px,1fr)!important}}
