/* Filled slot: one DD item card — face + OVR token · name/meta · money */
.th-deal-table .trade-slot.filled{display:flex!important;align-items:stretch;padding:0!important;border:0!important;background:none!important;box-shadow:none!important}
.th-deal-table .trade-slot-index{flex:0 0 auto;align-self:center;width:18px;font-size:11px;font-weight:900;color:var(--ds-label,#9fb3d9);text-align:center;position:static!important}
.th-deal-table .trade-asset-card{flex:1 1 auto;min-width:0;display:grid!important;grid-template-columns:52px minmax(0,1fr) auto!important;grid-template-rows:auto!important;align-items:center;gap:0 12px!important;
  padding:8px 34px 8px 10px!important;position:relative;border-radius:12px!important;background:linear-gradient(180deg,#2a4fae,#173579)!important;
  border:3px solid var(--dd-outline)!important;box-shadow:0 3px 0 var(--dd-outline),inset 0 2px 0 rgba(255,255,255,.12)!important;min-height:0!important;height:100%}
.th-deal-table .trade-asset-card > *{grid-row:1!important;min-width:0}
.th-deal-table .trade-asset-card .trade-asset-headshot{grid-column:1!important;--size:48px;width:48px!important;height:48px!important}
.th-deal-table .trade-asset-ovr-focus{grid-column:1!important;align-self:end;justify-self:end;position:relative;z-index:1;display:grid;place-items:center;width:28px;height:28px;margin:0 -8px -6px 0;border-radius:50%;
  background:radial-gradient(circle at 35% 30%,#3a64c8,#16306f);border:2px solid var(--dd-gold);box-shadow:0 0 0 2px var(--dd-outline)}
.th-deal-table .trade-asset-ovr-label{display:none!important}
.th-deal-table .trade-asset-ovr-number{font-family:var(--dd-font-display)!important;font-weight:400!important;font-size:13px!important;color:var(--dd-yellow)!important;-webkit-text-stroke:.8px var(--dd-outline);paint-order:stroke fill;line-height:1}
.th-deal-table .trade-asset-card-body{grid-column:2!important;display:flex!important;flex-direction:column;gap:2px;min-width:0}
.th-deal-table .trade-asset-card-name{display:flex!important;align-items:center;gap:6px;min-width:0;font-size:15px!important;font-weight:900!important}
.th-deal-table .trade-asset-card-name > span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.th-deal-table .trade-asset-card-name .trade-flag-badge{display:none!important}
.th-deal-table .trade-asset-franchise-mark{font-style:normal;color:var(--dd-yellow)}
.th-deal-table .trade-asset-card-meta{display:flex!important;gap:8px;align-items:center;font-size:12px!important;font-weight:800;color:var(--ds-label,#9fb3d9)}
.th-deal-table .trade-asset-card-meta > *{background:none!important;border:0!important;padding:0!important;min-width:0!important;font-size:12px!important}
.th-deal-table .trade-asset-pot-big{font-size:12px!important;font-weight:800!important;color:var(--ds-label,#9fb3d9)!important}
.th-deal-table .trade-asset-protected-warn{order:3;font-size:11px!important;font-weight:800;color:#ffb3a5!important;background:none!important;border:0!important;padding:0!important}
.th-deal-table .trade-asset-card-right{grid-column:3!important;display:flex!important;flex-direction:column;align-items:flex-end;gap:2px}
.th-deal-table .trade-asset-aav-badge{display:flex!important;align-items:baseline;gap:4px;background:none!important;border:0!important;padding:0!important}
.th-deal-table .trade-asset-aav-value{font-size:17px!important;font-weight:900!important;color:#fff!important}
.th-deal-table .trade-asset-aav-label{font-size:10px!important;color:var(--ds-label,#9fb3d9)!important}
.th-deal-table .trade-asset-cap-impact{font-size:10px!important;font-weight:800;background:none!important;border:0!important;padding:0!important;white-space:nowrap}
.th-deal-table .trade-asset-card-remove{position:absolute!important;top:50%;right:6px;transform:translateY(-50%);width:22px;height:22px;border-radius:50%;display:grid;place-items:center;padding:0!important;
  background:var(--dd-outline)!important;color:#fff!important;border:2px solid rgba(255,255,255,.35)!important;font-size:14px!important;line-height:1;cursor:pointer}
.th-deal-table .trade-asset-card-remove:hover{background:var(--dd-lacquer)!important;border-color:var(--dd-gold-hi)!important}
.th-deal-table .trade-asset-card{height:auto!important;gap:0 10px!important;grid-template-columns:48px minmax(0,1fr) auto!important}
.th-deal-table .trade-asset-card-body{flex-direction:row!important;flex-wrap:wrap;align-items:baseline;column-gap:8px;row-gap:2px}
.th-deal-table .trade-asset-card-name{flex:1 0 100%;font-size:14px!important}
.th-deal-table .trade-asset-protected-warn{flex:1 0 100%}
.th-deal-table .trade-asset-cap-impact{display:none!important}
.th-deal-table .trade-asset-aav-value{font-size:15px!important}
.th-deal-table .trade-asset-card-right .trade-asset-aav-label{display:none!important}
.th-deal-table .trade-asset-card-meta-tiny > *:not(:first-child)::before{content:"· ";color:rgba(159,179,217,.55)}
.th-deal-table .trade-slot{max-height:none!important}
.th-deal-table .trade-slot.filled{min-height:0!important;flex:0 0 auto}
.th-deal-table .trade-asset-card [class*=clause],.th-deal-table .trade-asset-card [class*=ntc]{font-size:10px!important}
.nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:minmax(240px,.7fr) minmax(600px,2fr) minmax(240px,.7fr)!important}
@media (min-width:1800px){.nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:minmax(340px,.85fr) minmax(820px,2fr) minmax(340px,.85fr)!important}}
@media (max-width:1280px){.nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:1fr 1fr!important}}
@media (max-width:820px){.nhlcal-root.trade-hub-root .trade-hub-main.th-deal-layout{grid-template-columns:1fr!important}}
.th-deal-table .trade-asset-card{padding:8px 12px 8px 10px!important}
.th-deal-table .trade-asset-card-remove{top:-8px!important;right:-8px!important;transform:none!important;z-index:2}
.th-deal-table .trade-package-col{padding:12px 14px 12px 8px!important}
.th-deal-table .trade-asset-card-meta{flex-wrap:nowrap;white-space:nowrap}
.trade-roster-rail .trade-pool-row:has(.trade-pool-status-pill) .trade-player-list-name-row{padding-right:64px}
.trade-roster-rail .trade-pool-status-pill{right:50px!important;top:7px!important;background:rgba(5,12,44,.85)!important;border:1px solid rgba(255,255,255,.2)!important;border-radius:999px!important}
@media (max-width:1280px){
  .th-deal-table{overflow:visible!important;min-height:auto!important}
  .th-deal-table .trade-construction-grid{flex:0 0 auto!important;min-height:auto!important}
  .th-deal-table .trade-package-col{overflow:visible!important;min-height:auto!important}
  .th-deal-table .trade-slot.empty{min-height:46px!important;flex:0 0 auto!important}
  .nhlcal-root.trade-hub-root .trade-roster-rail{height:460px;min-height:0}
