/* ==========================================================================
   SECTION: Contracts overhaul
   [ ← logo Contracts         [ $4.48M cap space ▬▬▬▬▬▬ hit · ceiling ]  slots ]
   [ Contracts · RFAs & offer sheets · Cap breakdown        Free agency wire → ]
   [ filters (with counts) .......... search ][                              ]
   [ sortable table, plain rows ............. ][  selected contract panel    ]
   One hero number (cap space), money to two decimals everywhere, table rows
   with no boxed cells, the panel beside the list instead of under it.
   ========================================================================== */
.cl-screen{--cl-gap:clamp(12px,1.2vw,22px);display:flex!important;flex-direction:column;gap:var(--cl-gap);height:100vh;min-height:0;overflow:hidden;
  padding:clamp(12px,1.4vw,28px) clamp(14px,2vw,40px)!important;box-sizing:border-box}
.cl-screen > *{flex-shrink:0}
.cl-screen,.cl-screen *{text-transform:none!important}

/* Header band */
.cl-top{display:grid;grid-template-columns:auto minmax(320px,1fr) auto;align-items:center;gap:var(--cl-gap) clamp(20px,3vw,56px)}
.cl-top__team{display:flex;align-items:center;gap:14px;min-width:0}
.cl-back{width:40px;height:40px;border-radius:50%;border:2px solid rgba(255,255,255,.22);background:none;color:var(--ds-text,#fff);font-size:18px;cursor:pointer}
.cl-back:hover{border-color:var(--dd-gold-hi);color:var(--dd-yellow)}
.cl-top__logo{width:clamp(48px,4vw,72px);height:clamp(48px,4vw,72px);object-fit:contain;filter:drop-shadow(0 3px 0 var(--dd-outline))}
.cl-top__logo--text{display:grid;place-items:center;font-weight:900;border-radius:12px;background:#16306f}
.cl-top h1{margin:0;font-family:var(--dd-font-display);font-weight:400;font-size:clamp(26px,2.4vw,44px);line-height:1;letter-spacing:.03em;color:var(--dd-yellow);-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)}
.cl-top__team p{margin:4px 0 0;color:var(--ds-label,#9fb3d9);font-weight:800;font-size:14px}
.cl-meter{display:grid;grid-template-columns:auto 1fr;grid-template-rows:auto auto;column-gap:18px;align-items:center;max-width:720px;width:100%;justify-self:center}
.cl-meter__space{grid-row:1/3;display:flex;flex-direction:column}
.cl-meter__space strong{font-size:clamp(28px,2.6vw,48px);font-weight:900;line-height:1;color:#8ff0b0;font-variant-numeric:tabular-nums}
.cl-meter__space span{font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.cl-meter.is-tight .cl-meter__space strong{color:#ffcf6b}
.cl-meter.is-over .cl-meter__space strong{color:#ff9b8a}
.cl-meter__bar{height:16px;border-radius:999px;border:3px solid var(--dd-outline);background:#0a0f2a;overflow:hidden;box-shadow:0 2px 0 var(--dd-outline)}
.cl-meter__bar i{display:block;height:100%;border-radius:999px;background:linear-gradient(180deg,var(--dd-yellow),var(--dd-yellow-deep))}
.cl-meter.is-tight .cl-meter__bar i{background:linear-gradient(180deg,#ffb347,#e07a10)}
.cl-meter.is-over .cl-meter__bar i{background:linear-gradient(180deg,var(--dd-lacquer-hi),var(--dd-lacquer))}
.cl-meter__scale{display:flex;justify-content:space-between;font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9);margin-top:4px}
.cl-meter__scale b{color:var(--ds-text,#fff);font-variant-numeric:tabular-nums}
.cl-top__slots{display:grid;grid-template-columns:repeat(2,auto);gap:2px 18px;margin:0}
.cl-top__slots > div{display:flex;justify-content:space-between;gap:10px;align-items:baseline}
.cl-top__slots dt{font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.cl-top__slots dd{margin:0;font-size:15px;font-weight:900;color:var(--ds-text,#fff);font-variant-numeric:tabular-nums}

/* Banners: one line, dismissable */
.cl-banner{display:flex;align-items:center;gap:12px;margin:0;padding:8px 14px;border-radius:10px;font-weight:800;font-size:14px;background:rgba(6,14,36,.7);border-left:4px solid var(--ds-active,#2ee6d6)}
.cl-banner.is-error{border-left-color:#ff6b5b;color:#ffc2b6}
.cl-banner.is-promise{border-left-color:var(--dd-yellow)}
.cl-banner button{margin-left:auto;background:none;border:0;color:inherit;font-size:16px;font-weight:900;cursor:pointer}

/* Tabs: DD tabs sitting on the frame, free agency an honest link */
.cl-tabs{display:flex;align-items:flex-end;gap:6px;margin-bottom:calc(var(--cl-gap) * -1 - 3px);position:relative;z-index:1;padding-left:14px}
.cl-tabs > button:not(.cl-tabs__link){font-family:var(--dd-font-display);font-size:16px;letter-spacing:.04em;padding:9px 18px 7px;border-radius:10px 10px 0 0;border:3px solid var(--dd-outline);border-bottom:0;cursor:pointer;
  background:linear-gradient(180deg,#24479e,#16306f);color:rgba(255,231,196,.65);text-shadow:0 2px 0 var(--dd-outline)}
.cl-tabs > button:not(.cl-tabs__link):hover{color:var(--dd-cream)}
.cl-tabs > button.is-active{background:linear-gradient(180deg,var(--dd-gold-hi),var(--dd-gold));color:var(--dd-yellow);-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)}
.cl-tabs__link{margin-left:auto;align-self:center;background:none;border:0;color:var(--ds-active,#2ee6d6);font-weight:800;font-size:14px;cursor:pointer;padding:6px 4px}
.cl-tabs__link:hover{text-decoration:underline;text-underline-offset:3px}

/* Main: list + panel side by side, filling the screen */
.cl-main{flex:1 1 auto!important;min-height:0;display:flex;flex-direction:column}
.cl-split{flex:1 1 auto;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) clamp(320px,28vw,460px);gap:var(--cl-gap)}
.cl-split.is-negotiating{grid-template-columns:minmax(0,.9fr) minmax(460px,1.1fr)}
.cl-board{display:flex;flex-direction:column;min-height:0;overflow:hidden;background:var(--dd-box-fill);border:3px solid var(--dd-outline);border-radius:14px;
  box-shadow:0 0 0 3px var(--dd-box-rim),0 0 0 6px var(--dd-outline),0 10px 22px rgba(0,0,0,.4);margin:6px}
.cl-board__toolbar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px 16px;padding:12px 14px;border-bottom:2px solid rgba(0,0,0,.35)}
.cl-filters{display:flex;flex-wrap:wrap;gap:4px}
.cl-filter{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;border-radius:999px;border:2px solid transparent;background:none;color:var(--ds-label,#9fb3d9);font-weight:800;font-size:13px;cursor:pointer}
.cl-filter span{font-size:11px;opacity:.8;font-variant-numeric:tabular-nums}
.cl-filter:hover:not(:disabled){color:var(--ds-text,#fff);border-color:rgba(255,255,255,.18)}
.cl-filter:disabled{opacity:.35;cursor:default}
.cl-filter.is-active{background:linear-gradient(180deg,var(--dd-yellow),var(--dd-yellow-deep));color:var(--dd-outline);border-color:var(--dd-outline);box-shadow:0 3px 0 var(--dd-outline)}
.cl-search{flex:0 1 240px;min-width:160px;padding:8px 14px;border-radius:999px;border:2px solid rgba(255,255,255,.18);background:rgba(5,12,44,.6);color:var(--ds-text,#fff);font-weight:700;font-size:14px}
.cl-search:focus{outline:none;border-color:var(--ds-active,#2ee6d6)}

/* Table: one grid shared by header and rows */
.cl-head,.cl-row{display:grid;grid-template-columns:minmax(200px,2.2fr) 56px minmax(84px,.8fr) minmax(130px,1.1fr) minmax(150px,1.4fr);align-items:center;gap:12px;padding:0 16px}
.cl-head{padding-top:8px;padding-bottom:8px;border-bottom:1px solid rgba(255,255,255,.08);background:rgba(5,12,44,.35)}
.cl-head__col{background:none;border:0;padding:0;text-align:left;font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9);cursor:pointer;font-family:inherit}
.cl-head__col.cl-head__status{cursor:default}
.cl-head__ovr,.cl-head__aav{text-align:right}
.cl-head__col.is-sorted{color:var(--dd-yellow)}
.cl-head__col.is-sorted::after{content:" ▾"}
.cl-board__list{flex:1 1 auto;min-height:0;overflow-y:auto}
.cl-row{width:100%;min-height:56px;padding-top:6px;padding-bottom:6px;background:none;border:0;border-bottom:1px solid rgba(255,255,255,.06);color:inherit;text-align:left;cursor:pointer;font-family:inherit}
.cl-row:hover{background:rgba(46,230,214,.07)}
.cl-row.is-selected{background:rgba(255,226,58,.1);box-shadow:inset 4px 0 0 var(--dd-yellow)}
.cl-row__who{display:flex;align-items:center;gap:12px;min-width:0}
.cl-row__face{flex:0 0 auto}
.cl-row__name{display:flex;flex-direction:column;min-width:0}
.cl-row__name strong{font-size:15px;font-weight:900;color:var(--ds-text,#fff);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cl-row__name em{font-style:normal;font-size:12px;font-weight:700;color:var(--ds-label,#9fb3d9)}
.cl-row__ovr{text-align:right;font-size:20px;font-weight:900;font-variant-numeric:tabular-nums;color:var(--ds-text,#fff)}
.cl-row__ovr.tone-gold{color:var(--dd-yellow)}
.cl-row__ovr.tone-muted{color:var(--ds-label,#9fb3d9)}
.cl-row__aav{text-align:right;font-size:17px;font-weight:900;font-variant-numeric:tabular-nums;color:var(--ds-text,#fff)}
.cl-row__term{display:flex;flex-direction:column;min-width:0}
.cl-row__term b{font-size:14px;font-weight:800;color:var(--ds-text,#fff);white-space:nowrap}
.cl-row__term small{font-size:11px;font-weight:800;color:#ffcf6b}
.cl-row.is-expiring .cl-row__term b{color:#ffcf6b}
.cl-row__status{display:flex;flex-wrap:wrap;gap:4px}

/* Tags: outline pills, colour = meaning */
.cl-tag{display:inline-flex;align-items:center;padding:2px 9px;border-radius:999px;border:2px solid rgba(255,255,255,.2);font-size:11px;font-weight:900;color:var(--ds-text,#fff);white-space:nowrap}
.cl-tag.is-ufa{border-color:#ff9b8a;color:#ffc2b6}
.cl-tag.is-rfa{border-color:#ffcf6b;color:#ffe2a3}
.cl-tag.is-elc{border-color:#8fd3ff;color:#c4e8ff}
.cl-tag.is-ntc{border-color:#c9a7ff;color:#e2d1ff}
.cl-tag.is-bargain,.cl-tag.is-core{border-color:#8ff0b0;color:#bff7d3}
.cl-tag.is-bad{border-color:#ff6b5b;color:#ffb3a5}

/* Panel */
.cl-panel{position:relative;display:flex;flex-direction:column;gap:16px;min-height:0;overflow-y:auto;padding:18px;border-radius:14px;margin:6px;
  background:linear-gradient(180deg,rgba(26,52,120,.9),rgba(12,28,72,.92));border:3px solid var(--dd-outline);box-shadow:0 0 0 3px var(--dd-gold),0 0 0 6px var(--dd-outline),0 10px 22px rgba(0,0,0,.4)}
.cl-panel--empty{justify-content:center}
.cl-panel--empty h3{margin:0;font-family:var(--dd-font-display);font-weight:400;font-size:24px;color:var(--dd-yellow);-webkit-text-stroke:1.2px var(--dd-outline);paint-order:stroke fill;text-shadow:0 2px 0 var(--dd-outline)}
.cl-panel--empty > p{margin:0;color:var(--ds-label,#9fb3d9);font-weight:700}
.cl-panel__close{position:absolute;top:10px;right:10px;width:30px;height:30px;border-radius:50%;border:2px solid rgba(255,255,255,.22);background:rgba(5,12,44,.6);color:#fff;font-size:16px;cursor:pointer}
.cl-panel__close:hover{border-color:var(--dd-gold-hi)}
.cl-panel__who{display:flex;align-items:center;gap:14px;padding-right:34px}
.cl-panel__who h3{margin:0;font-size:22px;font-weight:900;color:#fff;line-height:1.1}
.cl-panel__who p{margin:3px 0 0;font-size:13px;font-weight:700;color:var(--ds-label,#9fb3d9)}
.cl-panel__ratings{display:flex;gap:14px}
.cl-panel__ratings span{font-size:20px;font-weight:900;color:#fff}
.cl-panel__ratings .tone-gold{color:var(--dd-yellow)}
.cl-panel__ratings small{font-size:11px;color:var(--ds-label,#9fb3d9)}
.cl-panel__deal{display:flex;align-items:baseline;justify-content:space-between;gap:10px;padding:12px 14px;border-radius:12px;background:rgba(5,12,44,.55)}
.cl-panel__deal strong{font-size:30px;font-weight:900;color:#fff;font-variant-numeric:tabular-nums}
.cl-panel__deal span{font-weight:800;color:var(--ds-label,#9fb3d9)}
.cl-facts{display:grid;gap:6px;margin:0}
.cl-facts > div{display:flex;justify-content:space-between;gap:12px;padding-bottom:6px;border-bottom:1px solid rgba(255,255,255,.06)}
.cl-facts dt{font-size:13px;font-weight:700;color:var(--ds-label,#9fb3d9)}
.cl-facts dd{margin:0;font-size:14px;font-weight:900;color:var(--ds-text,#fff);text-align:right}
.cl-panel__tags{display:flex;flex-wrap:wrap;gap:6px}
.cl-panel__actions{display:flex;flex-wrap:wrap;gap:8px}
.cl-panel__note{margin:0;color:var(--ds-label,#9fb3d9);font-size:13px;font-weight:700}

/* Buttons: one lacquer primary, outline secondaries, red-edged danger */
.cl-btn{padding:8px 16px;border-radius:999px;border:2px solid rgba(255,255,255,.25);background:rgba(5,12,44,.5);color:#fff;font-weight:800;font-size:14px;cursor:pointer;font-family:inherit}
.cl-btn:hover:not(:disabled){border-color:var(--dd-gold-hi);color:var(--dd-yellow)}
.cl-btn:disabled{opacity:.45;cursor:not-allowed}
.cl-btn--primary{font-family:var(--dd-font-display);font-weight:400;font-size:17px;letter-spacing:.04em;color:var(--dd-cream);padding:10px 22px 8px;border-radius:8px;border:3px solid;border-color:var(--dd-gold-hi) var(--dd-gold) var(--dd-gold-lo) var(--dd-gold);
  background:linear-gradient(180deg,var(--dd-lacquer-hi),var(--dd-lacquer) 55%,var(--dd-lacquer-lo));text-shadow:0 2px 0 var(--dd-lacquer-lo);box-shadow:0 0 0 2px var(--dd-gold-lo),0 4px 0 var(--dd-outline)}
.cl-btn--primary:hover:not(:disabled){filter:brightness(1.1);color:var(--dd-cream)}
.cl-btn--primary:active:not(:disabled){transform:translateY(2px)}
.cl-panel__actions .cl-btn--primary{flex:1 1 100%}
.cl-btn--danger{border-color:rgba(255,107,91,.6);color:#ffc2b6}
.cl-btn--danger:hover:not(:disabled){border-color:#ff6b5b;color:#fff;background:rgba(168,48,15,.45)}
.cl-screen button:focus-visible,.cl-screen input:focus-visible{outline:3px solid var(--dd-yellow);outline-offset:2px}

/* Assignment moves */
.cl-moves{display:flex;flex-direction:column;gap:8px;padding-top:12px;border-top:2px solid rgba(0,0,0,.3)}
.cl-moves h4{margin:0;font-size:14px;font-weight:900;color:#fff}
.cl-moves__meta{margin:0;font-size:12px;font-weight:700;color:var(--ds-label,#9fb3d9)}
.cl-moves__note{margin:0;color:#8ff0b0;font-weight:800;font-size:13px}
.cl-moves__error{margin:0;color:#ffb3a5;font-weight:800;font-size:13px}

/* Negotiation dock keeps its own component; just frame it */
.cl-nego{min-height:0;overflow-y:auto;border-radius:14px;margin:6px}

/* Cap breakdown */
.cl-cap{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:var(--cl-gap);align-content:start;overflow-y:auto}
.cl-cap__group{padding:16px 18px;border-radius:14px;background:rgba(6,14,36,.6);border-top:3px solid var(--dd-gold)}
.cl-cap__group h3{margin:0 0 10px;font-size:16px;font-weight:900;color:var(--dd-yellow)}

/* RFA tab */
.cl-rfa{overflow-y:auto}
.cl-rfa__group{display:flex;flex-direction:column;padding:12px 0 6px}
.cl-rfa__group + .cl-rfa__group{border-top:2px solid rgba(0,0,0,.35)}
.cl-rfa__group h3{margin:0 16px 8px;font-size:16px;font-weight:900;color:#fff;display:flex;gap:8px;align-items:baseline}
.cl-rfa__group h3 span{font-size:12px;color:var(--ds-label,#9fb3d9)}
.cl-rfa__group.is-urgent h3{color:var(--dd-yellow)}
.cl-rfa__head,.cl-rfa__row{display:grid;grid-template-columns:minmax(180px,2fr) 56px minmax(110px,1fr) minmax(120px,1.2fr);gap:12px;align-items:center;padding:0 16px}
.cl-rfa__head{font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9);padding-bottom:6px}
.cl-rfa__row{min-height:48px;width:100%;background:none;border:0;border-top:1px solid rgba(255,255,255,.06);color:var(--ds-text,#fff);text-align:left;font-weight:800;font-size:14px;cursor:pointer;font-family:inherit}
.cl-rfa__row:hover{background:rgba(46,230,214,.07)}
.cl-rfa__row.is-selected{background:rgba(255,226,58,.1);box-shadow:inset 4px 0 0 var(--dd-yellow)}
.cl-rfa__name{display:flex;flex-direction:column}
.cl-rfa__name em{font-style:normal;font-size:12px;color:var(--ds-label,#9fb3d9)}
.cl-rfa__sheet{display:flex;flex-wrap:wrap;align-items:center;gap:8px 14px;padding:8px 16px;border-top:1px solid rgba(255,255,255,.06);font-weight:800}
.cl-rfa__form{display:flex;flex-wrap:wrap;align-items:flex-end;gap:12px;padding:14px 16px;border-top:2px solid rgba(0,0,0,.35)}
.cl-rfa__form h3{flex:1 0 100%;margin:0;font-size:16px;font-weight:900;color:var(--dd-yellow)}
.cl-rfa__form label{display:flex;flex-direction:column;gap:4px;font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.cl-rfa__form input{width:120px;padding:8px 10px;border-radius:8px;border:2px solid rgba(255,255,255,.2);background:rgba(5,12,44,.6);color:#fff;font-weight:800;font-size:15px}
.cl-empty{margin:0;padding:24px 16px;color:var(--ds-label,#9fb3d9);font-weight:700}

/* Big monitors: wider panel, roomier rows */
@media (min-width:1800px){
  .cl-row{min-height:64px}
  .cl-row__name strong{font-size:17px}
  .cl-row__aav{font-size:19px}
}
/* Laptops: tighter header, slots collapse into the meter line */
@media (max-width:1280px){
  .cl-top{grid-template-columns:auto 1fr}
  .cl-top__slots{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:4px 20px}
  .cl-split{grid-template-columns:minmax(0,1fr) 320px}
  .cl-split.is-negotiating{grid-template-columns:1fr}
  .cl-head,.cl-row{grid-template-columns:minmax(170px,2fr) 44px 84px minmax(110px,1fr) minmax(110px,1fr);gap:10px;padding-left:12px;padding-right:12px}
}
/* Narrow: stack — list then panel, page scrolls */
@media (max-width:980px){
  .cl-screen{height:auto;min-height:100vh;overflow:visible}
  .cl-top{grid-template-columns:1fr}
  .cl-meter{justify-self:stretch}
  .cl-split{grid-template-columns:1fr}
  .cl-board{max-height:70vh}
  .cl-head__status,.cl-row__status{display:none}
  .cl-head,.cl-row{grid-template-columns:minmax(150px,2fr) 40px 80px minmax(100px,1fr)}
  .cl-tabs{overflow-x:auto;padding-left:0}
}
.cl-panel--empty{justify-content:flex-start!important}
.cl-row__face.player-headshot{--size:40px;width:40px!important;height:40px!important}
@media (min-width:1281px){.cl-head,.cl-row{grid-template-columns:minmax(220px,1.3fr) 64px 110px minmax(170px,.9fr) minmax(180px,1.4fr)}}

/* ==========================================================================
   SECTION: League Operations — consistent placement
   Same skeleton as Contracts / Trade Desk: ← back top-left, DD title, your
   numbers top-right, DD tabs, one hero number, supporting facts on one line,
   the main visual beside the decisions list.
   ========================================================================== */
.lo-screen{padding:clamp(12px,1.4vw,28px) clamp(14px,2vw,40px)!important}
.lo-screen,.lo-screen *{text-transform:none!important}
.lo-header{display:flex!important;align-items:center!important;justify-content:space-between;gap:16px 32px;flex-wrap:wrap}
.lo-header-left{display:flex!important;align-items:center;gap:14px}
.lo-header h1{font-family:var(--dd-font-display)!important;font-weight:400!important;font-size:clamp(26px,2.4vw,44px)!important;line-height:1!important;letter-spacing:.03em!important;color:var(--dd-yellow)!important;
  -webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important;margin:0!important}
.lo-header-meta{margin-top:4px;font-weight:800;font-size:14px}
.lo-back{order:-1;width:40px!important;height:40px!important;min-width:0!important;padding:0!important;border-radius:50%!important;border:2px solid rgba(255,255,255,.22)!important;background:none!important;box-shadow:none!important;
  color:var(--ds-text,#fff)!important;font-size:18px!important;display:grid!important;place-items:center}
.lo-back:hover{border-color:var(--dd-gold-hi)!important;color:var(--dd-yellow)!important}
.lo-tabs{display:flex!important;gap:6px!important;border:0!important;background:none!important;padding:0 0 0 14px!important;margin-bottom:-3px;position:relative;z-index:1}
.lo-tabs button{font-family:var(--dd-font-display)!important;font-weight:400!important;font-size:16px!important;letter-spacing:.04em!important;padding:9px 18px 7px!important;border-radius:10px 10px 0 0!important;
  border:3px solid var(--dd-outline)!important;border-bottom:0!important;background:linear-gradient(180deg,#24479e,#16306f)!important;color:rgba(255,231,196,.65)!important;text-shadow:0 2px 0 var(--dd-outline)!important;box-shadow:none!important}
.lo-tabs button:hover{color:var(--dd-cream)!important}
.lo-tabs button.active{background:linear-gradient(180deg,var(--dd-gold-hi),var(--dd-gold))!important;color:var(--dd-yellow)!important;-webkit-text-stroke:1.5px var(--dd-outline);paint-order:stroke fill;text-shadow:0 3px 0 var(--dd-outline)!important}
.lo-workspace{border-radius:14px;border:3px solid var(--dd-outline);box-shadow:0 0 0 3px var(--dd-box-rim),0 0 0 6px var(--dd-outline),0 10px 22px rgba(0,0,0,.4);background:var(--dd-box-fill)!important;margin:0 6px 6px;padding:clamp(14px,1.4vw,24px)!important}

/* Overview */
.lo-ov{display:flex!important;flex-direction:column;gap:clamp(14px,1.4vw,24px)!important}
.lo-hero{display:flex;flex-wrap:wrap;align-items:flex-end;gap:16px clamp(24px,4vw,72px);padding-bottom:clamp(12px,1.2vw,20px);border-bottom:2px solid rgba(0,0,0,.35)}
.lo-hero__main{display:flex;flex-direction:column;gap:2px}
.lo-hero__label{font-size:13px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.lo-hero__main strong{font-size:clamp(40px,4.2vw,76px);font-weight:900;line-height:1;color:#fff;font-variant-numeric:tabular-nums;text-shadow:0 3px 0 var(--dd-outline)}
.lo-hero__delta{font-size:15px;font-weight:900}
.lo-hero__delta.pos{color:#8ff0b0}
.lo-hero__delta.neg{color:#ff9b8a}
.lo-hero__facts{display:flex;flex-wrap:wrap;gap:10px clamp(20px,2.4vw,44px);margin:0;padding-bottom:6px}
.lo-hero__facts > div{display:flex;flex-direction:column;gap:2px}
.lo-hero__facts dt{font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.lo-hero__facts dd{margin:0;font-size:clamp(16px,1.3vw,22px);font-weight:900;color:#fff;white-space:nowrap}
.lo-hero__facts dd b{font-weight:900;color:var(--dd-yellow)}
.lo-hero__facts dd b.pos{color:#8ff0b0}
.lo-ov-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(320px,1fr);gap:clamp(14px,1.6vw,28px);min-height:0;flex:1 1 auto}
.lo-ov-grid .lo-forecast,.lo-ov-grid .lo-priority{min-width:0;border:0!important;background:none!important;box-shadow:none!important;padding:0!important}
.lo-forecast-head h2,.lo-priority-title{font-size:18px!important;font-weight:900!important;color:#fff!important;letter-spacing:.01em!important;font-family:var(--dd-font-ui)!important}
.lo-ov-grid .lo-priority-list{grid-template-columns:1fr!important;gap:8px!important}
.lo-ov-grid .lo-priority-card{display:grid!important;grid-template-columns:1fr auto!important;grid-template-areas:"name state" "meta meta" "detail detail" "bal bal";gap:4px 10px!important;text-align:left;
  padding:12px 14px!important;border-radius:12px!important;border:2px solid rgba(255,255,255,.1)!important;background:rgba(6,14,36,.55)!important;cursor:pointer}
.lo-ov-grid .lo-priority-card:hover{border-color:var(--dd-gold-hi)!important}
.lo-ov-grid .lo-priority-card > strong{grid-area:name;font-size:15px;font-weight:900;color:#fff}
.lo-ov-grid .lo-priority-card > .state{grid-area:state;align-self:start}
.lo-ov-grid .lo-priority-meta{grid-area:meta;display:flex;gap:12px;font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.lo-ov-grid .lo-priority-card > p{grid-area:detail;margin:0;font-size:13px;color:var(--ds-text,#fff);opacity:.85}
.lo-ov-grid .lo-priority-balance{grid-area:bal}
.lo-pulse{display:none!important}

@media (max-width:1100px){
  .lo-ov-grid{grid-template-columns:1fr}
  .lo-header-right{width:100%}
}
@media (min-width:1800px){
  .lo-workspace{max-width:2400px}
}

/* ==========================================================================
   SECTION: Negotiation desk — two sides of one table
   [ ← face  Name · pos · OVR                         agent chip ]
   [ THEM: ask · conversation · why they'd stay ][ YOU: interest · offer · cap · act ]
   Money to two decimals (slider steps are $0.025M), one primary action.
   ========================================================================== */
.nd{display:flex;flex-direction:column;gap:14px;height:100%;min-height:0;padding:16px;border-radius:14px;
  background:var(--dd-box-fill);border:3px solid var(--dd-outline);box-shadow:0 0 0 3px var(--dd-gold),0 0 0 6px var(--dd-outline),0 10px 22px rgba(0,0,0,.4);overflow:hidden}
.nd-top{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding-bottom:12px;border-bottom:2px solid rgba(0,0,0,.35)}
.nd-back{width:36px;height:36px;border-radius:50%;border:2px solid rgba(255,255,255,.22);background:none;color:#fff;font-size:16px;cursor:pointer}
.nd-back:hover:not(:disabled){border-color:var(--dd-gold-hi);color:var(--dd-yellow)}
.nd-top__face.player-headshot{--size:52px;width:52px!important;height:52px!important}
.nd-top__who{min-width:0}
.nd-top__who h3{margin:0;font-family:var(--dd-font-display);font-weight:400;font-size:clamp(22px,1.8vw,30px);letter-spacing:.03em;line-height:1;color:var(--dd-yellow);-webkit-text-stroke:1.2px var(--dd-outline);paint-order:stroke fill;text-shadow:0 2px 0 var(--dd-outline)}
.nd-top__who p{margin:4px 0 0;font-size:13px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.nd-agent{margin-left:auto;display:flex;align-items:center;gap:10px;padding:6px 14px 6px 6px;border-radius:999px;background:rgba(5,12,44,.6);border:2px solid rgba(255,255,255,.14);max-width:100%}
.nd-agent__icon{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#16306f;font-size:15px}
.nd-agent__text{display:flex;flex-direction:column;min-width:0}
.nd-agent__text strong{font-size:14px;font-weight:900;color:#fff}
.nd-agent__text em{font-style:normal;font-size:11px;font-weight:800;color:var(--ds-label,#9fb3d9);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nd-agent.tone-hard .nd-agent__icon,.nd-agent.tone-danger .nd-agent__icon{background:var(--dd-lacquer)}
.nd-table{flex:1 1 auto;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:18px}
.nd-side{display:flex;flex-direction:column;gap:14px;min-height:0;overflow-y:auto;padding-right:4px}
.nd-ask{display:flex;flex-direction:column;gap:2px;padding:12px 14px;border-radius:12px;background:rgba(5,12,44,.55);border-left:4px solid var(--dd-gold)}
.nd-ask span{font-size:12px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.nd-ask strong{font-size:28px;font-weight:900;color:#fff;font-variant-numeric:tabular-nums}
.nd-ask strong small{font-size:15px;color:var(--ds-label,#9fb3d9)}
.nd-ask em{font-style:normal;font-size:13px;font-weight:800;color:#e2d1ff}
.nd-thread{display:flex;flex-direction:column;gap:8px}
.nd-bubble{margin:0;align-self:flex-start;max-width:95%;padding:9px 13px;border-radius:14px 14px 14px 4px;background:#21407f;color:#fff;font-size:14px;line-height:1.35;border:2px solid rgba(0,0,0,.25)}
.nd-bubble.is-mood{background:none;border:2px dashed rgba(255,255,255,.18);color:var(--ds-label,#9fb3d9);font-size:13px}
.nd-verdict{padding:10px 13px;border-radius:12px;background:rgba(5,12,44,.6);border:2px solid rgba(255,255,255,.14)}
.nd-verdict p{margin:6px 0 0;font-size:14px;color:#fff}
.nd-verdict__badge{display:inline-block;padding:2px 10px;border-radius:999px;font-size:11px;font-weight:900;background:#16306f;color:#fff}
.nd-verdict.is-countered{border-color:var(--dd-yellow)}
.nd-verdict.is-countered .nd-verdict__badge{background:var(--dd-yellow);color:var(--dd-outline)}
.nd-verdict.is-rejected{border-color:#ff6b5b}
.nd-verdict.is-rejected .nd-verdict__badge{background:var(--dd-lacquer)}
.nd-verdict.is-pending .nd-verdict__badge{background:#2a6fb0}
.nd-verdict.is-accepted{border-color:#8ff0b0}
.nd-link{margin-left:10px;background:none;border:0;padding:0;color:var(--ds-active,#2ee6d6);font-weight:800;cursor:pointer;text-decoration:underline;text-underline-offset:3px}
.nif{padding:10px 13px;border-radius:12px;background:rgba(5,12,44,.45)}
.nif__head{display:flex;justify-content:space-between;gap:8px;margin-bottom:6px;font-size:13px;font-weight:900;color:#fff}
.nif__row{display:flex;justify-content:space-between;gap:8px;padding:3px 0;font-size:13px;color:var(--ds-text,#fff);border-top:1px solid rgba(255,255,255,.05)}
.nif .is-good{color:#8ff0b0;font-variant-numeric:tabular-nums;white-space:nowrap}
.nif .is-bad{color:#ff9b8a;font-variant-numeric:tabular-nums;white-space:nowrap}
.nif .is-muted,.nif__empty{color:var(--ds-label,#9fb3d9);margin:0;font-size:13px}
.nif__premium{margin:6px 0 0;color:#ff9b8a;font-size:13px;font-weight:800}

/* Your side */
.nd-meter{padding:12px 14px;border-radius:12px;background:rgba(5,12,44,.6)}
.nd-meter__head{display:flex;align-items:baseline;gap:12px}
.nd-meter__head strong{font-size:44px;font-weight:900;line-height:1;color:#fff;font-variant-numeric:tabular-nums}
.nd-meter__head span{font-size:14px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.nd-meter.will-accept .nd-meter__head strong,.nd-meter.will-accept .nd-meter__head span{color:#8ff0b0}
.nd-meter__track{position:relative;height:16px;margin:10px 0 6px;border-radius:999px;border:3px solid var(--dd-outline);background:#0a0f2a;box-shadow:0 2px 0 var(--dd-outline)}
.nd-meter__fill{position:absolute;inset:0 auto 0 0;border-radius:999px;background:linear-gradient(180deg,#ffb347,#e07a10);transition:width .25s}
.nd-meter.tone-good .nd-meter__fill,.nd-meter.tone-instant .nd-meter__fill,.nd-meter.will-accept .nd-meter__fill{background:linear-gradient(180deg,#9cf5b8,#3dbb6c)}
.nd-meter.tone-bad .nd-meter__fill{background:linear-gradient(180deg,var(--dd-lacquer-hi),var(--dd-lacquer))}
.nd-meter__mark{position:absolute;top:-6px;bottom:-6px;width:3px;margin-left:-1px;background:#fff;border-radius:2px;box-shadow:0 0 0 1px var(--dd-outline)}
.nd-meter__mark.is-instant{background:var(--dd-yellow)}
.nd-meter__note{margin:0;font-size:12px;font-weight:700;color:var(--ds-label,#9fb3d9)}
.nd-field{display:flex;flex-direction:column;gap:8px}
.nd-field__head{display:flex;align-items:baseline;gap:10px}
.nd-field__head span{font-size:13px;font-weight:900;color:#fff}
.nd-field__head strong{margin-left:auto;font-size:20px;font-weight:900;color:var(--dd-yellow);font-variant-numeric:tabular-nums}
.nd-field__head em{font-style:normal;font-size:12px;font-weight:800;min-width:110px;text-align:right}
.nd-field__head em.is-up{color:#8ff0b0}
.nd-field__head em.is-down{color:#ffcf6b}
.nd-range{position:relative}
.nd-range input[type=range]{width:100%;accent-color:var(--dd-gold);height:24px;margin:0;cursor:pointer}
.nd-range__ask{position:absolute;top:-4px;width:2px;height:32px;margin-left:-1px;background:#e2d1ff;pointer-events:none;border-radius:2px}
.nd-range__ask::after{content:"ask";position:absolute;top:-14px;left:50%;transform:translateX(-50%);font-size:10px;font-weight:900;color:#e2d1ff}
.nd-range__scale{display:flex;justify-content:space-between;font-size:11px;font-weight:700;color:var(--ds-label,#9fb3d9)}
.nd-seg{display:flex;flex-wrap:wrap;gap:4px}
.nd-seg button{flex:1 0 44px;padding:8px 10px;border-radius:10px;border:2px solid rgba(255,255,255,.18);background:rgba(5,12,44,.5);color:#fff;font-weight:900;font-size:14px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px}
.nd-seg button em{font-style:normal;font-size:10px;font-weight:900;padding:1px 5px;border-radius:999px;background:#e2d1ff;color:var(--dd-outline)}
.nd-seg button:hover:not(:disabled){border-color:var(--dd-gold-hi)}
.nd-seg button.is-active{background:linear-gradient(180deg,var(--dd-yellow),var(--dd-yellow-deep));color:var(--dd-outline);border-color:var(--dd-outline);box-shadow:0 3px 0 var(--dd-outline)}
.nd-seg button:disabled{opacity:.4;cursor:not-allowed}
.nd-note{margin:0;font-size:12px;font-weight:700;color:var(--ds-label,#9fb3d9)}
.nd-cap{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px 14px;margin:0;padding:12px 14px;border-radius:12px;background:rgba(5,12,44,.45)}
.nd-cap > div{display:flex;flex-direction:column;gap:2px}
.nd-cap dt{font-size:11px;font-weight:800;color:var(--ds-label,#9fb3d9)}
.nd-cap dd{margin:0;font-size:17px;font-weight:900;color:#fff;font-variant-numeric:tabular-nums}
.nd-cap dd small{font-size:11px;color:var(--ds-label,#9fb3d9)}
.nd-cap dd.is-bad{color:#ff9b8a}
.nd-cap__bar{grid-column:1/-1;height:10px!important;border-radius:999px;background:#0a0f2a;border:2px solid var(--dd-outline);overflow:hidden;display:block!important}
.nd-cap__bar i{display:block;height:100%;background:linear-gradient(180deg,var(--dd-yellow),var(--dd-yellow-deep))}
.nd-cap__bar i.is-tight{background:linear-gradient(180deg,#ffb347,#e07a10)}
.nd-cap__bar i.is-over{background:linear-gradient(180deg,var(--dd-lacquer-hi),var(--dd-lacquer))}
.nd-cap .nd-note{grid-column:1/-1}
.nd-error{margin:0;padding:8px 12px;border-radius:10px;border-left:4px solid #ff6b5b;background:rgba(168,48,15,.25);color:#ffc2b6;font-weight:800;font-size:13px}
.nd-actions{display:flex;flex-wrap:wrap;gap:8px;position:sticky;bottom:0;padding-top:8px;background:linear-gradient(180deg,transparent,var(--dd-box-fill) 30%)}
.nd-btn{padding:8px 16px;border-radius:999px;border:2px solid rgba(255,255,255,.25);background:rgba(5,12,44,.6);color:#fff;font-weight:800;font-size:14px;cursor:pointer;font-family:inherit}
.nd-btn:hover:not(:disabled){border-color:var(--dd-gold-hi);color:var(--dd-yellow)}
.nd-btn:disabled{opacity:.45;cursor:not-allowed}
