/* Big monitors: the 3D wall scales with the window, so the HUD scales too */
@media (min-width:1700px){.office-broadcast,.office-urgent-desk,.hub-alert,.hub-console,.office-control-bar,.office-edge,.office-wire-ticker{zoom:1.25}}
@media (min-width:2300px){.office-broadcast,.office-urgent-desk,.hub-alert,.hub-console,.office-control-bar,.office-edge,.office-wire-ticker{zoom:1.5}}

/* ==========================================================================
   SECTION: Command-sheet layer — offseason player desks
   Same language as the prospect dossier (components/dossier/ProspectDossierView.js,
   DossierCommandSheet): cream identity band, orange decision block, lime for
   positives, coral for risk, sentence case, spacing instead of nested rims.
   ========================================================================== */
:root{--cs-ink:#071233;--cs-deep:#050c2c;--cs-region:#0d1d4d;--cs-cream:var(--dd-cream,#ffe7c4);--cs-orange:#ff8a1f;--cs-lime:#9be564;--cs-coral:#ff6b5c;--cs-blue:#5aa2ff;--cs-cyan:#3ee6ff;--cs-soft:#a9bfdc}

/* Re-sign desk: table beside the player panel, no rims, one scroll. */
.resign-root .resign-table-layout:not(.is-negotiating){grid-template-columns:minmax(0,1fr) 340px!important;gap:0!important;align-items:stretch}
@media (max-width:900px){.resign-root .resign-table-layout:not(.is-negotiating){grid-template-columns:1fr!important}}
.resign-root .resign-table-wrap{margin:0!important;border:0!important;border-radius:0!important;box-shadow:none!important;background:rgba(5,12,44,.6)!important}
.resign-root .resign-table thead th{font-size:11px!important;letter-spacing:0!important;text-transform:none!important;color:var(--cs-soft)!important}
.resign-root .resign-table tbody tr.is-selected td{background:rgba(255,231,196,.08)!important}
.resign-root .resign-table tbody tr.is-actionable td:first-child{box-shadow:inset 4px 0 0 var(--cs-orange)!important}
.resign-root .resign-row-action{border-radius:4px!important;border:0!important;background:var(--cs-orange)!important;color:#2a1200!important;font-weight:900!important;box-shadow:none!important;text-transform:none!important}
.resign-root .resign-row-action:hover{background:var(--cs-cream)!important;color:var(--cs-ink)!important}
.resign-root .resign-detail-panel{margin:0!important;padding:0!important;border:0!important;border-radius:0!important;box-shadow:-12px 0 24px rgba(0,0,0,.35)!important;background:var(--cs-deep)!important;display:flex;flex-direction:column;overflow:visible!important;min-height:0}
.resign-root .resign-identity{display:grid!important;grid-template-columns:60px minmax(0,1fr)!important;gap:12px!important;align-items:center!important;margin:0!important;padding:16px!important;background:var(--cs-cream)!important;color:var(--cs-ink)!important;border:0!important;box-shadow:none!important;border-radius:0!important}
.resign-root .resign-identity-shot{width:60px!important;height:60px!important;overflow:hidden!important;position:relative;background:var(--cs-ink);clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%);display:grid;place-items:center}
.resign-root .resign-identity-shot .player-headshot{zoom:.5}
.resign-root .resign-identity-copy{min-width:0}
.resign-root .resign-identity-copy h3{margin:2px 0 0!important;font-family:var(--dd-font-ui)!important;font-size:22px!important;font-weight:900!important;line-height:1.05!important;letter-spacing:-.01em!important;color:var(--cs-ink)!important;text-shadow:none!important;-webkit-text-stroke:0!important;overflow-wrap:anywhere}
.resign-root .resign-identity-copy p{margin:3px 0 0!important;font-size:13px!important;font-weight:700!important;color:#24315a!important}
.resign-root .resign-ovr-badge{display:inline-flex!important;align-items:baseline;gap:4px;padding:0!important;background:none!important;border:0!important;box-shadow:none!important;font-size:26px!important;font-weight:900!important;line-height:1!important;color:var(--cs-ink)!important}
.resign-root .resign-ovr-badge em{font-style:normal;font-size:11px!important;font-weight:800;color:#4b5a82!important}
.resign-root .resign-detail-tabs{display:grid!important;grid-template-columns:1fr 1fr!important;gap:0!important;margin:0!important;background:var(--cs-region)!important;border:0!important}
.resign-root .resign-detail-tabs button{border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;padding:9px 0!important;font-family:var(--dd-font-ui)!important;font-size:13px!important;font-weight:900!important;letter-spacing:0!important;text-transform:none!important;color:var(--cs-soft)!important;border-bottom:3px solid transparent!important}
.resign-root .resign-detail-tabs button.is-active{color:#fff!important;border-bottom-color:var(--cs-orange)!important}
.resign-root .resign-detail-tabs button:disabled{opacity:.45}
.resign-root .resign-detail-body{padding:14px 16px 16px!important;max-height:none!important;overflow:visible!important;display:flex;flex-direction:column;gap:12px}
.resign-root .resign-dossier-grid{display:grid!important;grid-template-columns:1fr 1fr!important;gap:12px 18px!important;margin:0!important}
.resign-root .resign-dossier-grid > div{padding:0!important;background:none!important;border:0!important;box-shadow:none!important;border-radius:0!important;min-width:0}
.resign-root .resign-dossier-grid span:not([class*="pill"]){display:block;font-size:11px!important;font-weight:800!important;letter-spacing:0!important;text-transform:none!important;color:var(--cs-soft)!important}
.resign-root .resign-dossier-grid strong{display:block;font-size:16px!important;font-weight:900!important;color:#fff!important;font-variant-numeric:tabular-nums}
.resign-root .resign-context{margin:0!important;font-size:12px!important;font-weight:700;color:var(--cs-cream)!important}
.resign-root .resign-interest-pill{background:none!important;border:0!important;padding:0!important;box-shadow:none!important;font-weight:900!important}
.resign-root .resign-interest-pill.tone-good,.resign-root .resign-interest-pill.tone-high{color:var(--cs-lime)!important}
.resign-root .resign-interest-pill.tone-warn,.resign-root .resign-interest-pill.tone-medium{color:var(--cs-cream)!important}
.resign-root .resign-interest-pill.tone-bad,.resign-root .resign-interest-pill.tone-low{color:var(--cs-coral)!important}
.resign-root .resign-decision-list,.resign-root .resign-special-actions{display:grid!important;gap:6px!important;margin:0!important;padding:12px!important;background:var(--cs-orange)!important;border:0!important;border-radius:0!important}
.resign-root .resign-special-actions{margin-top:-12px!important;padding-top:0!important}
.resign-root .resign-decision-btn{display:flex!important;justify-content:space-between;align-items:center;gap:8px;width:100%;padding:9px 12px!important;border:0!important;border-radius:4px!important;box-shadow:none!important;background:rgba(7,18,51,.12)!important;color:#2a1200!important;font-family:var(--dd-font-ui)!important;font-size:14px!important;font-weight:900!important;letter-spacing:0!important;text-transform:none!important;text-align:left}
.resign-root .resign-decision-btn.is-recommended{background:var(--cs-ink)!important;color:var(--cs-cream)!important}
.resign-root .resign-decision-btn:hover:not(:disabled){background:var(--cs-cream)!important;color:var(--cs-ink)!important}
.resign-root .resign-decision-btn:disabled{opacity:.5}
.resign-root .resign-decision-meta{font-size:11px!important;font-weight:700!important;opacity:.85}
.resign-root .resign-warn{margin:0!important;font-size:12px!important;font-weight:800;color:var(--cs-coral)!important}
/* The decision comes first, like the dossier verdict; the panel scrolls as one column. */
.resign-root .resign-detail-panel{overflow-y:auto!important}
.resign-root .resign-detail-body .resign-decision-list{order:-2}
.resign-root .resign-detail-body .resign-special-actions{order:-1;margin-top:-12px!important}

/* Draft review: cream identity band for the selected pick, the class grade as the
   orange decision block, open sections instead of boxed cards, sentence-case labels. */
.draftreview-root .draftreview-workspace{gap:14px!important}
.draftreview-root :is(.draftreview-kicker,.draftreview-hero-kicker,.draftreview-section-label,.draftreview-road-step-label,.draftreview-meter-head,.draftreview-org-kv,.draftreview-broadcast-show,.draftreview-broadcast-seg,.draftreview-ticker-tab,.draftreview-more-toggle,.draftreview-phase-text,.draftreview-haul-chip,.draftreview-value-banner,.draftreview-scout-col,.draftreview-prod-stat){text-transform:none!important;letter-spacing:0!important}
.draftreview-root .draftreview-haul-banner{background:var(--cs-orange)!important;color:#2a1200!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:10px 14px!important}
.draftreview-root .draftreview-haul-banner *{color:#2a1200!important;text-shadow:none!important}
.draftreview-root .draftreview-haul-banner-grade{background:var(--cs-ink)!important;border:0!important;border-radius:0!important;box-shadow:none!important;clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%)}
.draftreview-root .draftreview-haul-banner-grade,.draftreview-root .draftreview-haul-banner-grade *{color:var(--cs-cream)!important}
.draftreview-root .draftreview-haul-chip{background:rgba(7,18,51,.14)!important;border:0!important;border-radius:3px!important;font-weight:900!important}
.draftreview-root .draftreview-draft-card{background:var(--cs-cream)!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:14px 16px!important}
.draftreview-root .draftreview-draft-card :is(p,span,div,h2){color:var(--cs-ink)!important;text-shadow:none!important;-webkit-text-stroke:0!important}
.draftreview-root .draftreview-hero-name{font-family:var(--dd-font-ui)!important;font-size:28px!important;font-weight:900!important;letter-spacing:-.01em!important}
.draftreview-root .draftreview-hero-kicker,.draftreview-root .draftreview-hero-meta{color:#4b5a82!important;font-weight:700!important}
.draftreview-root .draftreview-pos-mark{background:var(--cs-ink)!important;border:0!important;border-radius:0!important;box-shadow:none!important;clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%)}
.draftreview-root .draftreview-pos-mark,.draftreview-root .draftreview-pos-mark *{color:var(--cs-cream)!important}
.draftreview-root .draftreview-value-banner{display:inline-block;background:var(--cs-ink)!important;border:0!important;border-radius:0!important;color:#fff!important;font-weight:900!important;transform:rotate(-2deg)}
.draftreview-root .draftreview-grade-shield{background:var(--cs-orange)!important;border:0!important;border-radius:0!important;box-shadow:none!important;clip-path:polygon(12% 0,100% 0,88% 100%,0 100%)}
.draftreview-root .draftreview-grade-shield,.draftreview-root .draftreview-grade-shield *{color:#2a1200!important}
.draftreview-root :is(.draftreview-projection-card,.draftreview-prod-card,.draftreview-roadmap-card,.draftreview-bottom-band){background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important}
.draftreview-root .draftreview-section-label,.draftreview-root .draftreview-kicker{font-size:12px!important;font-weight:800!important;color:var(--cs-soft)!important}
.draftreview-root .draftreview-projection-role{font-size:18px!important;font-weight:900!important;color:#fff!important}
.draftreview-root .draftreview-projection-eta{color:var(--cs-cream)!important;font-weight:800!important}
.draftreview-root .draftreview-meter-track{background:rgba(169,191,220,.18)!important;border:0!important}
.draftreview-root .draftreview-meter-fill{background:var(--cs-cream)!important;box-shadow:none!important}
.draftreview-root .draftreview-prod-hero,.draftreview-root .draftreview-prod-hero *{color:var(--cs-cream)!important;text-shadow:none!important}
.draftreview-root .draftreview-prod-stat{color:var(--cs-soft)!important}
.draftreview-root .draftreview-prod-stat :is(strong,b,span:last-child){color:#fff!important}
.draftreview-root .draftreview-road-step{background:var(--cs-region)!important;border:0!important;border-radius:0!important;box-shadow:none!important}
.draftreview-root .draftreview-road-step:first-child{border-left:4px solid var(--cs-cream)!important}
.draftreview-root .draftreview-road-step:last-child{border-left:4px solid var(--cs-lime)!important}
.draftreview-root .draftreview-road-step-eta{color:var(--cs-orange)!important;font-weight:900!important}
.draftreview-root .draftreview-scout-col{padding:8px 10px!important;border-radius:0!important;border:0!important;color:var(--cs-ink)!important}
.draftreview-root .draftreview-scout-col:first-of-type{background:var(--cs-lime)!important}
.draftreview-root .draftreview-scout-col:nth-of-type(2){background:var(--cs-coral)!important}
.draftreview-root .draftreview-scout-col *{color:var(--cs-ink)!important;font-weight:800}
.draftreview-root .draftreview-scout-item::before{color:var(--cs-ink)!important}
.draftreview-root .draftreview-depth-track{background:rgba(169,191,220,.18)!important}
.draftreview-root .draftreview-depth-fill{background:var(--cs-cream)!important;box-shadow:none!important}
.draftreview-root .draftreview-org-kv{color:var(--cs-soft)!important}
.draftreview-root .draftreview-org-kv :is(strong,b){color:#fff!important}
.draftreview-root .draftreview-panel{background:rgba(5,12,44,.7)!important;border:0!important;border-radius:0!important;box-shadow:none!important}
.draftreview-root .draftreview-haul-card{border-radius:0!important;border:0!important;box-shadow:none!important;background:transparent!important}
.draftreview-root .draftreview-rail-btn[aria-pressed="true"] .draftreview-haul-card,.draftreview-root .draftreview-rail-btn.is-active .draftreview-haul-card{background:rgba(255,231,196,.1)!important;box-shadow:inset 4px 0 0 var(--cs-orange)!important}
.draftreview-root .draftreview-ticker-tab{color:var(--cs-soft)!important;font-weight:900!important}
.draftreview-root .draftreview-ticker-tab.is-active,.draftreview-root .draftreview-ticker-tab[aria-selected="true"]{color:#fff!important;box-shadow:inset 0 -3px 0 var(--cs-orange)!important}
.draftreview-root .draftreview-more-toggle{color:var(--cs-cyan)!important;font-weight:900!important}
.draftreview-root .draftreview-draft-card .draftreview-value-banner{color:#fff!important;padding:2px 8px!important;margin-top:4px}
.draftreview-root .draftreview-haul-banner .draftreview-kicker{color:#4a1f02!important}
.draftreview-root .draftreview-projection-card,.draftreview-root .draftreview-prod-card{height:auto!important;min-height:0!important;overflow:visible!important}
.draftreview-root .draftreview-stage-grid{align-items:start!important;row-gap:16px!important}
.draftreview-root .draftreview-stage-grid{grid-template-rows:none!important;grid-auto-rows:auto!important;height:auto!important}
.draftreview-root .draftreview-workspace{overflow-y:auto!important}.draftreview-root .draftreview-review-main{overflow:visible!important;height:auto!important}
.draftreview-root .draftreview-review-main{flex:none!important}.draftreview-root .draftreview-review-main > *,.draftreview-root .draftreview-workspace > *{flex-shrink:0!important}


/* Free agency: the market list and the player desk get the height (they were squeezed
   to ~140px by the signings feed at 768px tall); cream identity band for the selected
   player, open sections, the offer controls as the orange decision area. */
/* The signings column is a full-height side rail. A 118px cap stacked
   Day / Wire / Social and the latest signing into one short card. */
.fa-root.fa-root--market .fa-stage{grid-template-columns:minmax(0,1fr) minmax(300px,340px)!important;grid-template-rows:minmax(0,1fr)!important;align-items:stretch!important}
.fa-root.fa-root--market .fa-panel{max-height:none!important;height:100%!important;min-height:0!important;align-self:stretch!important;overflow:hidden!important;display:flex!important;flex-direction:column!important;padding:0!important}
.fa-root.fa-root--market .fa-panel > h2:empty{display:none!important}
.fa-root.fa-root--market .fa-panel .fa-rail{max-height:none!important;flex:1 1 auto!important;min-height:0!important;display:flex!important;flex-direction:column!important;overflow:hidden!important}
.fa-root .fa-rail-shell{display:flex!important;flex-direction:column!important;min-height:0!important;height:100%!important}
.fa-root .fa-rail-tabs{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;flex:0 0 auto}
.fa-root .fa-rail-tabs button{letter-spacing:0!important;text-transform:none!important;font-size:13px!important;font-weight:800!important;padding:12px 6px!important;white-space:nowrap}
.fa-root .fa-rail-scroll{flex:1 1 auto!important;min-height:0!important;overflow-y:auto!important;display:flex!important;flex-direction:column!important;gap:10px!important;padding:12px!important}
.fa-root .fa-day-row,.fa-root .fa-wire-item,.fa-root .fa-social-post{padding:10px 12px!important}
.fa-root .fa-day-main strong{white-space:normal!important}
.fa-root .fa-fa-desk > .fa-empty{flex:1 1 auto;display:grid;place-items:center;text-align:center;margin:0;padding:40px 28px;font-size:16px;font-weight:800;line-height:1.45;max-width:28ch;align-self:center}
.fa-root .fa-fa-bar{border:0!important;box-shadow:none!important;border-radius:0!important;background:var(--cs-region)!important}
.fa-root .fa-fa-identity *{text-transform:none!important}
.fa-root .fa-fa-tools{gap:6px!important}
.fa-root .fa-fa-layout{flex:1 1 auto!important;min-height:0!important}
.fa-root :is(.fa-fa-list,.fa-fa-desk){border:0!important;border-radius:0!important;box-shadow:none!important;margin:0!important;background:rgba(5,12,44,.6)!important}
.fa-root .fa-fa-desk{background:var(--cs-deep)!important;padding:0!important;overflow-y:auto!important}
.fa-root .fa-fa-count,.fa-root .fa-mini-label,.fa-root .fa-nego-meter-head{text-transform:none!important;letter-spacing:0!important}
.fa-root .fa-fa-row{border:0!important;border-radius:0!important;box-shadow:none!important;background:transparent!important;border-bottom:1px solid rgba(169,191,220,.12)!important}
.fa-root .fa-fa-row.is-selected{background:rgba(255,231,196,.08)!important;box-shadow:inset 4px 0 0 var(--cs-orange)!important}
.fa-root .fa-fa-rating > *{background:transparent!important;border:0!important;box-shadow:none!important}
.fa-root .fa-fa-ask{color:var(--cs-cream)!important;font-weight:900!important}
.fa-root .fa-fa-identity{background:var(--cs-cream)!important;padding:14px 16px!important;margin:0!important;border:0!important;border-radius:0!important;box-shadow:none!important}
.fa-root .fa-fa-identity :is(p,span:not(.fa-rights-badge),div,h2,h3,strong){color:var(--cs-ink)!important;text-shadow:none!important;-webkit-text-stroke:0!important}
.fa-root .fa-fa-identity :is(h2,h3){font-family:var(--dd-font-ui)!important;font-weight:900!important;text-transform:none!important;letter-spacing:-.01em!important}
.fa-root .fa-fa-shot{overflow:hidden!important;background:var(--cs-ink)!important;border:0!important;border-radius:0!important;clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%)}
.fa-root .fa-fa-shot .player-headshot{zoom:.55}
.fa-root .fa-fa-ovr{color:var(--cs-ink)!important;font-size:22px!important;font-weight:900!important}
.fa-root .fa-rights-badge{background:var(--cs-ink)!important;color:var(--cs-cream)!important;border:0!important;border-radius:0!important}
.fa-root :is(.fa-nego-meter,.fa-fa-offers,.fa-fa-scout,.fa-fa-capbar){background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;margin:0 16px!important}
.fa-root .fa-nego-meter-track,.fa-root .fa-fa-captrack,.fa-root .fa-fa-pctile-track{background:rgba(169,191,220,.18)!important;border:0!important}
.fa-root .fa-nego-meter-fill{background:var(--cs-lime)!important;box-shadow:none!important}
.fa-root .fa-fa-offer{background:var(--cs-region)!important;border:0!important;border-radius:0!important}
.fa-root .fa-fa-controls{background:var(--cs-orange)!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:12px 16px!important;margin:12px 0 0!important;color:#2a1200!important}
.fa-root .fa-fa-controls :is(label,span,p,small,strong,legend){color:#2a1200!important;text-shadow:none!important}
.fa-root .fa-fa-controls :is(select,input[type="number"],input[type="text"]){background:#fff!important;color:var(--cs-ink)!important;border:0!important;border-radius:4px!important}
.fa-root .fa-fa-controls .fa-fa-capbar{margin:0!important}
.fa-root .fa-fa-controls :is(strong,b,span){color:#2a1200!important}
.fa-root .fa-fa-controls button:not([class*="submit"]):not([class*="cta"]):not(.nd-btn--primary){background:rgba(7,18,51,.14)!important;color:#2a1200!important;border:0!important;border-radius:4px!important;box-shadow:none!important;font-family:var(--dd-font-ui)!important;font-weight:900!important;text-transform:none!important;letter-spacing:0!important;text-shadow:none!important}
.fa-root .fa-fa-controls button:not([class*="submit"]):not([class*="cta"]):not(.nd-btn--primary):is(.is-active,.is-selected,[aria-pressed="true"]){background:var(--cs-ink)!important;color:var(--cs-cream)!important}
.fa-root .fa-fa-controls :is(button[class*="submit"],button[class*="cta"],.nhlcal-advance-button){background:var(--cs-ink)!important;color:var(--cs-cream)!important;border:0!important;border-radius:4px!important;box-shadow:none!important;clip-path:none!important;font-family:var(--dd-font-ui)!important;font-weight:900!important;text-transform:none!important;letter-spacing:0!important;text-shadow:none!important}
.fa-root .fa-fa-controls :is(button[class*="submit"],button[class*="cta"],.nhlcal-advance-button) *{color:var(--cs-cream)!important}
.fa-root .fa-fa-controls .fa-fa-captrack > *{background:var(--cs-ink)!important}
.fa-root .fa-fa-controls button.nd-btn--primary{background:var(--cs-ink)!important;color:var(--cs-cream)!important;padding:10px 14px!important}
.fa-root .fa-fa-controls button.nd-btn--primary *{color:var(--cs-cream)!important}
.fa-root .fa-fa-controls button.nd-btn--primary:hover:not(:disabled){background:var(--cs-cream)!important;color:var(--cs-ink)!important}

/* Draft review, restructured (DraftReviewEventMenu, .dr-*). Reading order: class verdict,
   the pick and what he did (observed), what scouts expect (projection), the case for and
   against, fit with the club. */
.draftreview-root .dr{display:flex;flex-direction:column;gap:12px;padding:2px 2px 8px;font-family:var(--dd-font-ui);color:#eef4ff}
.dr .dr-label{margin:0 0 4px;font-size:12px;font-weight:800;color:var(--cs-soft);text-transform:none;letter-spacing:0}
.dr .dr-note{margin:4px 0 0;font-size:12px;color:#c9d6ea}
.dr-verdict{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:14px;align-items:center;padding:10px 14px;background:var(--cs-orange);color:#2a1200}
.dr-verdict__grade{display:grid;place-items:center;width:62px;height:62px;background:var(--cs-ink);clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%)}
.dr-verdict__grade strong{font-family:var(--dd-font-display);font-size:30px;line-height:1;color:var(--cs-cream)}
.dr-verdict__grade span{font-size:10px;font-weight:800;color:var(--cs-cream);margin-top:-6px}
.dr-verdict__copy strong{display:block;font-size:20px;font-weight:900;line-height:1.1}
.dr-verdict__copy p{margin:2px 0 0;font-size:13px;font-weight:700}
.dr-verdict__copy .dr-verdict__mix{font-weight:900;color:#4a1f02}
.dr-verdict__facts{margin:0;display:grid;gap:4px;text-align:right}
.dr-verdict__facts dt{font-size:11px;font-weight:800;color:#4a1f02!important;text-transform:none!important;letter-spacing:0!important}
.dr-verdict__facts dd{margin:0;font-size:14px;font-weight:900}
.dr-main{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:0;align-items:stretch}
.dr-pick{background:var(--cs-cream);color:var(--cs-ink);display:flex;flex-direction:column;clip-path:polygon(0 0,100% 0,calc(100% - 14px) 100%,0 100%);padding-right:14px}
.dr-pick__id{display:flex;gap:12px;align-items:center;padding:14px 16px 10px}
.dr-pick__mark{flex:none;display:grid;place-items:center;width:56px;height:56px;background:var(--cs-ink);clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%)}
.dr-pick__mark strong{font-size:20px;font-weight:900;color:var(--cs-cream);line-height:1}
.dr-pick__mark span{font-size:10px;font-weight:800;color:var(--cs-cream);margin-top:-8px}
.dr-pick__copy{min-width:0}
.dr-pick__copy h2{margin:0;font-family:var(--dd-font-ui);font-size:30px;font-weight:900;line-height:1.02;letter-spacing:-.015em;color:var(--cs-ink);text-transform:none;text-shadow:none;-webkit-text-stroke:0;overflow-wrap:anywhere}
.dr-pick__copy p{margin:3px 0 0;font-size:13px;font-weight:700;color:#24315a}
.dr-pick__copy .dr-pick__slot{margin:0 0 2px;font-size:12px;font-weight:900;color:#a8300f}
.dr-pick__copy .dr-pick__club{font-weight:600;color:#4b5a82}
.dr-pick__verdict{display:flex;gap:10px;align-items:flex-start;margin:0 16px;padding:8px 10px;background:var(--cs-ink);color:var(--cs-cream)}
.dr-pick__grade{font-family:var(--dd-font-display);font-size:26px;line-height:1;color:var(--cs-cream)}
.dr-pick__verdict.tone-a .dr-pick__grade,.dr-pick__verdict.tone-good .dr-pick__grade{color:var(--cs-lime)}
.dr-pick__verdict.tone-c .dr-pick__grade,.dr-pick__verdict.tone-d .dr-pick__grade,.dr-pick__verdict.tone-bad .dr-pick__grade{color:var(--cs-coral)}
.dr-pick__verdict span{display:block;font-size:12px;font-weight:900}
.dr-pick__verdict p{margin:2px 0 0;font-size:12px;font-weight:600;color:#d6e2f4}
.dr-observed{padding:10px 16px 14px;margin-top:auto}
.dr-observed .dr-label{color:#4b5a82}
.dr-observed__row{display:flex;flex-wrap:wrap;align-items:flex-end;gap:6px 18px}
.dr-observed__hero strong{display:block;font-size:30px;font-weight:900;line-height:1;color:var(--cs-ink);font-variant-numeric:tabular-nums}
.dr-observed__hero span,.dr-observed__stat span{display:block;font-size:11px;font-weight:800;color:#4b5a82}
.dr-observed__stat strong{display:block;font-size:18px;font-weight:900;color:var(--cs-ink);font-variant-numeric:tabular-nums}
.dr-observed__headline{margin:0;font-weight:800}
.dr-observed .dr-note{color:#4b5a82}
.dr-proj{padding:12px 4px 12px 22px;display:flex;flex-direction:column;gap:6px;min-width:0}
.dr-proj__role{margin:0;font-size:19px;font-weight:900;line-height:1.15;color:#fff}
.dr-proj__eta{margin:0;font-size:13px;font-weight:900;color:var(--cs-orange)}
.dr-road{list-style:none;margin:6px 0 2px;padding:0;display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);gap:0;position:relative}
.dr-road::before{content:"";position:absolute;left:6px;right:6px;top:5px;height:2px;background:rgba(169,191,220,.35)}
.dr-road li{position:relative;padding:16px 8px 0 0;min-width:0}
.dr-road li::before{content:"";position:absolute;left:0;top:0;width:12px;height:12px;border-radius:50%;background:var(--cs-region);border:2px solid var(--cs-soft)}
.dr-road li.is-next::before{background:var(--cs-cream);border-color:var(--cs-cream)}
.dr-road li.is-projection::before{background:var(--cs-lime);border-color:var(--cs-lime)}
.dr-road__when{display:block;font-size:11px;font-weight:800;color:var(--cs-soft)}
.dr-road strong{display:block;font-size:14px;font-weight:900;color:#fff}
.dr-road__what{display:block;font-size:11px;color:#c9d6ea;overflow-wrap:anywhere}
.dr-reads{list-style:none;margin:6px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:4px 14px}
.dr-reads li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:0 6px;align-items:center;font-size:11px;font-weight:800;color:var(--cs-soft)}
.dr-reads li i{display:flex;gap:2px;grid-row:2}
.dr-reads li i b{width:14px;height:5px;background:rgba(169,191,220,.2)}
.dr-reads li em{grid-row:2;font-style:normal;color:#fff}
.dr-reads li.is-up i b.is-on{background:var(--cs-lime)}
.dr-reads li.is-mid i b.is-on{background:var(--cs-cream)}
.dr-reads li.is-down i b.is-on{background:var(--cs-coral)}
.dr-case{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:22px;padding-top:10px;border-top:1px solid rgba(169,191,220,.18)}
.dr-evidence{display:grid;gap:6px;align-content:start}
.dr-evidence p{margin:0;display:grid;grid-template-columns:18px minmax(0,1fr);gap:4px;font-size:13px;font-weight:700;color:#eef4ff}
.dr-evidence p b{font-weight:900;text-align:center}
.dr-evidence p.is-up b{color:var(--cs-lime)}
.dr-evidence p.is-down b{color:var(--cs-coral)}
.dr-fit__line{margin:0;font-size:15px;font-weight:900;color:#fff}
.dr-fit__depth{margin:2px 0 0;font-size:13px;font-weight:800;color:var(--cs-cream)}
.dr-fit__rights{margin:4px 0 0;font-size:12px;font-weight:800;color:var(--cs-orange)}
.dr-more button{background:none;border:0;padding:4px 0;color:var(--cs-cyan);font-weight:900;font-size:13px;cursor:pointer}
.dr-more__panel p{margin:0 0 4px;font-size:12px;color:#c9d6ea}
/* The pick list is part of the same desk: same surface, orange marks the open pick. */
.draftreview-root .draftreview-haul-card.is-active{background:rgba(255,231,196,.1)!important;box-shadow:inset 4px 0 0 var(--cs-orange)!important}
/* Primary action sized to the task, not a mobile purchase button. */
.draftreview-root .draftreview-cta-btn{background:var(--cs-orange)!important;color:#2a1200!important;border:0!important;border-radius:4px!important;box-shadow:none!important;clip-path:none!important;font-family:var(--dd-font-ui)!important;font-size:15px!important;font-weight:900!important;letter-spacing:0!important;text-transform:none!important;text-shadow:none!important;padding:10px 22px!important;min-height:0!important;height:auto!important}
.draftreview-root .draftreview-cta-btn *{color:#2a1200!important}
@media (max-width:900px){.dr-main,.dr-case{grid-template-columns:minmax(0,1fr)}.dr-pick{clip-path:none;padding-right:0}.dr-proj{padding-left:4px}}

/* Retirements: one row per player, open stats instead of boxed cells, the final rating as
   a plain number, the reason in the player's own line. */
.retirement-page .retirement-row{background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;border-bottom:1px solid rgba(169,191,220,.14)!important}
.retirement-page .retirement-row:first-child{border-left:4px solid var(--cs-cream)!important}
.retirement-page .retirement-headshot{width:56px!important;height:56px!important;overflow:hidden!important;background:var(--cs-ink)!important;clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%);border:0!important;border-radius:0!important}
.retirement-page .retirement-headshot .player-headshot{zoom:.6}
.retirement-page .retirement-player-name{font-family:var(--dd-font-ui)!important;font-size:18px!important;font-weight:900!important;color:var(--cs-cream)!important;text-transform:none!important}
.retirement-page .retirement-player-team{color:#fff!important;font-weight:800!important}
.retirement-page .retirement-player-tags{color:var(--cs-soft)!important;font-weight:700!important;text-transform:none!important}
.retirement-page .retirement-player-reason{display:block;margin-top:2px;font-size:12px;font-weight:700;color:var(--cs-orange)}
.retirement-page .retirement-ovr{background:transparent!important;border:0!important;box-shadow:none!important}
.retirement-page .retirement-ovr span{font-size:11px!important;font-weight:800!important;color:var(--cs-soft)!important;text-transform:none!important;letter-spacing:0!important}
.retirement-page .retirement-ovr strong{font-size:30px!important;font-weight:900!important;color:#fff!important}
.retirement-page .retirement-stat-group h3{font-size:12px!important;font-weight:800!important;color:var(--cs-soft)!important;text-transform:none!important;letter-spacing:0!important}
.retirement-page .retirement-stat-cell{background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:0 10px 0 0!important;text-align:left!important}
.retirement-page .retirement-stat-cell span{font-size:11px!important;color:var(--cs-soft)!important;text-transform:none!important;letter-spacing:0!important}
.retirement-page .retirement-stat-cell strong{font-size:16px!important;font-weight:900!important;color:#fff!important}
.retirement-page .retirement-continue-btn{background:var(--cs-orange)!important;color:#2a1200!important;border:0!important;border-radius:4px!important;box-shadow:none!important;clip-path:none!important;font-family:var(--dd-font-ui)!important;font-size:15px!important;font-weight:900!important;letter-spacing:0!important;text-transform:none!important;text-shadow:none!important;padding:10px 22px!important}

/* Board of Governors: the meeting floor kept its three columns only above 1100px; at
   1024 it stacked into three 208px boxes that each scrolled. Keep columns to 900px. */
@media (min-width:900px) and (max-width:1100px){.bog-floor{grid-template-columns:minmax(190px,220px) minmax(0,1fr) minmax(210px,240px)!important}}
@media (max-width:899px){.bog-floor > .bog-panel{max-height:none!important;overflow:visible!important}.bog-root{overflow-y:auto!important}}

/* ==========================================================================
   Negotiation desk, restructured (components/contracts/CapContractNegotiation.js, .nd2)
   Cream hero with the player and the gap between the two sides, one deal-interest
   gauge, your terms beside the agent, cap consequence next to the single primary
   action. Same colour language as the dossier: orange = decision, lime = yes,
   coral = no / over the cap, cream = the player and his numbers.
   ========================================================================== */
.nd.nd2{display:flex;flex-direction:column;gap:0;background:var(--cs-deep)!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;font-family:var(--dd-font-ui);color:#eef4ff;min-width:0}
.nd2 *{text-transform:none;letter-spacing:0}
.nd2-hero{display:grid;grid-template-columns:auto 56px minmax(0,1fr) auto;gap:12px;align-items:center;padding:14px 16px;background:var(--cs-cream);color:var(--cs-ink)}
.nd2-back{width:30px;height:30px;border:0;border-radius:4px;background:var(--cs-ink);color:var(--cs-cream);font-size:16px;font-weight:900;cursor:pointer}
.nd2-face{width:56px;height:56px;overflow:hidden;background:var(--cs-ink);clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%);display:grid;place-items:center}
.nd2-face .player-headshot{zoom:.62}
.nd2-who{min-width:0}
.nd2-who h3{margin:0;font-family:var(--dd-font-ui);font-size:22px;font-weight:900;line-height:1.05;color:var(--cs-ink);text-shadow:none;-webkit-text-stroke:0;overflow-wrap:anywhere}
.nd2-who p{margin:2px 0 0;font-size:12px;font-weight:700;color:#24315a}
.nd2-agent{color:#4b5a82!important}
.nd2-agent b{font-weight:900}
.nd2-agent.tone-good b,.nd2-agent.tone-easy b{color:#2f7d16}
.nd2-agent.tone-bad b,.nd2-agent.tone-hard b,.nd2-agent.tone-danger b{color:#a8300f}
.nd2-gap{display:grid;grid-template-columns:auto auto auto;align-items:center;gap:10px;text-align:right}
.nd2-gap > div span{display:block;font-size:11px;font-weight:800;color:#4b5a82}
.nd2-gap > div strong{display:block;font-size:22px;font-weight:900;line-height:1;color:var(--cs-ink);font-variant-numeric:tabular-nums}
.nd2-gap > div em{display:block;font-style:normal;font-size:11px;font-weight:800;color:#4b5a82}
.nd2-gap > div.is-you strong{color:#a8300f}
.nd2-gap > i{font-style:normal;font-size:12px;font-weight:900;padding:2px 6px;background:var(--cs-ink);color:var(--cs-cream)}
.nd2-gap > i.is-down{background:#a8300f;color:#fff}
.nd2-gauge{display:grid;grid-template-columns:auto minmax(0,1fr);gap:14px;align-items:center;padding:12px 16px;background:var(--cs-region)}
.nd2-gauge > strong{font-size:36px;font-weight:900;line-height:1;color:var(--cs-cream);font-variant-numeric:tabular-nums}
.nd2-gauge.will-accept > strong{color:var(--cs-lime)}
.nd2-gauge.tone-low > strong,.nd2-gauge.tone-bad > strong{color:var(--cs-coral)}
.nd2-gauge__body span{display:block;font-size:14px;font-weight:900;color:#fff}
.nd2-gauge.will-accept .nd2-gauge__body span{color:var(--cs-lime)}
.nd2-gauge__track{position:relative;height:10px;margin:6px 0 4px;background:rgba(169,191,220,.18)}
.nd2-gauge__fill{position:absolute;left:0;top:0;bottom:0;background:var(--cs-cream)}
.nd2-gauge.will-accept .nd2-gauge__fill{background:var(--cs-lime)}
.nd2-gauge.tone-low .nd2-gauge__fill,.nd2-gauge.tone-bad .nd2-gauge__fill{background:var(--cs-coral)}
.nd2-gauge__mark{position:absolute;top:-4px;bottom:-4px;width:2px;margin-left:-1px;background:#fff}
.nd2-gauge__body small{font-size:11px;font-weight:700;color:var(--cs-soft)}
.nd2-body{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:0}
.nd2-offer{padding:12px 16px;display:flex;flex-direction:column;gap:12px;min-width:0}
.nd2-talk{padding:12px 16px;border-left:1px solid rgba(169,191,220,.16);display:flex;flex-direction:column;gap:10px;min-width:0}
.nd2-field__head{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:4px}
.nd2-field__head span,.nd2-field--row > span{font-size:12px;font-weight:800;color:var(--cs-soft)}
.nd2-field__head strong{font-size:18px;font-weight:900;color:var(--cs-cream);font-variant-numeric:tabular-nums}
.nd2-field--row{display:grid;grid-template-columns:78px minmax(0,1fr);gap:8px;align-items:center}
.nd2-scale{display:flex;justify-content:space-between;font-size:10px;font-weight:700;color:var(--cs-soft);margin-top:2px}
.nd2 .nd-range{position:relative}
.nd2 .nd-range input[type="range"]{width:100%;accent-color:var(--cs-orange)}
.nd2 .nd-range__ask{position:absolute;top:2px;bottom:2px;width:2px;background:#fff;pointer-events:none}
.nd2 .nd-seg{display:flex;flex-wrap:wrap;gap:4px;background:none!important;border:0!important;box-shadow:none!important;padding:0!important}
.nd2 .nd-seg button{min-width:32px;padding:5px 9px!important;border:0!important;border-radius:4px!important;background:rgba(169,191,220,.12)!important;color:#d6e2f4!important;font-family:var(--dd-font-ui)!important;font-size:13px!important;font-weight:900!important;box-shadow:none!important;text-shadow:none!important;cursor:pointer}
.nd2 .nd-seg button.is-active{background:var(--cs-cream)!important;color:var(--cs-ink)!important}
.nd2 .nd-seg button em{font-style:normal;font-size:10px;font-weight:800;margin-left:4px;color:var(--cs-orange)}
.nd2 .nd-seg button.is-active em{color:#a8300f}
.nd2 .nd-seg button:disabled{opacity:.45}
.nd2-note{margin:2px 0 0;font-size:11px;font-weight:700;color:var(--cs-soft)}
.nd2-thread{display:flex;flex-direction:column;gap:6px;max-height:180px;overflow-y:auto}
.nd2-bubble{margin:0;padding:8px 10px;background:var(--cs-region);font-size:13px;font-weight:600;line-height:1.35;color:#eef4ff;border-left:3px solid var(--cs-cream)}
.nd2-bubble.is-mood{border-left-color:var(--cs-soft);color:#c9d6ea}
.nd2-verdict{padding:8px 10px;background:var(--cs-ink)}
.nd2-verdict strong{display:block;font-size:13px;font-weight:900;color:var(--cs-cream)}
.nd2-verdict.is-accepted strong,.nd2-verdict.is-signed strong{color:var(--cs-lime)}
.nd2-verdict.is-rejected strong{color:var(--cs-coral)}
.nd2-verdict.is-countered strong{color:var(--cs-orange)}
.nd2-verdict p{margin:4px 0 0;font-size:12px;font-weight:700;color:#d6e2f4}
.nd2-link{margin-left:8px;background:none;border:0;padding:0;color:var(--cs-cyan);font-weight:900;cursor:pointer}
.nd2-more > summary{cursor:pointer;list-style:none;font-size:12px;font-weight:900;color:var(--cs-cyan)}
.nd2-more > summary::-webkit-details-marker{display:none}
.nd2-more[open] > summary{margin-bottom:6px}
.nd2-foot{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;align-items:center;padding:10px 16px;background:var(--cs-region);border-top:3px solid var(--cs-orange)}
.nd2-cap{margin:0;display:flex;flex-wrap:wrap;gap:6px 18px;align-items:flex-end}
.nd2-cap dt{font-size:11px;font-weight:800;color:var(--cs-soft)!important;text-transform:none!important;letter-spacing:0!important}
.nd2-cap dd{margin:0;font-size:16px;font-weight:900;color:#fff;font-variant-numeric:tabular-nums}
.nd2-cap dd small{font-size:10px;font-weight:700;color:var(--cs-soft)}
.nd2-cap dd.is-bad{color:var(--cs-coral)}
.nd2-cap__bar{flex:1 1 100%;height:4px;background:rgba(169,191,220,.18)}
.nd2-cap__bar i{display:block;height:100%;background:var(--cs-cream)}
.nd2-cap__bar i.is-tight{background:var(--cs-orange)}
.nd2-cap__bar i.is-over{background:var(--cs-coral)}
.nd2-error{grid-column:1 / -1;margin:0;font-size:12px;font-weight:800;color:var(--cs-coral)}
.nd2-actions{display:flex;flex-direction:column;align-items:flex-end;gap:4px}
.nd2 .nd2-primary{background:var(--cs-orange)!important;color:#2a1200!important;border:0!important;border-radius:4px!important;box-shadow:none!important;clip-path:none!important;font-family:var(--dd-font-ui)!important;font-size:15px!important;font-weight:900!important;text-shadow:none!important;padding:10px 18px!important;white-space:nowrap}
.nd2 .nd2-primary:hover:not(:disabled){background:var(--cs-cream)!important}
.nd2-text{background:none;border:0;padding:0;color:var(--cs-cyan);font-family:var(--dd-font-ui);font-size:12px;font-weight:900;cursor:pointer}
.nd2-text:disabled,.nd2 .nd2-primary:disabled{opacity:.5;cursor:default}
.nd2-note--foot{padding:0 16px 8px;background:var(--cs-region);margin:0}
@container (max-width:620px){.nd2-hero{grid-template-columns:auto 48px minmax(0,1fr)}.nd2-gap{grid-column:1 / -1;justify-content:start;text-align:left}.nd2-body,.nd2-foot{grid-template-columns:minmax(0,1fr)}.nd2-talk{border-left:0;border-top:1px solid rgba(169,191,220,.16)}.nd2-actions{align-items:stretch}}
@media (max-width:860px){.nd2-hero{grid-template-columns:auto 48px minmax(0,1fr)}.nd2-gap{grid-column:1 / -1;justify-content:start;text-align:left}.nd2-body,.nd2-foot{grid-template-columns:minmax(0,1fr)}.nd2-talk{border-left:0;border-top:1px solid rgba(169,191,220,.16)}}
.nd2-agent.tone-green b{color:#2f7d16}
.nd2-agent.tone-gold b{color:#a8300f}
.nd2-gauge.tone-instant > strong,.nd2-gauge.tone-good > strong{color:var(--cs-lime)}

/* Free agency uses the same desk (nd2--fa): the right column is the market. */
.nd2--fa .nd2-hero{grid-template-columns:0 56px minmax(0,1fr) auto;gap:16px;padding:16px 18px}
.nd2--fa .nd2-offer,.nd2--fa .nd2-talk{padding:16px 18px;gap:14px}
.nd2--fa .nd2-body{gap:0}
.fa-root .fa-fa-desk .nd2{min-height:100%}
.nd2--fa .nd2-who h3 [class*="rights-badge"]{font-size:11px;vertical-align:middle}
.nd2-market{display:grid;gap:6px}
.nd2-market__label{display:block;font-size:12px;font-weight:800;color:var(--cs-soft)}
.nd2-market__row{display:grid;grid-template-columns:20px minmax(0,1fr) auto;gap:8px;align-items:center;font-size:13px}
.nd2-market__row strong{font-weight:900;color:#fff}
.nd2-market__row em{font-style:normal;font-weight:900;color:var(--cs-cream);font-variant-numeric:tabular-nums}
.nd2-market__row.is-you strong,.nd2-market__row.is-you em{color:var(--cs-orange)}
.nd2-market__logos{display:flex;flex-wrap:wrap;gap:6px}
.nd2-warn{color:var(--cs-coral)!important}
.nd2-stats{margin:6px 0;display:flex;flex-wrap:wrap;gap:4px 16px}
.nd2-stats dt{font-size:11px;font-weight:800;color:var(--cs-soft)!important;text-transform:none!important;letter-spacing:0!important}
.nd2-stats dd{margin:0;font-size:15px;font-weight:900;color:#fff}
.nd2-pctile{display:grid;grid-template-columns:90px minmax(0,1fr) 44px;gap:8px;align-items:center;font-size:12px;margin-top:3px}
.nd2-pctile span{color:#d6e2f4;font-weight:700}
.nd2-pctile i{display:block;height:5px;background:rgba(169,191,220,.18)}
.nd2-pctile i b{display:block;height:100%;background:var(--cs-blue)}
.nd2-pctile strong{text-align:right;font-weight:900;color:var(--cs-blue)}
.nd2-history p{margin:3px 0 0;font-size:12px;color:#c9d6ea}
.nd2-history strong{color:#fff}
.fa-root .fa-fa-desk{background:var(--cs-deep)!important;padding:0!important}

/* The decision stays in reach: the cap/action footer sticks to the bottom of the desk. */
.nd2 .nd2-foot{position:sticky;bottom:0;z-index:3;box-shadow:0 -10px 18px rgba(5,12,44,.55)}
/* While negotiating, the desk hero replaces the panel identity and tabs. */
.resign-root .resign-table-layout.is-negotiating .resign-detail-panel > :is(.resign-identity,.resign-detail-tabs){display:none!important}
.resign-root .resign-table-layout.is-negotiating .resign-detail-panel{box-shadow:none!important;background:transparent!important}
/* Desks respond to the column they sit in (free agency puts the desk in a ~420px column). */
.fa-root .fa-fa-desk,.resign-root .resign-detail-panel{container-type:inline-size}
@container (max-width:620px){.nd2--fa .nd2-hero{grid-template-columns:0 48px minmax(0,1fr)}}

/* The hub's first-run tour belongs to the hub; it was drawing over offseason screens. */
:root:has(.nhldev-root,.draftreview-root,.prospectrights-root,.resign-root,.fa-root,.cap-report-page,.bog-root,.an-root,.retirement-page,.nextseason-root,.dlot-root,.cleanup-root) .office-tour{display:none!important}

/* Development report: open rows, the rating change as the headline number, lime for
   gains and coral for drops, the reason as the player's own line. */
.nhldev-root .nhldev-prospect-row{background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;border-bottom:1px solid rgba(169,191,220,.14)!important}
.nhldev-root .nhldev-avatar{background:var(--cs-ink)!important;border:0!important;border-radius:0!important;clip-path:polygon(0 0,100% 0,100% 76%,76% 100%,0 100%);overflow:hidden}
.nhldev-root .nhldev-row-head strong,.nhldev-root .nhldev-row-head h3,.nhldev-root .nhldev-row-head h4{color:var(--cs-cream)!important;font-family:var(--dd-font-ui)!important;font-weight:900!important;text-transform:none!important}
.nhldev-root .nhldev-row-ovr{color:#fff!important;font-weight:900!important}
.nhldev-root .nhldev-row-meta{color:var(--cs-soft)!important;text-transform:none!important;letter-spacing:0!important}
.nhldev-root .nhldev-ovr-shift{color:#fff!important;font-weight:900!important}
.nhldev-root .nhldev-delta-pill{background:transparent!important;border:0!important;box-shadow:none!important;padding:0 0 0 6px!important;font-weight:900!important;color:var(--cs-lime)!important}
.nhldev-root .nhldev-delta-pill:is(.is-down,.tone-down,.is-negative,.is-regressed){color:var(--cs-coral)!important}
.nhldev-root .nhldev-reason-text{color:#d6e2f4!important;font-weight:700!important}
.nhldev-root .nhldev-group-head{background:transparent!important;border:0!important;box-shadow:none!important;text-transform:none!important;letter-spacing:0!important;color:#fff!important;font-weight:900!important}
.nhldev-root .nhldev-summary-line{text-transform:none!important;letter-spacing:0!important}
.nhldev-root .nhldev-delta-pill.down{color:var(--cs-coral)!important}
.nhldev-root .nhldev-delta-pill.neutral{color:var(--cs-soft)!important}

/* Draft lottery board: open rows in the command-sheet language. The pick number is the
   headline, the team in cream, lime for a jump, coral for a drop, your club in orange. */
.dlot-root .dlot-board{gap:0;container-type:inline-size}
.dlot-root .dlot-board-row{grid-template-columns:52px 40px minmax(0,1fr) 84px 110px;gap:10px;padding:6px 8px;border:0!important;border-bottom:1px solid rgba(169,191,220,.14)!important;border-radius:0;background:transparent!important}
.dlot-root .dlot-board-row.is-user{box-shadow:inset 3px 0 0 var(--cs-orange);background:rgba(255,138,31,.08)!important}
.dlot-root .dlot-board-row.is-jump .dlot-board-pick{color:var(--cs-lime)}
.dlot-root .dlot-board-row .dlot-logo.md{width:36px;height:36px}
.dlot-root .dlot-board-pick{font-variant-numeric:tabular-nums}
.dlot-root .dlot-board-team strong{color:var(--cs-cream)}
.dlot-root .dlot-board-team strong small{font-size:.75rem;font-weight:700;color:var(--cs-soft)}
.dlot-root .dlot-board-row.is-user .dlot-board-team span{color:var(--cs-orange);font-weight:800}
.dlot-root .dlot-board-col{color:var(--cs-soft);font-variant-numeric:tabular-nums}
@container (max-width:520px){.dlot-root .dlot-board-row{grid-template-columns:40px 32px minmax(0,1fr) auto}.dlot-root .dlot-board-row > .dlot-board-col:nth-last-child(2){display:none}}
.dlot-root .dlot-chip.tone-up{color:var(--cs-lime)!important}
.dlot-root .dlot-chip.tone-down{color:var(--cs-coral)!important}
.dlot-root .dlot-chip.tone-hold{color:var(--cs-soft)!important}
.dlot-root .dlot-board .dlot-chip{background:transparent!important;border:0!important;padding:0!important;font-weight:900}

/* Combine leaders strip: a thin, quiet scrollbar instead of the global orange one. */
.dcb-leaders{scrollbar-width:thin;scrollbar-color:rgba(169,191,220,.35) transparent}
.dcb-leaders::-webkit-scrollbar{height:4px}
.dcb-leaders::-webkit-scrollbar-thumb{background:rgba(169,191,220,.35);border-radius:0}
.dcb-leaders::-webkit-scrollbar-track,.dcb-leaders::-webkit-scrollbar-button{background:transparent;display:none}

/* Roster check chips: plain counts, coral only where a rule is broken. */
.cleanup-root .cleanup-chip{text-transform:none!important;letter-spacing:0!important;color:var(--cs-cream)!important}
.cleanup-root .cleanup-chip.is-blocked{color:var(--cs-coral)!important;border-color:rgba(255,107,92,.5)!important}
.cleanup-root .cleanup-chip.is-ready{color:var(--cs-lime)!important}

/* Development report sat on an 8%-alpha gradient, so the hub showed through. Solid navy base. */
.nhldev-root{background-color:var(--cs-deep,#0b1730)!important}
.dlot-root .dlot-board-col{background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important}
.dcb-root :is(.dcb-leaders,.dcb-table-wrap,.dcb-timeline-wrap),:is(.dcb-leaders,.dcb-table-wrap,.dcb-timeline-wrap){scrollbar-width:thin!important;scrollbar-color:rgba(169,191,220,.35) transparent!important}
:is(.dcb-leaders,.dcb-table-wrap,.dcb-timeline-wrap)::-webkit-scrollbar{height:4px!important;width:4px!important}
:is(.dcb-leaders,.dcb-table-wrap,.dcb-timeline-wrap)::-webkit-scrollbar-thumb{background:rgba(169,191,220,.35)!important;border:0!important;border-radius:0!important}
:is(.dcb-leaders,.dcb-table-wrap,.dcb-timeline-wrap)::-webkit-scrollbar-track{background:transparent!important}

/* Line ice-time steppers (replaces the range slider whose thumb the global range skin broke). */
.lb-deploy-share{min-width:0!important;gap:4px!important}
.lb-share-step{width:24px;height:24px;border:1px solid rgba(255,255,255,.2);border-radius:4px;background:rgba(255,255,255,.06);color:#fff;font-size:15px;font-weight:900;line-height:1;cursor:pointer;padding:0}
.lb-share-step:hover:not(:disabled){background:#2ee6d6;color:#062036}
.lb-share-step:disabled{opacity:.3;cursor:default}
.lb-share-step.is-text{width:auto;min-width:24px;padding:0 8px;font-size:11px;font-weight:700;letter-spacing:.02em}
.lb-share-step.is-active{background:#2ee6d6;color:#062036}
.lb-deploy-share > span{text-align:center}

/* Storylines player file: how he feels and his life in the room. Lime = good, coral = bad. */
.sl-feel{margin:10px 0;padding:10px 14px;background:rgba(8,18,46,.55);border-left:3px solid var(--cs-soft,#a9bfdc)}
.sl-feel--good{border-left-color:var(--cs-lime,#9be564)}
.sl-feel--warn{border-left-color:var(--cs-orange,#ff8a1f)}
.sl-feel--bad{border-left-color:var(--cs-coral,#ff6b5c)}
.sl-feel__head{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 12px}
.sl-feel__head span{font-size:12px;font-weight:800;color:var(--cs-soft,#a9bfdc)}
.sl-feel__head strong{font-size:20px;font-weight:900;color:#fff}
.sl-feel--good .sl-feel__head strong{color:var(--cs-lime,#9be564)}
.sl-feel--bad .sl-feel__head strong{color:var(--cs-coral,#ff6b5c)}
.sl-feel--warn .sl-feel__head strong{color:var(--cs-orange,#ff8a1f)}
.sl-feel__head em{font-style:normal;font-size:12px;font-weight:700;color:var(--cs-soft,#a9bfdc)}
.sl-feel__why{margin:6px 0 0;padding-left:18px;font-size:13px;font-weight:600;color:#d6e2f4}
.sl-life__bonds h4{margin:0 0 6px;font-size:13px;color:var(--cs-soft,#a9bfdc)}
.sl-life__bonds ul{list-style:none;margin:0 0 10px;padding:0;display:flex;flex-wrap:wrap;gap:6px 16px}
.sl-life__bonds li span{font-weight:800;color:var(--cs-cream,#fff3d6)}
.sl-life__bonds li em{font-style:normal;margin-left:6px;font-size:12px;font-weight:700;color:var(--cs-lime,#9be564)}
.sl-life__bonds li.is-friction em{color:var(--cs-coral,#ff6b5c)}
.sl-life__feed{list-style:none;margin:0;padding:0}
.sl-life__feed li{padding:8px 0 8px 10px;border-bottom:1px solid rgba(169,191,220,.14);border-left:3px solid rgba(169,191,220,.3)}
.sl-life__feed li.is-good{border-left-color:var(--cs-lime,#9be564)}
.sl-life__feed li.is-bad{border-left-color:var(--cs-coral,#ff6b5c)}
.sl-life__feed li span{font-size:11px;font-weight:800;color:var(--cs-soft,#a9bfdc)}
.sl-life__feed li p{margin:2px 0 0;font-size:13px;font-weight:600;line-height:1.4;color:#eef4ff}

/* PuckGPT — a chat desk over the save. Uses the office tokens, not a separate theme. */
.puckgpt-screen {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 22px 28px 20px;
  color: var(--cs-cream, #fff3d6);
  background:
    radial-gradient(1200px 420px at 10% -10%, rgba(248, 213, 138, 0.08), transparent 55%),
    linear-gradient(180deg, rgba(8, 18, 46, 0.2), rgba(8, 18, 46, 0.55));
}
.puckgpt-bar {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  border-bottom: 1px solid var(--office-line-strong, rgba(248, 213, 138, 0.35));
  padding-bottom: 10px;
}
.puckgpt-bar__actions { display: flex; gap: 8px; }
.puckgpt-mark {
  font-family: var(--font-office-display);
  letter-spacing: 0.22em;
  font-size: 1.15rem;
  color: var(--office-brass, #f8d58a);
}
.puckgpt-bar p { margin: 4px 0 0; color: var(--cs-soft, #a9bfdc); font-size: 13px; }
.puckgpt-back,
.puckgpt-go,
.puckgpt-chip,
.puckgpt-card {
  font-family: var(--font-office-display);
  letter-spacing: 0.04em;
  border: 1px solid var(--office-line-strong, rgba(248, 213, 138, 0.35));
  background: rgba(8, 18, 46, 0.55);
  color: var(--cs-cream, #fff3d6);
  border-radius: 4px;
  cursor: pointer;
}
.puckgpt-back { padding: 6px 12px; }
.puckgpt-back:hover,
.puckgpt-go:hover:not(:disabled),
.puckgpt-chip:hover,
.puckgpt-card:hover { background: var(--office-brass, #f8d58a); color: #1a1408; }
.puckgpt-thread {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding-right: 6px;
}
.puckgpt-empty h2 { margin: 18px 0 12px; font-size: 24px; font-weight: 800; }
.puckgpt-empty h3 { margin: 20px 0 8px; font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--cs-soft, #a9bfdc); }
.puckgpt-turn { display: flex; flex-direction: column; gap: 8px; }
.puckgpt-q {
  align-self: flex-end;
  max-width: 70%;
  margin: 0;
  padding: 8px 12px;
  border-radius: 4px;
  background: rgba(248, 213, 138, 0.14);
  border: 1px solid rgba(248, 213, 138, 0.3);
  font-size: 15px;
  font-weight: 700;
}
.puckgpt-thinking { margin: 0; color: var(--cs-soft, #a9bfdc); font-style: italic; }
.puckgpt-reply {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 14px;
  background: rgba(6, 14, 36, 0.6);
  border-left: 3px solid var(--office-brass, #f8d58a);
}
.puckgpt-readas { font-size: 12px; color: var(--cs-soft, #a9bfdc); }
.puckgpt-readas span { text-transform: uppercase; letter-spacing: 0.12em; margin-right: 4px; }
.puckgpt-readas b { margin-left: 6px; color: var(--cs-lime, #9be564); }
.puckgpt-readas.is-medium b { color: var(--office-brass, #f8d58a); }
.puckgpt-readas.is-low b { color: var(--cs-coral, #ff6b5c); }
.puckgpt-answer { margin: 0; font-size: 20px; font-weight: 800; line-height: 1.3; }
.puckgpt-analysis { margin: 0; padding-left: 18px; color: #d6e2f4; font-size: 14px; line-height: 1.5; }
.puckgpt-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.puckgpt-chip { padding: 6px 10px; font-size: 13px; display: inline-flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; }
.puckgpt-chip small { font-family: inherit; font-size: 11px; opacity: 0.7; letter-spacing: 0; }
.puckgpt-chip--ghost { border-style: dashed; }
.puckgpt-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 8px; }
.puckgpt-card { padding: 8px 10px; display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; }
.puckgpt-card b { font-size: 14px; }
.puckgpt-card span { font-size: 12px; opacity: 0.8; }
.puckgpt-table-wrap { overflow-x: auto; max-height: 360px; overflow-y: auto; }
.puckgpt-table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; }
.puckgpt-table th {
  position: sticky;
  top: 0;
  background: rgba(8, 18, 46, 0.95);
  text-align: left;
  padding: 6px 8px;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--office-brass, #f8d58a);
  border-bottom: 1px solid var(--office-line-strong, rgba(248, 213, 138, 0.35));
}
.puckgpt-table td { padding: 6px 8px; border-bottom: 1px solid rgba(169, 191, 220, 0.12); color: #e6eefb; white-space: nowrap; }
.puckgpt-table tr.is-link { cursor: pointer; }
.puckgpt-table tr.is-link:hover td { background: rgba(248, 213, 138, 0.1); }
.puckgpt-meta { margin: 0; font-size: 11px; color: var(--cs-soft, #a9bfdc); opacity: 0.7; }
.puckgpt-search { display: flex; gap: 8px; }
.puckgpt-query {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border-radius: 4px;
  border: 1px solid var(--office-line-strong, rgba(248, 213, 138, 0.35));
  background: rgba(6, 14, 36, 0.72);
  color: #fff;
  font-size: 16px;
}
.puckgpt-go { padding: 0 18px; font-size: 15px; }
.puckgpt-go:disabled { opacity: 0.55; cursor: default; }
.puckgpt-error { color: var(--cs-coral, #ff6b5c); margin: 0; }
@media (max-width: 640px) {
  .puckgpt-screen { padding: 14px 16px; }
  .puckgpt-q { max-width: 90%; }
}


/* ==========================================================================
   ONE STYLESHEET. Everything below used to live in per-screen .css files or in
   <style> blocks inside the screen components. It is all here now; screens do
   not ship their own CSS any more. Screen-only rules are wrapped in
   :where(:root:has(.screen-root)) so they apply only while that screen is up
   (same as when the <style> lived in the component) and add no specificity.
   ========================================================================== */

/* ===== screen sheet: events/awardsNight/awardsNight.dd.css ===== */
/* Awards Night in the Double Dash house style: a gala, not a dashboard.
   Stage blue under gold spotlights, a red-carpet top bar, trophy plaques for the
   running order, gold-framed result cards. Scoped to .an-root.an-broadcast.an-dd so it
   wins over the flat skin in styles/game.css (~30790), answering its !important rules
   on the same properties only. */

.an-root.an-broadcast.an-dd {
  --an-gold: var(--dd-gold, #c98a3c);
  --an-gold-hi: var(--dd-gold-hi, #f8d58a);
  --an-gold-lo: var(--dd-gold-lo, #6e4314);
  --an-yellow: var(--dd-yellow, #ffe23a);
  --an-cream: var(--dd-cream, #ffe7c4);
  --an-ink: var(--dd-outline, #1a0d05);
  --an-red: var(--dd-lacquer, #a8300f);
  --an-red-hi: var(--dd-lacquer-hi, #e0521f);
  --an-red-lo: var(--dd-lacquer-lo, #5e1606);
  --an-plate: rgba(8, 18, 62, 0.9);
  font-family: var(--dd-font-ui, "Nunito", sans-serif);
  color: var(--an-cream);
  background:
    radial-gradient(ellipse 34% 60% at 50% -12%, rgba(255, 226, 58, 0.30), transparent 70%),
    radial-gradient(ellipse 24% 50% at 14% -6%, rgba(248, 213, 138, 0.16), transparent 70%),
    radial-gradient(ellipse 24% 50% at 86% -6%, rgba(248, 213, 138, 0.16), transparent 70%),
    radial-gradient(circle at 1px 1px, rgba(255, 255, 255, 0.06) 1px, transparent 1.6px) 0 0 / 16px 16px,
    linear-gradient(180deg, var(--dd-stage, #0b1d5c) 0%, var(--dd-stage-deep, #050c2c) 100%);
}

/* ---- red carpet top bar ---- */
.an-root.an-broadcast.an-dd .an-topbar {
  background: linear-gradient(180deg, var(--an-red-hi), var(--an-red) 60%, var(--an-red-lo));
  border-bottom: 4px solid var(--an-gold-hi);
  box-shadow: 0 5px 0 var(--an-ink);
}
.an-root.an-broadcast.an-dd .an-page-title {
  font-size: 34px;
  line-height: 1;
  color: var(--an-yellow);
  -webkit-text-stroke: 2px var(--an-ink);
  paint-order: stroke fill;
  text-shadow: 0 4px 0 var(--an-ink), 3px 6px 0 var(--an-gold-lo);
  transform: rotate(-1.2deg);
}
.an-root.an-broadcast.an-dd .an-season { color: var(--an-cream); font-weight: 800; }
.an-root.an-broadcast.an-dd .an-milestones span { color: rgba(255, 231, 196, 0.72) !important; font-weight: 800; }
.an-root.an-broadcast.an-dd .an-milestones .is-current {
  color: var(--an-ink) !important;
  background: var(--an-yellow);
  border-radius: 4px;
  padding: 1px 7px;
  box-shadow: none !important;
}
.an-root.an-broadcast.an-dd .an-ghost-btn {
  font-family: var(--dd-font-display, "Luckiest Guy", sans-serif);
  letter-spacing: 0.04em;
  text-transform: uppercase !important;
  color: var(--an-ink);
  background: var(--an-cream);
  border: 2px solid var(--an-ink);
  border-radius: 6px;
  box-shadow: 0 3px 0 var(--an-ink);
  padding: 5px 10px;
}
.an-root.an-broadcast.an-dd .an-ghost-btn:hover { background: var(--an-yellow); }
.an-root.an-broadcast.an-dd .an-ghost-btn.is-on { background: var(--an-gold-hi); }

/* ---- running order: trophy plaques ---- */
.an-root.an-broadcast.an-dd .an-log,
.an-root.an-broadcast.an-dd .an-board { background: transparent; border: 0; box-shadow: none; }
.an-root.an-broadcast.an-dd .an-section-title {
  font-family: var(--dd-font-display, "Luckiest Guy", sans-serif);
  font-weight: 400;
  font-size: 18px;
  letter-spacing: 0.03em;
  color: var(--an-yellow);
  -webkit-text-stroke: 1px var(--an-ink);
  paint-order: stroke fill;
  text-shadow: 0 2px 0 var(--an-ink);
}
.an-root.an-broadcast.an-dd .an-log-row {
  margin: 0 0 6px;
  padding: 7px 10px;
  border: 2px solid var(--an-gold);
  border-color: var(--an-gold-hi) var(--an-gold) var(--an-gold-lo) var(--an-gold);
  border-radius: 6px;
  background: linear-gradient(180deg, rgba(110, 67, 20, 0.35), rgba(8, 18, 62, 0.85));
  color: var(--an-cream);
}
.an-root.an-broadcast.an-dd .an-log-row:hover { filter: brightness(1.12); }
.an-root.an-broadcast.an-dd .an-log-row.is-current,
.an-root.an-broadcast.an-dd .an-log-row[aria-current="true"] {
  background: linear-gradient(180deg, var(--an-gold-hi), var(--an-gold));
  color: var(--an-ink);
}
.an-root.an-broadcast.an-dd .an-log-num {
  font-family: var(--dd-font-display, "Luckiest Guy", sans-serif);
  color: var(--an-yellow);
  -webkit-text-stroke: 1px var(--an-ink);
  paint-order: stroke fill;
}

/* ---- the stage: gold frame, spotlight on the winner ---- */
.an-root.an-broadcast.an-dd .an-stagehead,
.an-root.an-broadcast.an-dd .an-card,
.an-root.an-broadcast.an-dd .an-dock {
  background: var(--an-plate) !important;
  border: 3px solid var(--an-gold) !important;
  border-color: var(--an-gold-hi) var(--an-gold) var(--an-gold-lo) var(--an-gold) !important;
  border-radius: 10px;
  box-shadow: 0 0 0 2px var(--an-ink), 0 8px 0 rgba(0, 0, 0, 0.45) !important;
}
.an-root.an-broadcast.an-dd .an-stagehead {
  background:
    radial-gradient(ellipse 60% 120% at 50% -30%, rgba(255, 226, 58, 0.22), transparent 70%),
    var(--an-plate) !important;
}
.an-root.an-broadcast.an-dd .an-stagehead-num {
  font-family: var(--dd-font-display, "Luckiest Guy", sans-serif) !important;
  font-weight: 400 !important;
  color: var(--an-yellow) !important;
  -webkit-text-stroke: 1.5px var(--an-ink);
  paint-order: stroke fill;
  text-shadow: 0 3px 0 var(--an-ink);
}
.an-root.an-broadcast.an-dd .an-stagehead-title,
.an-root.an-broadcast.an-dd .an-result-title {
  font-family: var(--dd-font-display, "Luckiest Guy", sans-serif);
  font-weight: 400;
  font-size: 30px;
  line-height: 1.02;
  letter-spacing: 0.01em;
  color: var(--an-yellow);
  -webkit-text-stroke: 1.5px var(--an-ink);
  paint-order: stroke fill;
  text-shadow: 0 3px 0 var(--an-ink), 3px 5px 0 var(--an-red);
}
.an-root.an-broadcast.an-dd .an-z-result,
.an-root.an-broadcast.an-dd .an-result-peak {
  background: linear-gradient(180deg, rgba(248, 213, 138, 0.16), transparent);
  border-radius: 8px;
}
.an-root.an-broadcast.an-dd .an-name,
.an-root.an-broadcast.an-dd .an-votes__name { font-weight: 900; color: #fff; }
.an-root.an-broadcast.an-dd .an-headshot {
  border: 3px solid var(--an-gold-hi);
  box-shadow: 0 0 0 3px var(--an-ink), 0 0 26px rgba(255, 226, 58, 0.35);
  border-radius: 50%;
}
.an-root.an-broadcast.an-dd .an-why {
  border-left: 4px solid var(--an-yellow);
  background: rgba(255, 226, 58, 0.08);
  padding: 8px 12px;
  border-radius: 0 6px 6px 0;
}
.an-root.an-broadcast.an-dd .an-finalist__label {
  font-family: var(--dd-font-display, "Luckiest Guy", sans-serif);
  color: var(--an-gold-hi);
  letter-spacing: 0.04em;
  text-transform: uppercase !important;
}

/* tables: gold-ruled ledger rows instead of grey grid */
.an-root.an-broadcast.an-dd .an-table-head {
  color: var(--an-gold-hi);
  border-bottom: 2px solid var(--an-gold);
  font-weight: 900;
}
.an-root.an-broadcast.an-dd .an-table-row { border-bottom: 1px dashed rgba(248, 213, 138, 0.22); }
.an-root.an-broadcast.an-dd .an-table-row:first-child .an-cell-name { color: var(--an-yellow); }
.an-root.an-broadcast.an-dd .an-num { font-variant-numeric: tabular-nums; }
.an-root.an-broadcast.an-dd .an-muted,
.an-root.an-broadcast.an-dd .an-cell-muted,
.an-root.an-broadcast.an-dd .an-section-meta { color: rgba(255, 231, 196, 0.68); }

/* ---- "How it's decided": the plain-language rule for every trophy ---- */
.an-root.an-broadcast.an-dd .an-criteria {
  margin: 10px 0 0;
  padding: 10px 14px;
  background: var(--an-cream);
  color: var(--an-ink);
  border-radius: 4px;
  box-shadow: 0 0 0 2px var(--an-ink), 4px 5px 0 var(--an-gold-lo);
  font-weight: 700;
  font-size: 13px;
  line-height: 1.45;
}
.an-root.an-broadcast.an-dd .an-criteria b {
  display: block;
  margin-bottom: 2px;
  font-family: var(--dd-font-display, "Luckiest Guy", sans-serif);
  font-weight: 400;
  letter-spacing: 0.03em;
  color: var(--an-red);
  text-transform: uppercase !important;
}

/* ---- dock: the big lacquer button is the next step ---- */
.an-root.an-broadcast.an-dd .an-dock-state { color: var(--an-cream); font-weight: 800; }

/* fan pulse keeps its own feed, framed like the rest */
.an-root.an-broadcast.an-dd .an-pulse-lane { background: transparent; }

@media (prefers-reduced-motion: reduce) {
  .an-root.an-broadcast.an-dd .an-page-title { transform: none; }
}

/* ===== screen sheet: components/storylines/gossip.css ===== */
/* The Bench Buzz: Storylines as a hockey gossip rag on the Double Dash stage.
   Scoped to .nhlcal-sl-root.storylines-skin.sl-gossip (three classes) so it wins over the
   screen's inline sheet, which scopes at two. Newsprint clippings carry the stories;
   the stage blue, lacquer red, yellow and hot pink carry the furniture. */

.nhlcal-sl-root.storylines-skin.sl-gossip {
  --gz-paper: #fff4dc;
  --gz-paper-2: #ffe9bf;
  --gz-ink: #1b1209;
  --gz-ink-soft: #5b4630;
  --gz-pink: #ff3d8b;
  --gz-yellow: var(--dd-yellow, #ffe23a);
  --gz-red: var(--dd-lacquer, #a8300f);
  --gz-red-hi: var(--dd-lacquer-hi, #e0521f);
  --gz-cyan: #36d6ff;
  --gz-lime: #9be22d;
  --gz-stage: var(--dd-stage, #0b1d5c);
  --gz-stage-deep: var(--dd-stage-deep, #050c2c);
  --gz-gold: var(--dd-gold, #c98a3c);
  --gz-gold-hi: var(--dd-gold-hi, #f8d58a);
  --gz-outline: var(--dd-outline, #1a0d05);
  --gz-display: var(--dd-font-display, "Luckiest Guy", "Archivo Black", sans-serif);
  --gz-ui: var(--dd-font-ui, "Nunito", sans-serif);
  /* the inline sheet's own tokens, re-pointed so panels it styles follow the new palette */
  --bg-deep: var(--gz-stage-deep);
  --panel: rgba(10, 22, 70, 0.92);
  --panel-2: rgba(14, 30, 88, 0.9);
  --panel-3: rgba(8, 18, 58, 0.96);
  --line: rgba(248, 213, 138, 0.22);
  --line-2: rgba(248, 213, 138, 0.38);
  font-family: var(--gz-ui);
  color: var(--dd-cream, #ffe7c4);
  background:
    radial-gradient(circle at 1px 1px, rgba(255, 255, 255, 0.07) 1px, transparent 1.6px) 0 0 / 14px 14px,
    radial-gradient(ellipse 70% 45% at 50% -10%, rgba(255, 61, 139, 0.22), transparent 70%),
    linear-gradient(180deg, var(--gz-stage) 0%, var(--gz-stage-deep) 100%);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-atmos { display: none; }

/* ---------------- masthead: a tabloid nameplate, not a stat strip ---------------- */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: 18px;
  padding: 10px 22px 12px;
  background: var(--gz-red);
  background-image: linear-gradient(180deg, var(--gz-red-hi), var(--gz-red) 60%, var(--dd-lacquer-lo, #5e1606));
  border: 0;
  border-bottom: 5px solid var(--gz-yellow);
  border-radius: 0;
  box-shadow: 0 6px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command__crest {
  width: 62px; height: 62px; border-radius: 50%;
  background: var(--gz-paper); border: 3px solid var(--gz-yellow); box-shadow: 0 3px 0 var(--gz-outline);
  display: grid; place-items: center; overflow: hidden;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command__crest img { width: 48px; height: 48px; object-fit: contain; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-nameplate {
  margin: 0;
  font-family: var(--gz-display);
  font-weight: 400;
  font-size: 46px;
  line-height: 0.95;
  letter-spacing: 0.01em;
  color: var(--gz-yellow);
  -webkit-text-stroke: 2px var(--gz-outline);
  paint-order: stroke fill;
  text-shadow: 0 4px 0 var(--gz-outline), 4px 6px 0 var(--gz-pink);
  transform: rotate(-1.5deg);
  transform-origin: left center;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command__sub {
  display: flex; flex-wrap: wrap; gap: 0; margin: 6px 0 0;
  font-size: 12px; font-weight: 800; color: var(--gz-paper);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command__sub span + span::before { content: "•"; margin: 0 8px; color: var(--gz-yellow); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk-sticker {
  display: grid; justify-items: center; gap: 0; padding: 8px 14px 9px;
  background: var(--gz-yellow); color: var(--gz-outline);
  border: 3px solid var(--gz-outline); border-radius: 50% 46% 52% 48% / 44% 52% 48% 56%;
  transform: rotate(4deg); cursor: pointer; font-family: var(--gz-ui);
  box-shadow: 0 4px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk-sticker strong { font: 400 28px/1 var(--gz-display); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk-sticker span { font-size: 10px; font-weight: 900; text-transform: uppercase; letter-spacing: 0.04em; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk-sticker:hover { transform: rotate(0deg) scale(1.05); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command__nav { display: flex; gap: 8px; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command__nav button {
  font: 400 14px var(--gz-display); letter-spacing: 0.04em; text-transform: uppercase;
  color: var(--gz-outline); background: var(--gz-paper); border: 3px solid var(--gz-outline);
  border-radius: 6px; padding: 6px 12px; box-shadow: 0 3px 0 var(--gz-outline); cursor: pointer;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command__nav button:hover { background: var(--gz-yellow); }

/* ---------------- ticker: a scrolling "overheard" banner ---------------- */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-ticker {
  margin: 0; border-radius: 0; border: 0;
  background: var(--gz-outline); border-bottom: 3px solid var(--gz-pink);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-ticker__flag {
  background: var(--gz-pink); color: #fff; font: 400 14px var(--gz-display); letter-spacing: 0.04em;
  border-radius: 0; text-transform: uppercase; padding: 0 14px;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-ticker__dot { background: var(--gz-yellow); box-shadow: none; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-ticker__item { color: var(--gz-paper); font-weight: 800; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-ticker__item i { font-style: normal; font-weight: 900; text-transform: uppercase; margin-right: 6px; }

/* ---------------- section strip: newspaper sections, no glyphs or badges ---------------- */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts {
  display: flex; flex-wrap: wrap; gap: 4px 2px; padding: 10px 18px 0;
  background: transparent; border: 0; border-bottom: 3px solid var(--gz-yellow);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts button {
  position: relative;
  padding: 7px 12px 6px; margin: 0;
  font: 900 13px var(--gz-ui); letter-spacing: 0.01em; text-transform: none;
  color: var(--gz-paper); background: rgba(255, 244, 220, 0.08);
  border: 0; border-radius: 8px 8px 0 0; box-shadow: none;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts button:hover { background: rgba(255, 244, 220, 0.18); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts button.is-active {
  background: var(--gz-yellow); color: var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts button em { display: none; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-dept-count {
  position: static; display: inline; margin-left: 3px; padding: 0; background: none; border: 0;
  font-size: 10px; font-weight: 900; color: var(--gz-pink); min-width: 0; height: auto;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts button.is-active .sl-dept-count { color: var(--gz-red); }

/* ---------------- lead story: the front-page splash ---------------- */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead {
  display: grid; grid-template-columns: 210px 1fr; gap: 26px; align-items: start;
  margin: 18px 22px 8px; padding: 22px 26px 22px 22px;
  background: var(--gz-paper); color: var(--gz-ink);
  border: 0; border-radius: 2px;
  box-shadow: 0 0 0 4px var(--gz-outline), 10px 12px 0 var(--gz-pink);
  transform: rotate(-0.4deg);
  overflow: visible;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__glow { display: none; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__portrait {
  position: relative; display: grid; justify-items: center; gap: 10px;
  padding: 14px 10px 12px; background: var(--gz-stage); border: 4px solid var(--gz-outline);
  transform: rotate(-3deg); box-shadow: 4px 5px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__sticker {
  position: absolute; top: -18px; right: -26px; z-index: 2;
  padding: 10px 12px; max-width: 120px; text-align: center;
  font: 400 17px/1 var(--gz-display); text-transform: uppercase; letter-spacing: 0.02em;
  background: var(--gz-yellow); color: var(--gz-outline);
  border: 3px solid var(--gz-outline); border-radius: 50%;
  transform: rotate(12deg); box-shadow: 0 3px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__heat {
  font: 900 11px var(--gz-ui); text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--gz-yellow);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__kickers { display: flex; gap: 10px; align-items: center; margin-bottom: 6px; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__age { color: var(--gz-ink-soft); font-weight: 800; font-size: 12px; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__headline {
  margin: 0 0 10px;
  font: 400 44px/1 var(--gz-display);
  letter-spacing: 0.005em;
  color: var(--gz-ink);
  text-wrap: balance;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__summary {
  margin: 0 0 12px; max-width: 68ch;
  font: 700 16px/1.45 var(--gz-ui); color: var(--gz-ink);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__summary::first-letter {
  float: left; font: 400 46px/0.86 var(--gz-display); color: var(--gz-red); margin: 4px 6px 0 0;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__meta {
  display: flex; flex-wrap: wrap; gap: 4px 18px; padding-top: 10px;
  border-top: 2px dashed rgba(27, 18, 9, 0.3); color: var(--gz-ink);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__meta span { font-weight: 800; font-size: 13px; color: var(--gz-ink); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__meta em {
  display: inline; margin-right: 5px; font-style: normal; font-size: 11px; font-weight: 900;
  text-transform: uppercase; letter-spacing: 0.04em; color: var(--gz-red);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__open {
  margin-top: 14px; background: none; border: 0; padding: 0; cursor: pointer;
  font: 400 16px var(--gz-display); color: var(--gz-red); text-transform: uppercase; letter-spacing: 0.02em;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__open::after { content: " »"; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__open:hover { color: var(--gz-pink); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead .sl-pm-cause,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead .sl-effects { color: var(--gz-ink); }

/* category stamp: ink on paper, accent kept from the story category */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-cat {
  background: transparent !important;
  border: 2px solid currentColor !important;
  border-radius: 3px; padding: 2px 7px;
  font: 900 11px var(--gz-ui); text-transform: uppercase; letter-spacing: 0.05em;
  filter: saturate(1.2) brightness(0.62);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-cat em { display: none; }

/* ---------------- the rumour mill: clippings pinned to the board ---------------- */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-gridhead,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-week__head {
  display: flex; align-items: baseline; gap: 12px; margin: 18px 22px 10px; padding: 0; border: 0;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-gridhead h3 {
  margin: 0; font: 400 30px/1 var(--gz-display); color: var(--gz-yellow);
  -webkit-text-stroke: 1.5px var(--gz-outline); paint-order: stroke fill; text-shadow: 0 3px 0 var(--gz-outline);
  text-transform: none; letter-spacing: 0.01em;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-gridhead span,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-week__head span { font-weight: 900; color: var(--gz-pink); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-week__head h4 {
  margin: 0; font: 900 14px var(--gz-ui); color: var(--gz-paper); text-transform: none; letter-spacing: 0;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-week__head h4::before { content: ""; display: inline-block; width: 22px; height: 3px; margin-right: 8px; vertical-align: middle; background: var(--gz-pink); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 22px 18px;
  padding: 6px 22px 10px;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card {
  position: relative; display: flex; flex-direction: column; gap: 8px; text-align: left;
  padding: 16px 16px 12px;
  background: var(--gz-paper); color: var(--gz-ink);
  border: 0; border-radius: 2px;
  box-shadow: 0 0 0 3px var(--gz-outline), 5px 6px 0 rgba(0, 0, 0, 0.45);
  animation: none; cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card:nth-child(3n + 1) { transform: rotate(-0.8deg); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card:nth-child(3n + 2) { transform: rotate(0.6deg); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card:nth-child(3n) { transform: rotate(-0.3deg); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card::before {
  /* tape */
  content: ""; position: absolute; top: -9px; left: 50%; width: 64px; height: 18px; margin-left: -32px;
  background: rgba(255, 226, 58, 0.78); transform: rotate(-3deg); box-shadow: 0 1px 0 rgba(0, 0, 0, 0.2);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card:hover {
  transform: rotate(0deg) translateY(-3px);
  box-shadow: 0 0 0 3px var(--gz-outline), 7px 9px 0 var(--gz-pink);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card:focus-visible { outline: 3px solid var(--gz-cyan); outline-offset: 4px; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card.is-ours { background: var(--gz-paper-2); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card.is-ours::after {
  content: "YOUR CLUB"; position: absolute; right: -8px; top: 10px;
  font: 400 11px var(--gz-display); letter-spacing: 0.04em; color: #fff;
  background: var(--gz-red); padding: 3px 8px; transform: rotate(4deg); box-shadow: 0 2px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card--boiling { box-shadow: 0 0 0 3px var(--gz-outline), 5px 6px 0 var(--gz-red-hi); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card--hot { box-shadow: 0 0 0 3px var(--gz-outline), 5px 6px 0 var(--gz-pink); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__rail { display: none; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__top { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__age { margin-left: auto; color: var(--gz-ink-soft); font-size: 11px; font-weight: 800; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__decision,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__prio {
  font: 400 11px var(--gz-display); letter-spacing: 0.04em; text-transform: uppercase;
  background: var(--gz-yellow); color: var(--gz-outline); border: 2px solid var(--gz-outline); border-radius: 3px; padding: 1px 6px;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__prio { background: var(--gz-red-hi); color: #fff; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__body { display: grid; grid-template-columns: auto 1fr; gap: 12px; align-items: start; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__body > :first-child:not(.sl-face) { display: none; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__text h3 {
  margin: 0 0 4px; font: 900 18px/1.12 var(--gz-ui); color: var(--gz-ink); letter-spacing: -0.005em; text-transform: none;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__text p { margin: 0; font: 600 13px/1.4 var(--gz-ui); color: var(--gz-ink-soft); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__text .sl-pm-cause,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__text .sl-effects { display: none; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__foot {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  margin-top: auto; padding-top: 8px; border-top: 2px dashed rgba(27, 18, 9, 0.22);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__byline { font-size: 11px; font-weight: 800; color: var(--gz-ink-soft); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__open { font: 400 13px var(--gz-display); color: var(--gz-red); text-transform: uppercase; letter-spacing: 0.03em; }

/* ---------------- toolbar: filters as newsstand tabs ---------------- */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-toolbar { margin: 16px 22px 0; padding: 0; background: none; border: 0; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-chips { gap: 6px; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-chip {
  font: 900 12px var(--gz-ui); text-transform: none; letter-spacing: 0;
  color: var(--gz-paper); background: rgba(255, 244, 220, 0.08);
  border: 2px solid rgba(255, 244, 220, 0.25); border-radius: 4px; padding: 5px 10px;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-chip b { margin-left: 5px; color: var(--gz-pink); font-weight: 900; background: none; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-chip.is-active { background: var(--gz-pink); border-color: var(--gz-outline); color: #fff; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-chip.is-active b { color: var(--gz-yellow); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-input,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-tools select {
  background: var(--gz-paper); color: var(--gz-ink); border: 2px solid var(--gz-outline); border-radius: 4px; font-weight: 800;
}

/* ---------------- secondary furniture: dark lacquer instead of glass ---------------- */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-panel,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-case__main,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-case__hero {
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk {
  margin: 16px 22px 0; background: var(--gz-yellow); color: var(--gz-outline);
  border: 3px solid var(--gz-outline); border-radius: 2px; box-shadow: 6px 6px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk__head h3 { font: 400 22px var(--gz-display); color: var(--gz-outline); text-transform: none; letter-spacing: 0.01em; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk__item { background: var(--gz-paper); color: var(--gz-ink); border: 2px solid var(--gz-outline); border-radius: 2px; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk__item strong { color: var(--gz-ink); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-desk__item span { color: var(--gz-ink-soft); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd {
  margin: 18px 22px 0; background: var(--gz-lime); color: var(--gz-outline);
  border: 3px solid var(--gz-outline); border-radius: 2px; box-shadow: 6px 6px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd__head h3 { font: 400 26px var(--gz-display); color: var(--gz-outline); text-transform: none; letter-spacing: 0.01em; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd__sub { color: var(--gz-outline); opacity: 0.75; font-weight: 800; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd__item { background: var(--gz-paper); border: 2px solid var(--gz-outline); border-radius: 2px; color: var(--gz-ink); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd__text strong { color: var(--gz-ink); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd__text em,
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd__text small { color: var(--gz-ink-soft); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-odd__all { color: var(--gz-outline); font-weight: 900; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-case__title {
  font: 400 38px/1.02 var(--gz-display); color: var(--gz-yellow); letter-spacing: 0.005em;
  -webkit-text-stroke: 1.5px var(--gz-outline); paint-order: stroke fill; text-shadow: 0 3px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-case__lede { font: 700 16px/1.5 var(--gz-ui); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-panel h3 {
  font: 400 18px var(--gz-display); color: var(--gz-yellow); text-transform: none; letter-spacing: 0.02em;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-back {
  font: 400 13px var(--gz-display); text-transform: uppercase; letter-spacing: 0.04em;
  color: var(--gz-outline); background: var(--gz-paper); border: 2px solid var(--gz-outline); border-radius: 4px; box-shadow: 0 2px 0 var(--gz-outline);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-choice {
  border: 2px solid var(--gz-gold-hi); border-radius: 6px;
  background: linear-gradient(180deg, var(--gz-red-hi), var(--gz-red));
  color: var(--dd-cream, #ffe7c4);
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-choice:hover:not(:disabled) { filter: brightness(1.12); }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-action-notice {
  margin: 12px 22px 0; background: var(--gz-cyan); color: var(--gz-outline); border: 3px solid var(--gz-outline); border-radius: 2px; font-weight: 800;
}

/* ================= Hot or Not rankings ================= */
.nhlcal-sl-root.storylines-skin.sl-gossip .slr { padding: 16px 22px 26px; color: var(--dd-cream, #ffe7c4); }
.slr-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; margin-bottom: 14px; }
.slr-kicker { display: block; font: 900 11px var(--gz-ui); text-transform: uppercase; letter-spacing: 0.08em; color: var(--gz-pink); }
.slr-title {
  margin: 2px 0 0; font: 400 46px/0.95 var(--gz-display); color: var(--gz-yellow);
  -webkit-text-stroke: 2px var(--gz-outline); paint-order: stroke fill; text-shadow: 0 4px 0 var(--gz-outline), 4px 6px 0 var(--gz-pink);
  transform: rotate(-1.5deg); transform-origin: left center;
}
.slr-switches { display: flex; gap: 10px; flex-wrap: wrap; }
.slr-seg { display: inline-flex; border: 3px solid var(--gz-outline); border-radius: 6px; overflow: hidden; box-shadow: 0 3px 0 var(--gz-outline); }
.slr-seg button { border: 0; padding: 7px 12px; font: 900 13px var(--gz-ui); background: var(--gz-paper); color: var(--gz-ink); cursor: pointer; }
.slr-seg button + button { border-left: 3px solid var(--gz-outline); }
.slr-seg button.is-on { background: var(--gz-pink); color: #fff; }
.slr-cats { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0 18px; }
.slr-cat {
  --tone: var(--gz-yellow);
  padding: 6px 12px; cursor: pointer;
  font: 900 13px var(--gz-ui); color: var(--gz-outline);
  background: var(--tone); border: 3px solid var(--gz-outline); border-radius: 4px;
  box-shadow: 0 3px 0 var(--gz-outline); transition: transform 0.1s ease;
}
.slr-cat:nth-child(odd) { transform: rotate(-1deg); }
.slr-cat:nth-child(even) { transform: rotate(1deg); }
.slr-cat:hover { transform: rotate(0) translateY(-2px); }
.slr-cat.is-on { background: var(--gz-outline); color: var(--tone); box-shadow: 0 3px 0 var(--tone); transform: rotate(0) translateY(1px); }
.slr-cat:focus-visible, .slr-seg button:focus-visible, .slr-list button:focus-visible, .slr-cover:focus-visible { outline: 3px solid var(--gz-cyan); outline-offset: 3px; }
.slr-tone-hot { --tone: var(--gz-yellow); }
.slr-tone-pink { --tone: #ff7ab3; }
.slr-tone-lime { --tone: var(--gz-lime); }
.slr-tone-sky { --tone: var(--gz-cyan); }
.slr-tone-tang { --tone: #ff9a3d; }
.slr-tone-grape { --tone: #c79bff; }
.slr-board { display: grid; grid-template-columns: minmax(320px, 1fr) minmax(360px, 1.25fr); gap: 22px 26px; align-items: start; }
.slr-cover {
  position: relative; display: grid; grid-template-columns: auto 1fr; gap: 18px; align-items: center;
  padding: 22px; cursor: pointer;
  background: var(--gz-paper); color: var(--gz-ink);
  box-shadow: 0 0 0 4px var(--gz-outline), 10px 12px 0 var(--gz-pink); transform: rotate(-0.8deg);
}
.slr-cover:hover { transform: rotate(0); }
.slr-sticker {
  position: absolute; top: -20px; left: -16px; width: 64px; height: 64px; display: grid; place-items: center;
  font: 400 26px var(--gz-display); color: var(--gz-outline); background: var(--gz-yellow);
  border: 3px solid var(--gz-outline); border-radius: 50%; transform: rotate(-12deg); box-shadow: 0 3px 0 var(--gz-outline);
}
.slr-cover__face { background: var(--gz-stage); border: 4px solid var(--gz-outline); padding: 6px; transform: rotate(3deg); }
.slr-cover__cat { font: 900 11px var(--gz-ui); text-transform: uppercase; letter-spacing: 0.06em; color: var(--gz-red); }
.slr-cover h3 { margin: 4px 0 8px; font: 400 30px/1.02 var(--gz-display); color: var(--gz-ink); text-wrap: balance; }
.slr-cover__num { margin: 0; font: 400 34px/1 var(--gz-display); color: var(--gz-red); }
.slr-cover__why { margin: 8px 0 0; font: 700 13px/1.4 var(--gz-ui); color: var(--gz-ink-soft); }
.slr-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.slr-list button {
  width: 100%; display: grid; grid-template-columns: 40px minmax(140px, 1.1fr) 1.4fr auto; gap: 12px; align-items: center;
  padding: 8px 12px; text-align: left; cursor: pointer;
  background: rgba(255, 244, 220, 0.06); color: var(--dd-cream, #ffe7c4);
  border: 0; border-left: 4px solid var(--gz-pink); font-family: var(--gz-ui);
}
.slr-list li:nth-child(even) button { border-left-color: var(--gz-yellow); }
.slr-list button:hover { background: rgba(255, 244, 220, 0.14); }
.slr-rank { font: 400 24px var(--gz-display); color: var(--gz-yellow); }
.slr-who { display: flex; flex-direction: column; min-width: 0; }
.slr-who b { font: 900 15px var(--gz-ui); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.slr-who small { font-size: 11px; font-weight: 700; opacity: 0.75; }
.slr-why { font-size: 12px; font-weight: 700; opacity: 0.85; }
.slr-val { font: 400 18px var(--gz-display); color: var(--gz-cyan); white-space: nowrap; }
.slr-method { grid-column: 1 / -1; margin: 4px 0 0; font-size: 12px; font-weight: 700; opacity: 0.8; }
.slr-method b { color: var(--gz-yellow); }
.slr-empty { padding: 20px; background: var(--gz-paper); color: var(--gz-ink); font-weight: 800; box-shadow: 0 0 0 3px var(--gz-outline); }

@media (max-width: 1100px) {
  .nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead { grid-template-columns: 1fr; }
  .nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead__headline { font-size: 34px; }
  .slr-board { grid-template-columns: 1fr; }
  .slr-list button { grid-template-columns: 34px 1fr auto; }
  .slr-why { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .nhlcal-sl-root.storylines-skin.sl-gossip .sl-card,
  .nhlcal-sl-root.storylines-skin.sl-gossip .sl-lead,
  .slr-cat, .slr-cover { transform: none !important; transition: none !important; }
}

/* ---- answers to the old flat skin's !important rules (styles/game.css ~30690-31000) ----
   Same properties, more specific selectors, so these win; nothing else is forced. */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command {
  background: linear-gradient(180deg, var(--gz-red-hi), var(--gz-red) 60%, var(--dd-lacquer-lo, #5e1606)) !important;
  border: 0 !important; border-bottom: 5px solid var(--gz-yellow) !important;
  box-shadow: 0 6px 0 var(--gz-outline) !important;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-command__id h1.sl-nameplate {
  font-family: var(--gz-display) !important; font-size: 46px !important; color: var(--gz-yellow) !important;
  -webkit-text-stroke: 2px var(--gz-outline) !important;
  text-shadow: 0 4px 0 var(--gz-outline), 4px 6px 0 var(--gz-pink) !important;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts {
  flex-wrap: wrap !important; background: transparent !important;
  border: 0 !important; border-bottom: 3px solid var(--gz-yellow) !important; box-shadow: none !important;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts > button {
  background: rgba(255, 244, 220, 0.08) !important; color: var(--gz-paper) !important;
  font-weight: 900 !important; letter-spacing: 0.01em !important; box-shadow: none !important;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts > button:hover { background: rgba(255, 244, 220, 0.18) !important; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-depts > button.is-active {
  background: var(--gz-yellow) !important; color: var(--gz-outline) !important; box-shadow: none !important;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-chip {
  background: rgba(255, 244, 220, 0.08) !important; border: 2px solid rgba(255, 244, 220, 0.25) !important;
  color: var(--gz-paper) !important; font-weight: 900 !important; box-shadow: none !important;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-chip.is-active {
  background: var(--gz-pink) !important; border-color: var(--gz-outline) !important; color: #fff !important; box-shadow: none !important;
}
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-gridhead h3 {
  font-size: 30px !important; font-weight: 400 !important; color: var(--gz-yellow) !important; letter-spacing: 0.01em !important;
}
.nhlcal-sl-root.storylines-skin.sl-gossip :is(.sl-lead__sticker, .sl-lead__heat, .sl-lead__open, .sl-lead__meta em,
  .sl-cat, .sl-card__decision, .sl-card__prio, .sl-card__open, .sl-command__nav button, .sl-desk-sticker span,
  .sl-ticker__flag, .sl-ticker__item i, .sl-back, .slr-kicker, .slr-cover__cat) {
  text-transform: uppercase !important;
}

/* cards: let the clipping breathe; the inline sheet clips and clamps */
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card { overflow: visible !important; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card__text h3 { -webkit-line-clamp: 3; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card.is-ours .sl-card__top { padding-right: 70px; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card.is-ours::after { white-space: nowrap; right: -10px; top: 12px; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card.is-ours::after { right: 10px !important; top: -12px !important; z-index: 2; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card.is-ours .sl-card__top { padding-right: 0; }
.nhlcal-sl-root.storylines-skin.sl-gossip .sl-card.is-ours::before { left: 34%; }

/* ===== screen sheet: components/legacy/legacy.css ===== */
/* Franchise Identity + Legacy Hall. Built on the Double Dash tokens (styles/game.css):
   curved rails and team-colour blocking for structure, brass for legacy, ice cyan for
   operational detail, arena orange for competitive moments. */
.lh-screen {
  --lh-brass: var(--dd-gold-hi, #f8d58a);
  --lh-brass-deep: var(--dd-gold, #c98a3c);
  --lh-cyan: #7fe3ff;
  --lh-orange: var(--arena-orange, #ff7a2f);
  --lh-ink: var(--dd-cream, #ffe7c4);
  --lh-muted: rgba(255, 231, 196, 0.62);
  --lh-sheet: rgba(6, 14, 46, 0.82);
  --lh-line: rgba(248, 213, 138, 0.22);
  --team-1: #1b2a55;
  --team-2: #c98a3c;
  --team-3: #ffffff;
  position: relative;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  color: var(--lh-ink);
  font-family: var(--dd-font-ui);
  font-size: 13px;
}
.lh-screen *::-webkit-scrollbar { width: 8px; }
.lh-screen *::-webkit-scrollbar-thumb { background: var(--lh-line); border-radius: 8px; }

/* ---- header rail: one sweeping band in the club's colours ---- */
.lh-rail {
  position: relative;
  display: grid;
  grid-template-columns: auto auto 1fr auto;
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 18px;
  padding: 12px 22px 0 18px;
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--team-1) 88%, black) 0%, color-mix(in srgb, var(--team-1) 55%, transparent) 58%, transparent 100%);
  border-bottom-right-radius: 220px 46px;
}
.lh-rail::after {
  content: "";
  position: absolute;
  left: 0;
  right: 8%;
  bottom: -5px;
  height: 5px;
  background: linear-gradient(90deg, var(--team-2), var(--lh-brass) 40%, transparent);
  border-bottom-right-radius: 120px 10px;
}
.lh-back { grid-row: 1 / span 2; align-self: center; }
.lh-rail-crest { grid-row: 1 / span 2; display: grid; place-items: center; width: 92px; height: 92px; }
.lh-rail-crest svg, .lh-rail-crest .lh-logo-img { width: 92px; height: 92px; }
.lh-rail-title { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.lh-eyebrow { font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--lh-cyan); font-weight: 800; }
.lh-h1 { margin: 0; font-size: 34px; line-height: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lh-h2 { margin: 0; font-family: var(--dd-font-display); font-weight: 400; font-size: 22px; color: var(--dd-yellow, #ffe23a); letter-spacing: 0.02em; }
.lh-rail-meta { color: var(--lh-muted); font-weight: 700; }
.lh-team-pick { display: flex; flex-direction: column; gap: 2px; font-size: 10px; text-transform: uppercase; letter-spacing: 0.14em; color: var(--lh-cyan); font-weight: 800; }
.lh-tabs {
  grid-column: 3 / span 2;
  display: flex;
  gap: 2px;
  margin-top: 8px;
  overflow-x: auto;
}
.lh-screen--hall .lh-tabs { grid-column: 2 / span 3; }
.lh-tab {
  border: 0;
  background: transparent;
  color: var(--lh-muted);
  padding: 8px 14px 10px;
  font: 800 12px var(--dd-font-ui);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  border-top-left-radius: 14px 18px;
  border-top-right-radius: 4px;
  white-space: nowrap;
}
.lh-tab:hover { color: var(--lh-ink); }
.lh-tab.is-on { color: var(--dd-outline, #1a0d05); background: linear-gradient(180deg, var(--lh-brass), var(--lh-brass-deep)); }

.lh-notice { margin: 10px 22px 0; padding: 8px 12px; border-left: 4px solid var(--lh-cyan); background: rgba(10, 40, 80, 0.7); cursor: pointer; }
.lh-notice--err { border-color: #ff5a4a; background: rgba(80, 10, 10, 0.7); }
.lh-notice--warn { border-color: var(--lh-orange); background: rgba(80, 40, 10, 0.55); margin: 0 0 8px; }

/* ---- shared surfaces: sheets have one sweeping corner, not boxes ---- */
.lh-sheet {
  position: relative;
  background: var(--lh-sheet);
  padding: 14px 16px 16px;
  border-left: 3px solid var(--lh-line);
  border-top-right-radius: 48px 26px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
  overflow: auto;
}
.lh-sheet--wide { grid-column: 1 / -1; }
.lh-sheet-head { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; flex-wrap: wrap; font-weight: 700; }
.lh-sheet-foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: auto; }
.lh-brass { color: var(--lh-brass); font-weight: 800; }
.lh-muted { color: var(--lh-muted); font-weight: 600; }
.lh-fact-label { display: block; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--lh-cyan); font-weight: 800; margin-top: 4px; }
.lh-empty { margin: 40px auto; max-width: 520px; text-align: center; color: var(--lh-muted); display: flex; flex-direction: column; gap: 14px; align-items: center; }
.lh-empty--inline { margin: 0; text-align: left; align-items: flex-start; }
.is-link { cursor: pointer; }
.is-link:hover { color: var(--lh-brass); }

.lh-event { padding: 5px 0 5px 10px; border-left: 2px solid var(--lh-line); line-height: 1.35; }
.lh-event b { color: var(--lh-cyan); margin-right: 6px; }
.lh-event.is-sel { border-left-color: var(--lh-brass); background: rgba(248, 213, 138, 0.06); }

.lh-table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.lh-table th { text-align: left; font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--lh-cyan); padding: 4px 6px; border-bottom: 1px solid var(--lh-line); }
.lh-table td { padding: 4px 6px; border-bottom: 1px solid rgba(255, 255, 255, 0.05); }
.lh-table tr.is-link:hover td { background: rgba(248, 213, 138, 0.07); }
.lh-table tr.is-champ td { color: var(--lh-brass); }

.lh-chip {
  border: 1px solid var(--lh-line);
  background: rgba(255, 255, 255, 0.04);
  color: var(--lh-ink);
  padding: 4px 10px;
  border-radius: 12px 3px 12px 3px;
  font: 800 11px var(--dd-font-ui);
  letter-spacing: 0.04em;
  cursor: pointer;
  text-transform: capitalize;
}
.lh-chip:hover:not(:disabled) { border-color: var(--lh-brass); }
.lh-chip.is-on { background: var(--lh-brass); color: var(--dd-outline, #1a0d05); border-color: var(--lh-brass); }
.lh-chip--warn { border-color: rgba(255, 122, 47, 0.5); color: #ffc29a; }
.lh-chip:disabled { opacity: 0.4; cursor: default; }
.lh-icon-btn { margin-left: auto; border: 0; background: none; color: var(--lh-muted); font: 700 10px var(--dd-font-ui); cursor: pointer; text-transform: uppercase; }
.lh-row-actions { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.lh-sep { width: 1px; height: 18px; background: var(--lh-line); margin: 0 6px; }

.lh-field { display: grid; grid-template-columns: 112px 1fr auto; align-items: center; gap: 8px; font-weight: 700; }
.lh-field > span:first-child { font-size: 11px; color: var(--lh-muted); text-transform: capitalize; }
.lh-field input:not([type="checkbox"]):not([type="color"]), .lh-field select, .lh-filter-row select, .lh-team-pick select, .lh-preset-row input {
  background: rgba(0, 0, 0, 0.35);
  color: var(--lh-ink);
  border: 1px solid var(--lh-line);
  padding: 4px 8px;
  font: 700 12px var(--dd-font-ui);
  border-radius: 3px 10px 3px 10px;
  min-width: 0;
}
.lh-field input[type="range"] { accent-color: var(--lh-brass); width: 100%; }
.lh-field code { font-size: 10px; color: var(--lh-muted); }
.lh-field--check { display: flex; gap: 8px; align-items: center; font-weight: 700; }
.lh-color { display: flex; align-items: center; gap: 8px; }
.lh-color input[type="color"] { width: 36px; height: 24px; padding: 0; border: 2px solid var(--lh-line); background: none; border-radius: 4px; cursor: pointer; }
.lh-swatch { display: inline-block; width: 16px; height: 16px; border: 2px solid transparent; border-radius: 3px 8px 3px 8px; flex: none; }
.lh-filter-row { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.lh-warn { margin: 0; padding: 8px 10px 8px 26px; background: rgba(255, 122, 47, 0.12); border-left: 3px solid var(--lh-orange); color: #ffd2b0; }

/* ---- identity overview: big focal jersey, compact sheet beside it ---- */
.lh-overview { flex: 1; min-height: 0; display: grid; grid-template-columns: 1.15fr 1fr; gap: 0; padding: 14px 22px 18px; }
.lh-focal {
  position: relative;
  background:
    radial-gradient(ellipse 60% 70% at 50% 45%, color-mix(in srgb, var(--team-1) 45%, transparent), transparent 70%),
    radial-gradient(ellipse 80% 30% at 50% 100%, rgba(127, 227, 255, 0.12), transparent 70%);
  border-bottom-left-radius: 200px 60px;
}
.lh-focal::before {
  content: "";
  position: absolute;
  inset: auto 4% 6% 4%;
  height: 34%;
  border-bottom: 3px solid color-mix(in srgb, var(--team-2) 70%, transparent);
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
  pointer-events: none;
}
.lh-studio-canvas { width: 100%; }
.lh-overview .lh-sheet { border-top-right-radius: 80px 34px; }
.lh-fact { display: grid; grid-template-columns: 170px 1fr; column-gap: 12px; padding: 4px 0; border-bottom: 1px solid rgba(255, 255, 255, 0.05); }
.lh-fact-label + .lh-fact-value { font-weight: 800; }
.lh-fact .lh-fact-label { margin: 0; align-self: center; }
.lh-fact-value { font-weight: 800; font-size: 14px; }
.lh-fact-sub { grid-column: 2; color: var(--lh-muted); font-size: 11px; font-weight: 600; }
.lh-fact.is-link:hover .lh-fact-value { color: var(--lh-brass); }
.lh-recent { margin-top: 6px; }
.lh-logo-img { width: 120px; height: 120px; object-fit: contain; }
.lh-logo-img--sm { width: 86px; height: 86px; }

/* ---- studio ---- */
.lh-studio { flex: 1; min-height: 0; display: grid; grid-template-columns: 1.3fr 1fr; gap: 14px; padding: 14px 22px 18px; }
.lh-studio-main { display: flex; flex-direction: column; gap: 8px; min-height: 0; overflow: auto; }
.lh-studio-side { display: flex; flex-direction: column; gap: 10px; min-height: 0; overflow: auto; background: var(--lh-sheet); padding: 14px 16px; border-left: 3px solid var(--team-2); border-top-right-radius: 64px 28px; }
.lh-view-bar, .lh-preview-bar { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
.lh-preview-bar .lh-field { grid-template-columns: auto 1fr; }
.lh-form { display: flex; flex-direction: column; gap: 6px; }
.lh-draft-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-top: auto; padding-top: 8px; border-top: 1px solid var(--lh-line); }
.lh-preset-row { display: flex; gap: 6px; align-items: center; }

.lh-crest-editor { display: grid; grid-template-columns: 250px 1fr; grid-template-rows: auto 1fr; gap: 12px; }
.lh-crest-stage { grid-row: 1 / span 2; display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 10px; background: radial-gradient(circle at 50% 35%, color-mix(in srgb, var(--team-1) 40%, transparent), transparent 70%); }
.lh-presets { display: flex; flex-wrap: wrap; gap: 4px; justify-content: center; }
.lh-layer-list { display: flex; flex-direction: column; gap: 3px; }
.lh-layer-head { display: flex; justify-content: space-between; align-items: center; gap: 6px; flex-wrap: wrap; font-size: 11px; font-weight: 800; color: var(--lh-cyan); text-transform: uppercase; letter-spacing: 0.1em; }
.lh-layer { display: flex; align-items: center; gap: 8px; padding: 4px 8px; cursor: pointer; border-left: 3px solid transparent; }
.lh-layer.is-sel { border-left-color: var(--lh-brass); background: rgba(248, 213, 138, 0.08); }
.lh-layer.is-hidden { opacity: 0.45; }
.lh-layer-name { font-weight: 800; text-transform: capitalize; }
.lh-layer-props { display: flex; flex-direction: column; gap: 5px; }

/* ---- two-column panels (philosophy, captaincy, players, league) ---- */
.lh-two { flex: 1; min-height: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 14px; padding: 14px 22px 18px; }
.lh-two .lh-two { padding: 0; }
.lh-two--wide { grid-template-columns: 1.05fr 1fr; }
.lh-option-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.lh-option { text-align: left; padding: 10px 12px; background: rgba(255, 255, 255, 0.03); color: var(--lh-ink); border: 1px solid var(--lh-line); font: 800 12px var(--dd-font-ui); cursor: pointer; border-radius: 18px 4px 18px 4px; }
.lh-option.is-on { border-color: var(--lh-brass); background: rgba(248, 213, 138, 0.14); color: var(--lh-brass); }
.lh-option:disabled { opacity: 0.6; cursor: default; }

/* ---- identity history ---- */
.lh-history { flex: 1; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 10px; padding: 14px 22px 18px; }
.lh-version { display: grid; grid-template-columns: 96px 1fr auto; gap: 14px; align-items: center; padding: 8px 14px; border-left: 3px solid var(--lh-line); background: var(--lh-sheet); border-top-right-radius: 40px 20px; }
.lh-version.is-current { border-left-color: var(--lh-brass); }
.lh-version-colors { display: flex; gap: 4px; }

/* ---- review modal ---- */
.lh-modal { position: absolute; inset: 0; display: grid; place-items: center; background: rgba(2, 6, 22, 0.72); z-index: 20; }
.lh-modal-card { width: min(640px, 92%); background: linear-gradient(170deg, rgba(14, 28, 82, 0.98), rgba(5, 12, 44, 0.98)); padding: 22px 26px; border-left: 4px solid var(--lh-brass); border-top-right-radius: 90px 34px; display: flex; flex-direction: column; gap: 10px; }
.lh-compare { display: grid; grid-template-columns: 1fr auto 1fr; gap: 14px; align-items: center; }
.lh-compare > div { display: flex; flex-direction: column; align-items: center; gap: 4px; }
.lh-compare-arrow { font: 400 32px var(--dd-font-display); color: var(--lh-brass); }

/* ---- Legacy Hall ---- */
.lh-discovery { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0; margin: 12px 22px 0; }
.lh-trivia { text-align: left; display: flex; flex-direction: column; gap: 4px; padding: 10px 16px; background: linear-gradient(110deg, rgba(248, 213, 138, 0.12), rgba(248, 213, 138, 0.02)); border: 0; border-left: 3px solid var(--lh-brass); color: var(--lh-ink); cursor: pointer; font-family: var(--dd-font-ui); }
.lh-trivia:first-child { border-bottom-left-radius: 46px 22px; }
.lh-trivia:last-child { border-top-right-radius: 46px 22px; }
.lh-trivia:disabled { cursor: default; }
.lh-trivia-text { font-weight: 800; font-size: 13px; line-height: 1.3; }
.lh-trivia .lh-muted { font-size: 10px; }
.lh-hall-body { flex: 1; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.lh-hall-body > .lh-sheet--wide { margin: 14px 22px 18px; }
.lh-grid-hall { flex: 1; min-height: 0; overflow: auto; display: grid; grid-template-columns: repeat(2, 1fr); grid-auto-rows: minmax(0, auto); gap: 14px; padding: 14px 22px 18px; }
.lh-season-strip { display: flex; gap: 4px; align-items: flex-end; height: 120px; padding-top: 6px; overflow-x: auto; }
.lh-season-bar { position: relative; flex: 0 0 34px; height: 100%; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; }
.lh-season-fill { width: 100%; background: rgba(255, 231, 196, 0.25); border-top-left-radius: 10px 6px; }
.lh-season-bar.is-po .lh-season-fill { background: var(--lh-cyan); }
.lh-season-bar.is-champ .lh-season-fill { background: linear-gradient(180deg, var(--lh-brass), var(--lh-brass-deep)); }
.lh-season-pts { position: absolute; top: 0; font-size: 10px; font-weight: 800; }
.lh-season-label { font-size: 9px; color: var(--lh-muted); margin-top: 2px; }
.lh-dossier { gap: 10px; }
.lh-dossier-facts { display: flex; flex-direction: column; gap: 3px; font-weight: 700; }
.lh-statline { display: flex; gap: 22px; }
.lh-statline b { font: 400 26px var(--dd-font-display); color: var(--dd-yellow, #ffe23a); }
.lh-draft-class, .lh-trade { padding-bottom: 10px; border-bottom: 1px solid var(--lh-line); }
.lh-era-track { display: flex; gap: 4px; align-items: stretch; overflow-x: auto; }
.lh-era { min-width: 160px; display: flex; flex-direction: column; gap: 4px; padding: 12px 14px; border-top: 4px solid var(--lh-line); background: rgba(255, 255, 255, 0.03); }
.lh-era:first-child { border-bottom-left-radius: 40px 20px; }
.lh-era:last-child { border-top-right-radius: 40px 20px; }
.lh-era--contender { border-top-color: var(--lh-brass); }
.lh-era--playoff { border-top-color: var(--lh-cyan); }
.lh-era--bubble { border-top-color: var(--lh-orange); }
.lh-era--rebuild { border-top-color: rgba(255, 255, 255, 0.25); }
.lh-rivalry { display: grid; grid-template-columns: 140px 1fr; column-gap: 12px; row-gap: 2px; align-items: center; padding: 6px 0; }
.lh-rivalry .lh-muted { grid-column: 2; }
.lh-rivalry-meter { grid-row: 1 / span 2; height: 10px; background: rgba(255, 255, 255, 0.08); border-radius: 0 10px 10px 0; overflow: hidden; }
.lh-rivalry-meter span { display: block; height: 100%; background: linear-gradient(90deg, var(--lh-orange), var(--lh-brass)); }

@media (max-width: 1100px) {
  .lh-overview, .lh-studio, .lh-two, .lh-grid-hall { grid-template-columns: 1fr; overflow: auto; }
  .lh-discovery { grid-template-columns: 1fr; }
}

/* ===== screen sheet: events/entryDraft/EntryDraftRecap.css ===== */
/* ==========================================================================
   Draft recap (drx-*) — follows the house pass rules in game.css
   (Storylines / Design system pass):
   - Luckiest Guy only for the page title (header) + the one primary action.
   - Heavy Nunito for headings and numbers, no outline.
   - Colour only when it means something: --ds-good / --ds-bad / #ffc94a warn,
     --ds-active for selected / ours / interactive, --ds-elite for elite only.
   - Labels sentence case, light tracking, --ds-label.
   - Unboxed sections; one card surface (the franchise reveal); hairline
     row lists; text links instead of pills; colour carried by the data.
   Potential is the story of a draft class: every pick shows a development
   lane (lineup roles, now -> ceiling) and a big tier-coloured POT number.
   ========================================================================== */

.drx {
  --drx-surface: rgba(14, 30, 72, 0.55);
  --drx-surface-2: rgba(14, 30, 72, 0.38);
  --drx-surface-hi: rgba(22, 44, 100, 0.72);
  --drx-warn: #ffc94a;
  --drx-gutter: clamp(16px, 2.6vw, 44px);
  --drx-accent: var(--ds-text);
  --tier-elite: var(--ds-elite);
  --tier-high: var(--ds-good);
  --tier-mid: var(--ds-text);
  --tier-low: var(--ds-label);
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
  gap: 28px;
  width: 100%;
  margin: 0;
  padding: var(--space-5) var(--drx-gutter) 0;
  font-family: var(--dd-font-ui);
  color: var(--ds-text);
}
.drx > * { flex-shrink: 0; }
.drx,
.drx * { text-transform: none !important; box-sizing: border-box; }
.drx.tone-good { --drx-accent: var(--ds-good); }
.drx.tone-mid { --drx-accent: var(--drx-warn); }
.drx.tone-bad { --drx-accent: var(--ds-bad); }
.drx button { font-family: var(--dd-font-ui); color: inherit; }
.drx button:focus-visible { outline: 2px solid var(--ds-active); outline-offset: 2px; }
.drx-dash { color: var(--ds-label); }
.drx .tier-elite { --tier: var(--tier-elite); }
.drx .tier-high { --tier: var(--tier-high); }
.drx .tier-mid { --tier: var(--tier-mid); }
.drx .tier-low, .drx .tier-none { --tier: var(--tier-low); }

.drx-kicker { margin: 0; font-size: 13px; font-weight: 800; letter-spacing: 0.02em; color: var(--ds-label); }

/* ---------- logos / flags / position ---------- */
.drx-logo { display: inline-grid; place-items: center; flex: none; }
.drx-logo img { width: 100%; height: 100%; object-fit: contain; filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.5)); }
.drx-logo b { font-size: 11px; font-weight: 900; color: var(--ds-label); }
.drx-logo--xs { width: 24px; height: 24px; }
.drx-logo--sm { width: 34px; height: 34px; }
.drx-logo--md { width: 44px; height: 44px; }
.drx-logo--lg { width: 64px; height: 64px; }
.drx .edraft-flag { flex: none; border-radius: 3px; box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35); }
.drx-pos {
  display: inline-block;
  margin-left: 8px;
  padding: 1px 7px;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 900;
  color: var(--ds-muted);
  background: rgba(255, 255, 255, 0.08);
}

/* ================= HERO ================= */
.drx-hero {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: auto minmax(0, 1.6fr) minmax(220px, 0.8fr) auto;
  align-items: center;
  gap: clamp(24px, 3vw, 52px);
  padding: clamp(22px, 2.4vw, 36px) clamp(22px, 2.8vw, 44px);
  border-radius: 16px;
  background:
    radial-gradient(ellipse 45% 120% at 0% 50%, color-mix(in srgb, var(--drx-accent) 14%, transparent), transparent 70%),
    var(--drx-surface);
  box-shadow: inset 4px 0 0 var(--drx-accent);
}
.drx-hero > *:not(.drx-hero__mark) { position: relative; z-index: 1; }
.drx-hero__mark {
  position: absolute;
  right: -40px;
  top: 50%;
  width: clamp(260px, 26vw, 420px);
  aspect-ratio: 1;
  transform: translateY(-50%);
  opacity: 0.06;
  pointer-events: none;
}
.drx-hero__mark img { width: 100%; height: 100%; object-fit: contain; }

.drx-grade-col { display: grid; justify-items: center; gap: 4px; min-width: 150px; }
.drx-grade { display: grid; place-items: center; animation: drx-pop 0.45s cubic-bezier(0.2, 1.3, 0.4, 1) both; }
.drx-grade strong { font-size: clamp(100px, 9vw, 156px); font-weight: 900; line-height: 0.9; letter-spacing: -0.03em; color: var(--drx-accent); }
.drx-grade__score { font-size: 20px; font-weight: 900; color: var(--ds-text); font-variant-numeric: tabular-nums; }
.drx-grade-col::after { content: "Draft grade"; font-size: 13px; font-weight: 800; color: var(--ds-label); }

.drx-kicker--team { display: flex; align-items: center; gap: 8px; }
.drx-headline { margin: 10px 0 20px; font-size: clamp(26px, 2.2vw, 36px); font-weight: 900; line-height: 1.12; color: var(--ds-text); text-wrap: balance; }

.drx-ladder { display: grid; grid-template-columns: repeat(32, 1fr); gap: 3px; height: 34px; align-items: end; }
.drx-ladder i { display: block; height: 12px; border-radius: 3px; background: rgba(255, 255, 255, 0.1); }
.drx-ladder i.is-top { background: color-mix(in srgb, var(--ds-good) 35%, transparent); }
.drx-ladder i.is-bottom { background: color-mix(in srgb, var(--ds-bad) 35%, transparent); }
.drx-ladder i.is-you { height: 34px; background: var(--ds-active); }
.drx-ladder-label { display: flex; justify-content: space-between; margin-top: 8px; font-size: 12px; font-weight: 700; color: var(--ds-label); }
.drx-ladder-label b { font-size: 15px; font-weight: 900; color: var(--ds-text); }

/* class ceiling map: the class at a glance by potential tier */
.drx-ceilmap { display: grid; gap: 8px; margin-top: 20px; }
.drx-ceilmap__bar { display: flex; gap: 3px; height: 12px; }
.drx-ceilmap__bar i { flex-basis: 0; border-radius: 3px; background: var(--tier); }
.drx-ceilmap__legend { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 14px; font-weight: 700; color: var(--ds-muted); }
.drx-ceilmap__legend b { font-weight: 900; color: var(--tier); }

.drx-board { display: grid; gap: 18px; }
.drx-board__main span,
.drx-board__row span { display: block; font-size: 13px; font-weight: 800; letter-spacing: 0.02em; color: var(--ds-label); }
.drx-board__main strong { display: block; font-size: clamp(48px, 4.2vw, 64px); font-weight: 900; line-height: 1; font-variant-numeric: tabular-nums; }
.drx-board__main em { font-style: normal; font-size: 14px; font-weight: 700; color: var(--ds-muted); }
.drx-board__main.tone-neg strong { color: var(--ds-bad); }
.drx-board__main.tone-pos strong { color: var(--ds-good); }
.drx-board__row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; padding-top: 14px; border-top: 1px solid var(--ds-hair); }
.drx-board__row strong { display: block; font-size: 30px; font-weight: 900; line-height: 1.1; font-variant-numeric: tabular-nums; }
.drx-board__row .tone-pos strong { color: var(--ds-good); }
.drx-board__row .tone-neg strong { color: var(--ds-bad); }

.drx-rink-wrap { display: grid; gap: 10px; justify-items: center; }
.drx-rink {
  width: 190px;
  aspect-ratio: 1 / 1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: 1fr 1fr 1fr;
  grid-template-areas: "lw c rw" "d d d" "g g g";
  padding: 10px;
  border-radius: 40px;
  border: 2px solid rgba(255, 255, 255, 0.16);
  background:
    linear-gradient(180deg, transparent calc(36% - 1px), rgba(56, 189, 248, 0.5) calc(36% - 1px) calc(36% + 1px), transparent calc(36% + 1px)),
    linear-gradient(180deg, transparent calc(68% - 1px), rgba(255, 95, 109, 0.5) calc(68% - 1px) calc(68% + 1px), transparent calc(68% + 1px)),
    rgba(255, 255, 255, 0.03);
}
.drx-spot { display: grid; place-items: center; align-content: center; gap: 1px; }
.drx-spot--lw { grid-area: lw; }
.drx-spot--c { grid-area: c; }
.drx-spot--rw { grid-area: rw; }
.drx-spot--d { grid-area: d; }
.drx-spot--g { grid-area: g; }
.drx-spot b { width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; font-size: 18px; font-weight: 900; color: var(--ds-label); background: rgba(255, 255, 255, 0.05); }
.drx-spot.has b { color: var(--ds-text); background: rgba(255, 255, 255, 0.18); }
.drx-spot.is-need b { box-shadow: inset 0 0 0 2px var(--drx-warn); color: var(--drx-warn); }
.drx-spot small { font-size: 11px; font-weight: 800; color: var(--ds-label); }
.drx-rink-cap { display: grid; justify-items: center; gap: 2px; text-align: center; }
.drx-rink-cap em { font-style: normal; font-size: 14px; font-weight: 800; }
.drx-rink-cap em.is-open { color: var(--drx-warn); }
.drx-rink-cap em.is-filled { color: var(--ds-good); }

/* ================= POTENTIAL: development lane ================= */
/* Lineup roles left to right; dot = now, bar = the climb, tick = ceiling. */
.drx-lane { display: block; min-width: 0; }
.drx-lane__track { position: relative; display: block; height: 10px; border-radius: 5px; background: rgba(255, 255, 255, 0.05); }
.drx-lane__zone { position: absolute; top: 0; bottom: 0; border-right: 2px solid rgba(8, 18, 46, 0.9); }
.drx-lane__zone:last-child { border-right: 0; }
.drx-lane__zone.is-mid { background: rgba(255, 255, 255, 0.05); }
.drx-lane__zone.is-high { background: rgba(255, 255, 255, 0.08); }
.drx-lane__zone.is-elite { background: rgba(255, 255, 255, 0.11); border-radius: 0 5px 5px 0; }
.drx-lane__zone.is-low { border-radius: 5px 0 0 5px; }
.drx-lane__zone.is-target { background: color-mix(in srgb, var(--tier) 22%, transparent); }
.drx-lane__climb { position: absolute; top: 2px; bottom: 2px; border-radius: 3px; background: var(--tier); opacity: 0.75; }
.drx-lane__now { position: absolute; top: 50%; width: 12px; height: 12px; margin: -6px 0 0 -6px; border-radius: 50%; background: var(--ds-text); box-shadow: 0 0 0 3px rgba(8, 18, 46, 0.9); }
.drx-lane__cap { position: absolute; top: -5px; bottom: -5px; width: 4px; margin-left: -2px; border-radius: 2px; background: var(--tier); box-shadow: 0 0 0 2px rgba(8, 18, 46, 0.9); }
.drx-lane.has-labels .drx-lane__track { height: 14px; margin-bottom: 22px; }
.drx-lane.has-labels .drx-lane__zone em {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  text-align: center;
  font-style: normal;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
  color: var(--ds-label);
}
.drx-lane.has-labels .drx-lane__zone.is-target em { color: var(--tier); }
.drx-climb-in .drx-lane__climb { animation: drx-climb 0.8s 0.3s ease-out backwards; transform-origin: left; }

.drx-pot { display: grid; justify-items: end; line-height: 1; }
.drx-pot strong { font-size: 30px; font-weight: 900; color: var(--tier); font-variant-numeric: tabular-nums; }
.drx-pot small { margin-top: 3px; font-size: 12px; font-weight: 700; color: var(--ds-label); white-space: nowrap; }
.drx-pot.is-big { justify-items: start; }
.drx-pot.is-big strong { font-size: 84px; letter-spacing: -0.02em; }
.drx-pot.is-big small { font-size: 14px; }

.drx-tier { font-size: 13px; font-weight: 900; color: var(--tier); }
.drx-tier.is-big { font-size: 20px; }

/* ================= BODY ================= */
.drx-body { display: grid; grid-template-columns: minmax(0, 1fr) clamp(340px, 32%, 820px); gap: clamp(24px, 2.6vw, 48px); align-items: start; }
.drx-head { display: flex; align-items: baseline; gap: 12px; margin-bottom: 14px; }
.drx-head h3 { margin: 0; font-size: 22px; font-weight: 900; letter-spacing: 0.01em; color: var(--ds-text); }
.drx-head > span { font-size: 14px; font-weight: 700; color: var(--ds-label); }
.drx-sort { display: flex; gap: 18px; margin-left: auto; }
.drx-sort button { padding: 4px 0; border: 0; background: none; cursor: pointer; font-size: 14px; font-weight: 800; color: var(--ds-label); }
.drx-sort button:hover { color: var(--ds-text); }
.drx-sort button.is-on { color: #fff; box-shadow: inset 0 -3px 0 var(--ds-active); }

/* franchise pick: a draft-stage reveal, not a stat card */
.drx-fcard {
  appearance: none;
  display: grid;
  gap: 8px;
  width: 100%;
  padding: 28px 32px 30px;
  text-align: left;
  cursor: pointer;
  border: 0;
  border-radius: 16px;
  background:
    radial-gradient(ellipse 50% 120% at 100% 0%, color-mix(in srgb, var(--tier) 14%, transparent), transparent 70%),
    var(--drx-surface);
  transition: background-color 0.15s ease;
  animation: drx-rise 0.4s 0.1s ease both;
}
.drx-fcard:hover { background-color: var(--drx-surface-hi); }
.drx-fcard__call { font-size: 16px; font-weight: 700; color: var(--ds-muted); }
.drx-fcard__name { display: flex; align-items: center; gap: 14px; font-size: clamp(34px, 3.2vw, 52px); font-weight: 900; line-height: 1.05; color: #fff; }
.drx-fcard__meta { font-size: 15px; font-weight: 700; color: var(--ds-label); }
.drx-fcard__grid {
  display: grid;
  grid-template-columns: auto minmax(260px, 1fr) auto;
  align-items: end;
  gap: 40px;
  margin-top: 18px;
  padding-top: 20px;
  border-top: 1px solid var(--ds-hair);
}
.drx-fcard__lane { display: grid; gap: 12px; align-self: center; }
.drx-fcard__facts { display: grid; justify-items: end; gap: 8px; text-align: right; }
.drx-fact { font-size: 13px; font-weight: 700; color: var(--ds-label); }
.drx-fact b { font-size: 16px; font-weight: 900; color: var(--ds-text); }
.drx-fact.is-low b { color: var(--drx-warn); }
.drx-open { font-size: 14px; font-weight: 800; color: var(--ds-active); }
.drx-fcard:hover .drx-open { text-decoration: underline; }

/* verdict: the word + the comparison it came from */
.drx-stamp { display: grid; justify-items: end; line-height: 1.15; white-space: nowrap; }
.drx-stamp b { font-size: 16px; font-weight: 900; font-variant-numeric: tabular-nums; }
.drx-stamp small { font-size: 12px; font-weight: 700; color: var(--ds-label); }
.drx-stamp.is-big b { font-size: 24px; }
.drx-stamp--value b { color: var(--ds-good); }
.drx-stamp--reach b { color: var(--ds-bad); }
.drx-stamp--expected b { color: var(--ds-muted); }

/* the rest of the class: one list, hairline rows, no boxes */
.drx-slips {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 700px), 1fr));
  column-gap: 40px;
  margin-top: 18px;
}
.drx-slip {
  appearance: none;
  display: grid;
  grid-template-columns: 52px minmax(170px, 1fr) minmax(110px, 0.8fr) 92px 112px;
  align-items: center;
  gap: 18px;
  width: 100%;
  min-height: 76px;
  padding: 10px 8px;
  text-align: left;
  cursor: pointer;
  border: 0;
  border-bottom: 1px solid var(--ds-hair);
  border-radius: 0;
  background: none;
  transition: background-color 0.14s ease;
  animation: drx-rise 0.35s ease both;
  animation-delay: calc(var(--i, 0) * 50ms + 200ms);
}
.drx-slip:hover { background: rgba(255, 255, 255, 0.04); }
.drx-slip:hover .drx-slip__name { color: #fff; }
.drx-slip.is-best { box-shadow: inset 3px 0 0 var(--ds-active); }
.drx-slip__stub { display: grid; justify-items: center; line-height: 1.05; }
.drx-slip__stub b { font-size: 24px; font-weight: 900; color: var(--ds-text); font-variant-numeric: tabular-nums; }
.drx-slip__stub small { font-size: 11px; font-weight: 700; color: var(--ds-label); }
.drx-slip__id { display: grid; gap: 4px; min-width: 0; }
.drx-slip__name { display: flex; align-items: center; gap: 8px; font-size: 18px; font-weight: 900; color: var(--ds-text); min-width: 0; }
.drx-slip__name > span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.drx-slip__sub { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; font-size: 13px; }
.drx-slip__pos { font-weight: 900; color: var(--ds-muted); }
.drx-slip__sub em { font-style: normal; color: var(--ds-label); }
.drx-lowconf { font-weight: 800; color: var(--drx-warn); }

.drx-empty-state { padding: 32px; border-radius: 14px; background: var(--drx-surface-2); text-align: center; color: var(--ds-label); }
.drx-empty-state h4 { margin: 0 0 6px; font-size: 20px; font-weight: 900; color: var(--ds-text); }

/* ================= RAIL (unboxed sections) ================= */
.drx-rail { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 32px 36px; align-items: start; animation: drx-rise 0.4s 0.35s ease both; }
.drx-rail > .drx-insight { grid-column: 1 / -1; }
.drx-insight { margin: 0; padding: 12px 14px; border-left: 3px solid var(--drx-warn); border-radius: 6px; background: rgba(255, 201, 74, 0.1); font-size: 15px; font-weight: 800; color: var(--ds-text); }
.drx-insight.is-story { border-left-color: rgba(255, 255, 255, 0.25); background: rgba(255, 255, 255, 0.04); font-weight: 700; color: var(--ds-muted); }

.drx-card { --card-tone: var(--ds-text); }
.drx-card--steal { --card-tone: var(--ds-good); }
.drx-card--reach { --card-tone: var(--ds-bad); }
.drx-card__head { display: flex; align-items: baseline; gap: 10px; padding-bottom: 8px; border-bottom: 1px solid var(--ds-hair); }
.drx-card__head h4 { margin: 0; font-size: 20px; font-weight: 900; color: var(--ds-text); }
.drx-count { font-size: 14px; font-weight: 800; color: var(--ds-label); }
.drx-empty { margin: 0; padding: 12px 0; font-size: 14px; color: var(--ds-label); }

.drx-mover {
  appearance: none;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px 0;
  text-align: left;
  cursor: pointer;
  border: 0;
  border-bottom: 1px solid var(--ds-hair);
  background: none;
}
.drx-mover:hover .drx-mover__body strong { color: var(--ds-active); }
.drx-mover__body { display: grid; gap: 2px; min-width: 0; }
.drx-mover__body strong { font-size: 15px; font-weight: 900; color: var(--ds-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.drx-mover__body small { font-size: 12px; color: var(--ds-label); }
.drx-mover__delta { font-size: 18px; font-weight: 900; color: var(--card-tone); font-variant-numeric: tabular-nums; }
.drx-mover.is-lead { padding: 18px 0 16px; }
.drx-mover.is-lead .drx-mover__body strong { font-size: 20px; white-space: normal; }
.drx-mover.is-lead .drx-mover__delta { font-size: 40px; line-height: 1; align-self: start; }
.drx-mover__move { color: var(--card-tone) !important; font-weight: 800; }
.drx-move-track { display: flex; align-items: center; gap: 8px; margin-top: 8px; font-size: 12px; font-weight: 700; color: var(--ds-label); white-space: nowrap; }
.drx-move-track i { flex: 1; height: 6px; border-radius: 3px; background: rgba(255, 255, 255, 0.08); overflow: hidden; }
.drx-move-track i b { display: block; height: 100%; border-radius: 3px; background: var(--card-tone); }
.drx-mover.is-user, .drx-avail.is-user { box-shadow: inset 3px 0 0 var(--ds-active); padding-left: 10px; }
.drx-you { margin-left: 6px; font-style: normal; font-size: 12px; font-weight: 800; color: var(--ds-active); }

.drx-avail { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--ds-hair); }
.drx-avail__id { display: grid; gap: 2px; min-width: 0; }
.drx-avail__id strong { display: flex; align-items: center; flex-direction: row-reverse; justify-content: flex-end; gap: 6px; font-size: 15px; font-weight: 900; color: var(--ds-text); }
.drx-avail__id strong .drx-pos { margin-left: 0; }
.drx-avail__id small { font-size: 12px; color: var(--ds-label); }
.drx-avail__rank { display: grid; justify-items: end; }
.drx-avail__rank small { font-size: 12px; font-weight: 700; color: var(--ds-label); }
.drx-avail__rank b { font-size: 18px; font-weight: 900; color: var(--ds-text); }

.drx-card__more { display: inline-flex; align-items: center; gap: 4px; margin-top: 10px; padding: 0; border: 0; background: none; cursor: pointer; font-size: 14px; font-weight: 800; color: var(--ds-active) !important; }
.drx-card__more:hover { text-decoration: underline; }

/* ================= LEAGUE: one team at a time ================= */
.drx-league { border-top: 1px solid var(--ds-hair); padding-top: 18px; margin-bottom: 8px; }
.drx-league__bar { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
.drx-league__bar h4 { margin: 0; flex: none; font-size: 22px; font-weight: 900; color: var(--ds-text); }
.drx-league__hint { font-size: 14px; font-weight: 700; color: var(--ds-label); }
.drx-league__logos { flex: 1 1 100%; display: flex; flex-wrap: wrap; gap: 6px 10px; padding: 4px 0; }
.drx-league__team { appearance: none; padding: 4px; border: 0; border-radius: 8px; background: none; cursor: pointer; opacity: 0.55; transition: opacity 0.14s ease, background-color 0.14s ease; }
.drx-league__team:hover { opacity: 1; background: rgba(255, 255, 255, 0.06); }
.drx-league__team.is-user { opacity: 0.9; }
.drx-league__team.is-focused { opacity: 1; background: rgba(46, 230, 214, 0.12); box-shadow: inset 0 -3px 0 var(--ds-active); }
.drx-teamboard { margin-top: 18px; animation: drx-rise 0.3s ease both; }
.drx-teamboard__head { display: flex; align-items: center; gap: 12px; }
.drx-teamboard__head h4 { margin: 0; font-size: 22px; font-weight: 900; color: var(--ds-text); }
.drx-teamboard__head > span { font-size: 14px; font-weight: 700; color: var(--ds-label); }
.drx-teamboard__head .drx-card__more { margin: 0 0 0 auto; }

/* ================= FOOTER: solid bar, nothing shows through ================= */
.drx-footer {
  position: sticky;
  bottom: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: auto calc(-1 * var(--drx-gutter)) 0;
  padding: 14px var(--drx-gutter) 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  background: #0e1f4d;
  box-shadow: 0 -12px 24px rgba(5, 12, 40, 0.5);
}
.drx-footer__status { display: inline-flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 800; color: var(--ds-text); }
.drx-continue { display: inline-flex; align-items: center; gap: 8px; padding: 10px 24px; font-size: 18px; }

/* ================= MOTION ================= */
@keyframes drx-rise { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes drx-pop { 0% { opacity: 0; transform: scale(1.35); } 100% { opacity: 1; transform: none; } }
@keyframes drx-climb { from { transform: scaleX(0); } }
.drx-lane__climb { animation: drx-climb 0.8s 0.3s ease-out backwards; transform-origin: left; }
@media (prefers-reduced-motion: reduce) {
  .drx *, .drx *::before, .drx *::after { animation: none !important; transition: none !important; }
}

/* ================= RESPONSIVE ================= */
@media (max-width: 1440px) {
  .drx-hero { grid-template-columns: auto minmax(0, 1fr) minmax(210px, 0.8fr); }
  .drx-rink-wrap { display: none; }
  .drx-slip { gap: 14px; }
}
@media (max-width: 1180px) {
  .drx-body { grid-template-columns: 1fr; }
  .drx-rail { grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); }
  .drx-fcard__grid { grid-template-columns: auto minmax(0, 1fr); }
  .drx-fcard__facts { grid-column: 1 / -1; justify-items: start; text-align: left; }
}
@media (max-width: 900px) {
  .drx-hero { grid-template-columns: auto 1fr; }
  .drx-board { grid-column: 1 / -1; }
  .drx-slip { grid-template-columns: 44px minmax(0, 1fr) auto; }
  .drx-slip .drx-lane, .drx-slip .drx-stamp { display: none; }
}

/* ==========================================================================
   Workshop palette — same language as the prospect dossier (ProspectDossierView
   .ws-*): cream paper cards with ink text and a slanted edge, ink stamps,
   orange verdict band, lime / coral finding blocks, deep matrix cells with a
   cream top rule. Tier colours follow the dossier's career-outcome bar:
   Star+ lime · Top-6 blue · Mid-6 cream · AHL slate.
   ========================================================================== */
.drx {
  --ws-cream: var(--dd-cream, #ffe7c4);
  --ws-ink: #071233;
  --ws-deep: #050c2c;
  --ws-orange: #ff8a1f;
  --ws-burnt: #e2621a;
  --ws-coral: #ff6b5c;
  --ws-lime: #9be564;
  --ws-blue: #5aa2ff;
  --ws-slate: #5a6b93;
  --ws-soft: #a9bfdc;
  --ws-line: rgba(169, 191, 220, 0.16);
  --tier-elite: var(--ws-lime);
  --tier-high: var(--ws-blue);
  --tier-mid: var(--ws-cream);
  --tier-low: var(--ws-slate);
}
.drx.tone-good { --drx-accent: var(--ws-lime); }
.drx.tone-mid { --drx-accent: var(--ws-orange); }
.drx.tone-bad { --drx-accent: var(--ws-coral); }

/* ---- hero: cream grade card + deep matrix ---- */
.drx-hero {
  background: var(--ws-deep);
  box-shadow: none;
  border-top: 3px solid var(--ws-cream);
  border-radius: 0;
  padding-left: 0;
}
.drx-grade-col {
  align-self: stretch;
  align-content: center;
  margin: calc(-1 * clamp(22px, 2.4vw, 36px)) 0;
  padding: 24px 54px 24px 34px;
  background: var(--ws-cream);
  clip-path: polygon(0 0, 100% 0, calc(100% - 22px) 100%, 0 100%);
}
.drx-grade strong { color: var(--ws-ink); }
.drx.tone-good .drx-grade strong { color: #2f7d16; }
.drx.tone-bad .drx-grade strong { color: #a8300f; }
.drx.tone-mid .drx-grade strong { color: #c4560f; }
.drx-grade__score { color: var(--ws-ink); }
.drx-grade-col::after { color: #4b5a82; }
.drx-headline { color: #fff; }
.drx-ladder i { background: var(--ws-line); }
.drx-ladder i.is-top { background: color-mix(in srgb, var(--ws-lime) 45%, transparent); }
.drx-ladder i.is-bottom { background: color-mix(in srgb, var(--ws-coral) 45%, transparent); }
.drx-ladder i.is-you { background: var(--ws-orange); }
.drx-ladder-label b { color: var(--ws-orange); }
.drx-ceilmap__bar { gap: 2px; height: 16px; }
.drx-ceilmap__bar i { border-radius: 0; }
.drx-board { gap: 1px; background: var(--ws-line); }
.drx-board__main,
.drx-board__row > div { padding: 10px 12px; background: var(--ws-deep); border-top: 3px solid var(--ws-cream); }
.drx-board__row { gap: 1px; padding-top: 0; border-top: 0; background: var(--ws-line); }
.drx-board__main.tone-pos strong, .drx-board__row .tone-pos strong { color: var(--ws-lime); }
.drx-board__main.tone-neg strong, .drx-board__row .tone-neg strong { color: var(--ws-coral); }
.drx-rink { border-color: var(--ws-line); border-radius: 36px; }
.drx-spot.has b { color: var(--ws-ink); background: var(--ws-cream); }
.drx-spot.is-need b { box-shadow: inset 0 0 0 2px var(--ws-orange); color: var(--ws-orange); }
.drx-rink-cap em.is-open { color: var(--ws-ink); background: var(--ws-orange); padding: 2px 8px; }
.drx-rink-cap em.is-filled { color: var(--ws-ink); background: var(--ws-lime); padding: 2px 8px; }
.drx-hero__mark { opacity: 0.05; }

/* ---- franchise pick: cream paper card, ink, slanted edge ---- */
.drx-fcard {
  color: var(--ws-ink);
  background: var(--ws-cream);
  border-radius: 0;
  clip-path: polygon(0 0, 100% 0, calc(100% - 26px) 100%, 0 100%);
  padding: 26px 56px 0 30px;
}
.drx-fcard:hover { background: #fff0d8; }
.drx-fcard__call { color: #a8300f; font-weight: 900; }
.drx-fcard__name { color: var(--ws-ink); }
.drx-fcard__name .edraft-flag { padding: 6px; background: var(--ws-ink); clip-path: polygon(0 0, 100% 0, 100% 76%, 76% 100%, 0 100%); box-shadow: none; width: 44px !important; height: auto !important; }
.drx-fcard__meta { color: #4b5a82; }
.drx-fcard__grid { border-top: 0; margin: 14px -56px 0 -30px; padding: 0; gap: 0; grid-template-columns: auto minmax(260px, 1fr) minmax(220px, auto); align-items: stretch; }
.drx-fcard__grid > * { padding: 18px 26px 22px; }
.drx-fcard .drx-pot.is-big { padding-left: 30px; }
.drx-fcard .drx-pot strong { color: #2f7d16; }
.drx-fcard .drx-pot small { color: #4b5a82; }
.drx-fcard .drx-tier.is-big {
  justify-self: start;
  padding: 3px 10px;
  font-size: 13px;
  letter-spacing: 0.06em;
  text-transform: uppercase !important;
  color: #fff;
  background: var(--ws-ink);
  transform: rotate(-2deg);
}
.drx-fcard .drx-lane__track { background: rgba(7, 18, 51, 0.1); }
.drx-fcard .drx-lane__zone { border-right-color: var(--ws-cream); background: none; }
.drx-fcard .drx-lane__zone.is-target { background: rgba(47, 125, 22, 0.18); }
.drx-fcard .drx-lane__climb { background: var(--ws-ink); opacity: 1; }
.drx-fcard .drx-lane__now { background: var(--ws-ink); box-shadow: 0 0 0 3px var(--ws-cream); }
.drx-fcard .drx-lane__cap { background: #2f7d16; box-shadow: 0 0 0 2px var(--ws-cream); }
.drx-fcard .drx-lane.has-labels .drx-lane__zone em { color: #4b5a82; }
.drx-fcard .drx-lane.has-labels .drx-lane__zone.is-target em { color: #2f7d16; }
/* orange verdict band, like the dossier's Board / Most likely strip */
.drx-fcard__facts {
  justify-items: start;
  align-content: center;
  text-align: left;
  color: #1a0b00;
  background: var(--ws-orange);
  clip-path: polygon(14px 0, 100% 0, 100% 100%, 0 100%);
  padding-left: 34px !important;
}
.drx-fcard .drx-stamp { justify-items: start; }
.drx-fcard .drx-stamp b { font-size: 26px; color: #1a0b00; }
.drx-fcard .drx-stamp--value b { color: #14460a; }
.drx-fcard .drx-stamp--reach b { color: #7a1206; }
.drx-fcard .drx-stamp small, .drx-fcard .drx-fact { color: #5a2a05; }
.drx-fcard .drx-fact b { color: #1a0b00; }
.drx-fcard .drx-fact.is-low b { color: #7a1206; }
.drx-fcard .drx-open { color: #1a0b00; text-decoration: underline; }

/* ---- class list: deep matrix cells with a cream top rule ---- */
.drx-slips { gap: 2px; column-gap: 2px; background: none; }
.drx-slip {
  background: var(--ws-deep);
  border-bottom: 0;
  border-top: 3px solid var(--ws-cream);
  padding: 10px 14px 10px 8px;
}
.drx-slip:hover { background: #0b1a4a; }
.drx-slip.is-best { box-shadow: inset 0 -3px 0 var(--ws-orange); }
.drx-slip__stub b { color: var(--ws-cream); }
.drx-slip__name { color: #fff; }
.drx-slip__pos { color: var(--ws-ink); background: var(--ws-cream); padding: 0 5px; }
.drx-lowconf { color: var(--ws-orange); }
.drx-lane__track { background: var(--ws-line); }
.drx-lane__zone { border-right-color: var(--ws-deep); }
.drx-lane__now { box-shadow: 0 0 0 3px var(--ws-deep); }
.drx-lane__cap { box-shadow: 0 0 0 2px var(--ws-deep); }
/* verdict as a finding block: lime = value, coral = reach, slate = expected */
.drx-stamp b { padding: 3px 9px; color: var(--ws-ink); }
.drx-stamp--value b { color: var(--ws-ink); background: var(--ws-lime); }
.drx-stamp--reach b { color: #2a0702; background: var(--ws-coral); }
.drx-stamp--expected b { color: #fff; background: var(--ws-slate); }
.drx-stamp small { margin-top: 3px; color: var(--ws-soft); }
.drx-fcard .drx-stamp b { padding: 0; background: none; }

/* ---- rail: coloured finding heads over deep lists ---- */
.drx-card { background: var(--ws-deep); }
.drx-card__head { padding: 8px 12px; border-bottom: 0; }
.drx-card--steal .drx-card__head { background: var(--ws-lime); }
.drx-card--reach .drx-card__head { background: var(--ws-coral); }
.drx-card--board .drx-card__head { background: var(--ws-cream); }
.drx-card__head h4, .drx-card__head .drx-count { color: var(--ws-ink); }
.drx-card--steal { --card-tone: var(--ws-lime); }
.drx-card--reach { --card-tone: var(--ws-coral); }
.drx-mover, .drx-avail { padding-left: 12px; padding-right: 12px; border-bottom-color: var(--ws-line); }
.drx-mover:hover { background: #0b1a4a; }
.drx-card__more { margin: 10px 12px 12px; color: var(--ws-cyan, #3ee6ff) !important; }
.drx-insight {
  border-left: 0;
  border-radius: 0;
  color: #1a0b00;
  background: var(--ws-orange);
  clip-path: polygon(0 0, 100% 0, calc(100% - 14px) 100%, 0 100%);
  padding-right: 28px;
}
.drx-insight.is-story { color: var(--ws-ink); background: var(--ws-cream); }
.drx-you { color: var(--ws-orange); }
.drx-mover.is-user, .drx-avail.is-user { box-shadow: inset 3px 0 0 var(--ws-orange); }

/* ---- league + footer ---- */
.drx-league__team.is-focused { background: rgba(255, 231, 196, 0.12); box-shadow: inset 0 -3px 0 var(--ws-orange); }
.drx-league__team.is-user { box-shadow: inset 0 0 0 2px rgba(255, 138, 31, 0.6); }
.drx-teamboard__head { padding: 10px 14px; background: var(--ws-cream); }
.drx-teamboard__head h4 { color: var(--ws-ink); }
.drx-teamboard__head > span { color: #4b5a82; }
.drx-teamboard__head .drx-card__more { margin: 0 0 0 auto; color: var(--ws-ink) !important; text-decoration: underline; }
.drx-teamboard .drx-slips { margin-top: 2px; }
.drx-footer { background: var(--ws-deep); border-top: 3px solid var(--ws-cream); }
@media (max-width: 1180px) {
  .drx-fcard__grid { grid-template-columns: auto minmax(0, 1fr); }
  .drx-fcard__facts { grid-column: 1 / -1; clip-path: none; }
}

/* ===== screen sheet: events/ProspectRightsDesk.css ===== */
/* ==========================================================================
   Rights Desk (Prospect Rights) — dossier workshop palette, house type rules.
   Cream paper card for the player, deep matrix cells with a cream rule for
   choices, orange band for the rights window, one lacquer primary.
   ========================================================================== */
.pr-desk {
  --ws-cream: var(--dd-cream, #ffe7c4);
  --ws-ink: #071233;
  --ws-deep: #050c2c;
  --ws-orange: #ff8a1f;
  --ws-burnt: #e2621a;
  --ws-coral: #ff6b5c;
  --ws-lime: #9be564;
  --ws-blue: #5aa2ff;
  --ws-slate: #5a6b93;
  --ws-soft: #a9bfdc;
  --ws-line: rgba(169, 191, 220, 0.16);
}
.pr-desk,
.pr-desk * { text-transform: none !important; }
.pr-desk .prospectrights-stage { grid-template-columns: minmax(0, 1fr) clamp(300px, 22vw, 380px) !important; gap: 0 !important; }
.pr-desk .prospectrights-reveal { min-height: 0; overflow-y: auto; }
.pr-desk .prospectrights-panel { background: var(--ws-deep) !important; border-left: 3px solid var(--ws-cream) !important; display: flex; flex-direction: column; min-height: 0; }
.pr-desk .prospectrights-panel > h2 { margin: 0; padding: 14px 16px 10px; font-family: var(--dd-font-ui) !important; font-size: 18px !important; font-weight: 900 !important; letter-spacing: 0.01em !important; color: #fff !important; }
.pr-desk .prospectrights-rail { flex: 1; min-height: 0; overflow-y: auto; padding: 0 0 12px; }
.pr-desk .prospectrights-rail-hint { padding: 8px 16px 12px; font-size: 12px; font-weight: 700; color: var(--ws-soft); }
/* the shell's Continue is the secondary action here; signing is the primary */
.pr-desk.prospectrights-root .prospectrights-cta-btn {
  font-family: var(--dd-font-ui) !important;
  font-size: 15px !important;
  font-weight: 900 !important;
  color: #fff !important;
  background: rgba(255, 255, 255, 0.06) !important;
  border: 2px solid rgba(255, 255, 255, 0.22) !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
.pr-desk.prospectrights-root .prospectrights-cta-btn:hover { border-color: rgba(255, 255, 255, 0.4) !important; }
.pr-desk .prospectrights-footer { border-top: 1px solid var(--ws-line); }

/* ---------- workspace ---------- */
.pr2 { display: grid; gap: 22px; padding: 22px clamp(16px, 2vw, 32px) 28px; font-family: var(--dd-font-ui); color: #fff; }
.pr2-alert { margin: 0; padding: 10px 14px; font-size: 14px; font-weight: 800; color: #1a0b00; background: var(--ws-orange); clip-path: polygon(0 0, 100% 0, calc(100% - 14px) 100%, 0 100%); }

/* ---------- player card ---------- */
.pr2-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: stretch;
  color: var(--ws-ink);
  background: var(--ws-cream);
  clip-path: polygon(0 0, 100% 0, calc(100% - 24px) 100%, 0 100%);
}
.pr2-face { display: grid; place-items: end center; padding: 16px 0 0 20px; }
.pr2-face .player-headshot { width: 112px !important; height: 112px !important; }
.pr2-who { display: grid; align-content: center; gap: 6px; padding: 18px 24px; min-width: 0; }
.pr2-tag { font-size: 12px; font-weight: 900; letter-spacing: 0.02em; color: #a8300f; }
.pr2-name { display: flex; align-items: center; gap: 12px; margin: 0; font-family: var(--dd-font-ui) !important; font-size: clamp(30px, 2.6vw, 42px); font-weight: 900; line-height: 1.05; letter-spacing: 0 !important; color: var(--ws-ink) !important; }
.pr2-flag { flex: none; display: grid; place-items: center; width: 40px; height: 40px; background: var(--ws-ink); clip-path: polygon(0 0, 100% 0, 100% 76%, 76% 100%, 0 100%); }
.pr2-flag img { width: 26px; height: auto; }
.pr2-line { margin: 0; font-size: 15px; font-weight: 700; color: #4b5a82; }
.pr2-stamp { justify-self: start; margin-top: 4px; padding: 3px 10px; font-size: 12px; font-weight: 900; letter-spacing: 0.06em; text-transform: uppercase !important; color: #fff; background: var(--ws-ink); transform: rotate(-2deg); }
.pr2-pot { display: flex; align-items: flex-end; gap: 14px; padding: 18px 28px; }
.pr2-pot small { display: block; font-size: 12px; font-weight: 800; color: #4b5a82; }
.pr2-pot strong { display: block; font-size: 60px; font-weight: 900; line-height: 0.95; color: var(--ws-ink); font-variant-numeric: tabular-nums; }
.pr2-pot .is-ceiling strong { color: #2f7d16; }
.pr2-pot > i { position: relative; width: 60px; height: 3px; margin-bottom: 22px; background: var(--ws-ink); }
.pr2-pot > i::after { content: ""; position: absolute; right: -2px; top: -5px; border-left: 10px solid var(--ws-ink); border-top: 6px solid transparent; border-bottom: 6px solid transparent; }
.pr2-rights { display: grid; align-content: center; gap: 12px; padding: 16px 52px 16px 28px; color: #1a0b00; background: var(--ws-orange); clip-path: polygon(16px 0, 100% 0, 100% 100%, 0 100%); }
.pr2-rights.is-urgent { background: var(--ws-coral); color: #2a0702; }
.pr2-rights small { display: block; font-size: 12px; font-weight: 900; color: #4a1f02; }
.pr2-rights strong { display: block; font-size: 24px; font-weight: 900; line-height: 1.05; }
.pr2-rights em { font-style: normal; font-size: 12px; font-weight: 800; opacity: 0.8; }

/* ---------- body ---------- */
.pr2-body { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(330px, 0.9fr); gap: 24px; align-items: start; }
.pr2-choose { display: grid; gap: 12px; min-width: 0; }
.pr2-h { margin: 6px 0 0; font-family: var(--dd-font-ui) !important; font-size: 18px; font-weight: 900; letter-spacing: 0.01em !important; color: #fff !important; }

/* ELC deals: three comparable cards */
.pr2-elcs { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 2px; }
.pr2-elc {
  position: relative;
  display: grid;
  gap: 8px;
  align-content: start;
  padding: 16px 18px 18px;
  text-align: left;
  cursor: pointer;
  color: #fff;
  border: 0;
  border-top: 3px solid var(--ws-cream);
  background: var(--ws-deep);
  font-family: var(--dd-font-ui);
  transition: background-color 0.14s ease, transform 0.14s ease;
}
.pr2-elc:hover:not(:disabled) { background: #0b1a4a; }
.pr2-elc.is-on { color: var(--ws-ink); background: var(--ws-cream); border-top-color: var(--ws-orange); transform: translateY(-3px); }
.pr2-elc:disabled { opacity: 0.4; cursor: not-allowed; }
.pr2-elc__rec { justify-self: start; padding: 2px 8px; font-size: 11px; font-weight: 900; color: var(--ws-ink); background: var(--ws-lime); }
.pr2-elc__name { font-size: 16px; font-weight: 900; }
.pr2-elc__bonus small { display: block; font-size: 12px; font-weight: 800; color: var(--ws-soft); }
.pr2-elc.is-on .pr2-elc__bonus small { color: #4b5a82; }
.pr2-elc__bonus b { display: block; font-size: 30px; font-weight: 900; line-height: 1.05; font-variant-numeric: tabular-nums; }
.pr2-elc.is-on .pr2-elc__bonus b { color: #2f7d16; }
.pr2-elc__terms { font-size: 13px; font-weight: 700; color: var(--ws-soft); }
.pr2-elc.is-on .pr2-elc__terms { color: #4b5a82; }

/* other paths: compact cells */
.pr2-paths { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 2px; }
.pr2-path {
  display: grid;
  gap: 3px;
  padding: 12px 14px;
  text-align: left;
  cursor: pointer;
  color: #fff;
  border: 0;
  border-top: 3px solid var(--ws-line);
  background: var(--ws-deep);
  font-family: var(--dd-font-ui);
  transition: background-color 0.14s ease;
}
.pr2-path:hover:not(:disabled) { background: #0b1a4a; }
.pr2-path strong { font-size: 15px; font-weight: 900; }
.pr2-path small { font-size: 12px; font-weight: 600; color: var(--ws-soft); }
.pr2-path.is-on { color: var(--ws-ink); background: var(--ws-cream); border-top-color: var(--ws-orange); }
.pr2-path.is-on small { color: #4b5a82; }
.pr2-path.is-danger strong { color: var(--ws-coral); }
.pr2-path.is-danger.is-on strong { color: #a8300f; }
.pr2-path:disabled { cursor: not-allowed; opacity: 0.38; background: transparent; box-shadow: inset 0 0 0 1px var(--ws-line); border-top-style: dashed; }
.pr2-stats { margin: 8px 0 0; padding-top: 12px; border-top: 1px solid var(--ws-line); font-size: 14px; font-weight: 700; color: var(--ws-soft); }

/* ---------- offer column ---------- */
.pr2-offer {
  position: sticky;
  top: 0;
  display: grid;
  gap: 18px;
  padding: 20px 22px 22px;
  background: var(--ws-deep);
  border-top: 3px solid var(--ws-cream);
}
.pr2-meter { display: grid; gap: 10px; --meter: var(--ws-soft); }
.pr2-meter.tone-good { --meter: var(--ws-lime); }
.pr2-meter.tone-mid { --meter: var(--ws-orange); }
.pr2-meter.tone-bad { --meter: var(--ws-coral); }
.pr2-meter__top { display: flex; align-items: center; gap: 14px; }
.pr2-meter__top strong { font-size: 56px; font-weight: 900; line-height: 1; color: var(--meter); font-variant-numeric: tabular-nums; }
.pr2-meter__top b { display: block; font-size: 17px; font-weight: 900; color: #fff; }
.pr2-meter__top small { display: block; font-size: 13px; font-weight: 700; color: var(--ws-soft); }
.pr2-meter__track { position: relative; height: 14px; background: rgba(169, 191, 220, 0.12); }
.pr2-meter__track > i { position: absolute; inset: 0 auto 0 0; background: var(--meter); transition: width 0.35s ease; }
.pr2-meter__track > span { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--ws-deep); }
.pr2-field { display: grid; gap: 6px; }
.pr2-field__head { display: flex; justify-content: space-between; align-items: baseline; }
.pr2-field__head span { font-size: 14px; font-weight: 800; color: var(--ws-soft); }
.pr2-field__head strong { font-size: 20px; font-weight: 900; color: #fff; font-variant-numeric: tabular-nums; }
.pr2-field input[type="range"] { width: 100%; height: 8px; accent-color: var(--ws-orange); cursor: pointer; }
.pr2-field__scale { display: flex; justify-content: space-between; font-size: 12px; font-weight: 700; color: var(--ws-slate); }
.pr2-hint { margin: -4px 0 0; padding: 10px 12px; font-size: 13px; font-weight: 700; color: var(--ws-ink); background: var(--ws-cream); }
.pr2-assign { display: grid; gap: 6px; }
.pr2-assign span { font-size: 14px; font-weight: 800; color: var(--ws-soft); }
.pr2-assign select { height: 38px; padding: 0 12px; font-family: var(--dd-font-ui); font-size: 14px; font-weight: 800; color: #fff; background: rgba(255, 255, 255, 0.06); border: 2px solid rgba(255, 255, 255, 0.18); border-radius: 0; }
.pr2-assign select option { color: var(--ws-ink); }
.pr2-decision small { display: block; font-size: 13px; font-weight: 800; color: var(--ws-soft); }
.pr2-decision strong { display: block; margin: 4px 0; font-size: 24px; font-weight: 900; }
.pr2-decision p { margin: 0; font-size: 14px; font-weight: 600; color: var(--ws-soft); }
.pr2-sum { display: grid; grid-template-columns: repeat(auto-fit, minmax(90px, 1fr)); gap: 1px; margin: 0; background: var(--ws-line); }
.pr2-sum > div { padding: 10px 12px; background: var(--ws-deep); }
.pr2-sum dt { font-size: 12px; font-weight: 800; color: var(--ws-soft); }
.pr2-sum dd { margin: 2px 0 0; font-size: 17px; font-weight: 900; color: #fff; font-variant-numeric: tabular-nums; }
.pr2-error { margin: 0; padding: 10px 12px; font-size: 14px; font-weight: 800; color: #2a0702; background: var(--ws-coral); }
.pr2-ok { margin: 0; padding: 10px 12px; font-size: 14px; font-weight: 800; color: var(--ws-ink); background: var(--ws-lime); }
.pr2-primary { width: 100%; min-height: 52px; font-size: 19px !important; }
.pr2-empty { padding: 28px; font-size: 16px; font-weight: 800; color: var(--ws-soft); }

/* ---------- prospect rail ---------- */
.pr2-row {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 16px;
  text-align: left;
  cursor: pointer;
  color: #fff;
  border: 0;
  border-bottom: 1px solid var(--ws-line);
  background: none;
  font-family: var(--dd-font-ui);
}
.pr2-row:hover { background: #0b1a4a; }
.pr2-row.is-urgent { box-shadow: inset 4px 0 0 var(--ws-coral); }
.pr2-row__pos { justify-self: start; padding: 1px 6px; font-size: 12px; font-weight: 900; color: var(--ws-ink); background: var(--ws-cream); }
.pr2-row__who { display: grid; min-width: 0; }
.pr2-row__who strong { font-size: 15px; font-weight: 900; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pr2-row__who small { font-size: 12px; font-weight: 700; color: var(--ws-soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pr2-row__nums { display: flex; align-items: baseline; gap: 5px; font-variant-numeric: tabular-nums; }
.pr2-row__nums b { font-size: 18px; font-weight: 900; }
.pr2-row__nums i { font-style: normal; font-size: 12px; color: var(--ws-slate); }
.pr2-row__nums .is-pot.tier-elite { color: var(--ws-lime); }
.pr2-row__nums .is-pot.tier-high { color: var(--ws-blue); }
.pr2-row__nums .is-pot.tier-mid { color: var(--ws-cream); }
.pr2-row__nums .is-pot.tier-low { color: var(--ws-slate); }
.pr2-row.is-active { color: var(--ws-ink); background: var(--ws-cream); }
.pr2-row.is-active .pr2-row__who small { color: #4b5a82; }
.pr2-row.is-active .pr2-row__pos { color: #fff; background: var(--ws-ink); }
.pr2-row.is-active .pr2-row__nums .is-pot { color: #2f7d16; }

@media (max-width: 1300px) {
  .pr2-card { grid-template-columns: auto minmax(0, 1fr) auto; }
  .pr2-rights { grid-column: 1 / -1; grid-auto-flow: column; justify-content: start; gap: 36px; clip-path: none; padding: 12px 24px; }
  .pr2-body { grid-template-columns: 1fr; }
  .pr2-offer { position: static; }
}
@media (prefers-reduced-motion: reduce) {
  .pr-desk * { transition: none !important; }
}

/* ===== screen sheet: screens/editLinesDD.css ===== */
/* ==========================================================================
   Lines — coaching board pass (Double Dash house rules).
   - The lineup is the focal point; everything else recedes.
   - One selection accent (--ds-active cyan) for selected unit / card / tab.
   - Semantic colour only: green good, amber caution, red problem.
   - No boxes for their own sake: players sit on a quiet row surface, the
     selected unit gets the only lifted surface.
   - Chemistry links are quiet until you hover or select a unit.
   - Ice time / deployment collapse to a one-line summary; controls open on
     the selected unit.
   Scoped to .linebuilder-root.lb-dd so it outranks the inline sheet and the
   earlier game.css de-clutter pass.
   ========================================================================== */
.linebuilder-root.lb-dd {
  --c-sel: var(--ds-active, #2ee6d6);
  --c-good: var(--ds-good, #52df94);
  --c-warn: #ffc94a;
  --c-bad: var(--ds-bad, #ff5f6d);
  --c-text: var(--ds-text, #f3f6ff);
  --c-muted: var(--ds-muted, #b2c3e4);
  --c-label: var(--ds-label, #9fb2d6);
  --c-hair: rgba(255, 255, 255, 0.07);
  --surf-row: rgba(8, 18, 46, 0.32);
  --surf-lift: rgba(16, 34, 82, 0.92);
  font-family: var(--dd-font-ui);
  background:
    radial-gradient(ellipse 55% 50% at 10% 6%, rgba(46, 230, 214, 0.1), transparent 70%),
    linear-gradient(165deg, #1d3c80 0%, #14295e 50%, #0e2150 100%);
}
.linebuilder-root.lb-dd,
.linebuilder-root.lb-dd *:not(.lb-title):not(.lb-btn.primary) { text-transform: none !important; letter-spacing: 0.01em; }

/* ---------- header: title, then one quiet line of team facts ---------- */
.linebuilder-root.lb-dd .lb-shell { grid-template-rows: auto auto minmax(0, 1fr) !important; gap: 6px !important; }
.linebuilder-root.lb-dd .lb-header { height: auto !important; padding: 4px 2px !important; }
.linebuilder-root.lb-dd .lb-title { font-size: 32px !important; }
.linebuilder-root.lb-dd .lb-logo img { width: 40px; height: 40px; object-fit: contain; }
.linebuilder-root.lb-dd .lb-subtitle { font-size: 13px !important; font-weight: 700 !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .lb-actions { gap: 6px !important; }
.linebuilder-root.lb-dd .lb-icon--history,
.linebuilder-root.lb-dd .lb-btn:not(.primary) {
  min-height: 34px !important;
  padding: 0 12px !important;
  font-family: var(--dd-font-ui) !important;
  font-size: 14px !important;
  font-weight: 800 !important;
  color: var(--c-muted) !important;
  text-shadow: none !important;
  background: none !important;
  border: 0 !important;
  border-radius: 6px !important;
}
.linebuilder-root.lb-dd .lb-icon--history:hover:not(:disabled),
.linebuilder-root.lb-dd .lb-btn:not(.primary):hover:not(:disabled) { color: #fff !important; background: rgba(255, 255, 255, 0.07) !important; }
.linebuilder-root.lb-dd .lb-icon--history:disabled { opacity: 0.3; }
.linebuilder-root.lb-dd .lb-btn.subtle.danger:hover { color: var(--c-bad) !important; }
.linebuilder-root.lb-dd .lb-btn.primary { min-height: 44px !important; padding: 0 22px !important; margin-left: 8px; }

.linebuilder-root.lb-dd .lb-status { height: auto !important; gap: 28px !important; padding: 0 4px 4px !important; overflow: visible !important; }
.linebuilder-root.lb-dd .lb-pill { display: flex !important; align-items: baseline; gap: 6px !important; height: auto !important; padding: 0 !important; background: none !important; border: 0 !important; }
.linebuilder-root.lb-dd .lb-pill-label { font-size: 13px !important; font-weight: 700 !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .lb-pill-value { margin: 0 !important; font-family: var(--dd-font-ui) !important; font-size: 20px !important; font-weight: 900 !important; text-shadow: none !important; color: var(--c-text) !important; }
