/* ---------- columns: lineup gets the room ---------- */
.linebuilder-root.lb-dd .lb-workspace { grid-template-columns: 236px minmax(0, 1fr) 280px; gap: 18px !important; }
.linebuilder-root.lb-dd .lb-region { background: none !important; border: 0 !important; }
