.linebuilder-root.lb-dd .lb-region-note { font-size: 13px !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .lb-modebar { gap: 20px !important; padding: 0 2px !important; }
.linebuilder-root.lb-dd .lb-mode { padding: 6px 0 !important; font-size: 14px !important; font-weight: 800 !important; color: var(--c-label) !important; background: none !important; border: 0 !important; border-radius: 0 !important; box-shadow: none !important; }
.linebuilder-root.lb-dd .lb-mode.active { color: #fff !important; box-shadow: inset 0 -3px 0 var(--c-sel) !important; }

/* ---------- player pool: name first, quieter metadata ---------- */
.linebuilder-root.lb-dd .lb-pool-region { background: none !important; border-radius: 0 !important; }
.linebuilder-root.lb-dd .lb-search { height: 36px; font-size: 14px; color: #fff; background: rgba(255, 255, 255, 0.06); border: 0; border-radius: 6px; }
.linebuilder-root.lb-dd .lb-player { min-height: 48px !important; grid-template-columns: 34px minmax(0, 1fr) auto !important; gap: 10px; padding: 6px 6px !important; border: 0 !important; border-radius: 6px !important; }
.linebuilder-root.lb-dd .lb-player:hover { background: rgba(255, 255, 255, 0.05) !important; }
.linebuilder-root.lb-dd .lb-player .player-headshot { width: 34px !important; height: 34px !important; }
.linebuilder-root.lb-dd .lb-player-name { font-size: 14px !important; font-weight: 800 !important; }
.linebuilder-root.lb-dd .lb-player-meta { font-size: 12px !important; font-weight: 600 !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .lb-player-ovr { font-size: 17px !important; font-weight: 900 !important; color: var(--c-text) !important; }
.linebuilder-root.lb-dd .lb-player .lb-dot { display: none; }
.linebuilder-root.lb-dd .lb-player.assigned { opacity: 0.45; }
.linebuilder-root.lb-dd .lb-player.selected { opacity: 1; background: rgba(46, 230, 214, 0.14) !important; box-shadow: inset 3px 0 0 var(--c-sel); }
.linebuilder-root.lb-dd .lb-player.disabled { opacity: 0.3; }

/* ---------- board ---------- */
.linebuilder-root.lb-dd .lb-board-region { background: none !important; }
.linebuilder-root.lb-dd .fm-scroll { padding: 4px 2px 20px !important; }
.linebuilder-root.lb-dd .fm-section { margin-bottom: 14px !important; }
.linebuilder-root.lb-dd .fm-section-head { margin: 8px 0 6px !important; }
.linebuilder-root.lb-dd .fm-section-title { font-size: 18px !important; font-weight: 900 !important; color: var(--c-text) !important; }
.linebuilder-root.lb-dd .fm-section-rule { height: 1px !important; background: var(--c-hair) !important; }
.linebuilder-root.lb-dd .fm-section-note { font-size: 13px !important; color: var(--c-label) !important; white-space: normal !important; max-width: 50%; text-align: right; }
.linebuilder-root.lb-dd .fm-depth { display: none !important; }

.linebuilder-root.lb-dd .fm-legend { justify-content: flex-start !important; align-items: center; gap: 14px !important; margin: 0 0 4px !important; padding: 2px !important; border: 0 !important; background: none; }
.linebuilder-root.lb-dd .fm-legend-title { font-size: 13px; font-weight: 800; color: var(--c-muted); }
.linebuilder-root.lb-dd .fm-legend-item { font-size: 13px !important; font-weight: 700 !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .fm-legend-swatch { width: 16px !important; height: 3px !important; border-radius: 2px !important; background: var(--c-good) !important; }
.linebuilder-root.lb-dd .fm-legend-swatch.forming { background: var(--c-warn) !important; }
.linebuilder-root.lb-dd .fm-legend-swatch.weak { background: var(--c-bad) !important; }
.linebuilder-root.lb-dd .fm-legend-hint { margin-left: auto; font-size: 12px; font-weight: 600; color: var(--c-label); opacity: 0.8; }

.linebuilder-root.lb-dd .fm-coach { margin: 0 0 8px !important; padding: 0 !important; border: 0 !important; background: none !important; }
.linebuilder-root.lb-dd .fm-coach .lb-deploy-row { gap: 12px !important; }
.linebuilder-root.lb-dd .fm-coach .lb-deploy-name { width: auto !important; font-size: 14px !important; font-weight: 800 !important; color: var(--c-muted) !important; }
.linebuilder-root.lb-dd .fm-coach .lb-deploy-share { min-width: 0 !important; gap: 0 !important; background: rgba(255, 255, 255, 0.06); border-radius: 6px; padding: 2px; }
.linebuilder-root.lb-dd .fm-coach .lb-share-step { min-width: 54px; height: 28px; padding: 0 10px; font-size: 13px; font-weight: 800; color: var(--c-muted); background: none; border: 0; border-radius: 5px; cursor: pointer; }
.linebuilder-root.lb-dd .fm-coach .lb-share-step.is-active { color: #062036; background: var(--c-sel); }
.linebuilder-root.lb-dd .fm-coach-note { font-size: 13px; font-weight: 600; color: var(--c-label); }

/* ---------- a unit: tag | players | deployment summary ---------- */
.linebuilder-root.lb-dd .fm-unit {
  display: grid !important;
  grid-template-columns: 128px minmax(0, 1fr) 190px;
  align-items: center;
  gap: 16px;
  height: auto !important;
  margin-bottom: 4px;
  padding: 4px 12px 4px 0 !important;
  border-radius: 10px !important;
  background: var(--surf-row) !important;
  box-shadow: none !important;
  transition: background-color 0.15s ease;
}
.linebuilder-root.lb-dd .fm-unit:hover { background: rgba(16, 34, 82, 0.55) !important; }
.linebuilder-root.lb-dd .fm-unit.selected { background: var(--surf-lift) !important; box-shadow: inset 3px 0 0 var(--c-sel), 0 10px 26px rgba(0, 0, 0, 0.35) !important; }
.linebuilder-root.lb-dd .fm-unit-board { position: relative; min-width: 0; height: 84px; margin: 6px 0; }

.linebuilder-root.lb-dd .fm-unit-tag {
  position: static !important;
  transform: none !important;
  width: auto !important;
  display: flex !important;
  flex-direction: column;
  align-items: flex-start !important;
  justify-content: center;
  gap: 1px !important;
  padding: 8px 0 8px 14px;
}
.linebuilder-root.lb-dd .fm-unit-kicker { font-size: 14px !important; font-weight: 800 !important; color: var(--c-muted) !important; }
.linebuilder-root.lb-dd .fm-unit-score { margin: 0 !important; font-size: 30px !important; font-weight: 900 !important; line-height: 1.05 !important; color: var(--c-good) !important; }
.linebuilder-root.lb-dd .fm-unit-score.warn { color: var(--c-warn) !important; }
.linebuilder-root.lb-dd .fm-unit-score.bad { color: var(--c-bad) !important; }
.linebuilder-root.lb-dd .fm-unit-chem { font-size: 12px; font-weight: 700; color: var(--c-label); }
.linebuilder-root.lb-dd .fm-unit-roles { max-width: 118px; margin-top: 3px; font-size: 11px; font-weight: 700; line-height: 1.25; color: var(--c-label); }
.linebuilder-root.lb-dd .fm-unit-roles.is-repeat { color: var(--c-warn); }
.linebuilder-root.lb-dd .fm-unit-flag { margin-top: 4px; font-size: 12px; font-weight: 800; color: var(--c-bad); }
.linebuilder-root.lb-dd .fm-unit-warn { margin-top: 3px !important; height: auto !important; padding: 0 !important; font-size: 12px !important; font-weight: 800 !important; border: 0 !important; color: var(--c-warn) !important; background: none !important; cursor: pointer; }
.linebuilder-root.lb-dd .fm-unit-warn::after { content: " warnings"; }
.linebuilder-root.lb-dd .fm-unit-menu-btn { display: none !important; }
.linebuilder-root.lb-dd .fm-unit.selected .fm-unit-menu-btn,
.linebuilder-root.lb-dd .fm-unit:hover .fm-unit-menu-btn { display: inline-block !important; margin-top: 3px !important; height: 20px !important; border: 0 !important; color: var(--c-label) !important; background: rgba(255, 255, 255, 0.06) !important; }
.linebuilder-root.lb-dd .fm-unit-menu { left: 128px !important; border-radius: 8px !important; background: var(--surf-lift) !important; border: 0 !important; box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5) !important; }

/* ---------- player: portrait, position + name, role; rating supporting ---------- */
.linebuilder-root.lb-dd .fm-card {
  display: grid !important;
  grid-template-columns: 52px minmax(0, 1fr) auto;
  grid-template-rows: auto auto auto;
  grid-template-areas: "face pos ovr" "face name ovr" "face meta ovr";
  column-gap: 10px;
  align-content: center;
  padding: 6px 10px 6px 6px !important;
  text-align: left !important;
  border: 0 !important;
  border-radius: 8px !important;
  background: none !important;
  box-shadow: none !important;
  transition: background-color 0.14s ease;
}
.linebuilder-root.lb-dd .fm-card:hover { background: rgba(255, 255, 255, 0.06) !important; }
.linebuilder-root.lb-dd .fm-card-face { grid-area: face; align-self: center; }
.linebuilder-root.lb-dd .fm-card-face .player-headshot { width: 52px !important; height: 52px !important; }
.linebuilder-root.lb-dd .fm-card-slot { grid-area: pos; position: static !important; font-size: 12px !important; font-weight: 900 !important; color: var(--c-sel) !important; background: none; padding: 0; }
.linebuilder-root.lb-dd .fm-card-name { grid-area: name; margin: 0 !important; padding: 0 !important; font-size: 17px !important; font-weight: 900 !important; line-height: 1.15 !important; color: var(--c-text) !important; }
.linebuilder-root.lb-dd .fm-card-meta { grid-area: meta; margin: 0 !important; font-size: 12px !important; font-weight: 600 !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .fm-card-ovr { grid-area: ovr; align-self: center; margin: 0 !important; font-size: 20px !important; font-weight: 800 !important; line-height: 1 !important; color: var(--c-muted) !important; text-shadow: none !important; }
.linebuilder-root.lb-dd .fm-card-new { margin-left: 6px; font-style: normal; font-weight: 800; color: var(--c-warn); }
.linebuilder-root.lb-dd .fm-card-flag { position: absolute; top: 4px !important; left: 4px; right: auto !important; padding: 0 4px; font-size: 10px !important; font-weight: 900; border-radius: 3px; color: #2a0508 !important; background: var(--c-bad); }
.linebuilder-root.lb-dd .fm-card-drop { position: static !important; grid-area: ovr; align-self: end; font-size: 11px !important; color: var(--c-bad) !important; }
.linebuilder-root.lb-dd .fm-pips { display: none !important; }
.linebuilder-root.lb-dd .fm-card.selected { background: rgba(46, 230, 214, 0.14) !important; box-shadow: inset 0 0 0 2px var(--c-sel) !important; }
.linebuilder-root.lb-dd .fm-card.empty { display: grid !important; place-items: center; grid-template-columns: 1fr; grid-template-areas: "x"; background: none !important; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12) !important; }
.linebuilder-root.lb-dd .fm-card.empty .fm-card-slot { grid-area: x; display: none; }
.linebuilder-root.lb-dd .fm-card-empty { font-size: 14px !important; font-weight: 700 !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .fm-card.valid { box-shadow: inset 0 0 0 2px var(--c-good) !important; }
.linebuilder-root.lb-dd .fm-card.swap { box-shadow: inset 0 0 0 2px var(--c-warn) !important; }
.linebuilder-root.lb-dd .fm-card.invalid { opacity: 0.35; }
.linebuilder-root.lb-dd .fm-card.locked .fm-card-meta::after { content: " · locked"; color: var(--c-warn); }
.linebuilder-root.lb-dd .fm-mini { min-width: 22px; height: 20px; border-radius: 4px; font-size: 12px; font-weight: 900; }

/* ---------- chemistry: quiet until you look at a unit ---------- */
.linebuilder-root.lb-dd .fm-links { opacity: 0.32; transition: opacity 0.15s ease; }
.linebuilder-root.lb-dd .fm-unit:hover .fm-links,
.linebuilder-root.lb-dd .fm-unit.selected .fm-links { opacity: 1; }
.linebuilder-root.lb-dd .fm-link { stroke-width: 3 !important; stroke: rgba(255, 255, 255, 0.25) !important; }
.linebuilder-root.lb-dd .fm-link.strong { stroke: var(--c-good) !important; }
.linebuilder-root.lb-dd .fm-link.forming { stroke: var(--c-warn) !important; }
.linebuilder-root.lb-dd .fm-link.weak { stroke: var(--c-bad) !important; }
.linebuilder-root.lb-dd .fm-badge {
  min-width: 0 !important;
  padding: 0 5px !important;
  border: 0 !important;
  border-radius: 4px !important;
  font-size: 13px !important;
  font-weight: 900 !important;
  color: var(--c-label) !important;
  background: #12285e !important;
  opacity: 0.75;
  transition: opacity 0.15s ease;
}
.linebuilder-root.lb-dd .fm-badge.strong { color: var(--c-good) !important; }
.linebuilder-root.lb-dd .fm-badge.forming { color: var(--c-warn) !important; }
.linebuilder-root.lb-dd .fm-badge.weak { color: var(--c-bad) !important; }
.linebuilder-root.lb-dd .fm-unit:hover .fm-badge,
.linebuilder-root.lb-dd .fm-unit.selected .fm-badge { opacity: 1; }
.linebuilder-root.lb-dd .fm-unit.selected .fm-badge { background: #172f6c !important; }
.linebuilder-root.lb-dd .fm-badge.is-wide { font-size: 12px !important; font-weight: 800 !important; }

/* ---------- deployment: summary, controls on the selected unit ---------- */
.linebuilder-root.lb-dd .fm-unit-deploy { display: grid; align-content: center; gap: 8px; padding: 8px 0; }
.linebuilder-root.lb-dd .fm-deploy-summary { display: grid; line-height: 1.2; }
.linebuilder-root.lb-dd .fm-deploy-summary strong { font-size: 20px; font-weight: 900; color: var(--c-text); font-variant-numeric: tabular-nums; }
.linebuilder-root.lb-dd .fm-deploy-summary strong::after { content: " ice time"; font-size: 12px; font-weight: 700; color: var(--c-label); }
.linebuilder-root.lb-dd .fm-deploy-summary span { font-size: 12px; font-weight: 700; color: var(--c-label); }
.linebuilder-root.lb-dd .fm-unit-deploy > :not(.fm-deploy-summary) { display: none; }
.linebuilder-root.lb-dd .fm-unit-deploy.is-open .fm-deploy-summary { display: none; }
.linebuilder-root.lb-dd .fm-unit-deploy.is-open > :not(.fm-deploy-summary) { display: grid; }
.linebuilder-root.lb-dd .fm-unit-deploy.is-open .fm-deploy-row { display: flex; }
.linebuilder-root.lb-dd .fm-unit.selected { grid-template-columns: 128px minmax(0, 1fr) 270px; }

.linebuilder-root.lb-dd .fm-deploy-share { grid-template-columns: auto 28px auto 28px; grid-template-areas: "label minus num plus" "bar bar bar bar"; align-items: center; column-gap: 6px; row-gap: 4px; }
.linebuilder-root.lb-dd .fm-deploy-share .fm-deploy-label { grid-area: label; }
.linebuilder-root.lb-dd .fm-deploy-share strong { grid-area: num; min-width: 44px; text-align: center; font-size: 20px; font-weight: 900; color: var(--c-text); font-variant-numeric: tabular-nums; }
.linebuilder-root.lb-dd .fm-step { width: 28px; height: 28px; font-size: 17px; font-weight: 900; color: var(--c-text); background: rgba(255, 255, 255, 0.08); border: 0; border-radius: 5px; cursor: pointer; }
.linebuilder-root.lb-dd .fm-step:hover:not(:disabled) { background: rgba(255, 255, 255, 0.16); }
.linebuilder-root.lb-dd .fm-step:disabled { opacity: 0.25; cursor: not-allowed; }
.linebuilder-root.lb-dd .fm-share-bar { grid-area: bar; height: 4px; border-radius: 2px; background: rgba(255, 255, 255, 0.1); overflow: hidden; }
.linebuilder-root.lb-dd .fm-share-bar i { display: block; height: 100%; background: var(--c-sel); }
.linebuilder-root.lb-dd .fm-deploy-row { align-items: center; gap: 8px; flex-wrap: wrap; }
.linebuilder-root.lb-dd .fm-deploy-label { min-width: 70px; font-size: 12px; font-weight: 700; color: var(--c-label); }
.linebuilder-root.lb-dd .lb-deploy-pills { gap: 0 !important; padding: 2px; border-radius: 6px; background: rgba(255, 255, 255, 0.06); }
.linebuilder-root.lb-dd .lb-deploy-pill { padding: 4px 9px !important; font-size: 12px !important; font-weight: 800 !important; color: var(--c-muted) !important; background: none !important; border: 0 !important; border-radius: 5px !important; box-shadow: none !important; }
.linebuilder-root.lb-dd .lb-deploy-pill:hover { color: #fff !important; }
.linebuilder-root.lb-dd .lb-deploy-pill.on { color: #062036 !important; background: var(--c-sel) !important; }

/* goalies */
.linebuilder-root.lb-dd .fm-unit.isolated { background: var(--surf-row) !important; border: 0 !important; }
.linebuilder-root.lb-dd .fm-isolated-note { position: absolute; right: 0; bottom: -4px; font-size: 12px !important; font-weight: 600 !important; color: var(--c-label) !important; }

/* ---------- inspector: reads as part of the selected unit ---------- */
.linebuilder-root.lb-dd .lb-inspector-region { background: var(--surf-lift) !important; border: 0 !important; border-radius: 10px !important; box-shadow: inset 3px 0 0 var(--c-sel) !important; }
.linebuilder-root.lb-dd .lb-inspector-title { font-size: 20px !important; font-weight: 900 !important; }
.linebuilder-root.lb-dd .lb-inspector-sub { font-size: 12px !important; font-weight: 600 !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .lb-inspector-body { gap: 12px !important; padding: 14px !important; font-size: 14px; }
.linebuilder-root.lb-dd .lb-inspector-player { border: 0 !important; border-radius: 8px !important; background: rgba(255, 255, 255, 0.05) !important; }
.linebuilder-root.lb-dd .lb-inspector-player-name { font-size: 15px !important; }
.linebuilder-root.lb-dd .lb-inspector-player-meta { font-size: 12px !important; color: var(--c-label) !important; }

/* ---------- smaller screens ---------- */
@media (max-width: 1500px) {
  .linebuilder-root.lb-dd .lb-workspace { grid-template-columns: 220px minmax(0, 1fr) !important; }
  .linebuilder-root.lb-dd .fm-unit,
  .linebuilder-root.lb-dd .fm-unit.selected { grid-template-columns: 110px minmax(0, 1fr) 170px; }
  .linebuilder-root.lb-dd .fm-unit.selected .fm-unit-deploy { grid-column: 1 / -1; grid-auto-flow: column; justify-content: start; padding: 0 14px 10px; gap: 18px; }
}
@media (max-width: 1100px) {
  .linebuilder-root.lb-dd .fm-card { grid-template-columns: 40px minmax(0, 1fr) auto; }
  .linebuilder-root.lb-dd .fm-card-face .player-headshot { width: 40px !important; height: 40px !important; }
  .linebuilder-root.lb-dd .fm-card-name { font-size: 14px !important; }
  .linebuilder-root.lb-dd .fm-unit { grid-template-columns: 96px minmax(0, 1fr); }
  .linebuilder-root.lb-dd .fm-unit-deploy { grid-column: 1 / -1; padding: 0 14px 8px; }
}
@media (prefers-reduced-motion: reduce) {
  .linebuilder-root.lb-dd * { transition: none !important; }
}

/* ---------- v3: compact player plates ----------
   Opaque plate so link lines stop at the card edge; rating sits right after
   the name instead of being pushed to the far edge of the slot. */
.linebuilder-root.lb-dd .fm-card {
  grid-template-columns: 52px minmax(0, max-content) auto !important;
  grid-template-areas: "face pos pos" "face name ovr" "face meta meta" !important;
  justify-content: start !important;
  column-gap: 10px !important;
  background: #16306b !important;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.25) !important;
}
.linebuilder-root.lb-dd .fm-unit.selected .fm-card { background: #1b3a7e !important; }
.linebuilder-root.lb-dd .fm-card:hover { background: #1d3d82 !important; }
.linebuilder-root.lb-dd .fm-card.selected { background: #1a4c7a !important; }
.linebuilder-root.lb-dd .fm-card-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.linebuilder-root.lb-dd .fm-card-ovr { align-self: baseline !important; padding-left: 2px; font-size: 18px !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .fm-card-ovr::before { content: "· "; font-weight: 700; opacity: 0.6; }
.linebuilder-root.lb-dd .fm-card.empty { background: none !important; }

/* ---------- v4: line is the component; symmetric rows; ice time inputs ---------- */
.linebuilder-root.lb-dd .fm-unit,
.linebuilder-root.lb-dd .fm-unit.selected { grid-template-columns: 150px minmax(0, 1fr) 300px !important; }
.linebuilder-root.lb-dd .fm-unit { padding: 6px 16px 6px 0 !important; margin-bottom: 6px; }
.linebuilder-root.lb-dd .fm-unit.selected { box-shadow: inset 3px 0 0 var(--c-sel) !important; }

/* players are elements of the line, not boxes */
.linebuilder-root.lb-dd .fm-card,
.linebuilder-root.lb-dd .fm-unit.selected .fm-card { background: none !important; box-shadow: none !important; }
.linebuilder-root.lb-dd .fm-card:hover { background: rgba(255, 255, 255, 0.05) !important; }
.linebuilder-root.lb-dd .fm-card.selected { background: rgba(46, 230, 214, 0.12) !important; box-shadow: none !important; }
.linebuilder-root.lb-dd .fm-card-name { font-size: 18px !important; }
.linebuilder-root.lb-dd .fm-card-ovr { font-size: 16px !important; }
.linebuilder-root.lb-dd .fm-links { opacity: 0.55; }

/* hockey identity under the line number */
.linebuilder-root.lb-dd .fm-unit-kicker { font-size: 13px !important; color: var(--c-label) !important; }
.linebuilder-root.lb-dd .fm-unit-identity { font-size: 16px; font-weight: 900; line-height: 1.1; color: var(--c-text); }
.linebuilder-root.lb-dd .fm-unit-score { font-size: 26px !important; margin-top: 4px !important; }

/* ice time: exact %, minutes, bar */
.linebuilder-root.lb-dd .fm-unit-deploy.is-open .fm-deploy-share {
  display: grid !important;
  grid-template-columns: auto auto 1fr;
  grid-template-areas: "input min bar";
  align-items: center;
  column-gap: 12px;
}
.linebuilder-root.lb-dd .fm-share-input { grid-area: input; display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px 2px 2px; border-radius: 6px; background: rgba(255, 255, 255, 0.08); }
.linebuilder-root.lb-dd .fm-share-input input {
  width: 48px;
  height: 30px;
  padding: 0 4px;
  text-align: right;
  font-family: var(--dd-font-ui);
  font-size: 18px;
  font-weight: 900;
  color: #fff;
  background: none;
  border: 0;
  outline: none;
  -moz-appearance: textfield;
}
.linebuilder-root.lb-dd .fm-share-input input::-webkit-outer-spin-button,
.linebuilder-root.lb-dd .fm-share-input input::-webkit-inner-spin-button { opacity: 1; }
.linebuilder-root.lb-dd .fm-share-input:focus-within { box-shadow: inset 0 0 0 2px var(--c-sel); }
.linebuilder-root.lb-dd .fm-share-input span { font-size: 14px; font-weight: 800; color: var(--c-label); }
.linebuilder-root.lb-dd .fm-share-min { grid-area: min; font-size: 13px; font-weight: 700; color: var(--c-label); white-space: nowrap; }
.linebuilder-root.lb-dd .fm-deploy-share .fm-share-bar { grid-area: bar; height: 8px; border-radius: 4px; }

.linebuilder-root.lb-dd .fm-share-total { display: inline-flex; align-items: baseline; gap: 8px; font-size: 14px; font-weight: 700; color: var(--c-label); }
.linebuilder-root.lb-dd .fm-share-total b { font-size: 18px; font-weight: 900; }
.linebuilder-root.lb-dd .fm-share-total.is-ok b { color: var(--c-good); }
.linebuilder-root.lb-dd .fm-share-total.is-off b,
.linebuilder-root.lb-dd .fm-share-total.is-off em { color: var(--c-bad); }
.linebuilder-root.lb-dd .fm-share-total em { font-style: normal; font-weight: 800; }

/* player pool recedes; the lineup leads */
.linebuilder-root.lb-dd .lb-player { opacity: 0.65; transition: opacity 0.12s ease, background-color 0.12s ease; }
.linebuilder-root.lb-dd .lb-player:hover,
.linebuilder-root.lb-dd .lb-player.selected { opacity: 1; }
.linebuilder-root.lb-dd .lb-player.assigned { opacity: 0.4; }

/* inspector: a little more readable */
.linebuilder-root.lb-dd .lb-inspector-body { font-size: 15px !important; }
.linebuilder-root.lb-dd .lb-inspector-body * { font-size: max(13px, 1em); }

@media (max-width: 1500px) {
  .linebuilder-root.lb-dd .fm-unit,
  .linebuilder-root.lb-dd .fm-unit.selected { grid-template-columns: 128px minmax(0, 1fr) !important; }
  .linebuilder-root.lb-dd .fm-unit-deploy { grid-column: 1 / -1; grid-auto-flow: column; justify-content: start; padding: 0 14px 8px; gap: 18px; }
}

/* ---------- v5: ice-time number box sized for its digits, no spinner ---------- */
.linebuilder-root.lb-dd .fm-share-input { padding: 0 10px 0 0 !important; gap: 2px !important; }
.linebuilder-root.lb-dd .fm-share-input input {
  width: 46px !important;
  height: 34px !important;
  padding: 0 2px 0 8px !important;
  text-align: right;
  font-size: 20px !important;
  line-height: 34px;
  appearance: textfield;
  -moz-appearance: textfield;
}
.linebuilder-root.lb-dd .fm-share-input input::-webkit-outer-spin-button,
.linebuilder-root.lb-dd .fm-share-input input::-webkit-inner-spin-button { -webkit-appearance: none !important; margin: 0; opacity: 0 !important; display: none; }
.linebuilder-root.lb-dd .fm-share-input span { font-size: 16px !important; }

/* ---------- v6: grab targets, no row hover, estimates marked ---------- */
/* each player is a clear target: a faint plate you can see before you grab */
.linebuilder-root.lb-dd .fm-card {
  background: rgba(255, 255, 255, 0.035) !important;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.07) !important;
  cursor: grab;
}
.linebuilder-root.lb-dd .fm-card:active { cursor: grabbing; }
.linebuilder-root.lb-dd .fm-card:hover { background: rgba(255, 255, 255, 0.07) !important; box-shadow: inset 0 0 0 1px rgba(46, 230, 214, 0.55) !important; }
.linebuilder-root.lb-dd .fm-card.selected { background: rgba(46, 230, 214, 0.14) !important; box-shadow: inset 0 0 0 2px var(--c-sel) !important; }
.linebuilder-root.lb-dd .fm-card.is-dragging { opacity: 0.35; }
body.lb-dragging .linebuilder-root.lb-dd .fm-card:not(.is-dragging) { box-shadow: inset 0 0 0 1px rgba(46, 230, 214, 0.35), 0 0 0 1px rgba(46, 230, 214, 0.15) !important; }
.linebuilder-root.lb-dd .fm-card.is-dragover {
  background: rgba(46, 230, 214, 0.2) !important;
  box-shadow: inset 0 0 0 3px var(--c-sel), 0 0 0 4px rgba(46, 230, 214, 0.18) !important;
  transform: scale(1.02);
}
.linebuilder-root.lb-dd .fm-card.is-dragover.invalid { background: rgba(255, 95, 109, 0.18) !important; box-shadow: inset 0 0 0 3px var(--c-bad) !important; }

/* the row no longer lights up on hover; only selection lifts it */
.linebuilder-root.lb-dd .fm-unit:hover { background: var(--surf-row) !important; }
.linebuilder-root.lb-dd .fm-unit.selected,
.linebuilder-root.lb-dd .fm-unit.selected:hover { background: var(--surf-lift) !important; }
.linebuilder-root.lb-dd .fm-unit:hover .fm-links { opacity: 0.55; }
.linebuilder-root.lb-dd .fm-unit.selected .fm-links { opacity: 1; }
.linebuilder-root.lb-dd .fm-unit:hover .fm-badge { opacity: 0.75; }
.linebuilder-root.lb-dd .fm-unit.selected .fm-badge { opacity: 1; }
.linebuilder-root.lb-dd .fm-unit:hover .fm-unit-menu-btn { display: none !important; }
.linebuilder-root.lb-dd .fm-unit.selected .fm-unit-menu-btn { display: inline-block !important; }

/* estimates read as estimates */
.linebuilder-root.lb-dd .fm-unit-score.is-projected { opacity: 0.8; }

/* ---------- v7: grab the player, not his photo ---------- */
.linebuilder-root.lb-dd .fm-card,
.linebuilder-root.lb-dd .lb-player { user-select: none; -webkit-user-select: none; }
.linebuilder-root.lb-dd .fm-card img,
.linebuilder-root.lb-dd .fm-card .player-headshot,
.linebuilder-root.lb-dd .lb-player img,
.linebuilder-root.lb-dd .lb-player .player-headshot { -webkit-user-drag: none; user-drag: none; pointer-events: none; }

/* ===== screen sheet: screens/calendarDD.css ===== */
/* ==========================================================================
   Calendar — Double Dash house rules + dossier workshop palette.
   Cream paper card for the next game, deep matrix cells with a cream rule for
   stats / rail, result blocks (lime win, coral loss, orange OTL), one lacquer
   primary (Advance day). Sentence case, heavy Nunito, no glow.
   Scoped to .nhlcal-root.nhlcal-dd so it outranks the game.css calendar pass.
   ========================================================================== */
.nhlcal-root.nhlcal-dd {
  --ws-cream: var(--dd-cream, #ffe7c4);
  --ws-ink: #071233;
  --ws-deep: #050c2c;
  --ws-cell: #0b1844;
  --ws-orange: #ff8a1f;
  --ws-coral: #ff6b5c;
  --ws-lime: #9be564;
  --ws-blue: #5aa2ff;
  --ws-slate: #5a6b93;
  --ws-soft: #a9bfdc;
  --ws-line: rgba(169, 191, 220, 0.16);
  font-family: var(--dd-font-ui);
  background:
    radial-gradient(ellipse 55% 50% at 10% 6%, rgba(46, 230, 214, 0.12), transparent 70%),
    radial-gradient(ellipse 50% 45% at 94% 96%, rgba(255, 180, 138, 0.12), transparent 70%),
    linear-gradient(165deg, #22448f 0%, #172f6a 45%, #0f2454 100%) !important;
}
.nhlcal-root.nhlcal-dd *:not(.nhlcal-month-title-block h2):not(.nhlcal-advance-button) { text-transform: none !important; letter-spacing: 0.01em; }

/* ---------- top bar ---------- */
.nhlcal-root.nhlcal-dd .nhlcal-team-identity h1,
.nhlcal-root.nhlcal-dd .nhlcal-topbar h1 { font-size: 30px !important; font-weight: 900 !important; color: #fff !important; -webkit-text-fill-color: #fff !important; }
.nhlcal-root.nhlcal-dd .nhlcal-season-phase { font-size: 13px !important; font-weight: 800 !important; color: var(--ws-soft) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-month-year { font-size: 13px !important; font-weight: 800 !important; color: var(--ws-soft) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-month-control button,
.nhlcal-root.nhlcal-dd .nhlcal-today-chip {
  min-height: 34px;
  padding: 0 12px;
  font-size: 14px !important;
  font-weight: 800 !important;
  color: #fff !important;
  background: rgba(255, 255, 255, 0.07) !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* ---------- next game: dossier paper card ---------- */
.nhlcal-root.nhlcal-dd .nhlcal-hero {
  align-items: stretch !important;
  gap: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: 0 !important;
  box-shadow: none !important;
}
.nhlcal-root.nhlcal-dd .nhlcal-hero-next {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 16px 48px 16px 22px !important;
  color: var(--ws-ink);
  background: var(--ws-cream) !important;
  border: 0 !important;
  border-radius: 0 !important;
  clip-path: polygon(0 0, 100% 0, calc(100% - 24px) 100%, 0 100%);
}
.nhlcal-root.nhlcal-dd .nhlcal-hero-next img { filter: drop-shadow(0 3px 4px rgba(7, 18, 51, 0.35)); }
.nhlcal-root.nhlcal-dd .nhlcal-hero-kicker { margin: 0 0 2px !important; font-size: 13px !important; font-weight: 900 !important; color: #a8300f !important; }
.nhlcal-root.nhlcal-dd .nhlcal-hero-title,
.nhlcal-root.nhlcal-dd .nhlcal-hero-title * {
  font-family: var(--dd-font-ui) !important;
  font-size: clamp(26px, 2.4vw, 38px) !important;
  font-weight: 900 !important;
  line-height: 1.05 !important;
  color: var(--ws-ink) !important;
  -webkit-text-fill-color: var(--ws-ink) !important;
  -webkit-text-stroke: 0 !important;
  text-shadow: none !important;
}
.nhlcal-root.nhlcal-dd .nhlcal-hero-intel,
.nhlcal-root.nhlcal-dd .nhlcal-hero-intel * { color: #4b5a82 !important; font-size: 14px !important; font-weight: 700 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-hero-intel strong,
.nhlcal-root.nhlcal-dd .nhlcal-hero-intel b { color: var(--ws-ink) !important; font-size: 18px !important; font-weight: 900 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-hero-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 18px 14px 34px !important;
  background: var(--ws-deep) !important;
  border-top: 3px solid var(--ws-cream);
  clip-path: polygon(18px 0, 100% 0, 100% 100%, 0 100%);
  margin-left: -6px;
}
.nhlcal-root.nhlcal-dd .nhlcal-advance-button-secondary {
  min-height: 42px;
  font-size: 14px !important;
  font-weight: 900 !important;
  color: #fff !important;
  background: rgba(255, 255, 255, 0.07) !important;
  border: 0 !important;
  border-radius: 0 !important;
}
.nhlcal-root.nhlcal-dd .nhlcal-schedule-alert { padding: 6px 10px; font-size: 13px !important; font-weight: 800 !important; color: #1a0b00 !important; background: var(--ws-orange) !important; border: 0 !important; border-radius: 0 !important; }

/* ---------- season stats: matrix cells ---------- */
.nhlcal-root.nhlcal-dd .nhlcal-stat-strip { display: grid !important; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 2px !important; padding: 0 !important; margin: 10px 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-stat-pill { display: grid !important; gap: 2px; padding: 10px 14px !important; background: var(--ws-deep) !important; border: 0 !important; border-top: 3px solid var(--ws-cream) !important; border-radius: 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-stat-pill > :first-child { display: block !important; }
.nhlcal-root.nhlcal-dd .nhlcal-stat-pill span,
.nhlcal-root.nhlcal-dd .nhlcal-stat-pill small { font-size: 12px !important; font-weight: 800 !important; color: var(--ws-soft) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-stat-pill strong,
.nhlcal-root.nhlcal-dd .nhlcal-stat-pill b { font-size: 24px !important; font-weight: 900 !important; color: #fff !important; }
.nhlcal-root.nhlcal-dd .nhlcal-stat-icon { display: none !important; }

/* ---------- view tabs ---------- */
.nhlcal-root.nhlcal-dd .nhlcal-tab-row { gap: 22px !important; background: none !important; border: 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-tab-row button { padding: 6px 0 !important; font-size: 14px !important; font-weight: 800 !important; color: var(--ws-soft) !important; background: none !important; border: 0 !important; border-radius: 0 !important; box-shadow: none !important; }
.nhlcal-root.nhlcal-dd .nhlcal-tab-row button.is-active,
.nhlcal-root.nhlcal-dd .nhlcal-tab-row button[aria-pressed="true"] { color: #fff !important; box-shadow: inset 0 -3px 0 var(--ws-orange) !important; }

/* ---------- month grid: deep matrix ---------- */
.nhlcal-root.nhlcal-dd .nhlcal-week-header { background: none !important; border: 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-week-header > * { font-size: 13px !important; font-weight: 900 !important; color: var(--ws-soft) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-month-grid { gap: 2px !important; background: none !important; border: 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-day-cell {
  background: var(--ws-cell) !important;
  border: 0 !important;
  border-top: 3px solid transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  transition: background-color 0.12s ease;
}
.nhlcal-root.nhlcal-dd .nhlcal-day-cell:hover { background: #10225a !important; }
.nhlcal-root.nhlcal-dd .nhlcal-day-cell.is-muted { background: rgba(11, 24, 68, 0.45) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-day-cell.is-muted .nhlcal-game-tile { opacity: 0.55; }
.nhlcal-root.nhlcal-dd .nhlcal-day-cell.has-team-game { border-top-color: rgba(255, 231, 196, 0.45) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-day-cell.is-today { border-top-color: var(--ws-orange) !important; box-shadow: inset 0 0 0 2px var(--ws-orange) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-day-cell.is-selected { background: #14295f !important; border-top-color: var(--ws-cream) !important; box-shadow: inset 0 0 0 2px var(--ws-cream) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-day-number { font-size: 15px !important; font-weight: 900 !important; color: var(--ws-cream) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-day-cell.is-muted .nhlcal-day-number { color: var(--ws-slate) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-game-tile.is-home { background: rgba(255, 231, 196, 0.05) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-game-tile::after {
  top: 6px !important;
  right: 6px !important;
  padding: 0 5px;
  font-size: 11px !important;
  font-weight: 900 !important;
  color: var(--ws-ink) !important;
  background: var(--ws-cream);
}
.nhlcal-root.nhlcal-dd .nhlcal-game-tile.is-away::after { color: #fff !important; background: var(--ws-slate); }
.nhlcal-root.nhlcal-dd .nhlcal-game-score-mini { border-radius: 0 !important; font-size: 14px !important; padding: 2px 8px !important; }
.nhlcal-root.nhlcal-dd .nhlcal-game-tile.result-win .nhlcal-game-score-mini { background: var(--ws-lime) !important; color: var(--ws-ink) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-game-tile.result-loss .nhlcal-game-score-mini { background: var(--ws-coral) !important; color: #2a0702 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-game-tile.result-otl .nhlcal-game-score-mini,
.nhlcal-root.nhlcal-dd .nhlcal-game-tile.result-ot .nhlcal-game-score-mini { background: var(--ws-orange) !important; color: #1a0b00 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-special-event-tile { border-radius: 0 !important; border-left-color: var(--ws-orange) !important; background: rgba(255, 138, 31, 0.12) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-day-cell.has-critical-event .nhlcal-day-number::after { background: var(--ws-coral) !important; }

/* legend */
.nhlcal-root.nhlcal-dd .nhlcal-legend { gap: 16px !important; padding: 8px 2px !important; background: none !important; border: 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-legend,
.nhlcal-root.nhlcal-dd .nhlcal-legend * { font-size: 13px !important; font-weight: 800 !important; color: var(--ws-soft) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-legend-filter.is-active { color: #fff !important; box-shadow: inset 0 -3px 0 var(--ws-orange) !important; }

/* ---------- right rail: matrix cards ---------- */
.nhlcal-root.nhlcal-dd .nhlcal-right-rail { gap: 12px !important; }
.nhlcal-root.nhlcal-dd .nhlcal-card,
.nhlcal-root.nhlcal-dd .nhlcal-selected-day-panel {
  background: var(--ws-deep) !important;
  border: 0 !important;
  border-top: 3px solid var(--ws-cream) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.nhlcal-root.nhlcal-dd .nhlcal-card-header { padding: 12px 14px 8px !important; background: none !important; border: 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-card-header h2,
.nhlcal-root.nhlcal-dd .nhlcal-card-header h3,
.nhlcal-root.nhlcal-dd .nhlcal-section-title { font-size: 17px !important; font-weight: 900 !important; color: #fff !important; }
.nhlcal-root.nhlcal-dd .nhlcal-card-header p,
.nhlcal-root.nhlcal-dd .nhlcal-subtext { font-size: 12px !important; font-weight: 700 !important; color: var(--ws-soft) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-selected-event-chip,
.nhlcal-root.nhlcal-dd .nhlcal-header-pill { font-size: 12px !important; font-weight: 800 !important; color: var(--ws-ink) !important; background: var(--ws-cream) !important; border: 0 !important; border-radius: 0 !important; }

/* matchup preview */
.nhlcal-root.nhlcal-dd .nhlcal-matchup-stage { background: none !important; border: 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-matchup-team strong { font-size: 20px !important; font-weight: 900 !important; color: #fff !important; }
.nhlcal-root.nhlcal-dd .nhlcal-matchup-team small,
.nhlcal-root.nhlcal-dd .nhlcal-matchup-team span { font-size: 13px !important; font-weight: 700 !important; color: var(--ws-soft) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-versus { font-size: 14px !important; font-weight: 900 !important; color: var(--ws-orange) !important; background: none !important; border: 0 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-preview-lines > * { font-size: 13px !important; border-bottom: 1px solid var(--ws-line); }

/* standings */
.nhlcal-root.nhlcal-dd .nhlcal-standings-table,
.nhlcal-root.nhlcal-dd .nhlcal-standings-row { font-size: 13px !important; }
.nhlcal-root.nhlcal-dd .nhlcal-standings-row { border-bottom: 1px solid var(--ws-line) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-standings-row.is-user,
.nhlcal-root.nhlcal-dd .nhlcal-standings-row.is-user-team { color: var(--ws-ink) !important; background: var(--ws-cream) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-standings-row.is-user *,
.nhlcal-root.nhlcal-dd .nhlcal-standings-row.is-user-team * { color: var(--ws-ink) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-standings-full-button,
.nhlcal-root.nhlcal-dd .nhlcal-wide-action {
  min-height: 36px;
  font-size: 14px !important;
  font-weight: 800 !important;
  color: #fff !important;
  background: rgba(255, 255, 255, 0.07) !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* upcoming stretch */
.nhlcal-root.nhlcal-dd .nhlcal-stretch-row { padding: 8px 0 !important; border-bottom: 1px solid var(--ws-line) !important; font-size: 14px !important; font-weight: 800 !important; }
.nhlcal-root.nhlcal-dd .nhlcal-game-relation { padding: 1px 7px !important; font-size: 12px !important; font-weight: 900 !important; border: 0 !important; border-radius: 0 !important; color: #fff !important; background: var(--ws-slate) !important; }
.nhlcal-root.nhlcal-dd .nhlcal-game-relation.is-home,
.nhlcal-root.nhlcal-dd .nhlcal-game-relation.home { color: var(--ws-ink) !important; background: var(--ws-cream) !important; }

/* drawers / modals keep the same family */
.nhlcal-root.nhlcal-dd .nhlcal-modal,
.nhlcal-root.nhlcal-dd .nhlcal-event-modal { background: var(--ws-deep) !important; border: 0 !important; border-top: 3px solid var(--ws-cream) !important; border-radius: 0 !important; }

/* ---------- v2: game cells carry the game; runs; month context ---------- */
.nhlcal-root.nhlcal-dd .nhlcal-month-grid { grid-template-rows: repeat(var(--weeks, 6), minmax(0, 1fr)) !important; }

/* tile: big crest on top, opponent + time / score underneath */
.nhlcal-root.nhlcal-dd .nhlcal-game-tile {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto !important;
  grid-template-rows: minmax(0, 1fr) auto !important;
  padding: 26px 8px 8px !important;
  gap: 4px 6px;
