.resign-nego-meter-fill.tone-bad { background: linear-gradient(90deg, #ff606d, #f0a35a); }
.resign-nego-meter-fill.tone-mid { background: linear-gradient(90deg, #f0a35a, #e9a83c); }
.resign-nego-meter-fill.tone-good { background: linear-gradient(90deg, #52df94, #13d8e7); }
.resign-nego-meter-fill.tone-instant { background: linear-gradient(90deg, #f4bd52, #fff0c2); }
.resign-nego-meter-mark {
  position: absolute; top: -2px; bottom: -2px; width: 2px;
