@media (max-width: 1280px) {
  .resign-table-layout { grid-template-columns: minmax(0, 1fr) minmax(300px, 38%); }
  .resign-stage { grid-template-columns: minmax(0, 1fr) min(250px, 26vw); }
}
@media (max-width: 1100px) {
  .resign-table-layout { grid-template-columns: 1fr; }
  .resign-detail-panel { max-height: min(46vh, 460px); }
  .resign-stage { grid-template-columns: 1fr; height: auto; max-height: none; overflow: auto; }
  .resign-root { height: auto; max-height: none; overflow: auto; }
}





@media (prefers-reduced-motion: reduce) {
  .resign-spotlight { opacity: 0.35; }
  .resign-ghost-btn:hover, .resign-skip-btn:hover, .resign-cta-btn:hover:not(:disabled) { transform: none; }
}

/* ===== components/contracts/NegotiationMeetingPanel.js (CSS) · active while .nmp, .nmp__opt, .nmp__toggle, .nmp__result, .nmp__flash is on screen ===== */
:where(:root:has(.nmp, .nmp__opt, .nmp__toggle, .nmp__result, .nmp__flash)) .nmp { border: 1px solid rgba(115,229,241,.22); border-radius: 10px; margin: 10px 0; background: rgba(46, 230, 214, .03); }
:where(:root:has(.nmp, .nmp__opt, .nmp__toggle, .nmp__result, .nmp__flash)) .nmp__toggle { width: 100%; display: flex; align-items: center; gap: 10px; padding: 9px 12px; background: transparent;
  border: 0; color: inherit; cursor: pointer; text-align: left; }
:where(:root:has(.nmp, .nmp__opt, .nmp__toggle, .nmp__result, .nmp__flash)) .nmp__toggle span { font-size: 15px; font-weight: 900; letter-spacing: .06em; text-transform: uppercase; }
:where(:root:has(.nmp, .nmp__opt, .nmp__toggle, .nmp__result, .nmp__flash)) .nmp__toggle em { font-style: normal; font-size: 14px; color: #8fb4c4; margin-left: auto; }
:where(:root:has(.nmp, .nmp__opt, .nmp__toggle, .nmp__result, .nmp__flash)) .nmp__toggle i { font-style: normal; color: #8fb4c4; }
:where(:root:has(.nmp, .nmp__opt, .nmp__toggle, .nmp__result, .nmp__flash)) .nmp__body { padding: 0 12px 12px; display: grid; gap: 10px; }
