/* ==========================================================================
   PUCKBUDDY — Pucky in the corner: a tip for the screen you're on, quick jumps,
   and the door to PuckGPT.
   ========================================================================== */
.puckbuddy {
  position: fixed;
  right: 18px;
  bottom: 16px;
  z-index: 3500;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
  pointer-events: none;
  font-family: var(--dd-font-ui, "Nunito", sans-serif);
}
.puckbuddy > * { pointer-events: auto; }
.puckbuddy__me {
  all: unset;
  cursor: pointer;
  padding: 6px;
  transition: transform 0.08s steps(2);
}
.puckbuddy__me:hover { transform: translateY(-3px) rotate(-4deg); }
.puckbuddy__me:active { transform: translateY(2px); }
.puckbuddy__me:focus-visible { outline: 3px dashed #ffe23a; outline-offset: 2px; }
.puckbuddy__bubble {
  position: relative;
  width: min(300px, calc(100vw - 40px));
  padding: 12px 14px;
  background: #ffe7c4;
  color: #071233;
  border-radius: 14px;
  box-shadow: inset 0 0 0 3px #071233, 5px 5px 0 #071233;
  animation: puckbuddy-pop 0.16s steps(3);
}
/* Speech-bubble tail pointing down at Pucky */
.puckbuddy__bubble::after {
  content: "";
  position: absolute;
  right: 30px;
  bottom: -9px;
  width: 16px;
  height: 16px;
  background: #ffe7c4;
  transform: rotate(45deg);
  box-shadow: inset -3px -3px 0 #071233;
}
.puckbuddy__bubble p { margin: 0; font-size: 14px; font-weight: 800; line-height: 1.35; }
.puckbuddy__nav { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.puckbuddy__row { display: flex; gap: 6px; margin-top: 8px; }
.puckbuddy__go,
.puckbuddy__ask,
.puckbuddy__hide {
  all: unset;
  cursor: pointer;
  padding: 5px 10px;
  border-radius: 9px;
  font-family: "Silkscreen", var(--dd-font-ui, monospace);
  font-size: 11px;
  text-transform: uppercase;
  color: #071233;
  background: #fff;
  box-shadow: inset 0 0 0 2px #071233, 0 3px 0 #071233;
}
.puckbuddy__ask { background: #ffe23a; flex: 1; text-align: center; }
.puckbuddy__hide { background: transparent; box-shadow: inset 0 0 0 2px rgba(7, 18, 51, 0.4); }
.puckbuddy__go:hover,
.puckbuddy__ask:hover { transform: translateY(-1px); box-shadow: inset 0 0 0 2px #071233, 0 4px 0 #071233; }
.puckbuddy__go:active,
.puckbuddy__ask:active { transform: translateY(2px); box-shadow: inset 0 0 0 2px #071233, 0 1px 0 #071233; }
.puckbuddy--mini {
  all: unset;
  position: fixed;
  right: 12px;
  bottom: 10px;
  z-index: 3500;
  cursor: pointer;
  opacity: 0.75;
}
.puckbuddy--mini:hover { opacity: 1; }
@keyframes puckbuddy-pop { 0% { transform: scale(0.6); } 50% { transform: scale(1.06); } 100% { transform: scale(1); } }

/* PuckGPT: Pucky is the logo, the empty-state host and the "thinking" face. */
.puckgpt-mark { display: inline-flex !important; align-items: center; gap: 12px; }
.puckgpt-mark .pucky { --pk-px: 3px; }
.puckgpt-hello { display: flex; align-items: center; gap: 16px; margin-bottom: 14px; }
.puckgpt-hello .pucky { --pk-px: 7px; }
.puckgpt-hello p { margin: 0; font-family: var(--dd-font-display, "Luckiest Guy", sans-serif); font-size: 26px; color: #ffe23a; text-shadow: 0 3px 0 #071233; letter-spacing: 0.02em; }
.puckgpt-thinking { display: flex !important; align-items: center; gap: 10px; }

/* ==========================================================================
   CARTOON ARCADE LAYER — the whole game reads like a game, not a website.
   Ink outlines, hard drop shadows that press down, sticker chips and pixel
   labels. Gated on html.cartoon-ui; :not(#_) lifts these over the older
   design-pass rules without touching layout (rings are box-shadows, no borders).
   ========================================================================== */
html.cartoon-ui {
  --toon-ink: #071233;
  --toon-cream: #ffe7c4;
  --toon-yellow: #ffe23a;
  --toon-orange: #ff8a1f;
  --toon-lime: #9be564;
  --toon-coral: #ff6b5c;
  --toon-pixel: "Silkscreen", "Press Start 2P", ui-monospace, monospace;
  --toon-ring: inset 0 0 0 2.5px var(--toon-ink);
}
html.cartoon-ui ::selection { background: var(--toon-yellow); color: var(--toon-ink); }

/* Chunky pixel scrollbars */
html.cartoon-ui ::-webkit-scrollbar { width: 12px; height: 12px; }
html.cartoon-ui ::-webkit-scrollbar-track { background: var(--toon-ink); }
html.cartoon-ui ::-webkit-scrollbar-thumb { background: var(--toon-yellow); border: 3px solid var(--toon-ink); border-radius: 0; }
html.cartoon-ui ::-webkit-scrollbar-thumb:hover { background: var(--toon-orange); }
html.cartoon-ui ::-webkit-scrollbar-corner { background: var(--toon-ink); }

/* Buttons: soft, bouncy and toy-like — rounded, a gentle ink edge and a floor
   shadow that squishes when pressed. */
html.cartoon-ui:not(#_) :is(button, a, [role="button"]):is([class*="btn"], [class*="button"], [class*="-cta"]):not([class*="close"]):not([class*="puckbuddy"]) {
  border-radius: 14px !important;
  box-shadow: inset 0 0 0 2px rgba(7, 18, 51, 0.85), 0 3px 0 rgba(7, 18, 51, 0.9), 0 6px 14px rgba(5, 12, 44, 0.25) !important;
  font-weight: 900 !important;
  text-shadow: none !important;
  transition: transform 0.22s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.18s ease, filter 0.18s ease !important;
}
html.cartoon-ui:not(#_) :is(button, a, [role="button"]):is([class*="btn"], [class*="button"], [class*="-cta"]):not([class*="close"]):not([class*="puckbuddy"]):hover:not(:disabled) {
  transform: translateY(-2px) scale(1.03) !important;
  filter: brightness(1.06);
  box-shadow: inset 0 0 0 2px rgba(7, 18, 51, 0.85), 0 5px 0 rgba(7, 18, 51, 0.9), 0 10px 18px rgba(5, 12, 44, 0.3) !important;
}
html.cartoon-ui:not(#_) :is(button, a, [role="button"]):is([class*="btn"], [class*="button"], [class*="-cta"]):not([class*="close"]):not([class*="puckbuddy"]):active:not(:disabled) {
  transform: translateY(2px) scale(0.97) !important;
  transition-duration: 0.06s !important;
  box-shadow: inset 0 0 0 2px rgba(7, 18, 51, 0.85), 0 1px 0 rgba(7, 18, 51, 0.9) !important;
}
html.cartoon-ui:not(#_) :is(button, a, [role="button"]):is([class*="btn"], [class*="button"]):disabled {
  box-shadow: inset 0 0 0 2px rgba(7, 18, 51, 0.45) !important;
  transform: none !important;
}
/* Icons wiggle a little instead of sitting dead still. */
html.cartoon-ui:not(#_) :is(button, a) :is(svg, img[class*="icon"], [class*="icon"]) {
  transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}
html.cartoon-ui:not(#_) :is(button, a):hover :is(svg, img[class*="icon"], [class*="icon"]) {
  transform: rotate(-7deg) scale(1.1);
}

/* Kickers, eyebrows and section labels: pixel font, like a game HUD. */
html.cartoon-ui:not(#_) :is([class*="kicker"], [class*="eyebrow"], [class*="overline"]) {
  font-family: var(--toon-pixel) !important;
  font-weight: 400 !important;
  font-size: 10px !important;
  letter-spacing: 0.06em !important;
  text-transform: uppercase !important;
  text-shadow: 0 2px 0 var(--toon-ink) !important;
}

/* Chips, pills, tags and badges become stickers. */
html.cartoon-ui:not(#_) :is([class$="-chip"], [class*="-chip "], [class$="-pill"], [class*="-pill "], [class$="-badge"], [class*="-badge "], [class$="-tag"], [class*="-tag "]):not(:is(table, tr, td, th)) {
  border-radius: 999px !important;
  box-shadow: inset 0 0 0 1.5px rgba(7, 18, 51, 0.75), 0 2px 0 rgba(7, 18, 51, 0.55) !important;
}

/* Outer cards and panels get a cartoon frame: ink outline + offset drop.
   Only the outermost one, so nested cards don't stack outlines. */
html.cartoon-ui:not(#_) :is([class$="-card"], [class*="-card "], [class$="-panel"], [class*="-panel "]):not(:is([class$="-card"], [class*="-card "], [class$="-panel"], [class*="-panel "]) *):not(.puckbuddy__bubble):not(:is(button, td, th, tr, li)) {
  border-radius: 18px !important;
  box-shadow: inset 0 0 0 2px rgba(7, 18, 51, 0.7), 4px 5px 0 rgba(5, 12, 44, 0.55), 0 14px 30px rgba(5, 12, 44, 0.28) !important;
}

/* Table headers read like a scoreboard. */
html.cartoon-ui:not(#_) table thead th {
  font-family: var(--toon-pixel) !important;
  font-weight: 400 !important;
  font-size: 10px !important;
  letter-spacing: 0.04em !important;
  text-transform: uppercase !important;
}
html.cartoon-ui:not(#_) table tbody tr:hover > td { background-color: rgba(255, 226, 58, 0.07); }

/* Inputs and selects: chunky cream fields. */
html.cartoon-ui:not(#_) :is(input[type="text"], input[type="search"], input[type="number"], select, textarea):not([class*="puckbuddy"]) {
  border-radius: 12px !important;
  box-shadow: inset 0 0 0 2px rgba(7, 18, 51, 0.8), inset 0 3px 0 rgba(7, 18, 51, 0.14) !important;
}
html.cartoon-ui:not(#_) :is(input, select, textarea):focus-visible {
  outline: 3px dashed var(--toon-yellow) !important;
  outline-offset: 2px !important;
}

/* Page titles: the cartoon headline (thick ink stroke and a hard drop). */
html.cartoon-ui:not(#_) h1 {
  font-family: var(--dd-font-display, "Luckiest Guy", sans-serif) !important;
  letter-spacing: 0.02em !important;
  paint-order: stroke fill;
  -webkit-text-stroke: 4px var(--toon-ink) !important;
  text-shadow: 0 4px 0 var(--toon-ink) !important;
}

/* ==========================================================================
   HAZE — a light game-camera filter over everything: soft vignette, slow
   drifting fog, film grain and faint scanlines. Never blocks clicks.
   Turn off with html.no-haze.
   ========================================================================== */
html.cartoon-ui:not(.no-haze)::before,
html.cartoon-ui:not(.no-haze)::after {
  content: "";
  position: fixed;
  inset: -10%;
  pointer-events: none;
  z-index: 3400;
}
html.cartoon-ui:not(.no-haze)::before {
  background:
    radial-gradient(ellipse at 50% 45%, transparent 52%, rgba(3, 6, 22, 0.42) 100%),
    radial-gradient(circle at 20% 30%, rgba(160, 180, 255, 0.07), transparent 40%),
    radial-gradient(circle at 80% 70%, rgba(160, 180, 255, 0.06), transparent 45%);
  animation: haze-drift 26s ease-in-out infinite alternate;
}
html.cartoon-ui:not(.no-haze)::after {
  opacity: 0.09;
  mix-blend-mode: overlay;
  background:
    repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.5) 0 1px, transparent 1px 3px),
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  animation: haze-grain 0.6s steps(3) infinite;
}
@keyframes haze-drift { from { transform: translate3d(-2%, -1%, 0) scale(1); } to { transform: translate3d(2%, 1.5%, 0) scale(1.04); } }
@keyframes haze-grain { 0% { transform: translate(0, 0); } 33% { transform: translate(-3%, 2%); } 66% { transform: translate(2%, -3%); } }
@media (prefers-reduced-motion: reduce) {
  html.cartoon-ui::before, html.cartoon-ui::after { animation: none !important; }
}

/* ==========================================================================
   CREATIVE PASS — every menu gets its own real-world motif (whiteboard, binder,
   war room, lottery machine...). Shared kit first: textures, stickers, stamps,
   tape and motion. All flat 2D: gradients, pseudo-elements and pixel sprites.
   ========================================================================== */
:root {
  --cp-ink: #071233;
  --cp-cream: #ffe7c4;
  --cp-yellow: #ffe23a;
  --cp-orange: #ff8a1f;
  --cp-lime: #9be564;
  --cp-coral: #ff6b5c;
  --cp-sky: #9fd8ff;
  --cp-pixel: "Silkscreen", ui-monospace, monospace;
  --cp-hand: "Nunito", system-ui, sans-serif;
  /* Dark textures (safe behind light text) */
  --tx-chalk:
    radial-gradient(circle at 18% 22%, rgba(255,255,255,.05), transparent 30%),
    radial-gradient(circle at 80% 70%, rgba(255,255,255,.04), transparent 35%),
    repeating-linear-gradient(-12deg, rgba(255,255,255,.018) 0 2px, transparent 2px 9px),
    #1d3b33;
  --tx-wood-dark:
    repeating-linear-gradient(90deg, rgba(0,0,0,.18) 0 2px, transparent 2px 22px, rgba(255,255,255,.04) 22px 24px, transparent 24px 60px),
    linear-gradient(180deg, #3b2414, #2a180c);
  --tx-felt:
    radial-gradient(ellipse at 50% 40%, rgba(255,255,255,.08), transparent 60%),
    repeating-radial-gradient(circle at 30% 30%, rgba(0,0,0,.05) 0 1px, transparent 1px 3px),
    #13573a;
  --tx-led:
    radial-gradient(circle, rgba(255,226,58,.07) 1px, transparent 1.6px) 0 0 / 5px 5px,
    linear-gradient(180deg, #050a1d, #0a1433);
  --tx-cork-dark:
    radial-gradient(circle at 30% 40%, rgba(0,0,0,.25) 1px, transparent 2px) 0 0 / 7px 7px,
    radial-gradient(circle at 70% 20%, rgba(255,210,150,.12) 1px, transparent 2px) 0 0 / 9px 9px,
    #6b4423;
  --tx-ice-dark:
    repeating-linear-gradient(28deg, rgba(255,255,255,.035) 0 1px, transparent 1px 40px),
    repeating-linear-gradient(-34deg, rgba(255,255,255,.03) 0 1px, transparent 1px 55px),
    radial-gradient(ellipse at 50% 0%, rgba(159,216,255,.16), transparent 60%),
    #0c2350;
  --tx-night:
    radial-gradient(circle at 15% 20%, rgba(255,255,255,.5) 0 1px, transparent 1.5px) 0 0 / 120px 90px,
    radial-gradient(circle at 60% 70%, rgba(255,255,255,.35) 0 1px, transparent 1.5px) 0 0 / 170px 130px,
    linear-gradient(180deg, #050b26, #0d1d4d);
  /* Light textures (only where text colour is set too) */
  --tx-paper:
    repeating-linear-gradient(0deg, transparent 0 21px, rgba(90,140,200,.22) 21px 22px),
    #fdf6e3;
  --tx-newsprint:
    radial-gradient(circle, rgba(0,0,0,.06) 1px, transparent 1.4px) 0 0 / 4px 4px,
    #efe7d2;
  --tx-whiteboard:
    linear-gradient(115deg, transparent 38%, rgba(255,255,255,.55) 48%, transparent 58%),
    #eef2f6;
  --tx-manila: linear-gradient(180deg, #f3d9a4, #e8c785);
}

/* Sticker: tilted cream label with an ink ring and a hard drop */
.cp-sticker,
.cp-stamp { font-family: var(--cp-pixel); text-transform: uppercase; letter-spacing: .04em; }

/* Masking tape strip (used via ::before on cards) */
@keyframes cp-pop { 0% { transform: scale(.6) rotate(-6deg); opacity: 0; } 60% { transform: scale(1.08) rotate(2deg); opacity: 1; } 100% { transform: scale(1) rotate(0); } }
@keyframes cp-slam { 0% { transform: scale(2.2) rotate(-14deg); opacity: 0; } 70% { transform: scale(.94) rotate(-9deg); opacity: 1; } 100% { transform: scale(1) rotate(-9deg); opacity: .92; } }
@keyframes cp-wobble { 0%,100% { transform: rotate(-2deg); } 50% { transform: rotate(2deg); } }
@keyframes cp-float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }
@keyframes cp-pulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.06); } }
@keyframes cp-flicker { 0%,100% { opacity: 1; } 48% { opacity: .85; } 50% { opacity: .55; } 52% { opacity: .9; } }
@keyframes cp-sweep { from { background-position: -200% 0; } to { background-position: 200% 0; } }
@keyframes cp-snow { from { background-position: 0 0, 0 0, 0 0; } to { background-position: 40px 400px, -60px 600px, 20px 800px; } }
@keyframes cp-spin { to { transform: rotate(360deg); } }
@keyframes cp-confetti { from { background-position: 0 -200px, 0 -300px, 0 -250px; } to { background-position: 30px 100vh, -40px 100vh, 10px 100vh; } }
@keyframes cp-ticker { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@keyframes cp-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: .25; } }
@media (prefers-reduced-motion: reduce) {
  html.cartoon-ui *, html.cartoon-ui *::before, html.cartoon-ui *::after { animation-duration: .001s !important; animation-iteration-count: 1 !important; }
}
