/* ---------- SIDEBAR ICONS: generic glyphs become pixel sprites, picked by the button's label ---------- */
html.cartoon-ui:not(#_) :is(button, a)[aria-label] :is([class*="side-icon"], [class*="nav-icon"]) {
  display: inline-block; width: 22px !important; height: 22px !important; font-size: 0 !important; color: transparent !important;
  background: var(--pxi-puck) center / contain no-repeat; image-rendering: pixelated;
  transition: transform .25s cubic-bezier(.34,1.56,.64,1);
}
html.cartoon-ui:not(#_) :is(button, a)[aria-label]:hover :is([class*="side-icon"], [class*="nav-icon"]) { transform: rotate(-10deg) scale(1.15); }
html.cartoon-ui:not(#_) :is(button, a)[aria-label].is-active :is([class*="side-icon"], [class*="nav-icon"]) { animation: cp-float 2s ease-in-out infinite; }
html.cartoon-ui:not(#_) :is(button, a)[aria-label*="office" i] :is([class*="side-icon"], [class*="nav-icon"]) { background-image: var(--pxi-puck); }
html.cartoon-ui:not(#_) :is(button, a)[aria-label*="hub" i] :is([class*="side-icon"], [class*="nav-icon"]) { background-image: var(--pxi-puck); }
html.cartoon-ui:not(#_) :is(button, a)[aria-label*="calendar" i] :is([class*="side-icon"], [class*="nav-icon"]) { background-image: var(--pxi-clock); }
html.cartoon-ui:not(#_) :is(button, a)[aria-label*="storyline" i] :is([class*="side-icon"], [class*="nav-icon"]) { background-image: var(--pxi-pin); }
html.cartoon-ui:not(#_) :is(button, a)[aria-label*="injur" i] :is([class*="side-icon"], [class*="nav-icon"]) { background-image: var(--pxi-heart); }
